window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["司法部"] = {"zhongguoweituogongzhengrenguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步健全委托公证人制度，加强对委托公证人的管理，提高委托公证的质量，维护当事人的合法权益，促进内地与香港社会经济的稳定发展，根据国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"委托公证人由司法部考试、考核合格后委托。委托期为三年，特殊情况可适当变更委托期限。委托期满，本人提出申请，经司法部考核合格并接受业务培训后，可连续委托。"},{"i":3,"n":"第三条","txt":"委托公证人的业务范围是证明发生在香港地区的法律行为、有法律意义的事实和文书。证明的使用范围在内地。"},{"i":4,"n":"第四条","txt":"委托公证人必须按照司法部规定或批准的委托业务范围、出证程序和文书格式出具公证文书。"},{"i":5,"n":"第五条","txt":"委托公证人出具的委托公证文书，须经中国法律服务(香港)有限公司(以下简称公司)审核，对符合出证程序以及文书格式要求的加章转递，对不符合上述要求的不予转递。公司应定期(7月15日前报上半年，1月15日前报上年度)将加章转递情况报司法部。"},{"i":6,"n":"第六条","txt":"委托公证人接受当事人委托后，应亲自办理委托公证事项。特殊情况下，需要内地公证机构或其他机构协助办理的，应征得当事人的同意，委托费用由委托公证人支付，或由委托公证人与当事人协商支付。"},{"i":7,"n":"第七条","txt":"委托公证人应定期接受业务培训。"},{"i":8,"n":"第八条","txt":"具备下列条件的香港律师，可向司法部提出成为委托公证人的申请： (一) 拥护《中华人民共和国宪法》，拥护《中华人民共和国香港特别行政区基本法》； (二) 在香港具有永久居留权的中国公民； (三) 担任香港律师十年以上； (四) 职业道德良好，未有因不名誉或违反职业道德受惩处的记录； (五) 掌握内地有关法律、法规和办证规则； (六) 能用中文书写公证文书，能用普通话进行业务活动。"},{"i":9,"n":"第九条","txt":"具备本办法第八条规定条件的香港律师申请担任委托公证人，由本人向司法部提出书面申请；向公司申领并据实填写申请委托公证人登记表。申请书、登记表原件，学历、经历等证件的影印件经委托公证人公证后交由公司一并报司法部。"},{"i":10,"n":"第十条","txt":"司法部接到有关申请后，对申请人资格进行审查并征求有关部门的意见，对符合申请条件的，集中组织进行法律知识和公证业务的培训，经培训后方可参加司法部组织的考试。"},{"i":11,"n":"第十一条","txt":"司法部每三年举行一次委托公证人考试。 考试分为笔试、面试。重点测试申请人对内地有关法律和规定及委托公证业务、普通话的掌握程度。 通过考试的人员由司法部进行考核。 考核合格者，由司法部颁发委托书并予以首次注册。"},{"i":12,"n":"第十二条","txt":"委托公证人应于每年12月15日前向司法部申请年度注册。未经注册的，不得办理委托公证业务。 司法部于每年一月份对注册的委托公证人进行年度公告。"},{"i":13,"n":"第十三条","txt":"委托公证人符合下列条件的准予注册： (一) 在上一年度无违纪和判工行为； (二) 职业道德良好，无违反本办法及协会章程的行为； (三) 能按要求办理委托事宜。"},{"i":14,"n":"第十四条","txt":"委托公证人注册程序： (一) 委托公证人向协会提出注册申请； (二) 填写协会发给的注册申请表，连同本人上年度办证情况及司法部规定需报的材料递交协会； (三) 协会理事会对委托公证人的注册申请签注意见后，将上述材料转交公司，公司将委托公证人所办公证加章转递情况签注意见后报司法部； (四)司法部根据委托公证人的注册申请及有关材料并参考有关部门的意见，作出准予或不准予注册的书面决定。准予注册的，通知公司和协会，由协会代办注册手续。"},{"i":15,"n":"第十五条","txt":"委托公证人受到本办法第十六条第二项处分期间应暂缓注册。"},{"i":16,"n":"第十六条","txt":"委托公证人有违反法律、法规、规章和执业纪律的行为分别给予以下处分： (一) 警告； (二) 中止委托； (三) 取消委托。"},{"i":17,"n":"第十七条","txt":"委托公证人有下列行为之一的予以警告处分： (一) 发往内地使用的公证文书未按规定的时间送公司审核转递的； (二) 不按规定的程序、格式及要求出具公证书，经提示未及时改正的。"},{"i":18,"n":"第十八条","txt":"委托公证人有下列行为之一的，根据不同情节，予以中止委托6至12个月的处分： (一) 发往内地使用的公证文书，不经加章转递的； (二) 因被投诉受到调查而不积极配合调查或经查实造成不良后果的； (三) 有判工行为但经提示及时改正的； (四) 不按规定的收费标准收费的； (五) 无正当理由不参加业务培训的； (六) 对协会理事会决议无正当理由不予执行的。"},{"i":19,"n":"第十九条","txt":"委托公证人有下列行为之一的，取消委托： (一) 发往内地使用的公证文书不经加章转递，受警告或中止委托处分后仍不改正的； (二) 不按规定的程序要求出具公证书，经书面提示仍不改正的； (三) 被投诉业经查实，确已造成严重后果的； (四) 有判工行为经提示不及时改正的； (五) 受到两次中止委托处分的； (六) 在申请登记表及其他申请文书中做虚假陈述的； (七) 其他丧失第八条规定条件的。"},{"i":20,"n":"第二十条","txt":"委托公证人接受委托一年内无正当理由不办理委托业务或不申请年度注册的，经协会书面提示仍不改变，视为自动中止委托。自动中止委托期限为6个月，到期经协会再次书面提示不申请恢复委托，视为自动放弃委托。申请恢复委托者，应说明理由。 因特殊原因，不能办理委托业务的应向司法部报告，经审查批准后，可予以注册。"},{"i":21,"n":"第二十一条","txt":"司法部设立委托公证人纪律监督委员会(以下简称委员会)，受理当事人对委托公证人的投诉，直接或委托有关单位进行调查。委员会应将调查结果及时向司法部报告并提出处理意见。"},{"i":22,"n":"第二十二条","txt":"委托公证人协会由委托公证人依法组成，是委托公证人的自律性组织。委托公证人协会接受司法部的委托，承办与委托公证人有关的具体事项。 委托公证人在任期内必须参加协会成为协会会员。"},{"i":23,"n":"第二十三条","txt":"委托公证人协会的职责由其章程作出规定。"},{"i":24,"n":"第二十四条","txt":"本办法由司法部解释。"},{"i":25,"n":"第二十五条","txt":"本办法自2002年4月1日起施行。原司法部第34号令《中国委托公证人(香港)管理办法》同时废止。"}],"xiangzhenfalvfuwuyewugongzuoxize":[{"i":1,"n":"第一条","txt":"为促进乡镇法律服务所开展各项法律服务业务，进一步提高工作质量，结合乡镇法律服务工作实际，制定本细则。"},{"i":2,"n":"第二条","txt":"乡镇法律服务所通过开展各项业务，维护当事人的合法权益，维护法律、法规的正确实施，保障和促进社会主义民主法制建设和经济建设。"},{"i":3,"n":"第三条","txt":"乡镇法律服务所的业务范围 （一）应聘担任法律顾问； （二）代理参加民事、经济、行政诉讼活动； （三）代理非诉讼法律事务； （四）主持调解纠纷； （五）解答法律询问； （六）代写法律事务文书； （七）协助办理公证事项； （八）协助司法助理员开展法制宣传教育和其他有关业务工作。"},{"i":4,"n":"第四条","txt":"乡镇法律服务所办理各项法律服务业务，应当在本乡镇人民政府及其司法助理员(司法所)的领导下进行。"},{"i":5,"n":"第五条","txt":"乡镇法律服务所办理各项法律服务业务，必须以事实为根据，以法律为准绳，恪守职业纪律和职业道德，不得超越职责权限。"},{"i":6,"n":"第六条","txt":"乡镇法律服务所应当立足基层，主要面向本辖区内的政府机关、群众自治组织、企业事业单位、社会团体和承包经营户、个体工商户、个人合伙组织以及公民提供法律服务，服务方式力求便民利民，及时有效。"},{"i":7,"n":"第七条","txt":"法律服务业务由乡镇法律服务所统一受理，并指派一至两名乡镇法律工作者承办；重大、疑难的法律服务业务，由乡镇法律服务所主任主持集体研究，确定工作方案，也可以商请当地律师事务所联合办理。 不同地区的乡镇法律服务所，根据需要可以进行业务协作。"},{"i":8,"n":"第八条","txt":"乡镇法律服务所的业务收费标准，按照各省、自治区、直辖市司法厅(局)会同物价、财政部门制定的有关收费管理办法执行;收费手续由乡镇法律服务所统一办理；对规定未列及的法律服务收费，可参照律师有关收费项目和标准执行;对规定可以酌情减免收费或者缓收费用的，由乡镇法律服务所主任决定。 乡镇法律服务所与律师事务所联合办理业务和协助办理公证的收费分成比例，按各省、自治区、直辖市司法厅(局)有关规定办理。"},{"i":9,"n":"第九条","txt":"乡镇法律工作者办结法律服务业务后，应当按照《乡镇法律服务所业务档案管理办法》的规定，及时将有关业务材料立卷归档;重大、疑难的法律服务业务，还应写出书面小结，以积累总结经验和教训。"},{"i":10,"n":"第十条","txt":"乡镇法律工作者承办各项法律服务业务，享有下列权利： （一）办理法律服务业务，不受非法干涉; （二）经人民法院同意，查阅案件有关材料; （三）根据承办事项的需要，持乡镇法律服务所证明和乡镇法律工作者证进行调查，向有关单位和个人查询，索取有关材料; （四）对坚持无理要求、故意隐瞒重大情节、提供虚假证据或者严重违反委托、聘应合同的当事人，可以拒绝接受或者解除委托、聘应关系。"},{"i":11,"n":"第十一条","txt":"乡镇法律工作者承办各项法律服务业务，应当承担下列义务： （一）不得私自接受委托和聘请办理法律服务业务，不得私自收取报酬和其他费用; （二）不得泄露国家秘密、在工作中得知的个人隐私和当事人提供的不宜公开的情况; （三）出庭代理，应遵守审判、仲裁和调解活动的正常秩序。 （四）不得进行任何有损乡镇法律工作者名誉和当事人合法权益的活动。"},{"i":12,"n":"第十二条","txt":"乡镇法律服务所办理各项法律服务业务，受司法行政机关和乡镇人民政府的管理和监督。当地律师事务所和公证处，应当在业务上给予法律服务所必要的指导和帮助。"},{"i":13,"n":"第十三条","txt":"乡镇法律工作者受乡镇法律服务所的指派，可接受聘请，担任本辖区内乡镇人民政府及其各行政管理部门，村民委员会，乡镇企业、事业单位，农村承包经营户、个体工商户、个人合伙组织以及公民的法律顾问。 法律顾问工作的重点是协助聘请方依法管理、依法经营、依法办事。"},{"i":14,"n":"第十四条","txt":"聘请法律顾问，由聘请方以书面或者口头形式向乡镇法律服务所提出，并提供有关证件和基本情况;乡镇法律服务所接到聘请后，根据聘请方的情况和本所的情况，决定是否应聘。 乡镇法律服务所决定应聘的，应当指派一至两名乡镇法律工作者担任法律顾问;聘请方对法律顾问有指名要求的，应尽可能予以满足。 乡镇法律服务所独自应聘有困难的，可以商请当地律师事务所联合应聘。"},{"i":15,"n":"第十五条","txt":"乡镇法律服务所与聘请方应当协商订立法律顾问聘应合同。聘应合同采用书面形式。 聘应合同应当包括以下主要内容： （一）双方名称，法律顾问的人数和姓名; （二）法律顾问的具体任务、职责范围和工作方式; （三）双方的权利和义务; （四）法律顾问报酬数额及给付方式; （五）违约责任; （六)合同生效日期和有效期限; （七）双方约定的其他事项。"},{"i":16,"n":"第十六条","txt":"担任乡镇人民政府及其各行政管理部门、村民委员会的法律顾问，办理下列法律服务业务： （一）就较重大的行政、经济决策进行法律论证，提供法律意见; （二）对行政规范性文件的拟定从法律角度提出修改、补充建议; （三）协助修改、审查经济合同、协议、章程等重要法律事务文书; （四）参与处理尚未形成诉讼的民事、经济、行政纠纷和其他较重大的纠纷; （五）代理参加行政、经济案件的调解、仲裁和诉讼活动; （六）协助进行法制宣传教育; （七）提供有关法律、法规资料和信息，对依法行政、建章立制方面的问题提出建议; （八）受托办理的其他法律服务业务。"},{"i":17,"n":"第十七条","txt":"担任乡镇企业、事业单位、承包经营户、个体工商户、个人合伙组织以及公民的法律顾问，办理下列法律服务业务： （一）参与生产、经营活动决策，就其中较重大的问题进行法律论证，提供法律意见; （二）协助起草、审查、订立经济合同等法律事务文书，代理参与经济法律事务谈判; （三）协助建立健全各项管理制度，特别是经济合同管理制度; （四）参与处理尚未形成诉讼的民事、经济、行政纠纷和其他较重大的纠纷; （五）代理参加行政、经济、民事纠纷、案件的调解、仲裁和诉讼活动; （六）代理工商登记、联营、租赁、承包、担保、税务、信贷、保险等业务活动中的法律事务; （七）协助对职工进行法制宣传教育; （八）受托办理的其他法律服务业务。"},{"i":18,"n":"第十八条","txt":"聘请方根据需要，可以聘请提供全面服务的常年法律顾问，也可以聘请专项法律顾问，具体形式由双方协商确定。 担任法律顾问，应当在聘应合同中明确规定法律顾问履行职务的方式和时间，法律顾问因故不能按时履行职务时，应及时通知聘请方。"},{"i":19,"n":"第十九条","txt":"乡镇法律工作者担任法律顾问，有权查阅聘请方的有关文件和资料，列席有关业务会议，进行调查取证，获得必要的工作条件和方便，并有权拒绝办理与法律顾问工作无关的事务。 担任法律顾问，应当在聘请方委托授权的范围内进行活动，不得参与和干预与执行职务无关或者未经委托的其他事务，不得泄露聘请方要求保密的事项。"},{"i":20,"n":"第二十条","txt":"担任法律顾问，应当建立工作计划制度、工作档案制度、集体讨论制度以及与聘请方的业务联系制度。"},{"i":21,"n":"第二十一条","txt":"乡镇法律服务所应当对法律顾问的工作加强检查和监督，定期听取聘请方的意见;发现不称职的，及时与聘请方协商撤换。"},{"i":22,"n":"第二十二条","txt":"法律顾问聘应合同终止后，聘请方要求续聘的，可与乡镇法律服务所协商订立新的聘应合同。 法律顾问聘应合同履行期间，一方提出变更或者解除合同的，应当与对方协商一致，否则应承担违约责任。"},{"i":23,"n":"第二十三条","txt":"乡镇法律工作者受乡镇法律服务所指派，接受民事、经济、行政诉讼一方当事人的委托，担任代理人参加诉讼活动的，应当支持委托人提出的合理要求，维护委托人的合法权益，促使案件得到依法公正解决。"},{"i":24,"n":"第二十四条","txt":"乡镇法律工作者受托代理的民事、经济、行政案件，应当具备下列条件： （一）委托人必须是与本案有利害关系的公民、法人或者其他组织; （二）有明确的对方当事人，具体的诉讼请求和事实根据; （三）本案属于人民法院管辖范围; （四）当事人一方位于本辖区内。"},{"i":25,"n":"第二十五条","txt":"乡镇法律服务所对有激化可能的民事案件，对严重影响正常经济秩序的经济案件，应当优先受托代理;对法律规定须经行政复议后才能提起诉讼的行政争议，应当告知或者协助委托人按照有关规定执行。"},{"i":26,"n":"第二十六条","txt":"乡镇法律工作者接受委托后，代表乡镇法律服务所与委托人订立委托代理合同，并由委托人出具委托书。 委托代理合同应当包括以下主要内容： （一）双方名称，代理人人数和姓名; （二）代理的事项; （三）代理的权限(包括一般代理和特别代理); （四）双方的权利和义务; （五）代理的报酬数额及给付方式; （六）违约责任; （七）合同的有效期限; （八）双方约定的其他事项。 委托人的特别授权包括：接受部分或者全部诉讼请求;变更或者放弃诉讼请求;进行和解、反诉、上诉或者申请撤回上诉。 委托书主要写明：被委托人的单位和姓名，委托代理的事项及代理权限。委托书一式三份，正本一份提交受诉法院，副本两份分别由委托人和乡镇法律服务所保存。"},{"i":27,"n":"第二十七条","txt":"代理人凭委托书和乡镇法律工作者证，经人民法院同意，查阅本案有关材料。阅卷应做好记录，掌握当事人起诉、反诉或者答辩的有关事实和理由，分析、判断证据是否合法、确实、充分。"},{"i":28,"n":"第二十八条","txt":"代理人持乡镇法律服务所证明和乡镇法律工作者证，向有关单位和个人进行调查取证。调查一般应由两人进行，并制作笔录。调查笔录经被调查人核对无误后，由调查人、记录人、被调查人签字或者盖章。"},{"i":29,"n":"第二十九条","txt":"代理人在开庭审理前，应当在分析、判断案情和证据的基础上，拟定代理方案，并与委托人协商交换意见。"},{"i":30,"n":"第三十条","txt":"委托人除特殊原因外，应当与代理人共同出庭;代理离婚案件，必须有委托人共同出庭。"},{"i":31,"n":"第三十一条","txt":"在法庭审理过程中，代理人应当遵守法庭规则，尊重审判人员，态度谦虚严肃，发言文明通俗，说理透彻有据，请求合法合理。"},{"i":32,"n":"第三十二条","txt":"在法庭调查阶段，经法庭允许，代理人就本案的疑点和关键事实，向证人、鉴定人和勘验人发问，核实案情和证据;必要时可向法庭申请新的证人到庭，申请重新鉴定、勘验或提交新的证据。"},{"i":33,"n":"第三十三条","txt":"在法庭辩论阶段，代理人应当依据事实和证据，提出正确适用法律、维护委托人合法权益的意见，反驳对方当事人的错误主张。"},{"i":34,"n":"第三十四条","txt":"法庭对案件进行调解，其调解方案合法合理的，代理人应当予以配合，说服委托人接受。"},{"i":35,"n":"第三十五条","txt":"代理民事、经济、行政案件一审诉讼，人民法院的裁决合法合理的，应当说服委托人服判并自觉执行;认为裁决在认定事实、适用法律方面有不当之处的，或者严重违反审判程序的，应当向委托人详细说明，委托人决定上诉并继续委托代理的，应当接受委托，为其上诉提供法律帮助。"},{"i":36,"n":"第三十六条","txt":"代理民事、经济、行政案件二审诉讼，人民法院的裁决合法合理的，应当说服委托人服判并自觉执行;认为裁决不当的，应当告知并协助委托人按照审判监督程序提出申诉。"},{"i":37,"n":"第三十七条","txt":"乡镇法律工作者受乡镇法律服务所指派，可以接受非诉讼法律事务当事人的委托，为当事人提供法律帮助，协助当事人办理有关法律事务。"},{"i":38,"n":"第三十八条","txt":"乡镇法律工作者接受当事人委托，代理下列非诉讼法律事务： （一）无争议的民事、经济和行政法律事务; （二）有争议的，但依法可以经非诉讼程序解决的法律事务; （三）不服行政裁决要求申请行政复议的法律事务。"},{"i":39,"n":"第三十九条","txt":"乡镇法律工作者代理非诉讼法律事务，在当事人授权委托的权限内行使职务;对法律、法规明确规定须经诉讼程序解决或者其他法定程序办理的法律事务，不得接受委托以非诉讼方式办理。"},{"i":40,"n":"第四十条","txt":"乡镇法律工作者接受委托后，应当代表乡镇法律服务所与委托人订立委托代理合同，并由委托人出具委托书。委托代理合同和委托书的格式参照本细则第二十六条的规定，由双方协商订立。 受托代理简易非诉讼法律事务的，也可由双方协商采用其他方式建立委托代理关系。"},{"i":41,"n":"第四十一条","txt":"乡镇法律工作者代理非诉讼法律事务，除采用解答法律询问、代写法律事务文书等一般服务方式外，还可以根据当事人的需求和授权以及承办事项的具体情况，分别采用下列条款规定的服务方式办理。"},{"i":42,"n":"第四十二条","txt":"乡镇法律服务所办理法律事务，可以根据掌握的事实和材料，依据法律、法规进行阐述和论证，指出解决争议的途径和办法，出具法律意见书。"},{"i":43,"n":"第四十三条","txt":"乡镇法律服务所协助审查合同、协议、章程等法律事务文书，应当审查合同主体资格是否合法，合同双方当事人的意思表示是否真实，合同内容是否符合法律规定，合同形式、条款是否完备，合同双方当事人是否具有履约能力，合同可能带来的经济效益和法律后果，并向委托人提出完善合同的意见或者终止订立合同的建议。"},{"i":44,"n":"第四十四条","txt":"乡镇法律服务所代理参与协商和谈判，应当支持委托人提出的合理要求，说服委托人接受对方当事人的合理意见，协助订立有关设立、变更、终止民事、经济等法律关系的法律事务文书，必要时受托代办公证。 代理参与解决涉及债权债务等争议法律事务的协商和谈判，协商成功的，应当及时协助订立书面和解协议，并尽可能即时清结;不能即时清结的，应当在协议中订明清结的具体方法和期限;协商无效的，应当告知或者受托协助委托人提交有关机关调解、仲裁或者向人民法院提起诉讼。 对另一方当事人距离较远而又不是急需办理的非诉讼法律事务，可以采用发函协商的方式办理。"},{"i":45,"n":"第四十五条","txt":"乡镇法律服务所代理参与调解、仲裁活动，应当运用事实和证据材料，支持委托人提出的合理要求，促成与对方当事人在协商一致的基础上达成调解协议;协商、调解无效时，应当说服委托人接受合法合理的仲裁决定。 调解协议达成后发现确有不当的，应当告知并协助委托人在调解书送达前向有关机关和对方当事人声明翻悔;委托人对仲裁不服的，可以受托代理在规定期限内向人民法院起诉;对方当事人期满不起诉又不执行的，可以受托代理申请人民法院强制执行。"},{"i":46,"n":"第四十六条","txt":"乡镇法律服务所代理申请行政复议，应当就有关行政行为及裁决认定事实是否清楚、定性是否准确、处理是否得当，依法提出代理意见，供受理机关重新复查、审定时参考，支持和维护委托人的合理要求与合法权益。"},{"i":47,"n":"第四十七条","txt":"乡镇法律服务所代理工商企业登记、联营、合作、租赁、承包、税务、信贷、保险、担保、鉴证、公民遗产继承、分家析产、赠与等单项经济、民事法律事务，应当协助委托人实现依法办事，依法经营，维护委托人的合法权益。"},{"i":48,"n":"第四十八条","txt":"乡镇法律服务所以调解人的身份主持有关经济、民事纠纷的调解，按照本细则第五章的规定办理。"},{"i":49,"n":"第四十九条","txt":"乡镇法律工作者受乡镇法律服务所的指派，接受纠纷当事人的申请，运用说服疏导的方式，主持对纠纷进行非诉讼调解，应当促使双方自愿协商，达成协议，解决纠纷，维护双方当事人的合法权益，维护基层正常的生产、生活和社会秩序。"},{"i":50,"n":"第五十条","txt":"乡镇法律服务所受理调解下列纠纷： （一）乡镇企业及其他集体、私营经济组织在生产、经营和管理过程中发生的各种经济纠纷和劳动争议纠纷; （二）承包经营户、个体工商户、个人合伙组织及农村村民在生产和经营过程中发生的各种涉及经济、财产权益的生产经营性纠纷; （三）农村公民之间发生的涉及遗产继承、分家析产、赡养扶养抚育、债权债务、民间赠与、侵权索赔等具有财产权益性质的民事纠纷; 法律、法规和规章规定必须由专门机关管辖处理的纠纷，人民法院、公安机关及其他部门已经受理或者解决的纠纷，乡镇法律服务所不得受理调解。"},{"i":51,"n":"第五十一条","txt":"乡镇法律工作者必须在查明事实、分清是非的基础上，依据法律、法规和政策进行调解;必须在双方当事人自愿、平等的基础上进行调解;不得因未经调解或者调解不成而阻止当事人向其他组织、机关投诉或者向人民法院起诉。"},{"i":52,"n":"第五十二条","txt":"乡镇法律工作者在主持调解中，有权决定调解的开始、中止、延期和终止，有权调查有关证据材料，批评、制止当事人干扰调解秩序的行为，有权拒绝非法干预。"},{"i":53,"n":"第五十三条","txt":"参加调解活动的各方当事人、代理人，有不受压制强迫、真实表达意愿、提出合理要求的权利，有提供、要求鉴定证据的权利，有进行答辩和反驳的权利，有申请中止、延期和终止调解的权利;同时必须履行如实提供纠纷事实和证据、服从调解主持人的指挥、遵守调解活动秩序的义务。"},{"i":54,"n":"第五十四条","txt":"乡镇法律工作者主持调解的纠纷，自当事人书面或者口头申请调解之日起，一般应当在两个月内调结，最长不得超过三个月。到期未调结的，视为调解不成。"},{"i":55,"n":"第五十五条","txt":"乡镇法律服务所受理纠纷，必须由纠纷一方当事人提出书面或者口头申请，并征得另一方当事人的同意。 调解申请应当符合下列条件： （一）申请调解的纠纷属于乡镇法律服务所调解的范围; （二）有明确的调解申请人和被申请人; （三）有明确的调解请求和纠纷的事实、证据材料。"},{"i":56,"n":"第五十六条","txt":"乡镇法律服务所接到调解申请后，经审查符合条件的，应当及时受理，指派调解主持人，并填写受理纠纷登记表;对于有可能激化或者严重影响正常生产、经营秩序的纠纷，应当优先受理;对于涉及面广或者跨地区、跨单位的疑难纠纷，应当积极争取有关部门、单位的配合与协作，或者商请有关部门、单位联合调解。 对于不符合受理条件的纠纷，应当告知当事人按照法律规定请求有关机关处理或者向人民法院起诉;随时有激化可能的，应当在采取必要的缓解疏导措施后，交由有关机关处理。"},{"i":57,"n":"第五十七条","txt":"调解主持人在调解开始前，应当进行下列准备工作： （一）分别向各方当事人询问纠纷的事实和情节，审查有关证据材料，了解双方的要求及其理由，并制作询问笔录; （二）持乡镇法律服务所证明和乡镇法律工作者证进行必要的调查，向有关单位和个人查询、索取纠纷情况和证据，或者进行实地勘验，并制作调查、勘验笔录;必要时还可以请有关部门进行损伤(害)鉴定，出具鉴定结论; （三）在分析、判断纠纷事实和证据材料的基础上，拟定调解方案，确定调解的时间、地点和方式，通知当事人。"},{"i":58,"n":"第五十八条","txt":"调解纠纷可以召集双方当事人到乡镇法律服务所进行，或者到纠纷发生地进行，也可以在双方当事人同意的其他地点进行。 调解主持人根据实际需要，可以邀请当事人的亲属及有关单位和个人协助调解。"},{"i":59,"n":"第五十九条","txt":"主持调解纠纷一般按照下列步骤进行： （一）向双方当事人说明乡镇法律服务所调解纠纷的性质、原则和效力，告知在调解活动中享有的权利和承担的义务; （二）由双方当事人陈述纠纷事实，提出证据，说明各自对纠纷责任的看法和解决纠纷的具体意见; （三）引导双方当事人就纠纷事实和责任的认定交换意见; （四）依据有关法律、法规和政策规定，对双方当事人进行说服、教育和疏导，促使双方在分清责任、协商一致的基础上，自行达成调解协议，或者在调解主持人提出的调解意见基础上，经协商同意达成调解协议; （五）调解达成协议的，除简易纠纷和即时清结的纠纷外，应当制作调解协议书。 一次调解不成的，可以中止调解，延期继续进行。"},{"i":60,"n":"第六十条","txt":"调解协议书应当包括下列内容： （一）双方当事人的自然情况，纠纷受理单位和调解主持人的姓名; （二）经调解认定的纠纷基本事实和各方应承担的责任; （三）协议的具体内容。即双方当事人各自应当享有的权利和承担的义务，以及履行的具体期限、方式和违约责任; （四）调解协议书的生效期限; （五）由双方当事人和调解主持人签名盖章，并加盖乡镇法律服务所印章;有协助调解人的也应当签名盖章;注明制作日期。 调解协议书一式三份，分别由双方当事人和乡镇法律服务所收存。"},{"i":61,"n":"第六十一条","txt":"乡镇法律服务所在调解协议履行期限内发现调解协议不当的，应当在征得双方当事人同意后，变更协议内容或者撤销原协议，主持协商订立新的调解协议。"},{"i":62,"n":"第六十二条","txt":"乡镇法律工作者主持下达成的调解协议，双方当事人应当自觉全面履行。 当事人一方或者双方无故不履行或者拖延履行的，应当进行说服教育、督促履行;当事人一方或双方确有困难或者因意外原因不能按期履行的，应当促使双方协商一致，缓期履行;当事人一方无故拒不履行并经说服无效的，可以告知、协助或者受托代理另一方当事人向人民法院起诉。"},{"i":63,"n":"第六十三条","txt":"当事人拒绝调解或者调解不成的，应当依据有关法律、法规，根据纠纷情况，告知当事人分别通过下列途径处理： （一）依法向有关机关提请仲裁; （二）依法向人民法院提起诉讼; （三）属于疑难民间纠纷的，提请乡镇人民政府处理。"},{"i":64,"n":"第六十四条","txt":"乡镇法律工作者对机关、法人和公民提出的有关法律事务方面的各种询问，应当做出解释和回答，并提供解决问题的具体途径、方法和依据，为询问人提供法律咨询服务，并通过这项业务进行法制宣传教育。"},{"i":65,"n":"第六十五条","txt":"乡镇法律工作者解答法律询问的范围，主要是有关民事、刑事、经济、行政实体法和程序法方面的问题，以及办理各项具体法律事务的方法和途径;对于有关政策问题的询问，可以依据所了解的有关政策规定进行解答。"},{"i":66,"n":"第六十六条","txt":"乡镇法律工作者解答法律询问，应当做到弄清问题、依法解答、查有实据、客观准确、耐心细致、通俗易懂。"},{"i":67,"n":"第六十七条","txt":"乡镇法律工作者针对询问的不同方式，可以分别予以口头解答或者书面解答。 乡镇法律工作者可以利用广播、板报等各种形式，定期或者不定期到机关、企业、田间、农贸集市、学校上门服务，开展解答法律询问活动。"},{"i":68,"n":"第六十八条","txt":"口头解答法律询问，应当按照下列步骤进行： （一）接待来访的询问人，问清并登记询问人的基本情况和询问事项; （二）听取询问人对问题和事实的陈述，查看询问人提供的有关证据和材料，进行必要的提问，弄清有关的事实情节和主要问题，并认真进行综合分析，酝酿解答方案; （三）依据有关法律、法规和政策规定，就询问事项做出有针对性的、准确无误的解释和回答，提供解决问题的具体方法及其依据;对于不能立即解答的疑难询问，应当在查阅有关规定或者提交乡镇法律服务所集体研究后，另约时间解答; （四）做好询问和解答笔录，解答结束后按规定项目填写法律咨询登记表。"},{"i":69,"n":"第六十九条","txt":"书面解答法律询问，应当在认真阅读和分析询问人来信所提问题和所叙述事实的基础上，对叙述事实清楚的，可以依法做出明确的解答;对叙述含糊不清的，一般只做原则性的解答。"},{"i":70,"n":"第七十条","txt":"乡镇法律工作者解答法律询问，应当注意下列事项： （一）对于涉及正在处理过程中的具体纠纷、具体案件中应判刑期和应赔偿数额等问题的询问，一般不应做出具体回答，不应就具体期限和数额发表意见; （二）对于现行法律、法规和政策都没有明文规定难以回答的询问，或者不属解答范围的询问，应当向询问人做出说明，或者告知询问人向有关部门进行咨询; （三）不得公开引用内部规定; （四）对于涉及纠纷事务的询问，如询问人情绪异常，可能作出不理智行为的，应尽可能采取必要的缓解和防范措施。"},{"i":71,"n":"第七十一条","txt":"乡镇法律工作者可以接受公民和法人的委托，代表委托人的合法意志，以委托人的名义，根据事实和法律，代为书写各种法律事务文书，为委托人办理各项法律事务提供帮助。"},{"i":72,"n":"第七十二条","txt":"乡镇法律工作者可以代写下列法律事务文书： （一）起诉书、控告书、答辩书、上诉书、申诉书、执行申请书等民事、经济、刑事、行政诉讼法律事务文书; （二）合同、协议、章程、遗嘱、申请书、赠与书、声明书等民事、经济、行政非诉讼法律事务文书; （三）其他具有法律意义的文书。"},{"i":73,"n":"第七十三条","txt":"代写法律事务文书，对请求合法、正当的，应当予以支持;对请求非法、不当的，应当劝说委托人放弃请求，或者拒绝予以代书;对不涉及法律事务的代书请求，一般不予受理。"},{"i":74,"n":"第七十四条","txt":"代写法律事务文书，应当做到目的观点明确，如实反映委托人提供的客观事实和证据材料，准确引用法律条文、语言规范精炼、逻辑严谨，通俗易懂;有法定标准格式的应当严格按照规定书写。"},{"i":75,"n":"第七十五条","txt":"代写法律事务文书，应当按照下列步骤进行： （一）接受来访人的代书委托，问清并登记委托人的基本情况和代书项目; （二）听取委托人对代书内容和有关事实的陈述，查看委托人提供的有关证据和材料，进行必要的提问，然后对有关事实、证据进行分析判断，酝酿代书方案; （三）代书请求合法、正当，事实清楚和证据齐全的，根据代书的繁简程度，可以当场代书，也可以在双方约定的期限内完成代书; （四）代书完成后，征求委托人的意见进行修改、定稿，正式打印或者誊写。 代写的法律事务文书，应当根据需要复制若干份，由委托人签字盖章，并加盖乡镇法律服务所代书专用章和代书承办人印章。乡镇法律服务所留存一份，其余交给委托人； （五）代写法律事务文书完结后，应当按照规定项目填写代书业务登记表。"},{"i":76,"n":"第七十六条","txt":"乡镇法律服务所可以在本地区公证处指导下，协助办理有关公证事项，为本乡镇的公民、法人和其他组织申办公证提供帮助。"},{"i":77,"n":"第七十七条","txt":"乡镇法律服务所可以协助办理下列与公证有关的事项： （一）协助开展证前服务; （二）协助办理公证申请; （三）协助办理公证过程中的有关事项; （四）协助开展证后服务。"},{"i":78,"n":"第七十八条","txt":"乡镇法律服务所协助办理公证，必须遵守有关公证的法律、法规和政策规定，严禁以乡镇法律服务所名义为当事人出具公证证明。"},{"i":79,"n":"第七十九条","txt":"乡镇法律服务所应当与本地区公证处协商建立公证协作和联系制度，可以在乡镇法律服务所内设置公证联络员。"},{"i":80,"n":"第八十条","txt":"乡镇法律工作者可以协助开展下列证前服务： （一）面向基层，采取多种形式，广泛深入地宣传公证制度的重要作用以及申请办理公证的有关知识; （二）协助收集、传递证源信息，做好介绍、联络公证工作; （三）解答公证法律询问，代写公证申请书以及与申办公证有关的其他法律事务文书; （四）授权交办的其他证前服务工作。"},{"i":81,"n":"第八十一条","txt":"乡镇法律工作者协助办理公证申请，应当按照下列步骤和方法进行： （一）接到当事人的口头或者书面公证申请后，应当协助对申办事项是否属于公证业务范围和由本地区公证处管辖，申请人的身份是否符合有关公证法规，申办的手续、有关文书和证明材料是否完备等问题进行初步审查； （二）经初步审查，对符合规定的公证申请应当移送公证处正式受理，对不符合规定的应当向申请人做出说明并指出解决办法，对申办手续和有关文书及材料不完备的应当告知并协助申请人补齐，对申办事项明显违背法律、法规和社会公共利益的应当拒绝协助办理； （三）对不符合规定的申请或违背法律、法规和社会公共利益的申请，决定不予协助时，应明确告知申请人有权申请公证处重新审查。"},{"i":82,"n":"第八十二条","txt":"乡镇法律工作者根据公证处的具体授权委托，可以协助办理公证过程中的下列有关事项： （一）协助审查申请公证的事实、文书及有关证明材料是否真实、合法，当事人的身份和行使权利、履行义务的能力; （二）公证处认为申办事项的证明材料不完备或者有疑义的，可以协助通知当事人按要求进行补充，或者协助向有关单位和个人调查、索取有关材料； （三）对规定必须由当事人亲自申办的公证事项，当事人确有困难的，可以协助公证员到当事人所在地办理； （四）协助向当事人送达公证文书；对公证处拒绝公证的，应当协助向当事人说明拒办的理由和对拒办不服的申诉程序； （五）协助当事人向公证处交纳公证费。"},{"i":83,"n":"第八十三条","txt":"乡镇法律工作者可以协助开展下列证后服务： （一）协助进行公证事务的证后回访，重点回访和检查经公证的合同、协议等民事、经济法律事务文书的履行情况； （二）对经协助办理的公证事务在证后发生纠纷的，根据当事人的申请，协助或者独自进行调解； （三）其他证后服务工作。"},{"i":84,"n":"第八十四条","txt":"乡镇法律工作者完成协助办理公证事务后，应当按规定项目填写协助办理公证登记表。"},{"i":85,"n":"第八十五条","txt":"乡镇法律服务所可以接受当事人的委托，代理申办公证。代理申办公证，应当依照本细则第四章规定的程序办理。但法律规定不能委托代办的公证事务，不得接受委托代为申办。"},{"i":86,"n":"第八十六条","txt":"本细则规定的各项法律服务业务专用文书格式，由司法部统一制定。"},{"i":87,"n":"第八十七条","txt":"城市街道法律服务所办理各项法律服务业务，参照本细则执行。"},{"i":88,"n":"第八十八条","txt":"本细则由司法部负责解释。"},{"i":89,"n":"第八十九条","txt":"本细则自发布之日起试行。"}],"gongzhengyuanzhiyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对公证员的任职管理和执业监督，规范公证员的执业行为，根据《中华人民共和国公证法》(以下简称《公证法》)和有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"公证员是符合《公证法》规定的条件，经法定任职程序，取得公证员执业证书，在公证机构从事公证业务的执业人员。 公证员的配备数量，根据公证机构的设置情况和公证业务的需要确定。公证员配备方案，由省、自治区、直辖市司法行政机关编制和核定，报司法部备案。"},{"i":3,"n":"第三条","txt":"公证员依法执业，受法律保护，任何单位和个人不得非法干预。 公证员有权获得劳动报酬，享受保险和福利待遇；有权提出辞职、申诉或者控告；非因法定事由和非经法定程序，不被免职或者处罚。"},{"i":4,"n":"第四条","txt":"公证员应当遵纪守法，恪守职业道德和执业纪律，依法履行公证职责，保守执业秘密。 公证员应当加入地方和全国的公证协会。"},{"i":5,"n":"第五条","txt":"司法行政机关依照《公证法》和有关法律、法规、规章，对公证员进行监督、指导。"},{"i":6,"n":"第六条","txt":"公证协会是公证业的自律性组织。公证协会依照《公证法》和章程，对公证员的执业活动进行监督。"},{"i":7,"n":"第七条","txt":"担任公证员，应当具备下列条件： (一)具有中华人民共和国国籍； (二)年龄二十五周岁以上六十五周岁以下； (三)公道正派，遵纪守法，品行良好； (四)通过国家司法考试； (五)在公证机构实习二年以上或者具有三年以上其他法律职业经历并在公证机构实习一年以上，经考核合格。"},{"i":8,"n":"第八条","txt":"符合本办法第七条第(一)项、第(二)项、第(三)项规定，并具备下列条件之一，已经离开原工作岗位的，经考核合格，可以担任公证员： (一)从事法学教学、研究工作，具有高级职称的人员； (二)具有本科以上学历，从事审判、检察、法制工作、法律服务满十年的公务员、律师。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，不得担任公证员： (一)无民事行为能力或者限制民事行为能力的； (二)因故意犯罪或者职务过失犯罪受过刑事处罚的； (三)被开除公职的； (四)被吊销执业证书的。"},{"i":10,"n":"第十条","txt":"符合本办法第七条规定条件的人员，由本人提出申请，经需要选配公证员的公证机构推荐，由所在地司法行政机关出具审查意见，逐级报请省、自治区、直辖市司法行政机关审核。 报请审核，应当提交下列材料： (一)担任公证员申请书； (二)公证机构推荐书； (三)申请人的居民身份证复印件和个人简历，具有三年以上其他法律职业经历的，应当同时提交相应的经历证明； (四)申请人的法律职业资格证书复印件； (五)公证机构出具的申请人实习鉴定和所在地司法行政机关出具的实习考核合格意见； (六)所在地司法行政机关对申请人的审查意见； (七)其他需要提交的材料。"},{"i":11,"n":"第十一条","txt":"符合本办法第八条规定条件的人员，由本人提出申请，经需要选配公证员的公证机构推荐，由所在地司法行政机关出具考核意见，逐级报请省、自治区、直辖市司法行政机关审核。 报请审核，应当提交下列材料： (一)担任公证员申请书； (二)公证机构推荐书； (三)申请人的居民身份证复印件和个人简历； (四)从事法学教学、研究工作并具有高级职称的证明，或者具有本科以上学历的证明和从事审判、检察、法制工作、法律服务满十年的经历及职务证明； (五)申请人已经离开原工作岗位的证明； (六)所在地司法行政机关对申请人的考核意见； (七)其他需要提交的材料。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市司法行政机关应当自收到报审材料之日起二十日内完成审核。对符合规定条件和公证员配备方案的，作出同意申请人担任公证员的审核意见，填制公证员任职报审表，报请司法部任命；对不符合规定条件或者公证员配备方案的，作出不同意申请人担任公证员的决定，并书面通知申请人和所在地司法行政机关。"},{"i":13,"n":"第十三条","txt":"司法部应当自收到省、自治区、直辖市司法行政机关报请任命公证员的材料之日起二十日内，制作并下达公证员任命决定。 司法部认为报请任命材料有疑义或者收到相关投诉、举报的，可以要求报请任命机关重新审核。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市司法行政机关应当自收到司法部下达的公证员任命决定之日起十日内，向申请人颁发公证员执业证书，并书面通知其所在地司法行政机关。"},{"i":15,"n":"第十五条","txt":"公证员变更执业机构，应当经所在公证机构同意和拟任用该公证员的公证机构推荐，报所在地司法行政机关同意后，报省、自治区、直辖市司法行政机关办理变更核准手续。 公证员跨省、自治区、直辖市变更执业机构的，经所在的省、自治区、直辖市司法行政机关核准后，由拟任用该公证员的公证机构所在的省、自治区、直辖市司法行政机关办理变更核准手续。"},{"i":16,"n":"第十六条","txt":"公证员有下列情形之一的，由所在地司法行政机关自确定该情形发生之日起三十日内，报告省、自治区、直辖市司法行政机关，由其提请司法部予以免职： (一)丧失中华人民共和国国籍的； (二)年满六十五周岁或者因健康原因不能继续履行职务的； (三)自愿辞去公证员职务的。 被吊销公证员执业证书的，由省、自治区、直辖市司法行政机关直接提请司法部予以免职。 提请免职，应当提交公证员免职报审表和符合法定免职事由的相关证明材料。司法部应当自收到提请免职材料之日起二十日内，制作并下达公证员免职决定。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市司法行政机关对报请司法部予以任命、免职或者经核准变更执业机构的公证员，应当在收到任免决定或者作出准予变更决定后二十日内，在省级报刊上予以公告。 司法部对决定予以任命或者免职的公证员，应当定期在全国性报刊上予以公告，并定期编制全国公证员名录。"},{"i":18,"n":"第十八条","txt":"公证员执业证书是公证员履行法定任职程序后在公证机构从事公证执业活动的有效证件。 公证员执业证书由司法部统一制作。证书编号办法由司法部制定。"},{"i":19,"n":"第十九条","txt":"公证员执业证书由公证员本人持有和使用，不得涂改、抵押、出借或者转让。 公证员执业证书损毁或者遗失的，由本人提出申请，所在公证机构予以证明，提请所在地司法行政机关报省、自治区、直辖市司法行政机关申请换发或者补发。执业证书遗失的，由所在公证机构在省级报刊上声明作废。"},{"i":20,"n":"第二十条","txt":"公证员变更执业机构的，经省、自治区、直辖市司法行政机关核准，予以换发公证员执业证书。 公证员受到停止执业处罚的，停止执业期间，应当将其公证员执业证书缴存所在地司法行政机关。 公证员受到吊销公证员执业证书处罚或者因其他法定事由予以免职的，应当收缴其公证员执业证书，由省、自治区、直辖市司法行政机关予以注销。"},{"i":21,"n":"第二十一条","txt":"司法行政机关应当依法建立健全行政监督管理制度，公证协会应当依据章程建立健全行业自律制度，加强对公证员执业活动的监督，依法维护公证员的执业权利。"},{"i":22,"n":"第二十二条","txt":"公证机构应当按照规定建立、完善各项内部管理制度，对公证员的执业行为进行监督，建立公证员执业过错责任追究制度，建立公证员执业年度考核制度。 公证机构应当为公证员依法执业提供便利和条件，保障其在任职期间依法享有的合法权益。"},{"i":23,"n":"第二十三条","txt":"公证员应当依法履行公证职责，不得有下列行为： (一)同时在两个以上公证机构执业； (二)从事有报酬的其他职业； (三)为本人及近亲属办理公证或者办理与本人及近亲属有利害关系的公证； (四)私自出具公证书； (五)为不真实、不合法的事项出具公证书； (六)侵占、挪用公证费或者侵占、盗窃公证专用物品； (七)毁损、篡改公证文书或者公证档案； (八)泄露在执业活动中知悉的国家秘密、商业秘密或者个人隐私； (九)法律、法规和司法部规定禁止的其他行为。"},{"i":24,"n":"第二十四条","txt":"公证机构应当在每年的第一个月份对所属公证员上一年度办理公证业务的情况和遵守职业道德、执业纪律的情况进行年度考核。考核结果，应当书面告知公证员，并报所在地司法行政机关备案。 公证机构的负责人履行管理职责的情况，由所在地司法行政机关进行考核。考核结果，应当书面告知公证机构的负责人，并报上一级司法行政机关备案。 经年度考核，对公证员在执业中存在的突出问题，公证机构应当责令其改正；对公证机构的负责人在管理中存在的突出问题，所在地司法行政机关应当责令其改正。"},{"i":25,"n":"第二十五条","txt":"公证员和公证机构的负责人被投诉和举报、执业中有不良记录或者经年度考核发现有突出问题的，所在地司法行政机关应当对其进行重点监督、指导。 对年度考核发现有突出问题的公证员和公证机构的负责人，由所在地或者设区的市司法行政机关组织专门的学习培训。"},{"i":26,"n":"第二十六条","txt":"司法行政机关实施监督检查，可以对公证员办理公证业务的情况进行检查，要求公证员及其所在公证机构说明有关情况，调阅相关材料和公证档案，向相关单位和人员调查、核实有关情况。 公证员及其所在公证机构不得拒绝司法行政机关依法实施的监督检查，不得谎报、隐匿、伪造、销毁相关证据材料。"},{"i":27,"n":"第二十七条","txt":"公证员应当接受司法行政机关和公证协会组织开展的职业培训。公证员每年参加职业培训的时间不得少于四十学时。 司法行政机关制定开展公证员职业培训的规划和方案，公证协会按年度制定具体实施计划，负责组织实施。 公证机构应当为公证员参加职业培训提供必要的条件和保障。"},{"i":28,"n":"第二十八条","txt":"公证员执业所在地司法行政机关应当建立公证员执业档案，将公证员任职审核任命情况、年度考核结果、监督检查掌握的情况以及受奖惩的情况记入执业档案。 公证员跨地区或者跨省、自治区、直辖市变更执业机构的，原执业所在地司法行政机关应当向变更后的执业所在地司法行政机关移交该公证员的执业档案。"},{"i":29,"n":"第二十九条","txt":"公证员有《公证法》第四十一条、第四十二条所列行为之一的，由省、自治区、直辖市或者设区的市司法行政机关依据《公证法》的规定，予以处罚。 公证员有依法应予吊销公证员执业证书情形的，由所在地司法行政机关逐级报请省、自治区、直辖市司法行政机关决定。"},{"i":30,"n":"第三十条","txt":"司法行政机关对公证员实施行政处罚，应当根据有关法律、法规和司法部有关行政处罚程序的规定进行。 司法行政机关查处公证员的违法行为，可以委托公证协会对公证员的违法行为进行调查、核实。"},{"i":31,"n":"第三十一条","txt":"司法行政机关在对公证员作出行政处罚决定之前，应当告知查明的违法行为事实、处罚的理由及依据，并告知其依法享有的权利。口头告知的，应当制作笔录。公证员有权进行陈述和申辩，有权依法申请听证。 公证员对行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":32,"n":"第三十二条","txt":"公证协会依据章程和有关行业规范，对公证员违反职业道德和执业纪律的行为，视其情节轻重，给予相应的行业处分。 公证协会在查处公证员违反职业道德和执业纪律行为的过程中，发现有依据《公证法》的规定应当给予行政处罚情形的，应当提交有管辖权的司法行政机关处理。"},{"i":33,"n":"第三十三条","txt":"公证员因过错给当事人、公证事项的利害关系人造成损失的，公证机构依法赔偿后，可以向有故意或者重大过失的公证员追偿。"},{"i":34,"n":"第三十四条","txt":"以欺骗、贿赂等不正当手段取得公证员任命和公证员执业证书的，经查证属实，由省、自治区、直辖市司法行政机关提请司法部撤销原任命决定，并收缴、注销其公证员执业证书。"},{"i":35,"n":"第三十五条","txt":"司法行政机关及其工作人员在公证员职务任免、公证员执业证书管理、对公证员执业活动实施监督检查的过程中，有滥用职权、玩忽职守、徇私舞弊、干预公证员依法执业行为的，应当依法追究责任人员的行政责任；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"公证员配备方案，应当遵照司法部有关公证业的总体发展规划和要求，根据当地公证机构设置、布局的安排、公证执业区域划分的安排、公证业务总体需求和地区分布情况，以及当地经济社会发展和人口状况，结合公证员年均办证数量和办证能力，予以编制和核定，并可以根据当地情况和公证需求的变化进行调整。"},{"i":37,"n":"第三十七条","txt":"公证员执业年度考核的具体办法，由省、自治区、直辖市司法行政机关制定。考核办法应当包括考核工作的原则、考核的内容、考核的等次和标准、考核的程序和时间安排。"},{"i":38,"n":"第三十八条","txt":"《公证法》和本办法施行前已担任公证员的，其公证员职务继续有效，适用《公证法》和本办法进行管理。"},{"i":39,"n":"第三十九条","txt":"本办法所称公证员执业所在地司法行政机关，是指负责组建该公证员所属的公证机构，并承担对该公证机构及其公证员实施日常监督、指导职能的司法行政机关。"},{"i":40,"n":"第四十条","txt":"本办法由司法部解释。"},{"i":41,"n":"第四十一条","txt":"本办法自发布之日起施行。司法部1995年6月2日发布的《中华人民共和国公证员注册管理办法》(司法部令第39号)同时废止。"}],"gongzhengzhiyehuodongtousuchulibanfa":[{"i":1,"n":"第一条","txt":"为了规范公证执业活动投诉处理工作，加强公证执业活动监督，维护投诉人的合法权益，根据《中华人民共和国公证法》等规定，结合公证管理工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"司法行政机关开展公证执业活动投诉处理工作，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称投诉人，是指认为公证机构或者公证员违法违规执业侵犯其合法权益，向司法行政机关投诉的自然人、法人或者其他组织。 本办法所称被投诉人，是指被投诉的公证机构或者公证员。"},{"i":4,"n":"第四条","txt":"司法行政机关开展公证执业活动投诉处理工作，应当遵循属地管理、依法公正、及时便民的原则。"},{"i":5,"n":"第五条","txt":"司法部负责监督、指导全国公证执业活动投诉处理工作。省、自治区、直辖市司法行政机关负责监督、指导本行政区域内公证执业活动投诉处理工作。 公证机构所在地司法行政机关或者公证员执业所在地司法行政机关（以下称投诉处理机关），具体负责投诉处理工作。"},{"i":6,"n":"第六条","txt":"公证协会应当根据司法行政机关要求，协助和配合开展公证执业活动投诉处理工作。"},{"i":7,"n":"第七条","txt":"司法行政机关发现公证执业活动投诉涉及民事纠纷的，可以引导投诉人和被投诉人在自愿、平等的基础上，依法通过调解等方式解决。"},{"i":8,"n":"第八条","txt":"自然人、法人或者其他组织认为公证机构或者公证员在执业活动中有下列违法违规行为侵犯其合法权益的，可以向投诉处理机关投诉： （一）为不真实、不合法的事项出具公证书； （二）私自出具公证书； （三）毁损、篡改公证文书或者公证档案； （四）违反规定的收费标准收取公证费； （五）侵占、挪用公证费或者侵占、盗窃公证专用物品； （六）以诋毁其他公证机构、公证员或者支付回扣、佣金等不正当手段争揽公证业务； （七）同时在二个以上公证机构执业； （八）从事有报酬的其他职业； （九）为本人及近亲属办理公证或者办理与本人及近亲属有利害关系的公证； （十）泄露在执业活动中知悉的国家秘密、商业秘密或者个人隐私； （十一）其他违反法律法规以及司法部规定的行为。"},{"i":9,"n":"第九条","txt":"投诉处理机关应当向社会公布公证执业活动投诉电话、传真、电子邮箱、通讯地址以及投诉事项范围、投诉处理程序等信息，并指定专人负责投诉接待和处理工作。"},{"i":10,"n":"第十条","txt":"投诉人应当自知道或者应当知道被投诉人执业活动侵犯其合法权益之日起三年内，向司法行政机关投诉。法律另有规定的除外。"},{"i":11,"n":"第十一条","txt":"投诉人向投诉处理机关提出投诉，一般应当采用书面形式，载明投诉人姓名（名称）、性别、身份证号码（统一社会信用代码）、住址、联系方式，被投诉人的姓名（名称），以及投诉事项、请求、事实、理由，并提交与投诉事项相关的证明材料。 采用书面形式投诉确有困难的，可以现场提出口头投诉，投诉处理机关应当当场记录前款规定的相关信息，并由投诉人签字或者捺印。"},{"i":12,"n":"第十二条","txt":"投诉人应当对其所提供材料内容的真实性负责，不得捏造、歪曲事实，不得诬告、陷害他人。"},{"i":13,"n":"第十三条","txt":"投诉人或者其法定代理人委托他人代理投诉的，代理人应当提供投诉人或者其法定代理人的授权委托书、代理人的联系方式和投诉人、代理人的身份证明。"},{"i":14,"n":"第十四条","txt":"投诉处理机关收到投诉材料后，应当及时登记，并进行审查。 其他司法行政机关收到投诉材料的，应当及时转送投诉处理机关，并书面告知投诉人。"},{"i":15,"n":"第十五条","txt":"投诉人提供的信息不齐全或者无相关证明材料的，投诉处理机关应当在收到投诉材料之日起七个工作日内一次性书面告知投诉人补充。书面告知内容应当包括需要补充的信息或者证明材料和合理的补充期限。 投诉人经告知后无正当理由逾期不补充的，视为投诉人放弃投诉。"},{"i":16,"n":"第十六条","txt":"投诉事项属于本办法第八条规定情形，投诉材料齐全的，投诉处理机关应当受理。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，不予受理： （一）投诉事项已经司法行政机关处理，且没有新的事实和证据的； （二）对人民法院等单位是否采信公证书有异议的； （三）投诉事项不属于本办法第八条规定情形的。"},{"i":18,"n":"第十八条","txt":"投诉处理机关应当自收到投诉材料之日起七个工作日内，作出是否受理的决定，并书面告知投诉人。情况复杂的，可以适当延长作出决定的时间，但延长期限不得超过十五个工作日，并应当将延长的时间和理由书面告知投诉人。 投诉人补充投诉材料所需的时间，不计算在前款规定的期限内。"},{"i":19,"n":"第十九条","txt":"投诉处理机关受理投诉后，应当全面、客观、公正地进行调查。必要时，可以委托下级司法行政机关或者相关公证协会进行调查。 投诉处理机关进行调查，不得妨碍被投诉人开展正常的公证执业活动。"},{"i":20,"n":"第二十条","txt":"在调查过程中，投诉人就同一投诉事项，以不同事实、理由和诉求对被投诉人多次提出投诉的，投诉处理机关可以合并办理。"},{"i":21,"n":"第二十一条","txt":"投诉处理机关进行调查，可以对公证机构进行实地调查，要求被投诉人说明情况、提交有关材料，调阅被投诉人有关业务案卷和档案材料，向有关单位、个人核实情况、收集证据；并可以根据需要，组织专家论证或者听取有关部门的意见、建议。 调查应当由两名以上工作人员进行。必要时,应当制作调查笔录，并由相关人员签字或者盖章；不能或者拒绝签字、盖章的，应当在笔录中注明有关情况。 调查人员应当对被投诉人及有关单位、个人提供的证据和有关材料进行登记并妥善保管；不能保存原件的，应当保存复印件，并由被投诉人或者有关单位、个人在复印件上签名或者盖章。"},{"i":22,"n":"第二十二条","txt":"被投诉人应当配合调查工作，在投诉处理机关要求的期限内如实陈述事实、提供有关材料，不得提供虚假、伪造的材料或者隐匿、毁损、涂改有关证据材料。 被投诉人为公证员的，其所在的公证机构应当配合调查。"},{"i":23,"n":"第二十三条","txt":"投诉处理机关在调查过程中，对于投诉人认为公证书有错误的，应当告知其可以向公证机构提出复查；对于投诉人对公证机构作出撤销或者不予撤销公证书的决定有异议的，应当告知其可以向有关地方公证协会提出公证复查争议投诉。投诉人向公证机构提出复查或者向地方公证协会提出公证复查争议投诉的，投诉处理机关应当中止调查，并书面告知投诉人。 投诉处理机关发现在受理投诉前投诉人已经向公证机构提出复查或者向地方公证协会提出公证复查争议投诉，尚未处理完毕的，应当中止调查，并书面告知投诉人。 公证机构复查或者地方公证协会对复查投诉处理结束后，司法行政机关应当及时恢复调查。"},{"i":24,"n":"第二十四条","txt":"投诉处理机关在调查过程中发现有本办法第十七条规定情形，或者投诉人书面申请撤回投诉的，可以终止投诉处理工作，并将终止决定和理由书面告知投诉人、被投诉人。"},{"i":25,"n":"第二十五条","txt":"投诉处理机关在调查过程中，发现被投诉人的违法违规行为仍处于连续或者继续状态的，应当责令被投诉人立即停止违法违规行为。"},{"i":26,"n":"第二十六条","txt":"公证协会接受委托开展投诉事项的调查工作，发现被投诉人有违反职业道德、执业纪律和行业规范行为的，应当依据行业规范对被投诉人实施行业惩戒。"},{"i":27,"n":"第二十七条","txt":"投诉处理机关应当根据对投诉事项的调查结果，分别作出如下处理： （一）被投诉人具有应当给予行政处罚的违法违规行为的，依法给予行政处罚或者移送有处罚权的司法行政机关依法给予行政处罚； （二）被投诉人违法违规情节轻微，没有造成危害后果，依法可以不予行政处罚的，应当给予批评教育、责令限期整改等处理； （三）投诉事项缺乏事实依据或者查证不实的，对投诉请求不予支持，并向投诉人说明情况。 被投诉人涉嫌违反职业道德、执业纪律和行业规范的，移交有关公证协会调查处理；涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"投诉处理机关受理投诉的，应当自作出投诉受理决定之日起六十日内作出处理决定；情况复杂，不能在规定期限内作出处理的，经本机关负责人批准，可以适当延长办理期限，但延长期限不得超过三十日，并应当将延长的时间和理由书面告知投诉人。 投诉案件因本办法第二十条规定的情形合并办理的，办理期限自受理最后一次投诉的时间开始计算。投诉调查工作因本办法第二十三条规定的情形中止的，中止期间不计入投诉处理期限。"},{"i":29,"n":"第二十九条","txt":"投诉处理机关应当自作出处理决定之日起七个工作日内，将处理决定书面告知投诉人、被投诉人。处理决定应当载明不服处理决定的法律救济途径和期限。"},{"i":30,"n":"第三十条","txt":"对于被投诉人存在违法违规行为并被处罚、处理的，投诉处理机关应当及时将投诉处理决定记入被投诉人的公证执业档案，通报相关公证协会，并依法向社会公开。"},{"i":31,"n":"第三十一条","txt":"投诉处理机关应当对被投诉人履行处罚、处理决定，纠正违法违规行为的情况进行监督、检查，发现问题应当责令其限期整改。"},{"i":32,"n":"第三十二条","txt":"上级司法行政机关应当加强对下级司法行政机关投诉处理工作的监督、指导和检查，发现有违法、不当情形的，应当及时责令改正。下级司法行政机关应当及时上报纠正情况。"},{"i":33,"n":"第三十三条","txt":"司法行政机关应当建立公证执业活动投诉处理工作档案，并按年度将公证执业活动投诉处理工作情况书面报告上一级司法行政机关。 对于涉及重大违法违规行为的投诉处理决定，应当及时报告上一级司法行政机关。"},{"i":34,"n":"第三十四条","txt":"司法行政机关工作人员在投诉处理工作中有滥用职权、玩忽职守或者其他违法违规行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"本办法所称公证机构所在地司法行政机关，是指根据当地公证机构设置方案的规定，负责组建该公证机构，并承担对其实施日常监督、指导职能的司法行政机关。公证员执业所在地司法行政机关，是指负责组建该公证员所属的公证机构，并承担对该公证机构及其公证员实施日常监督、指导职能的司法行政机关。"},{"i":36,"n":"第三十六条","txt":"本办法由司法部解释。"},{"i":37,"n":"第三十七条","txt":"本办法自2022年1月1日起施行。司法部此前制定的有关公证执业活动投诉处理规定与本办法不一致的，以本办法为准。"}],"gongzhengjigoubanlidiyadengjibanfa":[{"i":1,"n":"第一条","txt":"为规范公证机构的抵押登记活动，根据《中华人民共和国担保法》和《中华人民共和国公证暂行条例》等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"《中华人民共和国担保法》第四十三条第二款规定的公证部门为依法设立的公证机构。"},{"i":3,"n":"第三条","txt":"《中华人民共和国担保法》第四十三条规定的“其他财产”包括下列内容： (一) 个人、事业单位、社会团体和其他非企业组织所有的机械设备、牲畜等生产资料； (二) 位于农村的个人私有房产； (三) 个人所有的家俱、家用电器、金银珠宝及其制品等生活资料； (四) 其他除《中华人民共和国担保法》第三十七条和第四十二条规定之外的财产。 当事人以前款规定的财产抵押的，抵押人所在地的公证机构为登记部门，公证机构办理登记适用本办法规定。"},{"i":4,"n":"第四条","txt":"以《中华人民共和国担保法》第四十二条第(二)项规定的财产抵押，县级以上地方人民政府规定由公证机构登记的；以及法律、法规规定的抵押合同自公证机构办理登记之日起生效的，公证机构办理登记适用本办法规定。"},{"i":5,"n":"第五条","txt":"以本办法第三条规定的财产抵押的，抵押权人自公证机构出具《抵押登记证书》之日起获得对抗第三人的权利。 以本办法第四条规定的财产抵押的，抵押合同自公证机构出具《抵押登记证书》之日起生效。"},{"i":6,"n":"第六条","txt":"申办抵押登记，由抵押合同双方当事人共同提出申请，并填写《抵押登记申请表》。 《抵押登记申请表》应载明下列内容： (一)申请人为个人的，应载明其姓名、性别、出生日期、身份证明号码、工作单位、住址、联系方式等；申请人为法人或其他组织的，应载明法人或其他组织的名称、地址、法定代表人或负责人和代理人的姓名、性别、职务、联系方式； (二) 主合同和抵押合同的名称； (三) 被担保的主债权的种类、数额； (四) 抵押物的名称、数量、质量、状况、所在地、所有权或者使用权权属； (五) 债务人履行债务的期限； (六) 抵押担保的范围； (七) 抵押物属再次抵押的，应载明再次抵押的情况； (八) 申请抵押登记的日期； (九) 其他需要说明的问题。 申请人应当在申请表上签名或盖章。"},{"i":7,"n":"第七条","txt":"申请人应向公证机构提交下列材料： (一) 申请人和代理人的身份、资格证明； (二) 主合同、抵押合同及其他相关合同； (三)以本办法第四条规定的财产抵押的，应提交抵押物所有权或者使用权证书；以本办法第三条规定的财产抵押的，应提交抵押物所有权或者使用权证书或其他证明材料； (四) 抵押物清单； (五) 与抵押登记事项有关的其他材料。"},{"i":8,"n":"第八条","txt":"符合下列条件的申请，公证机构应予以受理： (一) 申请抵押登记的财产符合本办法第三条、第四条的规定； (二) 抵押登记事项属于本公证机构管辖； (三) 本办法第七条所列各项材料齐全。 公证机构不予受理的，应记录在案，并及时告知申请人。"},{"i":9,"n":"第九条","txt":"公证机构应当在受理之日起5个工作日内审查完毕，并决定是否予以登记。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，公证机构不予办理抵押登记： (一) 申请人提交的材料无效； (二) 申请人对抵押物的名称、数量、质量、状况、所在地、所有权或者使用权权属存在争议； (三) 以法律、法规规定的不得抵押的财产设定抵押的。 对不予登记的，公证机构应记录在案，并书面告知申请人。"},{"i":11,"n":"第十一条","txt":"公证机构决定予以登记的，应向当事人出具《抵押登记证书》。 《抵押登记证书》应载明下列内容： (一) 抵押人、抵押权人的姓名、身份证明号码或名称、单位代码、地址； (二) 抵押担保的主债权的种类、数额； (三) 抵押物的名称、数量、质量、状况、所在地、所有权或者使用权权属； (四) 债务人履行债务的期限； (五) 抵押担保的范围； (六) 再次抵押情况； (七) 抵押登记的日期； (八) 其他事项。"},{"i":12,"n":"第十二条","txt":"公证机构办理房地产抵押登记的，应在出具《抵押登记证书》后告知房地产管理部门。"},{"i":13,"n":"第十三条","txt":"办理抵押登记的公证机构应配备计算机，录入抵押登记信息，并设立书面登录簿，登录本公证机构办理抵押登记的资料。 办理抵押登记的公证机构应及时与其他公证机构交换抵押登记信息，信息的交换办法由各省、自治区、直辖市司法厅(局)制定。"},{"i":14,"n":"第十四条","txt":"当事人变更抵押合同向公证机构申请变更登记，经审查符合抵押登记规定的，公证机构应予以办理变更抵押登记。 当事人变更抵押合同未办理变更抵押登记的，自行变更后的抵押不发生《中华人民共和国担保法》规定的抵押登记效力。"},{"i":15,"n":"第十五条","txt":"当事人履行完毕主债务或提前终止、解除抵押合同向公证机构申请办理注销登记的，公证机构应予以办理注销抵押登记。"},{"i":16,"n":"第十六条","txt":"公证机构办理抵押登记，按规定收取抵押登记费。抵押登记费由当事人双方共同承担或从约定。"},{"i":17,"n":"第十七条","txt":"当事人及有关人员可以查阅、抄录或复印抵押登记的资料，但应按规定交纳费用。"},{"i":18,"n":"第十八条","txt":"以承包经营权等合同权益、应收帐款或未来可得权益进行物权担保的，公证机构办理登记可比照本办法执行。"},{"i":19,"n":"第十九条","txt":"本办法由司法部解释。"},{"i":20,"n":"第二十条","txt":"本办法自发布之日起施行。"}],"gongzhengjigouzhiyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对公证机构的审批管理和执业监督，规范公证机构的执业行为，根据《中华人民共和国公证法》(以下简称《公证法》)和有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"公证机构依照《公证法》和本办法设立。 设立公证机构，应当按照统筹规划、合理布局的原则，实行总量控制。"},{"i":3,"n":"第三条","txt":"公证机构办理公证，应当遵守法律，坚持客观、公正的原则，遵守公证执业规范和执业纪律。 公证机构应当加入地方和全国的公证协会。"},{"i":4,"n":"第四条","txt":"公证机构办理公证，不以营利为目的，独立行使公证职能，独立承担民事责任，任何单位和个人不得非法干预，其合法权益不受侵犯。"},{"i":5,"n":"第五条","txt":"司法行政机关依照《公证法》和有关法律、法规、规章，对公证机构进行监督、指导。"},{"i":6,"n":"第六条","txt":"公证协会是公证业的自律性组织。公证协会依照《公证法》和章程，对公证机构的执业活动进行监督。"},{"i":7,"n":"第七条","txt":"设立公证机构，由省、自治区、直辖市司法行政机关审核批准。"},{"i":8,"n":"第八条","txt":"公证机构可以在县、不设区的市、设区的市、直辖市或者市辖区设立；在设区的市、直辖市可以设立一个或者若干个公证机构。公证机构不按行政区划层层设立。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市司法行政机关应当按照公证机构设立原则，综合考虑当地经济社会发展程度、人口数量、交通状况和对公证业务的实际需求等情况，拟定本行政区域公证机构设置方案，并可以根据当地情况和公证需求的变化对设置方案进行调整。 公证机构设置方案包括：设置方案拟定的依据，公证机构设置和布局的安排，公证执业区域划分的安排，公证机构设置总量及地区分布的安排。 公证机构设置方案及其调整方案，应当报司法部核定。"},{"i":10,"n":"第十条","txt":"公证执业区域可以下列区域为单位划分： (一)县、不设区的市、市辖区的辖区； (二)设区的市、直辖市的辖区或者所辖城区的全部市辖区。 公证机构的执业区域，由省、自治区、直辖市司法行政机关在办理该公证机构设立或者变更审批时予以核定。"},{"i":11,"n":"第十一条","txt":"设立公证机构，应当具备下列条件： (一)有自己的名称； (二)有固定的场所； (三)有二名以上公证员； (四)有开展公证业务所必需的资金。 设立公证机构，应当符合经司法部核定的公证机构设置方案的要求。"},{"i":12,"n":"第十二条","txt":"公证机构的负责人应当在有三年以上执业经历的公证员中推选产生，由所在地司法行政机关核准，并逐级报省、自治区、直辖市司法行政机关备案。"},{"i":13,"n":"第十三条","txt":"公证机构的开办资金数额，由省、自治区、直辖市司法行政机关确定。"},{"i":14,"n":"第十四条","txt":"设立公证机构，由所在地司法行政机关组建，逐级报省、自治区、直辖市司法行政机关审批。 申请设立公证机构，应当提交下列材料： (一)设立公证机构的申请和组建报告； (二)拟采用的公证机构名称； (三)拟任公证员名单、简历、居民身份证复印件和符合担任公证员条件的证明材料； (四)拟推选的公证机构负责人的情况说明； (五)开办资金证明； (六)办公场所证明； (七)其他需要提交的材料。 设立公证机构需要配备新的公证员的，应当依照《公证法》和司法部规定的条件和程序，报请审核、任命。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市司法行政机关应当自收到申请材料之日起三十日内，完成审核，作出批准设立或者不予批准设立的决定。对准予设立的，颁发公证机构执业证书；对不准予设立的，应当在决定中告知不予批准的理由。 批准设立公证机构的决定，应当报司法部备案。"},{"i":16,"n":"第十六条","txt":"公证机构变更名称、办公场所，根据当地公证机构设置调整方案予以分立、合并或者变更执业区域的，应当由所在地司法行政机关审核后，逐级报省、自治区、直辖市司法行政机关办理变更核准手续。核准变更的，应当报司法部备案。 公证机构变更负责人的，经所在地司法行政机关核准后，逐级报省、自治区、直辖市司法行政机关备案。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市司法行政机关对经批准设立的公证机构以及公证机构重要的变更事项，应当在作出批准决定后二十日内，在省级报刊上予以公告。 司法部定期编制全国公证机构名录。"},{"i":18,"n":"第十八条","txt":"公证机构统称公证处。根据公证机构设置的不同情况，分别采用下列方式冠名： (一)在县、不设区的市设立公证机构的，冠名方式为：省(自治区、直辖市)名称＋本县、市名称＋公证处； (二)在设区的市或其市辖区设立公证机构的，冠名方式为：省(自治区)名称＋本市名称＋字号＋公证处； (三)在直辖市或其市辖区设立公证机构的，冠名方式为：直辖市名称＋字号＋公证处。"},{"i":19,"n":"第十九条","txt":"公证机构的名称，应当使用全国通用的文字。民族自治地方的公证机构的名称，可以同时使用当地通用的民族文字。 公证机构名称中的字号，应当由两个以上文字组成，并不得与所在省、自治区、直辖市内设立的其他公证机构的名称中的字号相同或者近似。 公证机构名称的内容和文字，应当符合国家有关规定。"},{"i":20,"n":"第二十条","txt":"公证机构的名称，由省、自治区、直辖市司法行政机关在办理该公证机构设立或者变更审批时予以核定。 公证机构对经核定的名称享有专用权。"},{"i":21,"n":"第二十一条","txt":"公证机构执业证书是公证机构获准设立和执业的凭证。 公证机构执业证书应当载明下列内容：公证机构名称、负责人、办公场所、执业区域、证书编号、颁证日期、审批机关等。公证机构执业证书分为正本和副本。正本用于在办公场所悬挂，副本用于接受查验。正本和副本具有同等法律效力。 公证机构执业证书由司法部统一制作。证书编号办法由司法部制定。"},{"i":22,"n":"第二十二条","txt":"公证机构执业证书不得涂改、出借、抵押或者转让。公证机构执业证书损毁或者遗失的，由该公证机构报经所在地司法行政机关，逐级向省、自治区、直辖市司法行政机关申请换发或者补发。"},{"i":23,"n":"第二十三条","txt":"公证机构变更名称、办公场所、负责人、执业区域或者分立、合并的，应当在报请核准的同时，申请换发公证机构执业证书。 公证机构受到停业整顿处罚的，停业整顿期间，应当将该公证机构执业证书缴存所在地司法行政机关。"},{"i":24,"n":"第二十四条","txt":"司法行政机关依法对公证机构的组织建设、队伍建设、执业活动、质量控制、内部管理等情况进行监督。"},{"i":25,"n":"第二十五条","txt":"省、自治区、直辖市司法行政机关对公证机构的下列事项实施监督： (一)公证机构保持法定设立条件的情况； (二)公证机构执行应当报批或者备案事项的情况； (三)公证机构和公证员的执业情况； (四)公证质量的监控情况； (五)法律、法规和司法部规定的其他监督检查事项。"},{"i":26,"n":"第二十六条","txt":"设区的市和公证机构所在地司法行政机关对本地公证机构的下列事项实施监督： (一)组织建设情况； (二)执业活动情况； (三)公证质量情况； (四)公证员执业年度考核情况； (五)档案管理情况； (六)财务制度执行情况； (七)内部管理制度建设情况； (八)司法部和省、自治区、直辖市司法行政机关要求进行监督检查的其他事项。"},{"i":27,"n":"第二十七条","txt":"公证机构应当建立健全业务、公证档案、财务、资产等管理制度，对公证员的执业行为进行监督，建立执业过错责任追究制度。 公证机构应当严格执行国家制定的公证收费标准。 公证机构应当按照规定参加公证执业责任保险。"},{"i":28,"n":"第二十八条","txt":"公证机构应当依法开展公证执业活动，不得有下列行为： (一)为不真实、不合法的事项出具公证书； (二)毁损、篡改公证文书或者公证档案； (三)以诋毁其他公证机构、公证员或者支付回扣、佣金等不正当手段争揽公证业务； (四)泄露在执业活动中知悉的国家秘密、商业秘密或者个人隐私； (五)违反规定的收费标准收取公证费； (六)法律、法规和司法部规定禁止的其他行为。"},{"i":29,"n":"第二十九条","txt":"公证机构应当依照《公证法》第二十五条的规定，在省、自治区、直辖市司法行政机关核定的执业区域内受理公证业务。"},{"i":30,"n":"第三十条","txt":"公证机构应当按照省、自治区、直辖市司法行政机关的规定，定期填报公证业务情况统计表，每年2月1日前向所在地司法行政机关提交本公证机构的年度工作报告。 年度工作报告应当真实、全面地反映本公证机构上一年度开展公证业务、公证质量监控、公证员遵守职业道德和执业纪律、公证收费、财务管理、内部制度建设等方面的情况。 公证业务情况统计表的统计项目及样式，由司法部制定。"},{"i":31,"n":"第三十一条","txt":"公证机构由所在地司法行政机关在每年的第一季度进行年度考核。年度考核，应当依照《公证法》的要求和本办法第二十六条规定的监督事项，审查公证机构的年度工作报告，结合日常监督检查掌握的情况，由所在地司法行政机关对公证机构的年度执业和管理情况作出综合评估。考核等次及其标准，由司法部制定。 年度考核结果，应当书面告知公证机构，并报上一级司法行政机关备案。"},{"i":32,"n":"第三十二条","txt":"公证机构应当对所属公证员的执业情况进行年度考核。 公证机构的负责人由所在地司法行政机关进行年度考核。"},{"i":33,"n":"第三十三条","txt":"公证机构存在下列情形之一的，所在地司法行政机关应当进行重点监督检查： (一)被投诉或者举报的； (二)执业中有不良记录的； (三)未保持法定设立条件的； (四)年度考核发现内部管理存在严重问题的。"},{"i":34,"n":"第三十四条","txt":"司法行政机关实施监督检查，可以对公证机构进行实地检查，要求公证机构和公证员说明有关情况，调阅公证机构相关材料和公证档案，向相关单位和人员调查、核实有关情况。 公证机构和公证员应当接受司法行政机关依法实施的监督检查，如实说明有关情况、提供相关资料，不得谎报、隐匿、伪造、销毁相关证据材料。"},{"i":35,"n":"第三十五条","txt":"司法行政机关应当建立有关公证机构设立、变更、备案事项、年度考核、违法违纪行为处罚、奖励等方面情况的执业档案。"},{"i":36,"n":"第三十六条","txt":"公证机构有《公证法》第四十一条、第四十二条规定所列行为之一的，由省、自治区、直辖市司法行政机关或者设区的市司法行政机关依据《公证法》的规定，予以处罚。 公证机构违反《公证法》第二十五条规定，跨执业区域受理公证业务的，由所在地或者设区的市司法行政机关予以制止，并责令改正。"},{"i":37,"n":"第三十七条","txt":"司法行政机关对公证机构违法行为实施行政处罚，应当根据有关法律、法规和司法部有关行政处罚程序的规定进行。"},{"i":38,"n":"第三十八条","txt":"司法行政机关在对公证机构作出行政处罚决定之前，应当告知其查明的违法行为事实、处罚的理由及依据，并告知其依法享有的权利。口头告知的，应当制作笔录。公证机构有权进行陈述和申辩，有权依法申请听证。 公证机构对行政处罚不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":39,"n":"第三十九条","txt":"司法行政机关在实施监督检查和年度考核过程中，发现公证机构存在违法行为或者收到相关投诉、举报的，应当及时立案调查，全面、客观、公正地查明事实，收集证据。被调查的公证机构应当向调查机关如实陈述事实，提供有关材料。"},{"i":40,"n":"第四十条","txt":"司法行政机关查处公证机构的违法行为，可以委托公证协会对公证机构的违法行为进行调查、核实。 接受委托的公证协会应当查明事实、核实证据，并向司法行政机关提出实施行政处罚的建议。"},{"i":41,"n":"第四十一条","txt":"公证协会依据章程和有关行业规范，对公证机构违反执业规范和执业纪律的行为，视其情节轻重，给予相应的行业处分。 公证协会在查处公证机构违反执业规范和执业纪律行为的过程中，发现有依据《公证法》的规定应当给予行政处罚情形的，应当提交有管辖权的司法行政机关处理。"},{"i":42,"n":"第四十二条","txt":"公证机构及其公证员因过错给当事人、公证事项的利害关系人造成损失的，由公证机构承担相应的赔偿责任；公证机构赔偿后，可以向有故意或者重大过失的公证员追偿。"},{"i":43,"n":"第四十三条","txt":"司法行政机关及其工作人员在公证机构设立审批、公证机构执业证书管理、对公证机构实施监督检查、年度考核的过程中，有滥用职权、玩忽职守、徇私舞弊、干预公证机构依法独立行使公证职能行为的，应当依法追究责任人员的行政责任；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"本办法所称公证机构所在地司法行政机关，是指根据当地公证机构设置方案的规定，负责组建该公证机构，并承担对其实施日常监督、指导职能的司法行政机关。"},{"i":45,"n":"第四十五条","txt":"《公证法》和本办法施行前设立的公证机构，其设置、布局、名称、执业区域及管理体制不符合《公证法》和本办法规定的，由省、自治区、直辖市司法行政机关拟定调整方案，报司法部核定后组织实施。"},{"i":46,"n":"第四十六条","txt":"本办法由司法部解释。"},{"i":47,"n":"第四十七条","txt":"本办法自二○○六年三月一日起施行。"}],"gongzhengchengxuguize":[{"i":1,"n":"第一条","txt":"为了规范公证程序，保证公证质量，根据《中华人民共和国公证法》(以下简称《公证法》)和有关法律、行政法规的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"公证机构办理公证，应当遵守法律，坚持客观、公正、便民的原则，遵守公证执业规范和执业纪律。"},{"i":3,"n":"第三条","txt":"公证机构依法独立行使公证职能，独立承担民事责任，任何单位、个人不得非法干预，其合法权益不受侵犯。"},{"i":4,"n":"第四条","txt":"公证机构应当根据《公证法》的规定，受理公证申请，办理公证业务，以本公证机构的名义出具公证书。"},{"i":5,"n":"第五条","txt":"公证员受公证机构指派，依照《公证法》和本规则规定的程序办理公证业务，并在出具的公证书上署名。 依照《公证法》和本规则的规定，在办理公证过程中须公证员亲自办理的事务，不得指派公证机构的其他工作人员办理。"},{"i":6,"n":"第六条","txt":"公证机构和公证员办理公证，不得有《公证法》第十三条、第二十三条禁止的行为。 公证机构的其他工作人员以及依据本规则接触到公证业务的相关人员，不得泄露在参与公证业务活动中知悉的国家秘密、商业秘密或者个人隐私。"},{"i":7,"n":"第七条","txt":"公证机构应当建立、健全公证业务管理制度和公证质量管理制度，对公证员的执业行为进行监督。"},{"i":8,"n":"第八条","txt":"司法行政机关依照《公证法》和本规则规定，对公证机构和公证员的执业活动和遵守程序规则的情况进行监督、指导。 公证协会依据章程和行业规范，对公证机构和公证员的执业活动和遵守程序规则的情况进行监督。"},{"i":9,"n":"第九条","txt":"公证当事人是指与公证事项有利害关系并以自己的名义向公证机构提出公证申请，在公证活动中享有权利和承担义务的自然人、法人或者其他组织。"},{"i":10,"n":"第十条","txt":"无民事行为能力人或者限制民事行为能力人申办公证，应当由其监护人代理。 法人申办公证，应当由其法定代表人代表。 其他组织申办公证，应当由其负责人代表。"},{"i":11,"n":"第十一条","txt":"当事人可以委托他人代理申办公证，但申办遗嘱、遗赠扶养协议、赠与、认领亲子、收养关系、解除收养关系、生存状况、委托、声明、保证及其他与自然人人身有密切关系的公证事项，应当由其本人亲自申办。 公证员、公证机构的其他工作人员不得代理当事人在本公证机构申办公证。"},{"i":12,"n":"第十二条","txt":"居住在香港、澳门、台湾地区的当事人，委托他人代理申办涉及继承、财产权益处分、人身关系变更等重要公证事项的，其授权委托书应当经其居住地的公证人(机构)公证，或者经司法部指定的机构、人员证明。 居住在国外的当事人，委托他人代理申办前款规定的重要公证事项的，其授权委托书应当经其居住地的公证人(机构)、我驻外使(领)馆公证。"},{"i":13,"n":"第十三条","txt":"公证执业区域是指由省、自治区、直辖市司法行政机关，根据《公证法》第二十五条和《公证机构执业管理办法》第十条的规定以及当地公证机构设置方案，划定的公证机构受理公证业务的地域范围。 公证机构的执业区域，由省、自治区、直辖市司法行政机关在办理该公证机构设立或者变更审批时予以核定。 公证机构应当在核定的执业区域内受理公证业务。"},{"i":14,"n":"第十四条","txt":"公证事项由当事人住所地、经常居住地、行为地或者事实发生地的公证机构受理。 涉及不动产的公证事项，由不动产所在地的公证机构受理;涉及不动产的委托、声明、赠与、遗嘱的公证事项，可以适用前款规定。"},{"i":15,"n":"第十五条","txt":"二个以上当事人共同申办同一公证事项的，可以共同到行为地、事实发生地或者其中一名当事人住所地、经常居住地的公证机构申办。"},{"i":16,"n":"第十六条","txt":"当事人向二个以上可以受理该公证事项的公证机构提出申请的，由最先受理申请的公证机构办理。"},{"i":17,"n":"第十七条","txt":"自然人、法人或者其他组织向公证机构申请办理公证，应当填写公证申请表。公证申请表应当载明下列内容： (一)申请人及其代理人的基本情况; (二)申请公证的事项及公证书的用途; (三)申请公证的文书的名称; (四)提交证明材料的名称、份数及有关证人的姓名、住址、联系方式; (五)申请的日期; (六)其他需要说明的情况。 申请人应当在申请表上签名或者盖章，不能签名、盖章的由本人捺指印。"},{"i":18,"n":"第十八条","txt":"自然人、法人或者其他组织申请办理公证，应当提交下列材料： (一)自然人的身份证明，法人的资格证明及其法定代表人的身份证明，其他组织的资格证明及其负责人的身份证明; (二)委托他人代为申请的，代理人须提交当事人的授权委托书，法定代理人或者其他代理人须提交有代理权的证明; (三)申请公证的文书; (四)申请公证的事项的证明材料，涉及财产关系的须提交有关财产权利证明; (五)与申请公证的事项有关的其他材料。 对于前款第四项、第五项所规定的申请人应当提交的证明材料，公证机构能够通过政务信息资源共享方式获取的，当事人可以不提交，但应当作出有关信息真实合法的书面承诺。"},{"i":19,"n":"第十九条","txt":"符合下列条件的申请，公证机构可以受理： (一)申请人与申请公证的事项有利害关系; (二)申请人之间对申请公证的事项无争议; (三)申请公证的事项符合《公证法》第十一条规定的范围; (四)申请公证的事项符合《公证法》第二十五条的规定和该公证机构在其执业区域内可以受理公证业务的范围。 法律、行政法规规定应当公证的事项，符合前款第一项、第二项、第四项规定条件的，公证机构应当受理。 对不符合本条第一款、第二款规定条件的申请，公证机构不予受理，并通知申请人。对因不符合本条第一款第四项规定不予受理的，应当告知申请人向可以受理该公证事项的公证机构申请。"},{"i":20,"n":"第二十条","txt":"公证机构受理公证申请后，应当指派承办公证员，并通知当事人。当事人要求该公证员回避，经查属于《公证法》第二十三条第三项规定应当回避情形的，公证机构应当改派其他公证员承办。"},{"i":21,"n":"第二十一条","txt":"公证机构受理公证申请后，应当告知当事人申请公证事项的法律意义和可能产生的法律后果，告知其在办理公证过程中享有的权利、承担的义务。告知内容、告知方式和时间，应当记录归档，并由申请人或其代理人签字。 公证机构受理公证申请后，应当在全国公证管理系统录入办证信息，加强公证办理流程管理，方便当事人查询。"},{"i":22,"n":"第二十二条","txt":"公证机构受理公证申请后，应当按照规定向当事人收取公证费。公证办结后，经核定的公证费与预收数额不一致的，应当办理退还或者补收手续。 对符合法律援助条件的当事人，公证机构应当按照规定减收或者免收公证费。"},{"i":23,"n":"第二十三条","txt":"公证机构受理公证申请后，应当根据不同公证事项的办证规则，分别审查下列事项： (一)当事人的人数、身份、申请办理该项公证的资格及相应的权利; (二)当事人的意思表示是否真实; (三)申请公证的文书的内容是否完备，含义是否清晰，签名、印鉴是否齐全; (四)提供的证明材料是否真实、合法、充分; (五)申请公证的事项是否真实、合法。"},{"i":24,"n":"第二十四条","txt":"当事人应当向公证机构如实说明申请公证的事项的有关情况，提交的证明材料应当真实、合法、充分。 公证机构在审查中，对申请公证的事项的真实性、合法性有疑义的，认为当事人的情况说明或者提供的证明材料不充分、不完备或者有疑义的，可以要求当事人作出说明或者补充证明材料。 当事人拒绝说明有关情况或者补充证明材料的，依照本规则第四十八条的规定处理。"},{"i":25,"n":"第二十五条","txt":"公证机构在审查中，对当事人的身份、申请公证的事项以及当事人提供的证明材料，按照有关办证规则需要核实或者对其有疑义的，应当进行核实，或者委托异地公证机构代为核实。有关单位或者个人应当依法予以协助。 审查自然人身份，应当采取使用身份识别核验设备等方式，并记录附卷。"},{"i":26,"n":"第二十六条","txt":"公证机构在审查中，应当询问当事人有关情况，释明法律风险，提出法律意见建议，解答当事人疑问;发现有重大、复杂情形的，应当由公证机构集体讨论。"},{"i":27,"n":"第二十七条","txt":"公证机构可以采用下列方式，核实公证事项的有关情况以及证明材料： (一)通过询问当事人、公证事项的利害关系人核实; (二)通过询问证人核实; (三)向有关单位或者个人了解相关情况或者核实、收集相关书证、物证、视听资料等证明材料; (四)通过现场勘验核实; (五)委托专业机构或者专业人员鉴定、检验检测、翻译。"},{"i":28,"n":"第二十八条","txt":"公证机构进行核实，应当遵守有关法律、法规和有关办证规则的规定。 公证机构派员外出核实的，应当由二人进行，但核实、收集书证的除外。特殊情况下只有一人外出核实的，应当有一名见证人在场。"},{"i":29,"n":"第二十九条","txt":"采用询问方式向当事人、公证事项的利害关系人或者有关证人了解、核实公证事项的有关情况以及证明材料的，应当告知被询问人享有的权利、承担的义务及其法律责任。询问的内容应当制作笔录。 询问笔录应当载明：询问日期、地点、询问人、记录人，询问事由，被询问人的基本情况，告知内容、询问谈话内容等。 询问笔录应当交由被询问人核对后签名或者盖章、捺指印。笔录中修改处应当由被询问人盖章或者捺指印认可。"},{"i":30,"n":"第三十条","txt":"在向当事人、公证事项的利害关系人、证人或者有关单位、个人核实或者收集有关公证事项的证明材料时，需要摘抄、复印(复制)有关资料、证明原件、档案材料或者对实物证据照相并作文字描述记载的，摘抄、复印(复制)的材料或者物证照片及文字描述记载应当与原件或者物证相符，并由资料、原件、物证所有人或者档案保管人对摘抄、复印(复制)的材料或者物证照片及文字描述记载核对后签名或者盖章。"},{"i":31,"n":"第三十一条","txt":"采用现场勘验方式核实公证事项及其有关证明材料的，应当制作勘验笔录，由核实人员及见证人签名或者盖章。根据需要，可以采用绘图、照相、录像或者录音等方式对勘验情况或者实物证据予以记载。"},{"i":32,"n":"第三十二条","txt":"需要委托专业机构或者专业人员对申请公证的文书或者公证事项的证明材料进行鉴定、检验检测、翻译的，应当告知当事人由其委托办理，或者征得当事人的同意代为办理。鉴定意见、检验检测结论、翻译材料，应当由相关专业机构及承办鉴定、检验检测、翻译的人员盖章和签名。 委托鉴定、检验检测、翻译所需的费用，由当事人支付。"},{"i":33,"n":"第三十三条","txt":"公证机构委托异地公证机构核实公证事项及其有关证明材料的，应当出具委托核实函，对需要核实的事项及内容提出明确的要求。受委托的公证机构收到委托函后，应当在一个月内完成核实。因故不能完成或者无法核实的，应当在上述期限内函告委托核实的公证机构。"},{"i":34,"n":"第三十四条","txt":"公证机构在审查中，认为申请公证的文书内容不完备、表达不准确的，应当指导当事人补正或者修改。当事人拒绝补正、修改的，应当在工作记录中注明。 应当事人的请求，公证机构可以代为起草、修改申请公证的文书。"},{"i":35,"n":"第三十五条","txt":"公证机构经审查，认为申请公证的事项符合《公证法》、本规则及有关办证规则规定的，应当自受理之日起十五个工作日内向当事人出具公证书。 因不可抗力、补充证明材料或者需要核实有关情况的，所需时间不计算在前款规定的期限内，并应当及时告知当事人。"},{"i":36,"n":"第三十六条","txt":"民事法律行为的公证，应当符合下列条件： (一)当事人具有从事该行为的资格和相应的民事行为能力; (二)当事人的意思表示真实; (三)该行为的内容和形式合法，不违背社会公德; (四)《公证法》规定的其他条件。 不同的民事法律行为公证的办证规则有特殊要求的，从其规定。"},{"i":37,"n":"第三十七条","txt":"有法律意义的事实或者文书的公证，应当符合下列条件： (一)该事实或者文书与当事人有利害关系; (二)事实或者文书真实无误; (三)事实或者文书的内容和形式合法，不违背社会公德; (四)《公证法》规定的其他条件。 不同的有法律意义的事实或者文书公证的办证规则有特殊要求的，从其规定。"},{"i":38,"n":"第三十八条","txt":"文书上的签名、印鉴、日期的公证，其签名、印鉴、日期应当准确、属实;文书的副本、影印本等文本的公证，其文本内容应当与原本相符。"},{"i":39,"n":"第三十九条","txt":"具有强制执行效力的债权文书的公证，应当符合下列条件： (一)债权文书以给付为内容; (二)债权债务关系明确，债权人和债务人对债权文书有关给付内容无疑义; (三)债务履行方式、内容、时限明确; (四)债权文书中载明当债务人不履行或者不适当履行义务时，债务人愿意接受强制执行的承诺; (五)债权人和债务人愿意接受公证机构对债务履行情况进行核实; (六)《公证法》规定的其他条件。"},{"i":40,"n":"第四十条","txt":"符合《公证法》、本规则及有关办证规则规定条件的公证事项，由承办公证员拟制公证书，连同被证明的文书、当事人提供的证明材料及核实情况的材料、公证审查意见，报公证机构的负责人或其指定的公证员审批。但按规定不需要审批的公证事项除外。 公证机构的负责人或者被指定负责审批的公证员不得审批自己承办的公证事项。"},{"i":41,"n":"第四十一条","txt":"审批公证事项及拟出具的公证书，应当审核以下内容： (一)申请公证的事项及其文书是否真实、合法; (二)公证事项的证明材料是否真实、合法、充分; (三)办证程序是否符合《公证法》、本规则及有关办证规则的规定; (四)拟出具的公证书的内容、表述和格式是否符合相关规定。 审批重大、复杂的公证事项，应当在审批前提交公证机构集体讨论。讨论的情况和形成的意见，应当记录归档。"},{"i":42,"n":"第四十二条","txt":"公证书应当按照司法部规定的格式制作。公证书包括以下主要内容： (一)公证书编号; (二)当事人及其代理人的基本情况; (三)公证证词; (四)承办公证员的签名(签名章)、公证机构印章; (五)出具日期。 公证证词证明的文书是公证书的组成部分。 有关办证规则对公证书的格式有特殊要求的，从其规定。"},{"i":43,"n":"第四十三条","txt":"制作公证书应当使用全国通用的文字。在民族自治地方，根据当事人的要求，可以同时制作当地通用的民族文字文本。两种文字的文本，具有同等效力。 发往香港、澳门、台湾地区使用的公证书应当使用全国通用的文字。 发往国外使用的公证书应当使用全国通用的文字。根据需要和当事人的要求，公证书可以附外文译文。"},{"i":44,"n":"第四十四条","txt":"公证书自出具之日起生效。 需要审批的公证事项，审批人的批准日期为公证书的出具日期;不需要审批的公证事项，承办公证员的签发日期为公证书的出具日期;现场监督类公证需要现场宣读公证证词的，宣读日期为公证书的出具日期。"},{"i":45,"n":"第四十五条","txt":"公证机构制作的公证书正本，由当事人各方各收执一份，并可以根据当事人的需要制作若干份副本。公证机构留存公证书原本(审批稿、签发稿)和一份正本归档。"},{"i":46,"n":"第四十六条","txt":"公证书出具后，可以由当事人或其代理人到公证机构领取，也可以应当事人的要求由公证机构发送。当事人或其代理人收到公证书应当在回执上签收。"},{"i":47,"n":"第四十七条","txt":"公证书需要办理领事认证的，根据有关规定或者当事人的委托，公证机构可以代为办理公证书认证，所需费用由当事人支付。"},{"i":48,"n":"第四十八条","txt":"公证事项有下列情形之一的，公证机构应当不予办理公证： (一)无民事行为能力人或者限制民事行为能力人没有监护人代理申请办理公证的; (二)当事人与申请公证的事项没有利害关系的; (三)申请公证的事项属专业技术鉴定、评估事项的; (四)当事人之间对申请公证的事项有争议的; (五)当事人虚构、隐瞒事实，或者提供虚假证明材料的; (六)当事人提供的证明材料不充分又无法补充，或者拒绝补充证明材料的; (七)申请公证的事项不真实、不合法的; (八)申请公证的事项违背社会公德的; (九)当事人拒绝按照规定支付公证费的。"},{"i":49,"n":"第四十九条","txt":"不予办理公证的，由承办公证员写出书面报告，报公证机构负责人审批。不予办理公证的决定应当书面通知当事人或其代理人。 不予办理公证的，公证机构应当根据不予办理的原因及责任，酌情退还部分或者全部收取的公证费。"},{"i":50,"n":"第五十条","txt":"公证事项有下列情形之一的，公证机构应当终止公证： (一)因当事人的原因致使该公证事项在六个月内不能办结的; (二)公证书出具前当事人撤回公证申请的; (三)因申请公证的自然人死亡、法人或者其他组织终止，不能继续办理公证或者继续办理公证已无意义的; (四)当事人阻挠、妨碍公证机构及承办公证员按规定的程序、期限办理公证的; (五)其他应当终止的情形。"},{"i":51,"n":"第五十一条","txt":"终止公证的，由承办公证员写出书面报告，报公证机构负责人审批。终止公证的决定应当书面通知当事人或其代理人。 终止公证的，公证机构应当根据终止的原因及责任，酌情退还部分收取的公证费。"},{"i":52,"n":"第五十二条","txt":"公证机构办理招标投标、拍卖、开奖等现场监督类公证，应当由二人共同办理。承办公证员应当依照有关规定，通过事前审查、现场监督，对其真实性、合法性予以证明，现场宣读公证证词，并在宣读后七日内将公证书发送当事人。该公证书自宣读公证证词之日起生效。 办理现场监督类公证，承办公证员发现当事人有弄虚作假、徇私舞弊、违反活动规则、违反国家法律和有关规定行为的，应当即时要求当事人改正;当事人拒不改正的，应当不予办理公证。"},{"i":53,"n":"第五十三条","txt":"公证机构办理遗嘱公证，应当由二人共同办理。承办公证员应当全程亲自办理，并对遗嘱人订立遗嘱的过程录音录像。 特殊情况下只能由一名公证员办理时，应当请一名见证人在场，见证人应当在询问笔录上签名或者盖章。 公证机构办理遗嘱公证，应当查询全国公证管理系统。出具公证书的，应当于出具当日录入办理信息。"},{"i":54,"n":"第五十四条","txt":"公证机构派员外出办理保全证据公证的，由二人共同办理，承办公证员应当亲自外出办理。 办理保全证据公证，承办公证员发现当事人是采用法律、法规禁止的方式取得证据的，应当不予办理公证。"},{"i":55,"n":"第五十五条","txt":"债务人不履行或者不适当履行经公证的具有强制执行效力的债权文书的，公证机构应当对履约情况进行核实后，依照有关规定出具执行证书。 债务人履约、公证机构核实、当事人就债权债务达成新的协议等涉及强制执行的情况，承办公证员应当制作工作记录附卷。 执行证书应当载明申请人、被申请执行人、申请执行标的和申请执行的期限。债务人已经履行的部分，应当在申请执行标的中予以扣除。因债务人不履行或者不适当履行而发生的违约金、滞纳金、利息等，可以应债权人的要求列入申请执行标的。"},{"i":56,"n":"第五十六条","txt":"经公证的事项在履行过程中发生争议的，出具公证书的公证机构可以应当事人的请求进行调解。经调解后当事人达成新的协议并申请公证的，公证机构可以办理公证;调解不成的，公证机构应当告知当事人就该争议依法向人民法院提起民事诉讼或者向仲裁机构申请仲裁。"},{"i":57,"n":"第五十七条","txt":"公证机构办理公证，应当填写公证登记簿，建立分类登记制度。 登记事项包括：公证事项类别、当事人姓名(名称)、代理人(代表人)姓名、受理日期、承办人、审批人(签发人)、　结案方式、办结日期、公证书编号等。 公证登记簿按年度建档，应当永久保存。"},{"i":58,"n":"第五十八条","txt":"公证机构在出具公证书后或者作出不予办理公证、终止公证的决定后，应当依照司法部、国家档案局制定的有关公证文书立卷归档和公证档案管理的规定，由承办公证员将公证文书和相关材料，在三个月内完成汇总整理、分类立卷、移交归档。"},{"i":59,"n":"第五十九条","txt":"公证机构受理公证申请后，承办公证员即应当着手立卷的准备工作，开始收集有关的证明材料，整理询问笔录和核实情况的有关材料等。 对不能附卷的证明原件或者实物证据，应当按照规定将其原件复印件(复制件)、物证照片及文字描述记载留存附卷。"},{"i":60,"n":"第六十条","txt":"公证案卷应当根据公证事项的类别、内容，划分为普通卷、密卷，分类归档保存。 公证案卷应当根据公证事项的类别、用途及其证据价值确定保管期限。保管期限分短期、长期、永久三种。 涉及国家秘密、遗嘱的公证事项，列为密卷。立遗嘱人死亡后，遗嘱公证案卷转为普通卷保存。 公证机构内部对公证事项的讨论意见和有关请示、批复等材料，应当装订成副卷，与正卷一起保存。"},{"i":61,"n":"第六十一条","txt":"当事人认为公证书有错误的，可以在收到公证书之日起一年内，向出具该公证书的公证机构提出复查。 公证事项的利害关系人认为公证书有错误的，可以自知道或者应当知道该项公证之日起一年内向出具该公证书的公证机构提出复查，但能证明自己不知道的除外。提出复查的期限自公证书出具之日起最长不得超过二十年。 复查申请应当以书面形式提出，载明申请人认为公证书存在的错误及其理由，提出撤销或者更正公证书的具体要求，并提供相关证明材料。"},{"i":62,"n":"第六十二条","txt":"公证机构收到复查申请后，应当指派原承办公证员之外的公证员进行复查。复查结论及处理意见，应当报公证机构的负责人审批。"},{"i":63,"n":"第六十三条","txt":"公证机构进行复查，应当对申请人提出的公证书的错误及其理由进行审查、核实，区别不同情况，按照以下规定予以处理： (一)公证书的内容合法、正确、办理程序无误的，作出维持公证书的处理决定; (二)公证书的内容合法、正确，仅证词表述或者格式不当的，应当收回公证书，更正后重新发给当事人;不能收回的，另行出具补正公证书; (三)公证书的基本内容违法或者与事实不符的，应当作出撤销公证书的处理决定; (四)公证书的部分内容违法或者与事实不符的，可以出具补正公证书，撤销对违法或者与事实不符部分的证明内容;也可以收回公证书，对违法或者与事实不符的部分进行删除、更正后，重新发给当事人; (五)公证书的内容合法、正确，但在办理过程中有违反程序规定、缺乏必要手续的情形，应当补办缺漏的程序和手续;无法补办或者严重违反公证程序的，应当撤销公证书。 被撤销的公证书应当收回，并予以公告，该公证书自始无效。 公证机构撤销"},{"i":64,"n":"第六十四条","txt":"公证机构应当自收到复查申请之日起三十日内完成复查，作出复查处理决定，发给申请人。需要对公证书作撤销或者更正、补正处理的，应当在作出复查处理决定后十日内完成。复查处理决定及处理后的公证书，应当存入原公证案卷。 公证机构办理复查，因不可抗力、补充证明材料或者需要核实有关情况的，所需时间不计算在前款规定的期限内，但补充证明材料或者需要核实有关情况的，最长不得超过六个月。"},{"i":65,"n":"第六十五条","txt":"公证机构发现出具的公证书的内容及办理程序有本规则第六十三条第二项至第五项规定情形的，应当通知当事人，按照本规则第六十三条的规定予以处理。"},{"i":66,"n":"第六十六条","txt":"公证书被撤销的，所收的公证费按以下规定处理： (一)因公证机构的过错撤销公证书的，收取的公证费应当全部退还当事人; (二)因当事人的过错撤销公证书的，收取的公证费不予退还; (三)因公证机构和当事人双方的过错撤销公证书的，收取的公证费酌情退还。"},{"i":67,"n":"第六十七条","txt":"当事人、公证事项的利害关系人对公证机构作出的撤销或者不予撤销公证书的决定有异议的，可以向地方公证协会投诉。 投诉的处理办法，由中国公证协会制定。"},{"i":68,"n":"第六十八条","txt":"当事人、公证事项的利害关系人对公证书涉及当事人之间或者当事人与公证事项的利害关系人之间实体权利义务的内容有争议的，公证机构应当告知其可以就该争议向人民法院提起民事诉讼。"},{"i":69,"n":"第六十九条","txt":"公证机构及其公证员因过错给当事人、公证事项的利害关系人造成损失的，由公证机构承担相应的赔偿责任;公证机构赔偿后，可以向有故意或者重大过失的公证员追偿。 当事人、公证事项的利害关系人与公证机构因过错责任和赔偿数额发生争议，协商不成的，可以向人民法院提起民事诉讼，也可以申请地方公证协会调解。"},{"i":70,"n":"第七十条","txt":"有关办证规则对不同的公证事项的办证程序有特殊规定的，从其规定。 公证机构采取在线方式办理公证业务，适用本规则。司法部另有规定的，从其规定。"},{"i":71,"n":"第七十一条","txt":"公证机构根据《公证法》第十二条规定受理的提存、登记、保管等事务，依照有关专门规定办理;没有专门规定的，参照本规则办理。"},{"i":72,"n":"第七十二条","txt":"公证机构及其公证员在办理公证过程中，有违反《公证法》第四十一条、第四十二条以及本规则规定行为的，由司法行政机关依据《公证法》、《公证机构执业管理办法》、《公证员执业管理办法》给予相应的处罚;有违反公证行业规范行为的，由公证协会给予相应的行业处分。"},{"i":73,"n":"第七十三条","txt":"本规则由司法部解释。"},{"i":74,"n":"第七十四条","txt":"本规则自2006年7月1日起施行。司法部2002年6月18日发布的《公证程序规则》(司法部令第72号)同时废止。"}],"guanyufanduilvshihangyebuzhengdangjingzhengxingweife57f1":[{"i":1,"n":"第一条","txt":"为了鼓励和保护律师、律师事务所之间的公平竞争，维护律师行为的正常执业秩序，制定本规定。"},{"i":2,"n":"第二条","txt":"律师及律师事务所的执业行为必须遵循公平、平等、诚实、信用的原则，遵守律师职业道德和执业纪律，遵守律师行业公认的执业准则。"},{"i":3,"n":"第三条","txt":"鼓励和保护一切组织和个人对律师执业不正当竞争行为进行监督。"},{"i":4,"n":"第四条","txt":"律师或律师事务所的下列行为，属不正当竞争行为： (一)通过招聘启事、律师事务所简介、领导人题写名称或其他方式，对律师或律师事务所进行不符合实际的宣传； (二)在律师名片上印有律师经历、专业技术职务或其他头衔的； (三)借助行政机关或行业管理部门的权力，或通过与某机关、部门联合设立某种形式的机构而对某地区、某部门、某行业或某一种类的法律事务进行垄断的； (四)故意诋毁其他律师或律师事务所声誉，争揽业务的； (五)无正当理由，以在规定收费标准以下收费为条件吸引客户的； (六)采用给予客户或介绍人提取“案件介绍费”或其它好处的方式承揽业务的； (七)故意在当事人与其代理律师之间制造纠纷的； (八)利用律师兼有的其他身份影响所承办业务正常处理和审理的。"},{"i":5,"n":"第五条","txt":"律师有本规定第四条第一、二项所列行为之一的，应给予警告；情节严重的，应停止执业3至6个月，并责令其消除影响； 律师有本规定第四条第三、四、五、六、七、八项所列行为之一的，给予警告；情节严重的，应停止执业3至12个月。"},{"i":6,"n":"第六条","txt":"律师事务所有本规定第四条第一、二项所列行为之一的，应给予警告；情节严重的，责令其公开澄清事实，消除影响； 律师事务所有第四条第三、四、五、六、七、八项所列行为之一的，应给予警告；情节严重的，可以停业整顿。"},{"i":7,"n":"第七条","txt":"对于实施两种或两种以上的不正当竞争行为的律师或律师事务所，应当从重处罚，直至报请司法行政机关取消其律师资格或撤消该律师事务所。"},{"i":8,"n":"第八条","txt":"律师惩戒委员会按照《律师惩戒规则》及本规定，负责对违反本规定的律师或律师事务所进行检查、监督和惩戒。"},{"i":9,"n":"第九条","txt":"地、市(州)的律师惩戒委员会负责对本辖区的律师及律师事务所的不正当竞争行为进行惩戒。 依照本规定应给予停止执业6个月以上或停业整顿以上惩戒的，应报省(自治区、直辖市)律师惩戒委员会批准决定。"},{"i":10,"n":"第十条","txt":"律师惩戒委员会受理投诉后，有权要求投诉人提供被投诉人的名称、地址，提供被投诉事项的书面材料和必要的证据；有权询问被投诉人，以及其他当事人、证人，并要求他们提供有关材料。"},{"i":11,"n":"第十一条","txt":"律师和律师事务所应当互相监督，对于有不正当竞争行为的，应当向司法机关、律师协会和律师惩戒委员会反映。司法行政机关和律师协会接到投诉的，应及时转有管辖权的律师惩戒委员会处理。"},{"i":12,"n":"第十二条","txt":"对律师或律师事务所进行的惩戒处分，应在全国或省级律师报刊上予以公告，所需费用由被惩戒的律师或律师事务所负担。"},{"i":13,"n":"第十三条","txt":"外国律师事务所驻华办事机构及其人员有不正当竞争行为的，参照本规定处罚。"},{"i":14,"n":"第十四条","txt":"本规定由司法部负责解释。"},{"i":15,"n":"第十五条","txt":"本规定自发布之日起施行。"}],"guanyuqicaosifaxingzhengfaguihezhidingbubanguizhanc970a5":[{"i":1,"n":"第一条","txt":"为了依法规范司法部司法行政法规(草案)起草和部颁规章制定工作，根据有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"司法部起草司法行政法规(草案)和制定部颁规章工作，必须以宪法、法律和行政法规为根据，贯彻依法治国基本方略，结合司法行政工作实际，坚持科学、民主、公开的原则，促进司法行政机关依法行政水平的提高。"},{"i":3,"n":"第三条","txt":"司法部起草司法行政法规(草案)和制定部颁规章工作，实行法制工作部门与业务司局相结合的工作原则，法制工作部门负责统一协商。"},{"i":4,"n":"第四条","txt":"司法部起草司法行政法规(草案)和制定部颁规章的工作计划，由法制工作部门组织业务司局草拟并提出，报部领导批准。"},{"i":5,"n":"第五条","txt":"编制司法部起草司法行政法规(草案)和制定部颁规章工作计划，可以征求各省(区、市)司法行政部门的意见以及有关部门、专家的意见。"},{"i":6,"n":"第六条","txt":"司法部起草司法行政法规(草案)和制定部颁规章工作计划，由法制工作部门负责统一协调实施。"},{"i":7,"n":"第七条","txt":"司法部起草司法行政法规(草案)计划以部名义报送国务院。"},{"i":8,"n":"第八条","txt":"司法行政法规(草案)、规章以及规范性文件的起草工作，由相关业务司局承担；必要时，法制工作部门也可以起草。"},{"i":9,"n":"第九条","txt":"业务司局在起草司法行政法规(草案)、规章以及规范性文件送审稿时，应当根据国家有关现行法律、行政法规规定进行调查研究，并对起草中涉及的主要问题进行必要的论证和说明。"},{"i":10,"n":"第十条","txt":"业务司局起草司法行政法规(草案)、规章以及规范性文件送审稿时，应当征求行政相对人、有关国家机关以及专家的意见。 业务司局根据前款规定征求意见或召开座谈会时，应当通知法制工作部门派员参加。"},{"i":11,"n":"第十一条","txt":"业务司局在司法行政法规(草案)、规章以及规范性文件送审稿起草工作完成后，应当将送审稿、有关部门和专家意见以及起草说明送法制工作部门审核。"},{"i":12,"n":"第十二条","txt":"法制工作部门审核送审稿，应当根据有关法律和政策，从有利于国家法制建设和司法行政工作发展的角度，进行审核，提出意见。"},{"i":13,"n":"第十三条","txt":"法制工作部门审核送审稿时，根据审核的需要，可以征求有关行政相对人、有关国家机关、各省(区市)司法行政部门以及专家的意见。必要时，经部领导批准，可以将审核修改稿在报刊上公布，公开征求意见。"},{"i":14,"n":"第十四条","txt":"法制工作部门审核送审稿时，审核意见与原起草的业务司局意见不一致的，应当与原起草的业务司局进行协商。协商后意见仍不一致的，法制工作部门在签报审核意见时，应当如实汇报业务司局的意见。 主管法制工作的部领导认为有必要的，可以召集法制工作部门与有关业务司局进行协调，或直接与主管该业务司局的部领导进行协商；也可以直接提交部长办公会议决定。"},{"i":15,"n":"第十五条","txt":"经法制工作部门审核修改形成的行政法规(草案)、规章以及规范性文件草案，由法制工作部门负责人签署审核意见后，报主管法制工作的部领导审查并决定提交部长办公会议审议。"},{"i":16,"n":"第十六条","txt":"部长办公会议审议司法行政法规(草案)、规章以及规范性文件草案时，由法制工作部门负责人作审核报告；根据需要，原起草的业务司局负责人对草案作起草说明。"},{"i":17,"n":"第十七条","txt":"部长办公会议审议时，根据需要可以邀请专家、行政相对人代表参加，听取其意见。"},{"i":18,"n":"第十八条","txt":"对于部长办公会议一次审议未获通过的司法行政法规(草案)、规章以及规范性文件草案，法制工作部门应当会同原起草的业务司局根据部长办公会议提出的意见进行修改，重新上报部长办公会议审议。"},{"i":19,"n":"第十九条","txt":"部长办公会议审议通过的司法行政法规(草案)，应当以司法部送审稿的发文形式报送国务院。"},{"i":20,"n":"第二十条","txt":"司法行政法规(草案)送审稿报送国务院后，由法制工作部门负责配合国务院法制工作机构进行审核修改工作。审核修改过程中，有关业务司局应当积极、主动地配合部法制工作部门的工作。"},{"i":21,"n":"第二十一条","txt":"部长办公会议审议通过的司法行政规章，以司法部部令形式发布。司法部部令由部长签署，法制工作部门统一编制序号。"},{"i":22,"n":"第二十二条","txt":"部长办公会议审议通过或部领导审定的规范性文件，由部长签署或主管法制工作的部领导和主管相关业务工作的部领导联名签署，发文形式以及编号由办公厅负责。"},{"i":23,"n":"第二十三条","txt":"司法部与其他有关部门联合发布的规范性文件，由部长会签后发布实施。"},{"i":24,"n":"第二十四条","txt":"司法部各业务司局不得以本司局名义发布面向全国适用的规范性文件。"},{"i":25,"n":"第二十五条","txt":"司法行政规章、规范性文件可以通过报刊或新闻媒体公开发布。"},{"i":26,"n":"第二十六条","txt":"司法行政规章的备案工作，由法制工作部门按照国务院有关规定办理。"},{"i":27,"n":"第二十七条","txt":"司法部受国务院委托起草司法行政法律草案的有关工作，适用本办法。"},{"i":28,"n":"第二十八条","txt":"对于全国人大常委会法制工作委员会、国务院法制办公室以及国务院有关部委征求司法部意见的法律法规草案或草稿，由法制工作部门负责组织有关业务司局研究答复。 法制工作部门对于与业务司局工作关系密切的法律法规草案或草稿，应当即时复印送相关业务司局研究，业务司局应当在规定的时间内反馈修改意见。"},{"i":29,"n":"第二十九条","txt":"法制工作部门与有关业务司局承办法律法规草案或草稿复函工作，应当从依法治国全局和司法行政工作的角度，及时高效、有理有据地提出意见。 对于重要的法律、法规草案或草稿的意见，法制工作部门应当向部领导汇报。"},{"i":30,"n":"第三十条","txt":"法制工作部门与有关业务司局可以根据需要组织有关专家和法律实务工作者对有关部门征求司法部意见的法律法规草案或草稿研究，提出意见。"},{"i":31,"n":"第三十一条","txt":"根据有关法律法规规定，涉及司法行政法律、行政法规的具体应用问题，由司法部进行解释。 司法行政规章需要明确界限或作补充规定的，由司法部进行解释。"},{"i":32,"n":"第三十二条","txt":"业务司局在征求法制工作部门的意见后，可以就个案适用法律、行政法规以及规章问题提出指导性意见，但只限于对提出请求的省(区、市)司法行政部门的相应业务处室予以答复，不得以本司局名义发布面向全国适用的解释。"},{"i":33,"n":"第三十三条","txt":"解释由有关业务司局起草，经法制工作部门审核后，报主管法制工作和相关业务工作的部领导审定。 法制工作部门也可以直接起草解释，但应当征求相关业务司局的意见。 上述解释，可以征求有关行政相对人的意见。"},{"i":34,"n":"第三十四条","txt":"解释应当经部长决定或部长办公会议审议通过，以规范性文件格式发布。"},{"i":35,"n":"第三十五条","txt":"解释包括“解释”、“批复”两种形式。"},{"i":36,"n":"第三十六条","txt":"解释需要修改或废止的，由原起草解释的业务司局提出具体意见，按照本章有关规定办理。"},{"i":37,"n":"第三十七条","txt":"司法行政法规修改和废止的建议，以及规章、规范性文件的修改和废止，适用本规定。"},{"i":38,"n":"第三十八条","txt":"司法行政法律、行政法规、规章以及规范性文件由法制工作部门负责按年度汇编出版，公开发行。"},{"i":39,"n":"第三十九条","txt":"法制工作部门负责组织对司法行政法律、行政法规、规章以及规范性文件的实施情况进行调查研究，提出修改、废止意见，向部领导汇报。"},{"i":40,"n":"第四十条","txt":"本规定自发布之日起实施。一九八九年一月二十日司法部部令第一号《司法部关于起草司法行政法律、法规和制定规章的规定》同时废止。"}],"banlifalvyuanzhuanjianchengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范办理法律援助案件程序，保证法律援助质量，根据《中华人民共和国法律援助法》《法律援助条例》等有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"法律援助机构组织办理法律援助案件，律师事务所、基层法律服务所和法律援助人员承办法律援助案件，适用本规定。 本规定所称法律援助人员，是指接受法律援助机构的指派或者安排，依法为经济困难公民和符合法定条件的其他当事人提供法律援助服务的律师、基层法律服务工作者、法律援助志愿者以及法律援助机构中具有律师资格或者法律职业资格的工作人员等。"},{"i":3,"n":"第三条","txt":"办理法律援助案件应当坚持中国共产党领导，坚持以人民为中心，尊重和保障人权，遵循公开、公平、公正的原则。"},{"i":4,"n":"第四条","txt":"法律援助机构应当建立健全工作机制，加强信息化建设，为公民获得法律援助提供便利。 法律援助机构为老年人、残疾人提供法律援助服务的，应当根据实际情况提供无障碍设施设备和服务。"},{"i":5,"n":"第五条","txt":"法律援助人员应当依照法律、法规及本规定，遵守有关法律服务业务规程，及时为受援人提供符合标准的法律援助服务，维护受援人的合法权益。"},{"i":6,"n":"第六条","txt":"法律援助人员应当恪守职业道德和执业纪律，自觉接受监督，不得向受援人收取任何财物。"},{"i":7,"n":"第七条","txt":"法律援助机构、法律援助人员对提供法律援助过程中知悉的国家秘密、商业秘密和个人隐私应当予以保密。"},{"i":8,"n":"第八条","txt":"法律援助机构应当向社会公布办公地址、联系方式等信息，在接待场所和司法行政机关政府网站公示并及时更新法律援助条件、程序、申请材料目录和申请示范文本等。"},{"i":9,"n":"第九条","txt":"法律援助机构组织法律援助人员，依照有关规定和服务规范要求提供法律咨询、代拟法律文书、值班律师法律帮助。法律援助人员在提供法律咨询、代拟法律文书、值班律师法律帮助过程中，对可能符合代理或者刑事辩护法律援助条件的，应当告知其可以依法提出申请。"},{"i":10,"n":"第十条","txt":"对诉讼事项的法律援助，由申请人向办案机关所在地的法律援助机构提出申请；对非诉讼事项的法律援助，由申请人向争议处理机关所在地或者事由发生地的法律援助机构提出申请。 申请人就同一事项向两个以上有管辖权的法律援助机构提出申请的，由最先收到申请的法律援助机构受理。"},{"i":11,"n":"第十一条","txt":"因经济困难申请代理、刑事辩护法律援助的，申请人应当如实提交下列材料： (一)法律援助申请表； (二)居民身份证或者其他有效身份证明，代为申请的还应当提交有代理权的证明； (三)经济困难状况说明表，如有能够说明经济状况的证件或者证明材料，可以一并提供； (四)与所申请法律援助事项有关的其他材料。 填写法律援助申请表、经济困难状况说明表确有困难的，由法律援助机构工作人员或者转交申请的机关、单位工作人员代为填写，申请人确认无误后签名或者按指印。 符合《中华人民共和国法律援助法》第三十二条规定情形的当事人申请代理、刑事辩护法律援助的，应当提交第一款第一项、第二项、第四项规定的材料。"},{"i":12,"n":"第十二条","txt":"被羁押的犯罪嫌疑人、被告人、服刑人员以及强制隔离戒毒人员等提出法律援助申请的，可以通过办案机关或者监管场所转交申请。办案机关、监管场所应当在二十四小时内将申请材料转交法律援助机构。 犯罪嫌疑人、被告人通过值班律师提出代理、刑事辩护等法律援助申请的，值班律师应当在二十四小时内将申请材料转交法律援助机构。"},{"i":13,"n":"第十三条","txt":"法律援助机构对申请人提出的法律援助申请，应当根据下列情况分别作出处理： (一)申请人提交的申请材料符合规定的，应当予以受理，并向申请人出具收到申请材料的书面凭证，载明收到申请材料的名称、数量、日期等； (二)申请人提交的申请材料不齐全，应当一次性告知申请人需要补充的全部内容，或者要求申请人作出必要的说明。申请人未按要求补充材料或者作出说明的，视为撤回申请； (三)申请事项不属于本法律援助机构受理范围的，应当告知申请人向有管辖权的法律援助机构申请或者向有关部门申请处理。"},{"i":14,"n":"第十四条","txt":"法律援助机构应当对法律援助申请进行审查，确定是否具备下列条件： (一)申请人系公民或者符合法定条件的其他当事人； (二)申请事项属于法律援助范围； (三)符合经济困难标准或者其他法定条件。"},{"i":15,"n":"第十五条","txt":"法律援助机构核查申请人的经济困难状况，可以通过信息共享查询，或者由申请人进行个人诚信承诺。 法律援助机构开展核查工作，可以依法向有关部门、单位、村民委员会、居民委员会或者个人核实有关情况。"},{"i":16,"n":"第十六条","txt":"受理申请的法律援助机构需要异地核查有关情况的，可以向核查事项所在地的法律援助机构请求协作。 法律援助机构请求协作的，应当向被请求的法律援助机构发出协作函件，说明基本情况、需要核查的事项、办理时限等。被请求的法律援助机构应当予以协作。因客观原因无法协作的，应当及时向请求协作的法律援助机构书面说明理由。"},{"i":17,"n":"第十七条","txt":"法律援助机构应当自收到法律援助申请之日起七日内进行审查，作出是否给予法律援助的决定。 申请人补充材料、作出说明所需的时间，法律援助机构请求异地法律援助机构协作核查的时间，不计入审查期限。"},{"i":18,"n":"第十八条","txt":"法律援助机构经审查，对于有下列情形之一的，应当认定申请人经济困难： （一）申请人及与其共同生活的家庭成员符合受理的法律援助机构所在省、自治区、直辖市人民政府规定的经济困难标准的； （二）申请事项的对方当事人是与申请人共同生活的家庭成员，申请人符合受理的法律援助机构所在省、自治区、直辖市人民政府规定的经济困难标准的； （三）符合《中华人民共和国法律援助法》第四十二条规定，申请人所提交材料真实有效的。"},{"i":19,"n":"第十九条","txt":"法律援助机构经审查，对符合法律援助条件的，应当决定给予法律援助，并制作给予法律援助决定书；对不符合法律援助条件的，应当决定不予法律援助，并制作不予法律援助决定书。 不予法律援助决定书应当载明不予法律援助的理由及申请人提出异议的途径和方式。"},{"i":20,"n":"第二十条","txt":"给予法律援助决定书或者不予法律援助决定书应当发送申请人；属于《中华人民共和国法律援助法》第三十九条规定情形的，法律援助机构还应当同时函告有关办案机关、监管场所。"},{"i":21,"n":"第二十一条","txt":"法律援助机构依据《中华人民共和国法律援助法》第四十四条规定先行提供法律援助的，受援人应当在法律援助机构要求的时限内，补办有关手续，补充有关材料。"},{"i":22,"n":"第二十二条","txt":"申请人对法律援助机构不予法律援助的决定有异议的，应当自收到决定之日起十五日内向设立该法律援助机构的司法行政机关提出。"},{"i":23,"n":"第二十三条","txt":"司法行政机关应当自收到异议之日起五日内进行审查，认为申请人符合法律援助条件的，应当以书面形式责令法律援助机构对该申请人提供法律援助，同时书面告知申请人；认为申请人不符合法律援助条件的，应当作出维持法律援助机构不予法律援助的决定，书面告知申请人并说明理由。 申请人对司法行政机关维持法律援助机构决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":24,"n":"第二十四条","txt":"法律援助机构应当自作出给予法律援助决定之日起三日内依法指派律师事务所、基层法律服务所安排本所律师或者基层法律服务工作者，或者安排本机构具有律师资格或者法律职业资格的工作人员承办法律援助案件。 对于通知辩护或者通知代理的刑事法律援助案件，法律援助机构收到人民法院、人民检察院、公安机关要求指派律师的通知后，应当在三日内指派律师承办法律援助案件，并通知人民法院、人民检察院、公安机关。"},{"i":25,"n":"第二十五条","txt":"法律援助机构应当根据本机构、律师事务所、基层法律服务所的人员数量、专业特长、执业经验等因素，合理指派承办机构或者安排法律援助机构工作人员承办案件。 律师事务所、基层法律服务所收到指派后，应当及时安排本所律师、基层法律服务工作者承办法律援助案件。"},{"i":26,"n":"第二十六条","txt":"对可能被判处无期徒刑、死刑的人，以及死刑复核案件的被告人，法律援助机构收到人民法院、人民检察院、公安机关通知后，应当指派具有三年以上刑事辩护经历的律师担任辩护人。 对于未成年人刑事案件，法律援助机构收到人民法院、人民检察院、公安机关通知后，应当指派熟悉未成年人身心特点的律师担任辩护人。"},{"i":27,"n":"第二十七条","txt":"法律援助人员所属单位应当自安排或者收到指派之日起五日内与受援人或者其法定代理人、近亲属签订委托协议和授权委托书，但因受援人原因或者其他客观原因无法按时签订的除外。"},{"i":28,"n":"第二十八条","txt":"法律援助机构已指派律师为犯罪嫌疑人、被告人提供辩护，犯罪嫌疑人、被告人的监护人或者近亲属又代为委托辩护人，犯罪嫌疑人、被告人决定接受委托辩护的，律师应当及时向法律援助机构报告。法律援助机构按照有关规定进行处理。"},{"i":29,"n":"第二十九条","txt":"律师承办刑事辩护法律援助案件，应当依法及时会见犯罪嫌疑人、被告人，了解案件情况并制作笔录。笔录应当经犯罪嫌疑人、被告人确认无误后签名或者按指印。犯罪嫌疑人、被告人无阅读能力的，律师应当向犯罪嫌疑人、被告人宣读笔录，并在笔录上载明。 对于通知辩护的案件，律师应当在首次会见犯罪嫌疑人、被告人时，询问是否同意为其辩护，并记录在案。犯罪嫌疑人、被告人不同意的，律师应当书面告知人民法院、人民检察院、公安机关和法律援助机构。"},{"i":30,"n":"第三十条","txt":"法律援助人员承办刑事代理、民事、行政等法律援助案件，应当约见受援人或者其法定代理人、近亲属，了解案件情况并制作笔录，但因受援人原因无法按时约见的除外。 法律援助人员首次约见受援人或者其法定代理人、近亲属时，应当告知下列事项： （一）法律援助人员的代理职责； （二）发现受援人可能符合司法救助条件的，告知其申请方式和途径； （三）本案主要诉讼风险及法律后果； （四）受援人在诉讼中的权利和义务。"},{"i":31,"n":"第三十一条","txt":"法律援助人员承办案件，可以根据需要依法向有关单位或者个人调查与承办案件有关的情况，收集与承办案件有关的材料，并可以根据需要请求法律援助机构出具必要的证明文件或者与有关机关、单位进行协调。 法律援助人员认为需要异地调查情况、收集材料的，可以向作出指派或者安排的法律援助机构报告。法律援助机构可以按照本规定第十六条向调查事项所在地的法律援助机构请求协作。"},{"i":32,"n":"第三十二条","txt":"法律援助人员可以帮助受援人通过和解、调解及其他非诉讼方式解决纠纷，依法最大限度维护受援人合法权益。 法律援助人员代理受援人以和解或者调解方式解决纠纷的，应当征得受援人同意。"},{"i":33,"n":"第三十三条","txt":"对处于侦查、审查起诉阶段的刑事辩护法律援助案件，承办律师应当积极履行辩护职责，在办案期限内依法完成会见、阅卷，并根据案情提出辩护意见。"},{"i":34,"n":"第三十四条","txt":"对于开庭审理的案件，法律援助人员应当做好开庭前准备；庭审中充分发表意见、举证、质证；庭审结束后，应当向人民法院或者劳动人事争议仲裁机构提交书面法律意见。 对于不开庭审理的案件，法律援助人员应当在会见或者约见受援人、查阅案卷材料、了解案件主要事实后，及时向人民法院提交书面法律意见。"},{"i":35,"n":"第三十五条","txt":"法律援助人员应当向受援人通报案件办理情况，答复受援人询问，并制作通报情况记录。"},{"i":36,"n":"第三十六条","txt":"法律援助人员应当按照法律援助机构要求报告案件承办情况。 法律援助案件有下列情形之一的，法律援助人员应当向法律援助机构报告： （一）主要证据认定、适用法律等方面存在重大疑义的； （二）涉及群体性事件的； （三）有重大社会影响的； （四）其他复杂、疑难情形。"},{"i":37,"n":"第三十七条","txt":"受援人有证据证明法律援助人员未依法履行职责的，可以请求法律援助机构更换法律援助人员。 法律援助机构应当自受援人申请更换之日起五日内决定是否更换。决定更换的，应当另行指派或者安排人员承办。对犯罪嫌疑人、被告人具有应当通知辩护情形，人民法院、人民检察院、公安机关决定为其另行通知辩护的，法律援助机构应当另行指派或者安排人员承办。法律援助机构应当及时将变更情况通知办案机关。 更换法律援助人员的，原法律援助人员所属单位应当与受援人解除或者变更委托协议和授权委托书，原法律援助人员应当与更换后的法律援助人员办理案件材料移交手续。"},{"i":38,"n":"第三十八条","txt":"法律援助人员在承办案件过程中，发现与本案存在利害关系或者因客观原因无法继续承办案件的，应当向法律援助机构报告。法律援助机构认为需要更换法律援助人员的，按照本规定第三十七条办理。"},{"i":39,"n":"第三十九条","txt":"存在《中华人民共和国法律援助法》第四十八条规定情形，法律援助机构决定终止法律援助的，应当制作终止法律援助决定书，并于三日内，发送受援人、通知法律援助人员所属单位并函告办案机关。 受援人对法律援助机构终止法律援助的决定有异议的，按照本规定第二十二条、第二十三条办理。"},{"i":40,"n":"第四十条","txt":"法律援助案件办理结束后，法律援助人员应当及时向法律援助机构报告，并自结案之日起三十日内向法律援助机构提交结案归档材料。 刑事诉讼案件侦查阶段应以承办律师收到起诉意见书或撤销案件的相关法律文书之日为结案日；审查起诉阶段应以承办律师收到起诉书或不起诉决定书之日为结案日；审判阶段以承办律师收到判决书、裁定书、调解书之日为结案日。其他诉讼案件以法律援助人员收到判决书、裁定书、调解书之日为结案日。劳动争议仲裁案件或者行政复议案件以法律援助人员收到仲裁裁决书、行政复议决定书之日为结案日。其他非诉讼法律事务以受援人与对方当事人达成和解、调解协议之日为结案日。无相关文书的，以义务人开始履行义务之日为结案日。法律援助机构终止法律援助的，以法律援助人员所属单位收到终止法律援助决定书之日为结案日。"},{"i":41,"n":"第四十一条","txt":"法律援助机构应当自收到法律援助人员提交的结案归档材料之日起三十日内进行审查。对于结案归档材料齐全规范的，应当及时向法律援助人员支付法律援助补贴。"},{"i":42,"n":"第四十二条","txt":"法律援助机构应当对法律援助案件申请、审查、指派等材料以及法律援助人员提交的结案归档材料进行整理，一案一卷，统一归档管理。"},{"i":43,"n":"第四十三条","txt":"法律援助机构、律师事务所、基层法律服务所和法律援助人员从事法律援助活动违反本规定的，依照《中华人民共和国法律援助法》《中华人民共和国律师法》《法律援助条例》《律师和律师事务所违法行为处罚办法》等法律、法规和规章的规定追究法律责任。"},{"i":44,"n":"第四十四条","txt":"本规定中期间开始的日，不算在期间以内。期间的最后一日是节假日的，以节假日后的第一日为期满日期。"},{"i":45,"n":"第四十五条","txt":"法律援助文书格式由司法部统一规定。"},{"i":46,"n":"第四十六条","txt":"本规定自2023年9月1日起施行。司法部2012年4月9日公布的《办理法律援助案件程序规定》（司法部令第124号）同时废止。"}],"qudeneidifalvzhiyezigedexianggangtebiexingzhengquh1c428d":[{"i":1,"n":"第一条","txt":"为了落实国务院批准的《内地与香港关于建立更紧密经贸关系的安排》和《内地与澳门关于建立更紧密经贸关系的安排》，规范取得内地法律职业资格的香港、澳门居民在内地从事律师职业的活动及管理，根据《中华人民共和国律师法》(以下简称《律师法》)及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"参加内地举行的国家司法考试合格，取得《中华人民共和国法律职业资格证书》的香港、澳门居民，可以在内地申请律师执业。"},{"i":3,"n":"第三条","txt":"取得内地法律职业资格的香港、澳门居民申请在内地律师事务所执业，应当依照司法部的有关规定参加实习，申请领取律师执业证。"},{"i":4,"n":"第四条","txt":"取得内地律师执业证的香港、澳门居民在内地律师事务所执业，可以从事内地非诉讼法律事务，可以代理涉港澳民事案件，代理涉港澳民事案件的范围由司法部以公告方式作出规定。 取得内地律师执业证的香港、澳门居民在内地从事涉港澳民事案件的代理活动应当依据有关具体规定办理。"},{"i":5,"n":"第五条","txt":"取得内地律师执业证的香港、澳门居民在内地律师事务所执业，应当遵守国家法律、法规和规章，恪守律师职业道德和执业纪律，接受内地司法行政机关的监督和管理，接受内地律师协会的行业管理。"},{"i":6,"n":"第六条","txt":"取得内地法律职业资格的香港、澳门居民申请在内地律师事务所执业的，除有本办法第十一条规定情形外，应当依照《律师法》、司法部和中华全国律师协会有关申请律师执业人员实习管理的规定，先在内地律师事务所参加为期1年的实习。香港居民参加实习，可以安排在内地律师事务所设在香港的分所进行。"},{"i":7,"n":"第七条","txt":"取得内地法律职业资格的香港、澳门居民在内地律师事务所参加实习，应当向拟选择进行实习的内地律师事务所提出申请。拟选择在内地律师事务所设在香港的分所进行实习的，可直接向内地律师事务所分所提出申请。 香港、澳门居民申请实习，由拟接收其实习的内地律师事务所向所在地的地(市)级律师协会办理实习登记，并按规定向地(市)级司法行政机关备案。"},{"i":8,"n":"第八条","txt":"在内地律师事务所或者内地律师事务所设在香港的分所实习的香港、澳门居民，应当按照内地实习管理的有关规定参加集中培训和实务训练，实务训练以办理非诉讼法律事务及代理有关涉港澳民事案件的训练为主，并遵守有关实习的规定和纪律。 接受香港、澳门居民实习的内地律师事务所或其分所，应当指派擅长办理非诉讼法律事务及代理涉港澳民事案件的律师指导实习人员进行实务训练。每名指导律师只能指导一名香港或者澳门的实习人员。"},{"i":9,"n":"第九条","txt":"在内地律师事务所或者内地律师事务所设在香港的分所实习的香港、澳门居民，应当确保参加实习的时间。因故暂停实习的时间最长不得超过3个月，并应当由接收实习的内地律师事务所将其暂停实习的原因和时间报所在地的地(市)级律师协会备案。"},{"i":10,"n":"第十条","txt":"取得内地法律职业资格的香港、澳门居民在内地律师事务所或者内地律师事务所设在香港的分所实习，由该内地律师事务所所在地的地(市)级律师协会依照规定予以监督和考核。 香港、澳门居民实习期满，由内地律师事务所出具实习鉴定意见，报所在地的地(市)级律师协会审查，并由其对实习人员进行考核。律师事务所的实习鉴定意见和律师协会的考核结果，由地(市)级律师协会报当地地(市)级司法行政机关备案。"},{"i":11,"n":"第十一条","txt":"取得内地法律职业资格的香港、澳门居民属于具有5年以上执业经历的香港法律执业者、澳门律师的，在内地申请律师执业，应当参加由内地地方律师协会组织的不少于1个月的集中培训，并经考核合格。 前款规定的香港法律执业者、澳门律师应当通过拟聘其执业的内地律师事务所向住所地的地(市)级律师协会申请参加培训。申请培训，除按照实习管理规定提交相关材料外，应当同时提交由香港律师会、大律师公会或者澳门律师公会出具并经内地认可的公证人公证的申请人在香港、澳门执业经历、年限的证明。"},{"i":12,"n":"第十二条","txt":"取得内地法律职业资格的香港、澳门居民，在内地律师事务所或者内地律师事务所设在香港的分所实习期满，经律师事务所鉴定和律师协会考核合格的，可以在内地申请律师执业。"},{"i":13,"n":"第十三条","txt":"获准在内地执业的香港、澳门居民，只能在一个内地律师事务所执业，不得同时受聘于外国律师事务所驻华代表机构或者香港、澳门律师事务所驻内地代表机构。"},{"i":14,"n":"第十四条","txt":"取得内地法律职业资格的香港、澳门居民在内地申请律师执业，应当依照《律师法》和司法部制定的《律师执业管理办法》的规定，向拟聘其执业的内地律师事务所住所地设区的市级或者直辖市区(县)司法行政机关提出申请，由其出具审查意见后报省级司法行政机关审核，作出是否准予申请人在内地执业的决定。 申请人按规定提交的文件中，其身份证明复印件和未受过刑事处罚的证明材料须经内地认可的公证人公证，同时还须说明是否具有香港、澳门、台湾地区或者外国律师资格以及是否受聘于香港、澳门、台湾地区或者外国律师事务所的情况。符合本办法第十一条规定情形的申请人应当同时提交由香港律师会、大律师公会或者澳门律师公会出具并经内地认可的公证人公证的申请人在香港、澳门的执业经历、年限的证明。 省级司法行政机关经审核予以颁发律师执业证的，应当自颁证之日起30日内将获准在内地执业的香港、澳门居民名单及执业登记材料报司法部备案。"},{"i":15,"n":"第十五条","txt":"获准在内地执业的香港、澳门居民，可以采取担任法律顾问、代理、咨询、代书等方式从事内地非诉讼法律事务，也可以采取担任诉讼代理人的方式代理涉港澳民事案件，享有相应的律师权利，履行相应的律师义务。"},{"i":16,"n":"第十六条","txt":"获准在内地执业的香港、澳门居民，符合规定条件的，可以成为内地律师事务所的合伙人。"},{"i":17,"n":"第十七条","txt":"获准在内地执业的香港、澳门居民，应当加入内地律师协会，享有会员的权利，履行会员的义务，参加内地律师协会组织的业务培训和交流活动。"},{"i":18,"n":"第十八条","txt":"获准在内地执业的香港、澳门居民，有违反《律师法》、司法部有关律师执业管理规章和本办法规定的行为的，依法给予相应的行政处罚；有违反律师职业道德和执业纪律行为的，给予相应的行业处分。"},{"i":19,"n":"第十九条","txt":"司法行政机关工作人员在行政管理活动中，有违反法律、法规和规章规定的行为的，依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"在内地实行国家司法考试前已考取内地律师资格的香港、澳门居民，申请在内地律师事务所实习和执业，依照本办法办理。"},{"i":21,"n":"第二十一条","txt":"本办法由司法部解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2004年1月1日起施行。"}],"qudeguojiafalvzhiyezigedetaiwanjuminzaidalucongshie70d9e":[{"i":1,"n":"第一条","txt":"为规范取得国家法律职业资格的台湾居民在大陆从事律师职业的活动及管理，根据《中华人民共和国律师法》(以下简称《律师法》)及《律师执业管理办法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"参加国家司法考试合格，取得《中华人民共和国法律职业资格证书》的台湾居民，可以依法在大陆申请律师执业。 台湾居民在大陆申请律师执业，还应当符合《律师法》规定的其他条件。"},{"i":3,"n":"第三条","txt":"台湾居民获准在大陆律师事务所执业，可以担任法律顾问、代理、咨询、代书等方式从事大陆非诉讼法律事务，也可以担任诉讼代理人的方式代理涉台民事案件，代理涉台民事案件的范围由司法部以公告方式作出规定。 台湾居民在大陆律师事务所执业，应当遵守国家法律、法规和规章，恪守律师职业道德和执业纪律，接受大陆司法行政机关的监督和管理，接受大陆律师协会的行业管理。"},{"i":4,"n":"第四条","txt":"台湾居民在大陆申请律师执业的，应当根据《律师法》、《律师执业管理办法》和中华全国律师协会制定的《申请律师执业人员实习管理规则》的规定，在大陆律师事务所参加为期一年的实习，并经当地地方律师协会考核合格。 台湾居民在大陆律师事务所实习，应当按照规定参加集中培训和实务训练，实务训练以办理非诉讼法律事务及代理有关涉台民事案件的训练为主，并遵守有关实习规定和纪律。 接收台湾居民实习的律师事务所应当指派擅长办理相关业务的律师指导实务训练。一名指导律师只能指导一名台湾居民实习。 台湾居民实习，应当确保参加实习的时间。因故暂停实习的时间最长不得超过三个月，并应当由接收实习的律师事务所将其暂停实习的原因和时间报所在地地市级律师协会备案。"},{"i":5,"n":"第五条","txt":"台湾居民申请律师执业，应当根据《律师法》和《律师执业管理办法》的有关规定，向设区的市级或者直辖市的区(县)司法行政机关提出申请，并提交与申请执业相关的证明材料。 台湾居民申请律师执业，提交的身份证明和其他在台湾地区出具的证明材料应当经台湾地区的公证机构公证，同时还应当书面说明是否具有台湾、香港、澳门地区或者外国律师资格以及是否受聘于台湾、香港、澳门地区或者外国律师事务所的情况。"},{"i":6,"n":"第六条","txt":"台湾居民申请律师执业，由设区的市级或者直辖市的区(县)司法行政机关受理申请，并进行初审，报省、自治区、直辖市司法行政机关审核，作出是否准予执业的决定。具体许可程序，根据《律师法》和《律师执业管理办法》的规定办理。"},{"i":7,"n":"第七条","txt":"台湾居民获准在大陆执业的，由准予其执业的省、自治区、直辖市司法行政机关自颁发律师执业证书之日起三十日内，将准予执业的决定及相关材料报司法部备案。"},{"i":8,"n":"第八条","txt":"台湾居民在大陆律师事务所执业，依法享有大陆律师相应的执业权利，履行相应的律师义务。"},{"i":9,"n":"第九条","txt":"获准执业的台湾居民，只能在一个大陆律师事务所执业，不得同时受聘于外国律师事务所驻华代表机构或者香港、澳门律师事务所驻内地代表机构。"},{"i":10,"n":"第十条","txt":"获准执业的台湾居民，符合规定条件的，可以成为大陆律师事务所的合伙人。"},{"i":11,"n":"第十一条","txt":"获准执业的台湾居民，应当加入大陆律师协会，享有会员的权利，履行会员的义务，参加大陆律师协会组织的业务培训和交流活动。"},{"i":12,"n":"第十二条","txt":"获准执业的台湾居民，有违反《律师法》、《律师执业管理办法》和本办法规定的行为的，依法给予相应的行政处罚；有违反律师职业道德和执业纪律行为的，给予相应的行业惩戒。"},{"i":13,"n":"第十三条","txt":"在实行国家司法考试前已取得大陆律师资格的台湾居民，在大陆申请律师执业的，依照本办法办理。"},{"i":14,"n":"第十四条","txt":"本办法自2009年1月1日起施行。"}],"taiwanjumincanjiaguojiasifakaoshiruoganguiding":[{"i":1,"n":"第一条","txt":"为规范台湾居民参加国家司法考试，根据《国家司法考试实施办法(试行)》，制定本规定。"},{"i":2,"n":"第二条","txt":"具有台湾地区居民身份的人员可以报名参加国家司法考试。"},{"i":3,"n":"第三条","txt":"台湾居民参加国家司法考试的报名条件、报名时间、报名方式、考试科目、考试内容、考试时间、应试规则、合格标准以及合格后授予国家法律职业资格的办法，适用《国家司法考试实施办法(试行)》以及有关国家司法考试规章的统一规定。 台湾居民参加国家司法考试的报名地点、考试地点以及考试合格申请授予资格的方式，按照本规定以及司法部有关台湾居民参加考试的年度安排执行。"},{"i":4,"n":"第四条","txt":"台湾居民报名参加国家司法考试，在大陆工作、学习或者居住的，应当在其居所地司法行政机关指定的报名点报名；在香港、澳门工作、学习或者居住的，应当在香港、澳门向承办考试组织工作的机构报名；在台湾地区或者外国工作、学习或者居住的，应当到司法部在大陆指定的报名点报名。"},{"i":5,"n":"第五条","txt":"台湾居民在考试报名时，应当向受理报名的机构提交以下证明其符合本规定第二条规定条件的有效身份证明： 台湾居民来往大陆通行证(简称台胞证)和台湾居民身份证； 不能提交台湾居民来往大陆通行证的，应当提交台湾居民身份证和户籍誊本或者户口名簿。提交户籍誊本或者户口名簿复印件的，须经台湾地区公证机构公证。 受理报名的机构认为必要时，可以要求报名人同时提交其他有关证明。"},{"i":6,"n":"第六条","txt":"台湾居民在考试报名时，持大陆高等院校学历(学位)证书的，可以向受理报名的机构直接办理报名手续；持台湾、香港、澳门地区高等院校或者外国高等院校学历(学位)证书报名的，须同时提交经教育部有关机构出具的学历(学位)认证证明。"},{"i":7,"n":"第七条","txt":"台湾居民参加国家司法考试，在大陆报名的，应当在报名地司法行政机关设置的考场参加考试；在香港、澳门报名的，应当在香港、澳门承办考试组织工作的机构所确定的本地考场参加考试。"},{"i":8,"n":"第八条","txt":"台湾居民参加国家司法考试合格的，可以根据《法律职业资格证书管理办法》的规定，申请授予法律职业资格。 在大陆报名参加考试合格的人员，向报名地司法行政机关递交申请及有关材料，由其按照规定程序审查上报。 在香港、澳门报名参加考试合格的人员，向司法部委托的承办资格申请受理事务的大陆驻港澳机构递交申请及有关材料，由其按照规定程序上报司法部进行审查。"},{"i":9,"n":"第九条","txt":"台湾居民取得国家法律职业资格，在大陆申请律师执业的，依照司法部有关规定办理。"},{"i":10,"n":"第十条","txt":"台湾居民报名参加国家司法考试的具体安排，由司法部在年度国家司法考试公告以及国家司法考试办公室相关文件中公布。"},{"i":11,"n":"第十一条","txt":"本规定由司法部解释。"},{"i":12,"n":"第十二条","txt":"本规定自发布之日起施行。"}],"sifaxingzhengjiguanxinfanggongzuobanfa":[{"i":1,"n":"第一条","txt":"为规范司法行政机关信访工作，依法保障信访人的合法权益，维护信访工作秩序，根据《信访条例》和国家有关规定，结合司法行政工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称信访，是指公民、法人和其他非法人组织采取书信、电子邮件、传真、电话、走访等形式，向司法行政机关反映情况，提出建议、意见或者投诉请求，依法由司法行政机关处理的活动。 本办法所称信访人，是指采用前款规定的形式，向司法行政机关反映情况，提出建议、意见或者投诉请求的公民、法人和其他非法人组织。"},{"i":3,"n":"第三条","txt":"司法行政机关应当成立司法行政机关信访工作领导小组，建立统一领导、分工协作、各负其责、齐抓共管的信访工作格局，及时有效化解矛盾纠纷。"},{"i":4,"n":"第四条","txt":"司法行政机关信访工作应当遵循下列原则： (一)公开便民、公平合理； (二)属地管理、分级负责，谁主管、谁负责； (三)实行诉讼、仲裁、行政复议、国家赔偿、法律服务执业投诉与信访相分离； (四)依法、及时、就地解决问题与疏导教育相结合。"},{"i":5,"n":"第五条","txt":"司法行政机关应当建立健全联系群众制度，负责人应当通过阅批重要来信、接待重要来访、定期听取信访工作汇报等方式，听取群众意愿，了解社情民意，研究解决信访工作中的突出问题。"},{"i":6,"n":"第六条","txt":"司法行政机关应当科学、民主决策，依法履行职责，建立健全矛盾纠纷预防和化解机制，开展重大决策社会稳定风险评估，从源头预防导致信访事项的矛盾和纠纷。"},{"i":7,"n":"第七条","txt":"司法行政机关应当建立信访事项办理与人民调解、行政调解、法律援助的衔接机制，协调有关部门，组织人民调解组织、法律援助机构或者相关专家学者、社会志愿者等共同参与，为符合条件的信访人提供法律援助，依法调解、化解信访事项。"},{"i":8,"n":"第八条","txt":"司法行政机关应当建立律师参与信访工作机制，通过政府购买服务、公益加补助等方式，组织律师参与接待群众来访，办理复杂疑难信访事项。"},{"i":9,"n":"第九条","txt":"司法行政机关应当建立信访工作责任制，将信访工作绩效纳入公务员考核体系，对信访工作中的失职、渎职行为，依法追究相关人员的责任，对做出优异成绩的单位或者个人给予奖励。"},{"i":10,"n":"第十条","txt":"司法行政机关应当按照有利工作、方便信访人的原则，确定负责信访工作的机构，配备与信访工作需要相适应的信访工作人员。"},{"i":11,"n":"第十一条","txt":"司法行政机关应当确定政治坚定、业务精通、作风优良，具有相应法律知识、政策水平和群众工作经验的人员从事信访工作。 司法行政机关应当建立健全信访工作人员培训、交流机制，提高信访工作人员的工作能力和水平。"},{"i":12,"n":"第十二条","txt":"司法行政机关信访工作机构应当配备必要的安全防护设施、装备，提高信访工作人员的安全防护意识，建立健全突发事件应对处置机制。"},{"i":13,"n":"第十三条","txt":"司法行政机关信访工作机构应当履行下列职责： (一)登记信访事项，受理属于本机关职责范围的信访事项； (二)向本机关有关内设机构或者所属单位、下级司法行政机关转办、交办信访事项； (三)承办上级机关和本级人民政府转办、交办的信访事项； (四)向信访人宣传有关法律、法规、规章和政策，解答信访咨询； (五)协调、督促检查信访事项的办理； (六)研究、分析信访工作情况，定期编写信访工作信息，提出完善制度或者改进工作的建议，向本机关报告； (七)总结交流信访工作经验，指导下级司法行政机关信访工作机构工作； (八)向本机关和上一级司法行政机关定期报送信访情况分析统计报告。"},{"i":14,"n":"第十四条","txt":"司法行政机关应当在信访接待场所、门户网站或者通过其他方式向社会公开信访工作机构的网络信访工作平台、通信地址、电子邮箱、咨询投诉电话、信访接待的时间和地点，本机关信访事项受理范围和办理程序，以及查询信访事项办理进展和结果的方式等相关事项。"},{"i":15,"n":"第十五条","txt":"司法行政机关应当建立负责人信访接待、处理信访事项制度，由司法行政机关负责人直接协调办理信访事项。 司法行政机关负责人或者其指定的人员，可以就信访人反映突出的问题到信访人居住地与信访人面谈沟通。"},{"i":16,"n":"第十六条","txt":"司法行政机关应当充分利用政务信息网络资源，建立网络信访工作平台，运用信访信息系统，为信访人通过网络提出信访事项、查询信访事项办理情况提供便利，提高信访工作信息化水平。"},{"i":17,"n":"第十七条","txt":"信访人向司法行政机关提出信访事项，一般应当采用书信、电子邮件、传真等书面形式。信访人提出投诉请求的，还应当载明信访人的姓名(名称)、性别、身份证号码、联系方式、住址和请求、事实、理由。 对采用口头形式提出的投诉请求，司法行政机关应当记录信访人的姓名(名称)、性别、身份证号码、联系方式、住址和请求、事实、理由。"},{"i":18,"n":"第十八条","txt":"信访人采用走访形式提出信访事项的，应当持本人有效身份证件到司法行政机关设立或者指定的接待场所提出。 多人采用走访形式提出共同的信访事项的，应当推选代表，代表人数不得超过5人。"},{"i":19,"n":"第十九条","txt":"司法行政机关信访工作机构收到信访事项后，应当进行登记。登记内容包括：登记号、登记人、信访人姓名(名称)、性别、身份证号码、住址、收到信访事项的日期、信访事项摘要、联系方式等。 司法行政机关其他内设机构收到信访人提出的信访事项，应当及时转交本机关信访工作机构。 司法行政机关信访工作人员应当告知信访人提出信访事项需要采取的形式以及多人走访的相关要求等重点事项，做好耐心细致的沟通解释工作。"},{"i":20,"n":"第二十条","txt":"司法行政机关信访工作的受理范围根据本机关的职责范围确定。 司法行政机关信访工作机构收到信访事项，在15日内按照下列方式处理： (一)属于本级司法行政机关工作职责范围的信访事项，应当直接受理，并根据所反映问题的性质、内容确定办理机构。对于反映司法行政机关及其工作人员违法违纪行为的信访事项，转交有关纪检监察机关或者部门； (二)信访事项涉及下级司法行政机关的，应当转送下级司法行政机关办理。对其中的重要信访事项，可以向下级司法行政机关进行交办，要求其在规定的期限内反馈结果，并提交办结报告； (三)属于本级司法行政机关所属单位办理的信访事项，应当转送相关单位办理或者向相关单位进行交办； (四)已经或者依法应当通过诉讼、仲裁、行政复议、国家赔偿、法律服务执业投诉等法定途径解决的信访事项，应当告知信访人按照有关规定向有关机关、单位提出； (五)依法不属于司法行政机关职责范围的事项，应当告知信访人向"},{"i":21,"n":"第二十一条","txt":"司法行政机关信访工作机构能够当场受理信访事项的，应当当场受理并出具受理通知；不能当场受理的，应当自收到信访事项之日起15日内决定是否受理，并书面告知信访人，但重复信访、信访人的姓名(名称)、住址和联系方式不清楚的除外。"},{"i":22,"n":"第二十二条","txt":"司法行政机关及其工作人员办理信访事项，应当恪尽职守、秉公办事，查明事实、分清责任，宣传法治、教育疏导，及时妥善办理，不得推诿、敷衍、拖延；不得将信访人的检举、揭发材料以及有关情况透露或者转给被检举、揭发的人员或者单位。"},{"i":23,"n":"第二十三条","txt":"司法行政机关应当认真研究信访人提出的建议和意见，对于有利于改进工作的，应当积极采纳。"},{"i":24,"n":"第二十四条","txt":"司法行政机关办理信访事项，应当听取信访人陈述事实和理由；可以要求信访人、有关组织和人员说明情况，提供有关证明材料；需要进一步核实有关情况的，可以依法向其他组织和人员调查。 参与信访工作的律师，可以依法对与信访事项有关的情况进行调查核实。 对重大、复杂、疑难信访事项，司法行政机关信访工作机构可以按照有关规定，举行听证。"},{"i":25,"n":"第二十五条","txt":"司法行政机关对经调查核实的信访事项，应当依法分别作出以下处理，并书面答复信访人： (一)请求事实清楚，符合或者部分符合法律、法规、规章及其他有关规定的，予以支持或者部分支持； (二)请求合理但缺乏法律、法规、规章及其他有关规定依据的，向信访人做好解释工作； (三)请求缺乏事实根据或者不符合法律、法规、规章及其他有关规定的，不予支持。 司法行政机关作出支持信访请求意见的，应当督促有关机关或者单位执行。 书面答复应当载明具体请求、事实认定情况、处理意见和依据以及不服处理意见的救济途径和期限。同时，一般应当采用电话沟通的方式作出必要的解释和说明。"},{"i":26,"n":"第二十六条","txt":"司法行政机关办理信访事项应当自受理之日起60日内办结；情况复杂的，经本机关负责人批准，可以适当延长办理期限，但延长期限最多不超过30日，并告知信访人延期理由。"},{"i":27,"n":"第二十七条","txt":"信访人对司法行政机关作出的信访事项处理意见不服的，可以自收到书面答复之日起30日内请求原办理司法行政机关的本级人民政府或者其上一级司法行政机关复查。 负责复查的司法行政机关应当自收到复查请求之日起30日内复查完毕，提出复查意见，书面答复信访人。 信访人对省级司法行政机关处理意见不服的，应当向省级人民政府提出复查请求。"},{"i":28,"n":"第二十八条","txt":"信访人对司法行政机关复查意见不服的，可以自收到书面答复之日起30日内向作出复查意见的司法行政机关的本级人民政府或者其上一级司法行政机关请求复核。 负责复核的司法行政机关应当自收到复核请求之日起30日内复核完毕，提出复核意见，书面答复信访人。 信访人对省级司法行政机关复查意见不服的，应当向省级人民政府提出复核请求。"},{"i":29,"n":"第二十九条","txt":"信访事项的处理意见、复查意见作出后，信访人在规定期限内未提出复查、复核申请的，或者信访人对复核意见不服，仍以同一事实和理由提出投诉请求的，司法行政机关不再受理，并告知信访人。信访人就同一信访事项提出新的事实和理由的，司法行政机关应当受理。"},{"i":30,"n":"第三十条","txt":"原处理意见、复查意见认定事实清楚、证据确凿、适用依据正确、程序合法、结论适当的，负责复查、复核的司法行政机关应当予以维持，并书面答复信访人。 原处理意见、复查意见有下列情形之一的，负责复查、复核的司法行政机关应当予以撤销或者变更： (一)主要事实不清、证据不足的； (二)适用依据错误的； (三)违反法定程序的； (四)超越或者滥用职权的； (五)结论明显不当的。 予以撤销的，应当责令原作出处理意见、负责复查的司法行政机关在指定期限内重新作出处理意见、复查意见。"},{"i":31,"n":"第三十一条","txt":"对信访人不服司法行政机关作出的已经生效的结论，其救济权利已经充分行使、放弃行使或者已经丧失，反映的问题已经依法公正办理，信访人仍以同一事实和理由反复到司法行政机关信访的信访事项，司法行政机关可以按照有关规定予以审查终结，并告知信访人。"},{"i":32,"n":"第三十二条","txt":"司法行政机关信访事项终结主要包括以下情形： (一)信访人不服司法行政机关信访处理决定，其反映的问题已经按信访程序逐级办理、复查、复核完毕并答复，或者其拒不逐级提出信访复查、复核请求，且已超过规定时限的； (二)信访人反映的问题已经依法按照程序办理，信访人同意接受处理意见后又反悔，且提不出新的事实和理由的； (三)信访事项在办理过程中存在实体或者程序上的瑕疵，依法已经得到纠正，信访人的合法权益已经得到维护的。 对已经终结的信访事项，司法行政机关不再受理、转办、交办、统计、通报，但应当做好解释、疏导工作。"},{"i":33,"n":"第三十三条","txt":"司法行政机关对简单明了的初次信访事项，可以简化程序，缩短时限，方便快捷地受理、办理，及时就地解决信访问题。 初次信访事项有下列情形之一的，可以适用简易办理程序： (一)事实清楚、责任明确、争议不大、易于解决的； (二)提出咨询或者意见建议，可以即时反馈的； (三)涉及群众日常生产生活、时效性强，应当即时办理的； (四)司法行政机关已有明确承诺或者结论，能够即时履行的； (五)其他可以适用简易办理程序的。"},{"i":34,"n":"第三十四条","txt":"适用简易办理程序的信访事项，可以即时受理并办结的，应当即时受理并办结；不能即时受理的，应当自收到之日起3个工作日内决定是否受理，并告知信访人；决定受理的，应当自受理之日起10日内办结。 适用简易办理程序的信访事项，除信访人要求出具纸质告知书和意见书的以外，可以通过网络系统、手机短信等方式告知和答复信访人。 司法行政机关信访工作机构在办理过程中，发现不宜适用简易办理程序的，应当经本机关负责人批准，按照普通信访程序办理，并告知信访人；办理期限自信访事项受理之日起计算。"},{"i":35,"n":"第三十五条","txt":"本机关有关内设机构、所属单位和下级司法行政机关有下列情形之一的，司法行政机关信访工作机构应当及时督办，并提出改进建议： (一)应当受理而未受理信访事项的； (二)未按照规定程序办理信访事项的； (三)未按照规定报告交办信访事项办理结果的； (四)办理信访事项推诿、敷衍、拖延、造假的； (五)不执行信访事项处理意见的； (六)其他需要督办的情形。 收到改进建议的单位应当在30日内书面反馈情况；未采纳改进建议的，应当说明理由。"},{"i":36,"n":"第三十六条","txt":"因下列情形之一导致信访事项发生，造成严重后果的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任： (一)超越或者滥用职权，侵害信访人合法权益的； (二)司法行政机关应当作为而不作为，侵害信访人合法权益的； (三)适用法律、法规错误或者违反法定程序，侵害信访人合法权益的； (四)拒不执行有权处理的行政机关作出的支持信访请求意见的。"},{"i":37,"n":"第三十七条","txt":"司法行政机关在受理、办理信访事项过程中，有下列情形之一的，由其上级司法行政机关责令改正；造成严重后果的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分： (一)对收到的信访事项未按规定登记的； (二)对属于其法定职权范围的信访事项不予受理的； (三)未在规定期限内书面告知信访人是否受理信访事项的； (四)推诿、敷衍、拖延信访事项办理或者未在规定期限内办结信访事项的； (五)对事实清楚，符合法律、法规、规章或者其他有关规定的投诉请求未予支持的。"},{"i":38,"n":"第三十八条","txt":"司法行政机关工作人员在办理信访事项过程中，有下列情形之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任： (一)将信访人的检举、揭发材料或者有关情况透露、转给被检举、揭发的人员或者单位的； (二)对可能造成社会影响的重大、紧急信访事项和信访信息，隐瞒、谎报、缓报，或者授意他人隐瞒、谎报、缓报，造成严重后果的； (三)作风粗暴，激化矛盾并造成严重后果的； (四)打击报复信访人的。"},{"i":39,"n":"第三十九条","txt":"信访人不遵守信访秩序，在信访过程中采取过激行为的，司法行政机关应当进行劝阻、批评或者教育；经劝阻、批评或者教育无效的，应当告知公安机关依法处置；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"对外国人、无国籍人、外国组织向司法行政机关提出的信访事项的办理，参照本办法执行。"},{"i":41,"n":"第四十一条","txt":"本办法由司法部负责解释。"},{"i":42,"n":"第四十二条","txt":"本办法自2018年4月1日起施行。1991年1月24日司法部公布的《司法行政机关信访工作办法(试行)》(司法部令第14号)同时废止。"}],"sifaxingzhengjiguanqiangzhigelijiedugongzuoguiding":[{"i":1,"n":"第一条","txt":"为了规范司法行政机关强制隔离戒毒工作，帮助吸毒成瘾人员戒除毒瘾，维护社会秩序，根据《中华人民共和国禁毒法》、《戒毒条例》等法律法规和相关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"司法行政机关强制隔离戒毒工作应当遵循以人为本、科学戒毒、综合矫治、关怀救助的原则，教育和挽救吸毒成瘾人员。"},{"i":3,"n":"第三条","txt":"司法行政机关强制隔离戒毒所对经公安机关作出强制隔离戒毒决定，在公安机关强制隔离戒毒场所执行三个月至六个月后，或者依据省、自治区、直辖市具体执行方案送交的强制隔离戒毒人员(以下简称“戒毒人员”)，依法执行强制隔离戒毒。"},{"i":4,"n":"第四条","txt":"从事强制隔离戒毒工作的人民警察应当严格、公正、廉洁、文明执法，尊重戒毒人员人格，保障其合法权益。"},{"i":5,"n":"第五条","txt":"司法行政机关强制隔离戒毒工作所需经费，按照国家规定的标准纳入当地政府财政预算。"},{"i":6,"n":"第六条","txt":"设置司法行政机关强制隔离戒毒所，应当符合司法部的规划，经省、自治区、直辖市司法厅(局)审核，由省级人民政府批准，并报司法部备案。 具备条件的地方，应当单独设置收治女性戒毒人员的强制隔离戒毒所和收治未成年戒毒人员的强制隔离戒毒所。"},{"i":7,"n":"第七条","txt":"强制隔离戒毒所以其所在地地名加“强制隔离戒毒所”命名，同一地域有多个强制隔离戒毒所的，可以采取其他方式命名。 专门收治女性戒毒人员的强制隔离戒毒所名称，为地名后加“女子强制隔离戒毒所”；专门收治未成年人的强制隔离戒毒所名称，为地名后加“未成年人强制隔离戒毒所”。"},{"i":8,"n":"第八条","txt":"强制隔离戒毒所设所长一人、政治委员一人、副所长若干人，设置职能机构和戒毒大队，根据收治规模配备从事管教、医疗和后勤保障的工作人员。"},{"i":9,"n":"第九条","txt":"强制隔离戒毒所设置医疗机构，接受卫生行政部门对医疗工作的指导和监督。"},{"i":10,"n":"第十条","txt":"强制隔离戒毒所工作人员享受国家规定的工资福利待遇及保险。"},{"i":11,"n":"第十一条","txt":"强制隔离戒毒所根据县级以上人民政府公安机关强制隔离戒毒决定书接收戒毒人员。"},{"i":12,"n":"第十二条","txt":"强制隔离戒毒所接收戒毒人员时，应当核对戒毒人员身份，进行必要的健康检查，填写强制隔离戒毒人员入所健康状况检查表。 戒毒人员身体有伤的，强制隔离戒毒所应当予以记录，由移送的公安机关工作人员和戒毒人员本人签字确认。 对女性戒毒人员应当进行妊娠检测。对怀孕或者正在哺乳自己不满一周岁婴儿的妇女，不予接收。"},{"i":13,"n":"第十三条","txt":"强制隔离戒毒所应当对接收的戒毒人员的身体和携带物品进行检查，依法处理违禁品，对生活必需品以外的其他物品进行登记并由戒毒人员本人签字，由其指定的近亲属领回或者由强制隔离戒毒所代为保管。检查时应当有两名以上人民警察在场。 女性戒毒人员的身体检查，应当由女性人民警察进行。"},{"i":14,"n":"第十四条","txt":"强制隔离戒毒所接收戒毒人员，应当填写强制隔离戒毒人员入所登记表，查收戒毒人员在公安机关强制隔离戒毒期间的相关材料。"},{"i":15,"n":"第十五条","txt":"戒毒人员入所后，强制隔离戒毒所应当书面通知其家属，通知书应当自戒毒人员入所之日起五日内发出。"},{"i":16,"n":"第十六条","txt":"强制隔离戒毒所应当根据性别、年龄、患病等情况，对戒毒人员实行分别管理；根据戒毒治疗情况，对戒毒人员实行分期管理；根据戒毒人员表现，实行逐步适应社会的分级管理。"},{"i":17,"n":"第十七条","txt":"强制隔离戒毒所人民警察对戒毒人员实行直接管理，严禁由其他人员代行管理职权。 女性戒毒人员由女性人民警察直接管理。"},{"i":18,"n":"第十八条","txt":"强制隔离戒毒所应当建立安全管理制度，进行安全检查，及时发现和消除安全隐患。 强制隔离戒毒所应当制定突发事件应急预案，并定期演练。"},{"i":19,"n":"第十九条","txt":"强制隔离戒毒所应当安装监控、应急报警、门禁检查和违禁品检测等安全技防系统，按照规定保存监控录像和有关信息资料。 强制隔离戒毒所应当安排专门人民警察负责强制隔离戒毒所的安全警戒工作。"},{"i":20,"n":"第二十条","txt":"对强制隔离戒毒所以外的人员交给戒毒人员的物品和邮件，强制隔离戒毒所应当进行检查，防止夹带毒品及其他违禁品。检查时，应当有两名以上人民警察在场。 检查邮件时，应当依法保护戒毒人员的通信自由和通信秘密。"},{"i":21,"n":"第二十一条","txt":"经强制隔离戒毒所批准，戒毒人员可以使用指定的固定电话与其亲属、监护人或者所在单位、就读学校有关人员通话。 戒毒人员在所内不得持有、使用移动通讯设备。"},{"i":22,"n":"第二十二条","txt":"戒毒人员的亲属和所在单位或者就读学校的工作人员，可以按照强制隔离戒毒所探访规定探访戒毒人员。 强制隔离戒毒所应当检查探访人员身份证件，对身份不明或者无法核实的不允许探访。 对正被采取保护性约束措施或者正处于单独管理期间的戒毒人员，不予安排探访。"},{"i":23,"n":"第二十三条","txt":"探访应当在探访室进行。探访人员应当遵守探访规定；探访人员违反规定经劝阻无效的，可以终止其探访。 探访人员交给戒毒人员物品须经批准，并由人民警察当面检查；交给戒毒人员现金的，应当存入戒毒人员所内个人账户；发现探访人员利用探访传递毒品的，应当移交公安机关依法处理；发现探访人员利用探访传递其他违禁品的，应当依照有关规定处理。"},{"i":24,"n":"第二十四条","txt":"戒毒人员因配偶、直系亲属病危、死亡或者家庭有其他重大变故，可以申请外出探视。申请外出探视须有医疗单位、戒毒人员户籍所在地或者现居住地公安派出所、原单位或者街道(乡、镇)的证明材料。 除前款规定外，强制隔离戒毒所可以批准戒治效果好的戒毒人员外出探视其配偶、直系亲属。"},{"i":25,"n":"第二十五条","txt":"强制隔离戒毒所批准戒毒人员外出探视的，应当发给戒毒人员外出探视证明。戒毒人员外出探视及在途时间不得超过十日。对非因不可抗力逾期不归的戒毒人员，视作脱逃处理。"},{"i":26,"n":"第二十六条","txt":"戒毒人员外出探视回所后，强制隔离戒毒所应当对其进行检测。发现重新吸毒的，不得报请提前解除强制隔离戒毒。"},{"i":27,"n":"第二十七条","txt":"对有下列情形之一的戒毒人员，应当根据不同情节分别给予警告、训诫、责令具结悔过： (一)违反戒毒人员行为规范、不遵守强制隔离戒毒所纪律，经教育不改正的； (二)欺侮、殴打、虐待其他戒毒人员的； (三)隐匿违禁品的； (四)交流吸毒信息、传授犯罪方法的。 对戒毒人员处以警告、训诫和责令具结悔过，由戒毒大队决定并执行。"},{"i":28,"n":"第二十八条","txt":"对有严重扰乱所内秩序、私藏或者吸食、注射毒品、预谋或者实施脱逃、行凶、自杀、自伤、自残等行为以及涉嫌犯罪应当移送司法机关处理的戒毒人员，强制隔离戒毒所应当对其实行单独管理。 单独管理应当经强制隔离戒毒所负责人批准。在紧急情况下，可以先行采取单独管理措施，并在二十四小时内补办审批手续。 对单独管理的戒毒人员，应当安排人民警察专门管理。一次单独管理的时间不得超过五日。单独管理不得连续使用。"},{"i":29,"n":"第二十九条","txt":"对私藏或者吸食、注射毒品的戒毒人员，不得报请提前解除强制隔离戒毒，并应当在期满前诊断评估时，作为延长强制隔离戒毒期限的依据；涉嫌犯罪的，应当依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"遇有戒毒人员脱逃、暴力袭击他人等危险行为，强制隔离戒毒所人民警察可以依法使用警械予以制止。警械使用情况，应当记录在案。"},{"i":31,"n":"第三十一条","txt":"戒毒人员脱逃的，强制隔离戒毒所应当立即通知当地公安机关，并配合公安机关追回脱逃人员。被追回的戒毒人员应当继续执行强制隔离戒毒，脱逃期间不计入强制隔离戒毒期限。对被追回的戒毒人员不得报请提前解除强制隔离戒毒。"},{"i":32,"n":"第三十二条","txt":"戒毒人员提出申诉、检举、揭发、控告的，强制隔离戒毒所应当及时依法处理；对强制隔离戒毒决定不服提起行政复议或者行政诉讼的，强制隔离戒毒所应当将有关材料登记后及时转送有关部门。"},{"i":33,"n":"第三十三条","txt":"强制隔离戒毒所工作人员因工作失职致使毒品等违禁品进入强制隔离戒毒所，违反规定允许戒毒人员携带、使用或者为其传递毒品等违禁品的，应当依法给予处分；涉嫌犯罪的，应当依法追究刑事责任。 进入强制隔离戒毒所的其他人员为戒毒人员传递毒品的，应当移交司法机关依法处理。"},{"i":34,"n":"第三十四条","txt":"强制隔离戒毒所应当根据戒毒人员吸食、注射毒品的种类、成瘾程度和戒断症状等进行有针对性的生理治疗、心理治疗和身体康复训练。 对公安机关强制隔离戒毒所移送的戒毒人员，应当做好戒毒治疗的衔接工作。"},{"i":35,"n":"第三十五条","txt":"对戒毒人员进行戒毒治疗，应当采用科学、规范的诊疗技术和方法，使用符合国家有关规定的药物、医疗器械。戒毒治疗使用的麻醉药品和精神药品应当按照规定申请购买并严格管理，使用时须由具有麻醉药品、精神药品处方权的医师按照有关技术规范开具处方。 禁止以戒毒人员为对象进行戒毒药物试验。"},{"i":36,"n":"第三十六条","txt":"强制隔离戒毒所应当定期对戒毒人员进行身体检查。对患有疾病的戒毒人员，应当及时治疗。对患有传染病的戒毒人员，应当按照国家有关规定采取必要的隔离治疗措施。"},{"i":37,"n":"第三十七条","txt":"戒毒人员患有严重疾病，不出所治疗可能危及生命的，凭所内医疗机构或者二级以上医院出具的诊断证明，经强制隔离戒毒所所在省、自治区、直辖市司法行政机关戒毒管理部门批准，报强制隔离戒毒决定机关备案，强制隔离戒毒所可以允许其所外就医，并发给所外就医证明。"},{"i":38,"n":"第三十八条","txt":"戒毒人员所外就医期间，强制隔离戒毒期限连续计算。对于健康状况不再适宜回所执行强制隔离戒毒的，强制隔离戒毒所应当向强制隔离戒毒决定机关提出变更为社区戒毒的建议，同时报强制隔离戒毒所所在省、自治区、直辖市司法行政机关戒毒管理部门备案。"},{"i":39,"n":"第三十九条","txt":"强制隔离戒毒所应当建立戒毒人员心理健康档案，开展心理健康教育，提供心理咨询，对戒毒人员进行心理治疗；对心理状态严重异常或者有行凶、自伤、自残等危险倾向的戒毒人员应当实施心理危机干预。"},{"i":40,"n":"第四十条","txt":"对可能发生自伤、自残等情形的戒毒人员使用保护性约束措施应当经强制隔离戒毒所负责人批准。采取保护性约束措施应当遵守有关医疗规范。 对被采取保护性约束措施的戒毒人员，人民警察和医护人员应当密切观察；可能发生自伤、自残等情形消除后，应当及时解除保护性约束措施。"},{"i":41,"n":"第四十一条","txt":"强制隔离戒毒所可以与社会医疗机构开展医疗合作，提高戒毒治疗水平和医疗质量。"},{"i":42,"n":"第四十二条","txt":"强制隔离戒毒所应当通过组织体育锻炼、娱乐活动、生活技能培训等方式对戒毒人员进行身体康复训练，帮助戒毒人员恢复身体机能、增强体能。"},{"i":43,"n":"第四十三条","txt":"强制隔离戒毒所根据戒毒的需要，可以组织有劳动能力的戒毒人员参加必要的生产劳动。 组织戒毒人员参加生产劳动的，应当支付劳动报酬。戒毒人员劳动时间每周不超过五天，每天不超过六小时。法定节假日不得安排戒毒人员参加生产劳动。"},{"i":44,"n":"第四十四条","txt":"强制隔离戒毒所应当建立安全生产管理制度，对参加生产劳动的戒毒人员进行安全生产教育，提供必要的劳动防护用品。生产劳动场地和劳动项目应当符合安全生产管理的有关规定，不得引进易燃、易爆等危险生产项目，不得组织戒毒人员从事有碍身体康复的劳动。"},{"i":45,"n":"第四十五条","txt":"强制隔离戒毒所应当对新接收的戒毒人员进行时间不少于一个月的入所教育，教育内容包括强制隔离戒毒有关法律法规、所规所纪、戒毒人员权利义务等。"},{"i":46,"n":"第四十六条","txt":"强制隔离戒毒所应当采取课堂教学的方式，对戒毒人员集中进行卫生、法制、道德和形势政策等教育。"},{"i":47,"n":"第四十七条","txt":"强制隔离戒毒所应当对戒毒人员开展有针对性的个别教育。戒毒大队人民警察应当熟悉分管戒毒人员的基本情况，掌握思想动态，对分管的每名戒毒人员每月至少进行一次个别谈话。戒毒人员有严重思想、情绪波动的，应当及时进行谈话疏导。"},{"i":48,"n":"第四十八条","txt":"强制隔离戒毒所应当开展戒毒文化建设，运用影视、广播、展览、文艺演出、图书、报刊、宣传栏和所内局域网等文化载体，活跃戒毒人员文化生活，丰富教育形式。"},{"i":49,"n":"第四十九条","txt":"强制隔离戒毒所应当加强同当地有关部门和单位的联系，通过签订帮教协议、来所开展帮教等形式，做好戒毒人员的教育工作。 强制隔离戒毒所可以邀请有关专家、学者、社会工作者、志愿人员以及戒毒成功人员协助开展教育工作。对协助教育有显著成绩和突出贡献的，应当予以表彰、奖励。"},{"i":50,"n":"第五十条","txt":"强制隔离戒毒所应当协调人力资源社会保障部门，对戒毒人员进行职业技能培训和职业技能鉴定；职业技能鉴定合格的，颁发相应的职业资格证书。"},{"i":51,"n":"第五十一条","txt":"强制隔离戒毒所应当在戒毒人员出所前进行回归社会教育，教育时间不少于一周。 强制隔离戒毒所可以安排戒毒人员到戒毒康复场所及戒毒药物维持治疗场所参观、体验，开展戒毒康复、戒毒药物维持治疗相关知识的宣传教育，为解除强制隔离戒毒后自愿进入戒毒康复场所康复或者参加戒毒药物维持治疗的戒毒人员提供便利。"},{"i":52,"n":"第五十二条","txt":"强制隔离戒毒所应当按规定设置戒毒人员生活设施。戒毒人员宿舍应当坚固安全、通风明亮，配备必要的生活用品。戒毒人员的生活环境应当绿化美化。"},{"i":53,"n":"第五十三条","txt":"强制隔离戒毒所应当保持戒毒人员生活区整洁，定期组织戒毒人员理发、洗澡、晾晒被褥，保持其个人卫生。 强制隔离戒毒所应当统一戒毒人员的着装。"},{"i":54,"n":"第五十四条","txt":"强制隔离戒毒所应当保证戒毒人员的伙食供应不低于规定标准。戒毒人员伙食经费不得挪作他用。戒毒人员食堂应当按月公布伙食账目。 对正在进行脱毒治疗和患病的戒毒人员在伙食上应当给予适当照顾。对少数民族戒毒人员，应当尊重其饮食习惯。"},{"i":55,"n":"第五十五条","txt":"强制隔离戒毒所应当保证戒毒人员的饮食安全。食堂管理人员和炊事人员应当取得卫生行政主管部门颁发的健康证明，每半年进行一次健康检查，健康检查不合格的应当及时予以调整。 戒毒人员食堂实行四十八小时食品留样制度。"},{"i":56,"n":"第五十六条","txt":"戒毒人员可以在所内商店购买日常用品。所内商店出售商品应当价格合理，明码标价，禁止出售过期、变质商品。 强制隔离戒毒所应当对所内商店采购的商品进行检查，防止违禁品流入。"},{"i":57,"n":"第五十七条","txt":"强制隔离戒毒所应当做好疾病预防控制工作。发生传染病疫情，应当按规定及时报告主管机关和当地疾病预防控制部门，并采取相应的防治措施。"},{"i":58,"n":"第五十八条","txt":"强制隔离戒毒所应当按照有关规定对戒毒人员进行诊断评估。对强制隔离戒毒期限届满且经诊断评估达到规定标准的戒毒人员，应当解除强制隔离戒毒。 经诊断评估，对符合规定条件的戒毒人员，强制隔离戒毒所可以提出提前解除强制隔离戒毒的意见或者延长强制隔离戒毒期限的意见，并按规定程序报强制隔离戒毒决定机关批准。强制隔离戒毒所收到强制隔离戒毒决定机关出具的提前解除强制隔离戒毒决定书或者延长强制隔离戒毒期限决定书的，应当及时送达戒毒人员。"},{"i":59,"n":"第五十九条","txt":"强制隔离戒毒所应当在解除强制隔离戒毒三日前通知强制隔离戒毒决定机关，同时通知戒毒人员家属、所在单位、户籍所在地或者现居住地公安派出所将其按期领回。戒毒人员出所时无人领回，自行离所的，强制隔离戒毒所应当及时通知强制隔离戒毒决定机关。 对解除强制隔离戒毒的所外就医人员，强制隔离戒毒所应当及时通知其来所办理解除强制隔离戒毒手续。"},{"i":60,"n":"第六十条","txt":"解除强制隔离戒毒的，强制隔离戒毒所应当向戒毒人员出具解除强制隔离戒毒证明书，同时发还代管财物。"},{"i":61,"n":"第六十一条","txt":"戒毒人员被依法收监执行刑罚或者依法拘留、逮捕的，强制隔离戒毒所应当根据有关法律文书，与相关部门办理移交手续，并通知强制隔离戒毒决定机关；戒毒人员被依法释放时强制隔离戒毒尚未期满的，继续执行强制隔离戒毒。"},{"i":62,"n":"第六十二条","txt":"戒毒人员在强制隔离戒毒所内死亡的，强制隔离戒毒所应当立即报告所属主管机关，通知其家属、强制隔离戒毒决定机关和当地人民检察院。戒毒人员家属对死亡原因有疑义的，可以委托有关部门作出鉴定。其他善后事宜依照国家有关规定处理。"},{"i":63,"n":"第六十三条","txt":"强制隔离戒毒所应当妥善保管戒毒人员档案。档案内容包括：强制隔离戒毒决定书、强制隔离戒毒人员入所登记表、强制隔离戒毒人员入所健康状况检查表、财物保管登记表、病历、心理健康档案、诊断评估结果、提前解除强制隔离戒毒决定书或者延长强制隔离戒毒期限决定书、解除强制隔离戒毒证明书以及在强制隔离戒毒期间产生的重要文书、视听资料。 除法律明确规定外，强制隔离戒毒所不得对外提供戒毒人员档案信息。"},{"i":64,"n":"第六十四条","txt":"吸毒成瘾人员自愿接受强制隔离戒毒的，应当凭强制隔离戒毒所所在地公安机关的书面同意意见，向强制隔离戒毒所提出申请。强制隔离戒毒所同意接收的，应当与其就戒毒治疗期限、戒毒治疗措施、权利义务等事项签订书面协议；协议未约定的，参照本规定有关规定执行。"},{"i":65,"n":"第六十五条","txt":"本规定自2013年6月1日起施行。"}],"sifaxingzhengjiguanxingzhengchufatingzhengchengxugbd6bd2":[{"i":1,"n":"第一条","txt":"为规范司法行政机关行政处罚听证程序，保障司法行政机关依法实施行政处罚，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》和有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"司法行政机关对依法应当进行听证的行政处罚案件在作出行政处罚决定之前，依照本规定进行听证。"},{"i":3,"n":"第三条","txt":"本规定适用于依法享有行政处罚权的县级以上司法行政机关和依法要求听证的行政处罚当事人和其他听证参加人。"},{"i":4,"n":"第四条","txt":"司法行政机关行政处罚听证由法制工作部门或者承担法制工作的部门负责。"},{"i":5,"n":"第五条","txt":"司法行政机关对依法应当进行听证的行政处罚案件不组织听证，行政处罚不能成立。"},{"i":6,"n":"第六条","txt":"司法行政机关举行听证，应当遵循公开、公正原则。"},{"i":7,"n":"第七条","txt":"司法行政机关的听证主持人、听证记录员由法制工作部门或者由承担法制工作的部门的公务员担任。 案件调查人员不得担任听证主持人。"},{"i":8,"n":"第八条","txt":"听证主持人有下列情形之一的，应当自行回避，当事人有权以口头或者书面方式申请其回避： (一)本案当事人或者委托代理人的近亲属； (二)与本案有利害关系； (三)与案件当事人有其他关系，可能影响听证公正进行的。"},{"i":9,"n":"第九条","txt":"当事人提出回避申请，应当说明理由。听证主持人应当将当事人的回避申请报告本部门负责人，由本部门负责人决定其是否回避；本部门负责人担任听证主持人的，由本机关负责人决定其是否回避。"},{"i":10,"n":"第十条","txt":"听证主持人在听证活动中依法行使下列职权： (一)决定举行听证的时间和地点； (二)决定听证的延期、中止或者终结； (三)询问听证参加人； (四)接收并审核有关证据； (五)维护听证秩序，对违反听证秩序的人员进行警告，对情节严重者可以责令其退场； (六)提出案件听证之后的处理意见； (七)司法行政规章赋予的其他职权。"},{"i":11,"n":"第十一条","txt":"听证主持人在听证活动中依法承担下列义务： (一)将听证通知书依法及时送达当事人及其他有关人员； (二)应当公开、公正地履行主持听证的职责，保证当事人行使陈述权、申辩权和质证权； (三)保守听证案件涉及的国家秘密、商业秘密和个人隐私； (四)不得徇私枉法，包庇纵容违法行为。 听证记录员应当认真、如实制作听证笔录，并承担本条第(三)项的义务。"},{"i":12,"n":"第十二条","txt":"听证主持人有违反行政处罚法行为的，视情节轻重，给予行政处分。"},{"i":13,"n":"第十三条","txt":"听证参加人是指案件调查人员、当事人、第三人、委托代理人、证人、鉴定人、勘验人、翻译人员。"},{"i":14,"n":"第十四条","txt":"听证当事人是指要求举行听证的公民、法人或者其他组织。听证当事人依法享有下列权利： (一)依法申请听证主持人回避； (二)当事人可以亲自参加听证，也可以委托一至二人代理参加听证； (三)就案件调查人员提出的案件的事实、证据和行政处罚建议进行申辩； (四)对案件的证据向调查人员及其证人进行质证； (五)听证结束前进行最后陈述。 (六)审核听证笔录。"},{"i":15,"n":"第十五条","txt":"听证案件的当事人依法承担下列义务： (一)按时参加听证； (二)依法举证； (三)如实回答听证主持人的询问； (四)遵守听证秩序。"},{"i":16,"n":"第十六条","txt":"第三人是指与听证案件有利害关系的其他公民、法人或者其他组织。听证主持人可以通知其参加听证。"},{"i":17,"n":"第十七条","txt":"听证当事人委托他人代理参加听证的，应当向司法行政机关提交由委托人签名或者盖章的授权委托书。 授权委托书应当载明委托事项及权限。 授权委托书应经听证主持人确认。"},{"i":18,"n":"第十八条","txt":"案件调查人员应当参加听证，向听证主持人提出当事人违法的事实、证据和行政处罚建议。"},{"i":19,"n":"第十九条","txt":"听证主持人可以通知与听证案件有关的证人、鉴定人、勘验人、翻译人员参加听证。"},{"i":20,"n":"第二十条","txt":"司法行政机关在作出下列行政处罚之前，案件调查部门应当告知当事人在三日内有要求举行听证的权利： (一)责令停业； (二)吊销许可证或者执业证书； (三)对个人处以三千元以上罚款，对法人或者其他组织处以二万元以上罚款； (四)法律法规以及规章规定的其他行政处罚。"},{"i":21,"n":"第二十一条","txt":"案件调查部门可以直接将听证告知书送达当事人，也可以邮寄送达或者委托当事人住所地的司法行政机关代为送达。"},{"i":22,"n":"第二十二条","txt":"当事人要求听证的，应当在接到听证告知书之日起三日内以书面或者口头形式提出，案件调查部门应当在当事人要求听证之日起三日内告知法制工作部门，并将案卷一并移送给法制工作部门。"},{"i":23,"n":"第二十三条","txt":"当事人因不可抗力或者其他正当理由无法提出听证要求的，在障碍消除后三日以内，可以申请延长听证期限。案件调查部门对其申请和事实核实无误后，应当批准其申请。"},{"i":24,"n":"第二十四条","txt":"法制工作部门应当在接到案件调查部门移送的当事人要求听证的材料之后确定听证主持人，并应当于举行听证七日前给当事人、听证参加人送达听证通知书，并通知案件调查人员。"},{"i":25,"n":"第二十五条","txt":"公开举行听证的，司法行政机关应当先期公告当事人姓名或者名称，案由，听证时间、地点。 对涉及国家秘密、商业秘密或者个人隐私不公开举行听证的案件，司法行政机关应当向听证参加人说明不公开听证的理由。"},{"i":26,"n":"第二十六条","txt":"听证开始前，听证记录员应当查明听证参加人是否到场，并宣布以下听证纪律： (一)未经听证主持人允许不得发言、提问； (二)未经听证主持人允许不得录音、录相和摄影； (三)未经听证主持人允许听证参加人不得退场； (四)旁听人员不得大声喧哗，不得鼓掌、哄闹或者进行其他妨碍听证秩序的活动。"},{"i":27,"n":"第二十七条","txt":"听证主持人核对听证参加人，宣布听证主持人、听证记录员名单，告知听证参加人在听证中的权利义务，询问当事人是否申请回避。 当事人申请回避的，由听证主持人宣布暂停听证，按本规定第八条、第九条处理。"},{"i":28,"n":"第二十八条","txt":"听证应当按照下列程序进行： (一)听证主持人宣布听证开始，宣布案由； (二)案件调查人员提出当事人违法的事实、证据和行政处罚的建议； (三)当事人及其委托代理人就调查人员提出的违法的事实、证据和行政处罚建议进行申辩和质证，并可以出示无违法事实、违法事实较轻，或者减轻、免除行政处罚的证据材料； (四)案件调查人员和当事人经听证主持人允许，可以就有关证据进行质问，也可以向到场的证人、鉴定人、勘验人发问； (五)当事人作最后陈述； (六)听证主持人宣布听证结束。"},{"i":29,"n":"第二十九条","txt":"听证主持人根据下列情形，决定延期举行听证： (一)当事人因不可抗拒的事由无法到场的； (二)当事人临时申请回避的； (三)其他应当延期的情形。"},{"i":30,"n":"第三十条","txt":"听证主持人根据下列情形，可以中止听证： (一)需要通知新的证人到场或者需要重新鉴定、勘验的； (二)当事人因不可抗拒的事由，无法继续参加听证的； (三)当事人死亡或者解散，需要等待权利义务继承人的； (四)其他应当中止听证的情形。"},{"i":31,"n":"第三十一条","txt":"延期、中止听证的情形消失后，由听证主持人决定恢复听证并将听证的时间、地点通知听证参加人。"},{"i":32,"n":"第三十二条","txt":"听证主持人根据下列情形，应当终止听证： (一)当事人撤回听证要求的； (二)当事人无正当理由不参加听证的，或者未经听证主持人允许中途退场的； (三)当事人死亡或者解散满三个月后，未确定权利义务继承人的； (四)拟作出的行政处罚决定改变，依法不应举行听证的； (五)其他应当终止听证的情形。"},{"i":33,"n":"第三十三条","txt":"听证记录员应当将听证的全部活动记入笔录，由听证主持人和听证记录员签名。 听证笔录应当由当事人当场签名或者盖章。当事人拒绝签名或者盖章的，听证主持人在听证笔录上应当记明情况。"},{"i":34,"n":"第三十四条","txt":"听证结束后，由法制工作部门写出听证报告，连同听证笔录、案件材料一并上报本机关负责人审批。 听证报告应当包括以下内容： (一)听证案由； (二)听证主持人和听证参加人的姓名、名称及其他情况； (三)听证的时间、地点、方式； (四)听证的过程； (五)案件事实和认定的证据； (六)对拟实施行政处罚的意见及处理意见。"},{"i":35,"n":"第三十五条","txt":"司法行政机关组织听证所需的费用由司法业务经费支出。"},{"i":36,"n":"第三十六条","txt":"本规定由司法部解释。"},{"i":37,"n":"第三十七条","txt":"本规定自公布之日起施行。"}],"sifaxingzhengjiguanxingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为促进司法行政机关依法行政水平，保障行政管理相对人的合法权益，规范司法行政机关行政处罚程序，根据《中华人民共和国行政处罚法》和有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"司法行政机关对公民、法人或者其他组织有违反律师管理、法律服务管理以及其他司法行政管理秩序的行为，有权依照本规定进行处罚。"},{"i":3,"n":"第三条","txt":"司法行政机关实施行政处罚，必须在职权范围内严格按照《中华人民共和国行政处罚法》的规定以及有关法律、法规、规章的规定进行。 违法事实不清楚的，不得给予行政处罚。"},{"i":4,"n":"第四条","txt":"司法行政机关行政处罚的种类有： （一）警告; （二）罚款; （三）没收违法所得; （四）停业; （五）吊销执业证书; （六）法律法规以及规章规定的其他行政处罚。 司法行政机关实施行政处罚时，应当责令当事人改正或者限期改正违法行为。"},{"i":5,"n":"第五条","txt":"司法行政机关实施行政处罚，必须以事实为根据，以法律为准绳，坚持责任处罚相当的原则。"},{"i":6,"n":"第六条","txt":"司法行政机关实施行政处罚，应当充分保障当事人陈述权、申辩权等权利的行使。 当事人对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。 当事人因司法行政机关违法给予行政处罚受到损害的，有权提出国家赔偿要求。"},{"i":7,"n":"第七条","txt":"司法行政机关实施行政处罚，实行社会监督的工作原则，对于公民投诉或者反映的案件，应当在作出是否立案决定后告知投诉人;对立案处理的投诉案件，应当办结后将处罚决定告知投诉人。 对于应当给予行政处罚的案件，必须立案处理。"},{"i":8,"n":"第八条","txt":"司法行政机关行政处罚案件，由违法行为发生地的司法行政机关管辖。法律、行政法规另有规定的除外。"},{"i":9,"n":"第九条","txt":"对同一违法行为，两个以上的司法行政机关都有管辖权的，由先立案的司法行政机关管辖。 司法行政机关之间对管辖权有争议的，由共同的上级司法行政机关指定管辖。"},{"i":10,"n":"第十条","txt":"对于触犯刑律构成犯罪的案件，应当移送有关司法机关追究刑事责任。"},{"i":11,"n":"第十一条","txt":"司法行政机关实施行政处罚，根据情况分别适用简易程序和一般程序。"},{"i":12,"n":"第十二条","txt":"适用简易程序当场实施行政处罚时，执法人员应当向当事人出示执法身份证件，并填写符合《中华人民共和国行政处罚法》第三十四条规定的行政处罚决定书。行政处罚决定书当场交付当事人。"},{"i":13,"n":"第十三条","txt":"适用一般程序查处违法行为，业务工作部门应当立案并依法进行调查取证。必要时，应当对现场进行勘验和技术鉴定;对重要书证，可以进行复制。"},{"i":14,"n":"第十四条","txt":"案件调查终结后，业务工作部门应当根据案件的情况，分别作出如下处理： （一）违法事实不清或者证据不足的，报经机关负责人审批后作出不予处罚决定; （二）违法事实清楚，证据确实，按规定不需要听证的，提出处罚意见报机关负责人审批后作出予以处罚决定; （三）违法事实清楚，证据确实，应当予以处罚，但按照规定需要举行听证会的，提出处罚意见后送法制工作部门，由法制工作部门举行听证会。"},{"i":15,"n":"第十五条","txt":"对当事人拟作出责令停业、吊销执业证书、对个人处以三千元以上罚款、对机构处以二万元以上罚款等行政处罚的，业务工作部门应即告知当事人在三日内有要求举行听证的权利。"},{"i":16,"n":"第十六条","txt":"司法行政机关行政处罚听证会由法制工作部门(人员)主持。当事人要求听证的，业务工作部门应当在三日内告知法制工作部门，法制工作部门应当在十日内组织听证，并将举行听证的时间、地点于举行听证会七日前通知当事人。"},{"i":17,"n":"第十七条","txt":"当事人超过三日提出听证要求的，司法行政机关可以根据情况决定是否组织听证。 当事人要求听证后，又无故不出席听证会的，司法行政机关可以宣布听证终止。"},{"i":18,"n":"第十八条","txt":"听证按照下列程序进行： （一）听证主持人宣布实施行政处罚的行政机关、当事人名称以及案由; （二）听证主持人宣布当事人的申请回避权、陈述权、申辩权、质证权以及申请复议、提起诉讼等权利; （三）行政机关的具体调查人员就当事人的违法行为提出证据材料、处罚的法律依据和处罚意见; （四）当事人就调查人员提出的事实和有关问题陈述意见、出示证据材料，进行申辩; （五）行政机关调查人员与当事人就各自出具的证据材料的真实性和处罚的法律依据进行辩论; （六）当事人进行最后陈述。 听证时双方的意见应当制作笔录，经核查无误后由当事人或者其代理人、行政机关调查人员和听证主持人签字。"},{"i":19,"n":"第十九条","txt":"听证主持人有权对听证过程中听证参加人不当的发言予以制止。"},{"i":20,"n":"第二十条","txt":"听证结束后，法制工作部门应当在充分听取业务工作部门的意见后提出对该案的处理意见，连同听证笔录一并送交行政机关负责人审批。 法制工作部门的意见与业务工作部门的意见不一致时，在提交时应当附上业务工作部门的详细意见。"},{"i":21,"n":"第二十一条","txt":"吊销执业证书的行政处罚决定，应当由机关负责人集体讨论决定。"},{"i":22,"n":"第二十二条","txt":"司法行政机关应当在听证后的十五日内，将处罚决定结果书面通知当事人。决定不予处罚的，制作不予处罚决定书;决定予以处罚的，制作处罚决定书。"},{"i":23,"n":"第二十三条","txt":"司法行政机关实施行政处罚必须出具行政处罚决定书。行政处罚决定书的内容必须符合《中华人民共和国行政处罚法》第三十九条规定的要求。"},{"i":24,"n":"第二十四条","txt":"对当事人处以罚款的，在行政处罚决定书中应当载明缴纳罚款的银行。当事人应当自收到行政处罚决定书之日起十五日内，到指定的银行缴纳罚款。 当场执行的，应当出具统一收据，并应当及时向本机关报告。"},{"i":25,"n":"第二十五条","txt":"凡需作出责令停业、吊销执业证书行政处罚的，如果办案机关与原核发执业证书机关不是同一机关的，由办案机关建议或者上级司法行政机关责成原核发执业证书机关实施处罚。"},{"i":26,"n":"第二十六条","txt":"行政处罚决定书的送达，依照《民事诉讼法》规定的方式送达。"},{"i":27,"n":"第二十七条","txt":"决定不予处罚的，如无新的证据，不得再就同一事项重新作出予以处罚的决定。"},{"i":28,"n":"第二十八条","txt":"司法行政机关行政处罚的执行，应当严格按照《中华人民共和国行政处罚法》的规定进行。"},{"i":29,"n":"第二十九条","txt":"上一级司法行政机关可以委托下一级司法行政机关代执行。"},{"i":30,"n":"第三十条","txt":"行政处罚案件统一由司法行政机关的法制工作部门负责综合统计，业务工作部门办理的行政处罚案件应当及时向法制工作部门备案。 下一级司法行政机关应当于每年一月份向上一级司法行政机关报送本机关上一年度行政处罚工作情况。"},{"i":31,"n":"第三十一条","txt":"司法行政机关作出行政处罚后，发现行政处罚错误或者不当的，应当及时纠正。 上一级司法行政机关发现下一级司法行政机关作出的行政处罚错误或者不当，应当通知下一级司法行政机关纠正。"},{"i":32,"n":"第三十二条","txt":"司法行政机关及其工作人员在行政处罚工作中，有违反《中华人民共和国行政处罚法》第七章规定的，必须依法承担法律责任。"},{"i":33,"n":"第三十三条","txt":"单位或者个人在办理行政处罚案件中有下列行为之一的，对直接责任人员应当进行批评教育，情节严重的，给予行政处分： （一）不允许当事人行使合法权利的; （二）办案中故意歪曲事实、曲解法律的; （三）严重违反处罚程序，导致处罚错误的; （四）办案中收取当事人财物的; （五）故意包庇应予追究刑事责任的当事人，不移交司法机关处理的; （六）应当给予行政处分的其他行为。"},{"i":34,"n":"第三十四条","txt":"司法行政机关实施行政处罚的文书格式，由司法部统一制定。"},{"i":35,"n":"第三十五条","txt":"本规定由司法部解释。"},{"i":36,"n":"第三十六条","txt":"本规定自发布之日起实施。"}],"sifaxingzhengjiguanxingzhengxukeshishiyujiandugongb47fa7":[{"i":1,"n":"第一条","txt":"为了规范司法行政机关行政许可的实施与监督，维护法律的正确实施，保障行政相对人的合法权益，根据《中华人民共和国行政许可法》(以下简称《行政许可法》)等法律、行政法规和国务院有关决定，制定本规则。"},{"i":2,"n":"第二条","txt":"司法行政机关实施行政许可的事项，应当依法设定；实施行政许可的主体，应当依法确定。 司法行政机关应当依照《行政许可法》、有关法律、法规、规章和本规则的规定，实施行政许可，并对行政许可行为和公民、法人或者其他组织从事行政许可事项活动的情况进行监督。"},{"i":3,"n":"第三条","txt":"司法行政机关实施行政许可，应当遵循公开、公平、公正、便民、高效和信赖保护的原则。"},{"i":4,"n":"第四条","txt":"司法行政机关内设机构在行政许可的实施与监督工作中，应当按照权责明确、分工配合的原则，严格依法履行职责，提供优质服务。 实施行政许可，应当由法定的司法行政机关的相关内设业务机构承办；需要多个内设业务机构办理的，由主办业务机构或者办公厅(室)负责统一受理行政许可申请，协调提出审查意见，统一送达行政许可决定；有关行政许可的文件、文书及证件，一律以实施机关的名义对外发布或者签发。"},{"i":5,"n":"第五条","txt":"司法行政机关对依法定职责实施的行政许可事项，应当依照《行政许可法》第三十条第一款规定的内容，在办公场所进行公示，还可以在本机关开设的政府网站上进行公示。 申请人要求对公示的内容予以说明、解释的，承办业务机构及其工作人员应当负责任地作出说明、解释。"},{"i":6,"n":"第六条","txt":"申请人向司法行政机关提出行政许可申请的，承办业务机构应当即时制作记录，并进行审查。行政许可申请的记录，应当载明收到的日期。 司法行政机关有条件采用电子政务方式办公的，承办业务机构应当安排专人，负责每日查收通过电子数据交换渠道提出的行政许可申请。"},{"i":7,"n":"第七条","txt":"司法行政机关接到行政许可申请后，应当按照下列事项对是否受理该项申请进行审查： (一)申请事项是否属于本机关管辖范围； (二)申请事项是否属于依法需要取得行政许可的事项； (三)申请人是否具有不得提出行政许可申请的情形； (四)申请人是否按照法律、法规、规章规定提交了符合规定种类、内容的申请材料，以及申请材料是否有明显的错误； (五)申请人提供的申请材料是否符合规定的格式、数量。"},{"i":8,"n":"第八条","txt":"根据《行政许可法》第三十二条的规定，对行政许可申请，经审查，按下列情形分别处理： (一)对依法不需要取得行政许可的，应当即时告知申请人不予受理； (二)对依法不属于本机关管辖范围的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请； (三)对申请材料存在当场可以更正的错误的，应当允许申请人当场更正，并由申请人签字确认； (四)申请材料不齐全或者不符合规定格式、数量的，应当当场或者自收到申请材料之日起五日内一次告知申请人需要补正的全部内容，告知情况应当记录；逾期不告知的，自收到申请材料之日起即为受理； (五)对符合《行政许可法》第三十二条第五项规定的，应当予以受理。 司法行政机关应当以书面形式作出受理或者不予受理行政许可申请的决定，并加盖本机关印章和注明日期，送达申请人。"},{"i":9,"n":"第九条","txt":"司法行政机关应当免费向申请人提供行政许可申请书格式文本。 法律、行政法规及国务院决定设定的司法行政机关实施的各项行政许可的申请书格式文本，由司法部统一制定。"},{"i":10,"n":"第十条","txt":"司法行政机关对受理的行政许可申请，应当依照法定的条件对申请材料进行审查。重点审查以下内容： (一)申请材料反映的申请人条件是否合法； (二)申请材料的相关内容是否真实。 根据法定条件和程序，需要对申请材料的实质内容进行核实的，应当指派两名以上工作人员进行核查。核查情况应当记录，并提交核查报告。"},{"i":11,"n":"第十一条","txt":"依法应当先由下级司法行政机关审查后报上级司法行政机关决定的行政许可，下级司法行政机关应当自受理行政许可申请之日起二十日内审查完毕，将初步审查意见和全部申请材料报送上级司法行政机关。 司法行政机关实施行政许可前置审查的，应当依照有关法律、法规规定的期限完成审查，将前置审查意见和全部申请材料移送主办该项行政许可的行政机关。 法律、法规对初步审查期限另有规定的，依照其规定。"},{"i":12,"n":"第十二条","txt":"受理行政许可申请后，除当场作出行政许可决定的外，司法行政机关应当在法定期限内按照规定程序作出准予行政许可或者不予行政许可的书面决定。 申请人的申请符合法定条件、标准的，司法行政机关应当依法作出准予行政许可书面决定；作出不予行政许可的书面决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":13,"n":"第十三条","txt":"司法行政机关作出的准予行政许可或者不予行政许可的书面决定，由承办业务机构自作出决定之日起十日内向申请人送达。送达方式，参照《中华人民共和国民事诉讼法》关于送达的规定执行。 作出准予行政许可的决定，需要颁发行政许可证件的，应当同时向申请人颁发加盖本机关印章的相关行政许可证件。"},{"i":14,"n":"第十四条","txt":"司法行政机关作出的准予行政许可的决定，应当予以公开。公众要求查阅的，应当准予查阅并提供必要的条件。"},{"i":15,"n":"第十五条","txt":"被许可人要求变更行政许可事项，并向作出行政许可的司法行政机关提出申请的，司法行政机关按照本章规定的行政许可申请审查的有关规定办理。法律、法规另有规定的，依照其规定。 被许可人依法提出需延续取得的行政许可有效期申请的，司法行政机关按照本章规定的行政许可申请审查的有关规定办理，并在该行政许可有效期届满前作出是否准予延续的书面决定。法律、法规另有规定的，依照其规定。"},{"i":16,"n":"第十六条","txt":"根据《行政许可法》第四十二条的规定，除可以当场作出行政许可决定的外，司法行政机关应当自受理行政许可申请之日起二十日内作出行政许可决定。二十日内不能作出决定的，由承办业务机构报本机关主管负责人批准，可以延长十日，并于前述规定期限届满前将延长期限的理由告知申请人，口头告知的应当记录在案。法律、法规对期限另有规定的，依照其规定。"},{"i":17,"n":"第十七条","txt":"司法行政机关实施行政许可，依照法律、行政法规规定收取费用的，应当按照行政事业性收费主管机关核定、公布的项目和标准收取。"},{"i":18,"n":"第十八条","txt":"法律、法规、规章规定实施行政许可应当听证的事项，或者司法行政机关认为需要听证的涉及公共利益的行政许可事项，司法行政机关应当在行政许可事项涉及的区域内向社会公告。与该行政许可事项有关的人员可以申请参加听证。 听证公告应当载明听证事项、听证举行的时间、地点、参加人员要求及提出申请的时间和方式等。"},{"i":19,"n":"第十九条","txt":"行政许可直接涉及申请人与他人重大利益关系的，司法行政机关在作出行政许可决定前，应当向申请人、利害关系人发出《行政许可听证告知书》，告知其享有要求听证的权利及提出申请的时间和方式。 申请人、利害关系人要求听证的，应当自收到《行政许可听证告知书》之日起五日内以书面形式提出听证申请；逾期不提出申请的，视为放弃听证的权利。 司法行政机关应当自收到听证申请之日起二十日内组织听证。听证申请人在举行听证前撤回听证申请，行政许可申请人或者利害关系人无异议的，司法行政机关应当准许，并记录在案。"},{"i":20,"n":"第二十条","txt":"听证由实施行政许可的司法行政机关的法制工作机构组织，并派员主持。审查该行政许可申请的工作人员不得担任听证主持人。 组织听证所需时间不计算在行政许可的审查期限内。司法行政机关应当将听证所需时间在《行政许可听证告知书》中一并告知申请人。 组织听证的费用，由司法行政机关承担。"},{"i":21,"n":"第二十一条","txt":"根据《行政许可法》第四十八条的规定，司法行政机关组织听证应当按照下列程序和要求进行： (一)听证举行七日前应当将举行听证的时间、地点、听证主持人等事项通知申请人、利害关系人以及其他听证参加人，必要时予以公告。 (二)听证应当公开举行。但涉及国家秘密、商业秘密和个人隐私的除外。 (三)听证主持人有下列情形之一的，应当自行回避；申请人、利害关系人有权申请回避： 1．是申请人、利害关系人或者其委托代理人的近亲属的； 2．与该行政许可事项有直接利害关系的； 3．与申请人、利害关系人有其他关系，可能影响听证公正举行的。 (四)举行听证时，审查该行政许可申请的工作人员应当提出审查意见，并提供相关的证据、理由，申请人、利害关系人可以发表意见、提供证据，并进行申辩和质证。 (五)听证应当制作笔录，由听证主持人和记录人签名，并经听证参加人确认无误后当场签名或者盖章。听证参加人对笔录内容有异议的，听证主持"},{"i":22,"n":"第二十二条","txt":"司法行政机关应当根据听证笔录，作出准予行政许可或者不予行政许可的决定。 对听证笔录没有认定、记载的事实、证据，申请人、利害关系人在听证举行后作出行政许可决定前提出新的事实或者证据，司法行政机关认为足以影响对行政许可作出决定的，应当通知利害关系人或者申请人，并征求他们的意见。申请人或者利害关系人在作出的笔录上签字后，司法行政机关可视情决定是否将相关事实、证据采纳作为作出行政许可决定的依据；必要时，司法行政机关应当另行举行补充听证。"},{"i":23,"n":"第二十三条","txt":"司法行政机关应当加强对本机关实施行政许可工作及其工作人员的内部监督，保障本机关行政许可实施和监督工作严格依法进行。 上级司法行政机关应当加强对下级司法行政机关实施行政许可工作的监督。发现有需要纠正的行为的，应当及时提出意见，限期改正。 司法行政机关收到对本机关各相关业务机构及其工作人员违反规定实施行政许可的举报、投诉，应当及时依法核查，认真作出处理，或者提请监察机关依法处理，并负责将处理结果书面答复举报人、投诉人。对举报人、投诉人的情况，应当保密。"},{"i":24,"n":"第二十四条","txt":"司法行政机关对被许可人从事许可活动的情况实施监督检查，以对被许可人从事行政许可事项活动的有关材料和年度报告进行书面审查的形式为主，必要时可以进行实地检查。 司法行政机关应当将被许可人从事行政许可事项活动的情况，实施监督检查的材料和考核意见以及处理结果建立档案。公众要求查阅的，应当在收到申请后及时安排查阅。 对监督检查中涉及的国家机密、商业秘密或者个人隐私，应当予以保密。"},{"i":25,"n":"第二十五条","txt":"司法行政机关及其工作人员在实施监督检查工作中，应当遵守公务活动的规则和纪律，不得妨碍被许可人正常的业务活动，不得索取或者收受被许可人的财物，不得利用职务之便利牟取其他利益，不得与被许可人串通损害他人或者公共利益。"},{"i":26,"n":"第二十六条","txt":"被许可人在作出行政许可决定的司法行政机关管辖区域内违法从事行政许可事项活动的，由作出行政许可决定的司法行政机关依法进行处理。 被许可人在作出行政许可决定的司法行政机关管辖区域外违法从事行政许可事项活动的，违法行为发生地的司法行政机关应当依法立案查处，并将查处情况书面告知作出行政许可决定的司法行政机关。需要给予停止执业、停业整顿、吊销执业证书处罚或者撤销行政许可的，应当提出处罚建议，移送作出行政许可决定的司法行政机关处理。"},{"i":27,"n":"第二十七条","txt":"根据《行政许可法》第六十九条第一款的规定，利害关系人提出撤销行政许可请求的，司法行政机关应当自收到请求材料之日起三十日内完成核查，作出是否予以撤销该行政许可的书面决定，并将决定送达利害关系人和被许可人。 司法行政机关发现有可以撤销行政许可情形的，可以依据职权作出撤销该行政许可的决定，并将决定送达被许可人。 撤销行政许可，被许可人合法权益受到损害的赔偿及相关可取得利益的保护，依照《行政许可法》第六十九条第四款的规定执行。"},{"i":28,"n":"第二十八条","txt":"司法行政机关在对被许可人实施监督检查中发现有《行政许可法》第七十条规定情形的，应当依法办理有关行政许可的注销手续，并将注销的理由和依据书面告知被许可人，收回行政许可证件，必要时予以公告。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，司法行政机关可以依法变更或者撤回行政许可： (一)行政许可依据的法律、法规、规章修改或者废止的； (二)行政许可依据的客观情况发生重大变化的。 依法变更或者撤回行政许可，司法行政机关应当作出书面决定，说明理由和依据，并送达被许可人。 依法变更或者撤回行政许可，给当事人造成财产损失的，依照《行政许可法》第八条第二款的规定处理。"},{"i":30,"n":"第三十条","txt":"上级司法行政机关发现下级司法行政机关有违反《行政许可法》第十七条规定设定行政许可情形的，应当责令其限期改正，下级司法行政机关应当在限期届满前将改正情况报上级司法行政机关；或者由上级司法行政机关依法予以撤销。"},{"i":31,"n":"第三十一条","txt":"司法行政机关发现本机关内设业务机构及其工作人员或者上级司法行政机关发现下级司法行政机关及其工作人员有《行政许可法》第七十二条、第七十三条、第七十四条、第七十五条、第七十七条规定情形的，由本机关或者上级司法行政机关，或者提请监察机关分别情况责令其改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"司法行政机关违法实施行政许可，给当事人的合法权益造成损害的，应当依照《中华人民共和国国家赔偿法》的规定给予赔偿。 司法行政机关因违法实施行政许可承担赔偿责任的，可以依照《中华人民共和国国家赔偿法》第十四条第一款的规定，责令有故意或者重大过失的工作人员承担部分或者全部赔偿费用。"},{"i":33,"n":"第三十三条","txt":"行政许可申请人有《行政许可法》第七十八条规定情形的，被许可人有《行政许可法》第七十九条、第八十条规定情形的，司法行政机关应当依法处理。"},{"i":34,"n":"第三十四条","txt":"公民、法人或者其他组织未经行政许可，擅自从事依法应当取得司法行政机关行政许可的活动的，司法行政机关应当依法采取措施予以制止，并依法给予行政处罚，或者提请有关机关依法处理。"},{"i":35,"n":"第三十五条","txt":"各省、自治区、直辖市司法行政机关应当根据《行政许可法》和有关法律、法规、规章以及本规则的规定，建立健全行政许可实施与监督工作制度。有关规范性文件报司法部备案。"},{"i":36,"n":"第三十六条","txt":"本规则由司法部解释。"},{"i":37,"n":"第三十七条","txt":"本规则自发布之日起施行。"}],"sifabuguanyulvshidanrenqiyefalvguwenderuoganguidinb4b59a":[{"i":1,"n":"第一条","txt":"为加强对律师担任企业法律顾问工作的领导和管理，根据《中华人民共和国律师暂行条例》的规定，结合律师工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"律师担任企业法律顾问的任务是：为企业依法治厂，按照《企业法》和其他有关的法律、法规进行生产、经营、管理或其他活动提供法律服务，受企业委托办理有关法律事务，维护企业的合法权益，促进企业深化改革，扩大开放，转换企业经营机制，提高企业经济效益，推进企业生产、经营的发展。"},{"i":3,"n":"第三条","txt":"律师担任企业法律顾问，受企业委托办理下列法律事务： （一）就企业生产、经营、管理方面的重大决策提出法律意见，从法律上进行论证，提供法律依据; （二）草拟、修改、审查企业在生产、经营、管理及对外联系活动中的合同、协议以及其他有关法律事务文书和规章制度; （三）办理企业的非诉讼法律事务; （四）代理企业参加民事、经济、行政诉讼和仲裁，行政复议; （五)参加经济项目谈判，审查或准备谈判所需的各类法律文件; （六）提供与企业活动有关的法律信息; （七）就企业深化改革、扩大开放，发展外向型经济，转换企业经营机制，提高企业经济效益，加强生产、经营、管理和对外联系中的有关问题，提出法律意见; （八）协助企业对干部职工进行法制宣传教育和法律培训; （九）对企业内部的法律工作人员的工作进行指导; （十）其他法律事务。"},{"i":4,"n":"第四条","txt":"企业聘请律师担任法律顾问，由企业与律师事务所(法律顾问处—下同)签订聘应合同、协议。"},{"i":5,"n":"第五条","txt":"企业聘请律师担任法律顾问，由律师事务所指派本所律师担任，并尽可能满足企业对律师的指名要求。 必要时可以指派二名以上律师组成法律顾问团(组)，法律顾问团(组)可以设首席法律顾问。 未经律师事务所指派，律师个人不得以任何形式或名义担任企业法律顾问。 律师助理人员不得独立担任企业法律顾问，但可以协助律师做法律顾问工作。"},{"i":6,"n":"第六条","txt":"律师事务所与企业之间签订的聘应合同、协议，应包括以下主要内容： （一）双方法定名称、指派律师姓名; （二）法律顾问的具体工作范围、工作方式; （三）双方的权利、义务; （四）双方共同遵守的原则; （五）法律顾问费数额、支付办法; （六）合同、协议的中止、变更和解除; （七）合同、协议有效期限; （八）双方约定的其他事项。 律师担任企业法律顾问的聘应合同、协议必须加盖聘应双方公章，并由双方法定代表人签名或盖章。"},{"i":7,"n":"第七条","txt":"律师担任企业法律顾问可以采取下列方式： （一）常年法律顾问：法律事务所与企业签订以一年或一年以上的聘应协议，在协议期限内，受律师事务所指派的律师，以法律顾问的身份为企业提供协议范围内的法律服务。协议期满，法律顾问关系即终止，继续聘应的，重新签订协议。 （二）专项法律顾问：律师事务所可以与企业签订办理某一法律事项的聘应协议，该法律事项办结，法律顾问关系即终止。 律师担任企业法律顾问时，对外可称为律师，也可称为企业的法律顾问。"},{"i":8,"n":"第八条","txt":"律师担任企业法律顾问的聘应合同、协议，应载明律师享有如下权利： （一）查阅与承办法律事务有关的企业文件和资料; （二）了解企业的生产、经营、管理和对外联系活动中的有关情况; （三）列席企业领导人召集的生产、经营、管理和对外活动中的有关会议; （四）获得履行企业法律顾问职责所必须的办公、交通及其他工作条件和便利。"},{"i":9,"n":"第九条","txt":"律师担任企业法律顾问，由律师事务所依据《律师业务收费管理办法》和《律师业务收费标准》向企业收取费用。"},{"i":10,"n":"第十条","txt":"担任企业法律顾问的律师应当及时承办顾问单位委托办理的有关法律事务，认真履行职责。"},{"i":11,"n":"第十一条","txt":"律师担任企业法律顾问，应当坚持以事实为根据，以法律为准绳的原则，发现顾问单位有违法行为的，应当予以劝阻纠正。"},{"i":12,"n":"第十二条","txt":"律师担任企业法律顾问，应根据合同、协议规定和企业的委托授权进行工作，不得超越委托代理权限。"},{"i":13,"n":"第十三条","txt":"担任企业法律顾问的律师，不得从事有损于聘请单位合法权益的活动，不得在民事、经济、行政诉讼或仲裁活动中担任对立一方当事人的代理人。"},{"i":14,"n":"第十四条","txt":"担任企业法律顾问的律师在其受聘的两个(或两个以上)的企业之间发生争议时，应当进行调解，但律师不得代理任何一方参加诉讼或仲裁。"},{"i":15,"n":"第十五条","txt":"担任企业法律顾问的律师，对在工作中接触、了解到的有关企业生产、经营管理和对外联系活动中的业务秘密，负有保守秘密的责任。"},{"i":16,"n":"第十六条","txt":"担任企业法律顾问的律师，应当建立律师事务所与聘请单位定期联系、律师与聘请单位法定代表人定期会见等制度。"},{"i":17,"n":"第十七条","txt":"受聘律师因故不能履行企业法律顾问职责时，受聘律师事务所应当与聘请单位协商，另行指派律师接替。"},{"i":18,"n":"第十八条","txt":"律师事务所对律师担任企业法律顾问工作，应定期进行检查和考核，以保证工作的质量。"},{"i":19,"n":"第十九条","txt":"司法行政机关应当加强律师担任企业法律顾问工作的指导、管理和监督。对担任企业法律顾问的律师，成绩突出的，应予以表彰和奖励;不称职的应责成律师事务所予以调整;严重不称职，给聘请单位造成损失，或违反有关规定的，应当作出处理。"},{"i":20,"n":"第二十条","txt":"本规定所指企业，包括全民所有制企业、集体所有制企业、私营企业、外资企业、中外合资企业、中外合作企业以及外商派驻机构。 事业单位、其他社会经济组织以及公民个人聘请律师担任法律顾问，参照本规定执行。"},{"i":21,"n":"第二十一条","txt":"各省、自治区、直辖市司法厅(局)可依据本规定制定具体实施办法和工作细则。"},{"i":22,"n":"第二十二条","txt":"本规定自发布之日起施行。"}],"sifabuguanyulvshidanrenzhengfufalvguwenderuoganguie82334":[{"i":1,"n":"第一条","txt":"为适应政府法制建设的需要，加强对律师担任政府法律顾问工作的领导和管理，根据《中华人民共和国律师暂行条例》，结合律师工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"律师担任政府法律顾问的任务，是为政府在法律规定的权限内行使管理职能提供法律服务，促进政府工作的法律化、制度化。"},{"i":3,"n":"第三条","txt":"律师担任政府法律顾问，受政府委托办理下列法律事务： (一)就政府的重大决策提供法律方面的意见，或者应政府要求，对决策进行法律论证; (二)对政府起草或者拟发布的规范性文件，从法律方面提出修改和补充建议; (三)参与处理涉及政府的尚未形成诉讼的民事纠纷、经济纠纷、行政纠纷和其他重大纠纷; (四)代理政府参加诉讼，维护政府依法行使行政职权和维护政府机关的合法权益; (五)协助政府审查重大的经济合同、经济项目以及重要的法律文书; (六)协助政府进行法制宣传教育; (七)向政府提供国家有关法律信息，就政府行政管理中的法律问题提出建议; (八)办理政府委托办理的其他法律事务。"},{"i":4,"n":"第四条","txt":"律师担任政府法律顾问，应当在协商一致的基础上，由政府与法律顾问处(律师事务所)签订聘应合同。聘应合同一般应采用书面形式。 法律顾问处(律师事务所)和政府也可以根据具体情况，协商采用其他方式建立法律顾问关系。"},{"i":5,"n":"第五条","txt":"政府与法律顾问处(律师事务所)之间的聘应合同，应当包括以下主要内容： (一)双方法定名称、指派律师姓名; (二)法律顾问的具体职责范围、工作方式; (三)双方的权利、义务; (四)双方共同遵守的原则; (五)报酬数额及给付方式; (六)合同生效日期和有效期限; (七)双方需约定或者写明的其他事项。"},{"i":6,"n":"第六条","txt":"法律顾问处(律师事务所)应当指派具备较高的思想政治觉悟和政策业务水平的律师担任政府法律顾问。"},{"i":7,"n":"第七条","txt":"律师担任政府法律顾问，应当根据合同规定和政府委托的权限进行活动，不得超越委托权限，也不得从事与履行法律顾问职责无关的事务。"},{"i":8,"n":"第八条","txt":"为便于政府法律顾问开展工作，担任政府法律顾问的律师应当享有如下权利： (一)查阅有关文件及资料; (二)参加政府召开的有关会议; (三)获得履行政府法律顾问职责所必需的其他工作条件和便利。"},{"i":9,"n":"第九条","txt":"担任政府法律顾问的律师，对其工作中接触、了解到的机密和不宜公开的情况，负有保守秘密的责任。"},{"i":10,"n":"第十条","txt":"担任政府法律顾问的律师，不得同时接受他人委托办理下列事务： (一)在民事诉讼、经济诉讼和行政诉讼中，担任政府对方当事人的代理人; (二)其他有损于政府利益或者违反政府决定的事务。"},{"i":11,"n":"第十一条","txt":"律师担任政府法律顾问，不得利用政府法律顾问的身份，代理他人办理法律事务。"},{"i":12,"n":"第十二条","txt":"政府聘请法律顾问，根据需要可以由法律顾问处(律师事务所)指派一名或者数名律师担任，也可以由同级政府司法行政机关负责人和律师组成的法律顾问团(组)担任。法律顾问团(组)可以设首席法律顾问。"},{"i":13,"n":"第十三条","txt":"司法行政机关对律师担任政府法律顾问工作，应当加强指导、管理和监督，对不适宜承担这项工作的律师，应当及时予以撤换。"},{"i":14,"n":"第十四条","txt":"本规定所称的政府包括各级人民政府。 各级人民政府的各行政主管部门聘请律师担任法律顾问，可以参照本规定执行。"},{"i":15,"n":"第十五条","txt":"各省、自治区、直辖市司法厅(局)，可以依照本规定制定实施办法。"},{"i":16,"n":"第十六条","txt":"本规定自发布之日起施行。"}],"sifabuguanyuzhixingwaiguolvshishiwusuozhuhuadaibia1453a5":[{"i":1,"n":"第一条","txt":"为执行《外国律师事务所驻华代表机构管理条例》(简称《条例》)，履行司法行政部门对中国境内的外国法律服务活动的管理职责，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外国律师事务所，是指在我国境外合法设立、由外国执业律师组成、从事中国法律事务以外的法律服务活动，并对外独立由其全部成员或部分成员承担民事责任的律师执业机构。但下列情形除外： (一)外国政府、商业组织和其他机构中的法律服务部门; (二)不共享利润、不共担风险的二个或二个以上外国执业律师或律师事务所的执业联合体。"},{"i":3,"n":"第三条","txt":"本规定所称外国执业律师，是指合法取得外国律师执业资格、在执业资格取得国获得该国法定执业许可的人员。"},{"i":4,"n":"第四条","txt":"《条例》第七条第三项规定的“有在华设立代表机构开展法律服务业务的实际需要”，应当根据下列因素认定： (一)拟设代表处住所地的社会经济发展状况; (二)拟设代表处住所地法律服务的发展需要; (三)申请人的规模、成立时间、主要业务领域和专业特长、对拟设代表处业务前景的分析、未来业务发展规划; (四)中国法律、法规对从事特定法律服务活动或事务的限制性规定。"},{"i":5,"n":"第五条","txt":"《条例》第八条第一款第一项规定的“该外国律师事务所主要负责人签署的设立代表机构、派驻代表的申请书”，应当包括以下内容： (一)拟设代表处的中文名称和外文名称，拟驻在城市名称; (二)申请人的基本情况：包括开业时间、律师人数、合伙人人数、业务领域、主要业绩、在其他国家或地区设立分支机构或代表处情况、与中国有关的业务活动、总部地址和通讯方法等; (三)申请人的组织形式和承担法律责任的形式; (四)申请人购买执业风险保险的金额和范围; (五)对拟设代表处业务前景的可行性分析和发展计划，拟设代表处的主要业务范围; (六)对拟设代表处及其拟派驻代表在中国境内从事法律服务活动承担全部民事责任的承诺; (七)对所提供的信息、材料的真实性、完整性和准确性及中文译文与原文一致的承诺; (八)对申请获得批准后遵守中国法律、法规、规章的承诺; (九)对申请获得批准后将为代表处及其派驻代表持续购买符合要求的执"},{"i":6,"n":"第六条","txt":"提交《条例》第八条第一款第三项规定的“该外国律师事务所的合伙协议或者成立章程”确有困难的，可以提供由主要负责人签署的介绍合伙协议、股东协议或者章程中涉及签订时间、发起人、组织形式、法律责任形式等内容的文件材料。"},{"i":7,"n":"第七条","txt":"按照《条例》第八条第三款规定提交的文件材料，应当附中文译文，按正、副本形式分别装帧成三份。"},{"i":8,"n":"第八条","txt":"拟设代表处的外国律师事务所的中文译名不得使用中国法律、法规、规章禁止或限制的名称，不得使用可能使公众产生误解的文字。"},{"i":9,"n":"第九条","txt":"申请设立代表处，应当有拟派驻的一名首席代表和拟派驻的若干代表。"},{"i":10,"n":"第十条","txt":"申请增设代表处，应当符合下列条件： (一)在华最近设立的代表处连续执业满三年; (二)已经设立的各代表处及其代表遵守中国法律、法规、规章，遵守律师职业道德和执业纪律，没有被追究《条例》规定的各项法律责任。 前款第一项规定的连续执业时间，自代表处住所地的省、自治区、直辖市司法厅(局)首次办理开业注册之日起计算。"},{"i":11,"n":"第十一条","txt":"申请增设代表处，除应当提交《条例》第八条规定的材料外，还应当提交下列材料： (一)已设立的各代表处的基本情况; (二)已设立的各代表处的《外国律师事务所驻华代表处执业许可证》(副本)复印件; (三)已设立的各代表处住所地的省、自治区、直辖市司法厅(局)出具的符合本规定第十条第一款第一、二项规定的证明文件。 以上材料应当附中文译文，按正、副本形式分别装帧成三份。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市司法厅(局)收到申请人提交的申请设立代表处的材料后，应当根据下列情形予以处理： (一)申请材料齐全的，按照《条例》第九条的规定办理; (二)申请材料不齐全的，自收到申请材料之日起15日内通知申请人补充材料。申请人在首次提交申请材料之日起3个月内补齐材料的，按照前项规定办理;申请人在首次提交申请材料之日起满3个月未能补齐材料的，应当作出不予受理的决定，并于15日内书面通知申请人。"},{"i":13,"n":"第十三条","txt":"司法部收到省、自治区、直辖市司法厅(局)报送的申请人申请材料和审查意见后，应当在6个月内作出决定，对许可设立的代表处发给执业许可证及副本，并通知省、自治区、直辖市司法厅(局)对其代表发给执业证书;对不予许可的，应当书面告知理由。"},{"i":14,"n":"第十四条","txt":"申请人应当自执业许可证书签发之日起30日内，持副本到代表处住所地技术监督、公安、劳动、银行、税务和中国驻外使领馆等部门办理登记和代表工作签证等手续。"},{"i":15,"n":"第十五条","txt":"申请人应当在办结本规定第十四条规定的手续后30日内，到住所地的省、自治区、直辖市司法厅(局)办理开业注册，并交纳注册费。 办理开业注册手续，应当提交下列材料的复印件： (一)外国律师事务所驻华代表处执业许可证(副本); (二)外国律师事务所代表处代表执业证; (三)经过公证的办公场所证明，包括产权证明、房屋租赁协议(期限应当在1年以上)。 超过本条第一款规定的时间未办理开业注册的，外国律师事务所驻华代表处执业许可证和外国律师事务所代表处代表执业证自行失效。"},{"i":16,"n":"第十六条","txt":"未办理开业注册手续，代表处不得开展法律服务。"},{"i":17,"n":"第十七条","txt":"代表处办理年检注册，除提交《条例》第二十二条规定的各项材料外，还应当提供经公证、认证的派驻代表执业资格取得国的律师管理机构出具的下列文件材料： (一)代表处代表上一年度没有受过刑事处罚和没有因违反律师职业道德、执业纪律受过处罚的证明材料; (二)代表处及其代表有效的本年度执业责任风险保险文件复印件。"},{"i":18,"n":"第十八条","txt":"代表处及其代表通过年度检验的，省、自治区、直辖市司法厅(局)应当办理代表处和派驻代表的年度注册，并收取注册费。"},{"i":19,"n":"第十九条","txt":"设立代表处的外国律师事务所具有下列情形之一的，代表处应当向住所地的省、自治区、直辖市司法厅(局)备案： (一)律师事务所名称、总部住所、主要负责人变更的; (二)律师事务所合并、分立的。"},{"i":20,"n":"第二十条","txt":"代表处变更中、英文名称的，外国律师事务所应当向代表处住所地的省、自治区、直辖市司法厅(局)提交其主要负责人签署的申请书和有关的文件材料。司法厅(局)应当在收到申请材料之日起15日内提出审查意见报司法部。司法部应当自收到审查意见之日起15日内办理核准手续。 代表处持司法部核准通知，到住所地的省、自治区、直辖市司法厅(局)和有关部门办理相关变更手续。"},{"i":21,"n":"第二十一条","txt":"外国律师事务所申请注销代表处的，应当向代表处住所地的省、自治区、直辖市司法厅(局)提交其主要负责人签署的申请书。 省、自治区、直辖市司法厅(局)自收到申请之日起30日内将审查意见报司法部，司法部应当自收到审查意见之日起30日内办理核准手续。"},{"i":22,"n":"第二十二条","txt":"代表处自收到司法部核准注销通知之日起，应当依法进行清算。债务清偿完毕前财产不得转移。 对被注销的代表处，应当收回其执业许可证及其副本和代表执业证，并由住所地的省、自治区、直辖市司法厅(局)予以公告。"},{"i":23,"n":"第二十三条","txt":"代表处被注销后，债权人有权就尚未清偿的债权向外国律师事务所追偿。"},{"i":24,"n":"第二十四条","txt":"具有《条例》第十四条第一款第一、三项情形之一的，代表处应当自所属的律师事务所解散或注销之日起三个月内报告住所地的省、自治区、直辖市司法厅(局)，由司法厅(局)报司法部撤消其执业许可证，并根据本规定办理注销手续。"},{"i":25,"n":"第二十五条","txt":"代表处因特殊情况需要休业的，所属的外国律师事务所应当向住所地的省、自治区、直辖市司法厅(局)提交其主要负责人签署的申请书，经核准后，公告休业。 代表处休业期限不超过1年。超过1年的，视为自行注销。"},{"i":26,"n":"第二十六条","txt":"申请将代表处迁往其他城市的，由该外国律师事务所向拟迁往地的省、自治区、直辖市司法厅(局)提出申请，经审查后，报司法部核准。 代表处持核准通知，按规定办理相关注销和注册手续。"},{"i":27,"n":"第二十七条","txt":"代表处派驻或变更首席代表、派驻代表，应当符合《条例》第七条第二项的规定。 执业资格取得国律师协会会员，是指执业资格取得国法定的全国性或地区性律师行业组织成员。未设立律师行业组织的，可以是在执业资格取得国律师管理机构登记注册的人员。 境外执业时间，是指在执业资格取得国获得律师执业许可后，在该国法定律师注册登记机构进行律师执业注册登记的时间，包括在中国单独关税区的执业时间。境外执业时间可以累计计算。 相同职位的人员，是指在事务所经营管理、利润分享和风险分担方面与合伙人具有相同权利义务的执业律师。"},{"i":28,"n":"第二十八条","txt":"外国律师事务所派驻或变更首席代表、派驻代表，应当提交下列材料： (一)该外国律师事务所主要负责人签署的申请书。申请书应当包括下列内容： 1.拟派驻或变更首席代表、派驻代表的基本情况; 2.拟任职务、期限; 3.符合《条例》第七条第二项规定的承诺; 4.对所提供的信息、材料的真实性、完整性、准确性及中文译文与原文的一致性的承诺; 5.申请获得批准后遵守中国法律、法规、规章的承诺; 6.申请获得批准后将为其持续购买符合要求的执业风险保险的承诺。 (二)《条例》第八条第四至七项规定的各项材料; (三)拟任代表的执业风险保险文件复印件; (四)拟任代表的身份证明。 前款第二、三项规定的材料，应当经公证、认证。 上述申请材料应当附中文译文，按正、副本形式分别装帧成三份。"},{"i":29,"n":"第二十九条","txt":"省、自治区、直辖市司法厅(局)对外国律师事务所提交的拟任代表的申请材料，应当根据下列情形予以处理： (一)申请材料齐全的，按照《条例》第九条的规定办理; (二)申请材料不齐全的，自收到申请材料之日起15日内通知申请人补充材料。申请人在首次提交申请材料之日起3个月内补齐材料的，按照前项规定办理;申请人在首次提交申请材料之日起满3个月未能补齐材料的，应当作出不予受理的决定，并于15日内书面通知申请人。"},{"i":30,"n":"第三十条","txt":"司法部收到省、自治区、直辖市司法厅(局)报送的外国律师事务所申请材料和审查意见后，应当在6个月内予以核准，不予核准的，书面告知理由。 代表处持核准通知，到住所地的省、自治区、直辖市司法厅(局)领取外国律师事务所代表处代表执业证，并到有关部门办理相关手续。"},{"i":31,"n":"第三十一条","txt":"具有《条例》第十三条规定情形之一，司法部撤消代表执业证的，代表处住所地的省、自治区、直辖市司法厅(局)应当收回其执业证书，注销其执业注册，并予公告。"},{"i":32,"n":"第三十二条","txt":"下列行为，应当认定为《条例》第十五条规定的“中国法律事务”： (一)以律师身份在中国境内参与诉讼活动; (二)就合同、协议、章程或其他书面文件中适用中国法律的具体问题提供意见或证明; (三)就适用中国法律的行为或事件提供意见和证明; (四)在仲裁活动中，以代理人身份对中国法律的适用发表代理意见; (五)代表委托人向中国政府机关或其他法律法规授权的具有行政管理职能的组织办理登记、变更、申请、备案手续以及其他手续。"},{"i":33,"n":"第三十三条","txt":"代表处及其代表根据《条例》第十五条第一款第五项的规定，提供有关中国法律环境影响的信息时，不得就中国法律的适用提供具体意见或判断。"},{"i":34,"n":"第三十四条","txt":"根据《条例》第十一条的规定，代表处应当设立银行人民币账户和外汇账户，接受境内客户的汇入款项。 代表处应当按照中国税收法律法规的规定，依法办理税务登记，履行纳税义务，可以向当地主管税务机关申请领购发票。"},{"i":35,"n":"第三十五条","txt":"代表处聘用中国籍辅助人员的，应当与住所地外国企业服务部门办理聘用关系，并到住所地的省、自治区、直辖市司法厅(局)领取雇员证。"},{"i":36,"n":"第三十六条","txt":"代表处聘用外籍辅助人员的，应当按照外国人在华就业的有关规定，向住所地的省、自治区、直辖市司法厅(局)提出申请，经许可后，到有关部门办理就业和居留手续。"},{"i":37,"n":"第三十七条","txt":"代表处进行宣传，应当遵守下列规则： (一)向客户表明可以在中国境内从事业务的，应当同时表明其不具有从事中国法律服务的资格、执照或能力; (二)向客户声明具有中国律师资格或曾经担任中国执业律师的，应当同时声明其现在不能作为中国律师执业; (三)在信笺、名片上进行上述宣传的，应当有本条第一、二项规定的声明。"},{"i":38,"n":"第三十八条","txt":"代表处代表及其辅助人员不得以“中国法律顾问”名义为客户提供中国法律服务。"},{"i":39,"n":"第三十九条","txt":"代表处及其所属的律师事务所不得实施下列行为： (一)直接或间接地向中国律师事务所投资; (二)与中国律师事务所或中国律师组成共享利润或共担风险的执业联合体; (三)建立联合办公室或派员入驻中国律师事务所从事法律服务活动; (四)管理、经营、控制或享有中国律师事务所的股权性权益。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，应当认定为聘用中国执业律师： (一)与中国执业律师达成雇佣或劳务协议; (二)与中国执业律师形成事实上的雇佣或劳务关系; (三)与中国执业律师达成共享利润、共担风险或参与管理的协议; (四)向中国执业律师个人支付报酬、费用或业务分成; (五)聘请中国执业律师以代表处所属的律师事务所或代表处的名义对外从事业务活动。"},{"i":41,"n":"第四十一条","txt":"代表处应当就被投诉的行为进行澄清和说明。"},{"i":42,"n":"第四十二条","txt":"代表处应当在办公场所显著位置悬挂《外国律师事务所驻华代表处执业许可证》。 代表处应当在办公场所设置标牌，标牌上书写完整的中英文名称。"},{"i":43,"n":"第四十三条","txt":"《外国律师事务所代表处执业许可证》由司法部印制、颁发。 《外国律师事务所代表处代表执业证》和《外国律师事务所代表处雇员证》由司法部印制，省、自治区、直辖市司法厅(局)发放。"},{"i":44,"n":"第四十四条","txt":"《外国律师事务所代表处执业许可证》、《外国律师事务所代表处代表执业证》、《外国律师事务所代表处雇员证》，除发证机关依照法定程序可以扣留或吊销外，其他任何单位和个人不得收缴、扣押和损坏。"},{"i":45,"n":"第四十五条","txt":"代表处执业许可证及其副本、代表执业证和雇员证不得伪造、涂改、出租、出借、转让、出卖。 违反前款规定的，依法追究相应的法律责任。"},{"i":46,"n":"第四十六条","txt":"代表处执业许可证和代表执业证遗失的，经公告声明后，方可申请补领。"},{"i":47,"n":"第四十七条","txt":"本规定自二○○二年九月一日起施行。"}],"sifajiandingrendengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对司法鉴定人的管理，规范司法鉴定活动，建立统一的司法鉴定管理体制，适应司法机关和公民、组织的诉讼需要，保障当事人的诉讼权利，促进司法公正和效率，根据《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》和其他相关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"司法鉴定人从事《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》第二条规定的司法鉴定业务，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称的司法鉴定人是指运用科学技术或者专门知识对诉讼涉及的专门性问题进行鉴别和判断并提出鉴定意见的人员。 司法鉴定人应当具备本办法规定的条件，经省级司法行政机关审核登记，取得《司法鉴定人执业证》，按照登记的司法鉴定执业类别，从事司法鉴定业务。 司法鉴定人应当在一个司法鉴定机构中执业。"},{"i":4,"n":"第四条","txt":"司法鉴定管理实行行政管理与行业管理相结合的管理制度。 司法行政机关对司法鉴定人及其执业活动进行指导、管理和监督、检查，司法鉴定行业协会依法进行自律管理。"},{"i":5,"n":"第五条","txt":"全国实行统一的司法鉴定机构及司法鉴定人审核登记、名册编制和名册公告制度。"},{"i":6,"n":"第六条","txt":"司法鉴定人应当科学、客观、独立、公正地从事司法鉴定活动，遵守法律、法规的规定，遵守职业道德和职业纪律，遵守司法鉴定管理规范。"},{"i":7,"n":"第七条","txt":"司法鉴定人执业实行回避、保密、时限和错鉴责任追究制度。"},{"i":8,"n":"第八条","txt":"司法部负责全国司法鉴定人的登记管理工作，依法履行下列职责： (一)指导和监督省级司法行政机关对司法鉴定人的审核登记、名册编制和名册公告工作； (二)制定司法鉴定人执业规则和职业道德、职业纪律规范； (三)制定司法鉴定人诚信等级评估制度并指导实施； (四)会同国务院有关部门制定司法鉴定人专业技术职称评聘标准和办法； (五)制定和发布司法鉴定人继续教育规划并指导实施； (六)法律、法规规定的其他职责。"},{"i":9,"n":"第九条","txt":"省级司法行政机关负责本行政区域内司法鉴定人的登记管理工作，依法履行下列职责： (一)负责司法鉴定人的审核登记、名册编制和名册公告； (二)负责司法鉴定人诚信等级评估工作； (三)负责对司法鉴定人进行监督、检查； (四)负责对司法鉴定人违法违纪执业行为进行调查处理； (五)组织开展司法鉴定人专业技术职称评聘工作； (六)组织司法鉴定人参加司法鉴定岗前培训和继续教育； (七)法律、法规和规章规定的其他职责。"},{"i":10,"n":"第十条","txt":"省级司法行政机关可以委托下一级司法行政机关协助办理本办法第九条规定的有关工作。"},{"i":11,"n":"第十一条","txt":"司法鉴定人的登记事项包括：姓名、性别、出生年月、学历、专业技术职称或者行业资格、执业类别、执业机构等。"},{"i":12,"n":"第十二条","txt":"个人申请从事司法鉴定业务，应当具备下列条件： (一)拥护中华人民共和国宪法，遵守法律、法规和社会公德，品行良好的公民； (二)具有相关的高级专业技术职称；或者具有相关的行业执业资格或者高等院校相关专业本科以上学历，从事相关工作五年以上； (三)申请从事经验鉴定型或者技能鉴定型司法鉴定业务的，应当具备相关专业工作十年以上经历和较强的专业技能； (四)所申请从事的司法鉴定业务，行业有特殊规定的，应当符合行业规定； (五)拟执业机构已经取得或者正在申请《司法鉴定许可证》； (六)身体健康，能够适应司法鉴定工作需要。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，不得申请从事司法鉴定业务： (一)因故意犯罪或者职务过失犯罪受过刑事处罚的； (二)受过开除公职处分的； (三)被司法行政机关撤销司法鉴定人登记的； (四)所在的司法鉴定机构受到停业处罚，处罚期未满的； (五)无民事行为能力或者限制行为能力的； (六)法律、法规和规章规定的其他情形。"},{"i":14,"n":"第十四条","txt":"个人申请从事司法鉴定业务，应当由拟执业的司法鉴定机构向司法行政机关提交下列材料： (一)申请表； (二)身份证、专业技术职称、行业执业资格、学历、符合特殊行业要求的相关资格、从事相关专业工作经历、专业技术水平评价及业务成果等证明材料； (三)应当提交的其他材料。 个人兼职从事司法鉴定业务的，应当符合法律、法规的规定，并提供所在单位同意其兼职从事司法鉴定业务的书面意见。"},{"i":15,"n":"第十五条","txt":"司法鉴定人审核登记程序、期限参照《司法鉴定机构登记管理办法》中司法鉴定机构审核登记的相关规定办理。"},{"i":16,"n":"第十六条","txt":"经审核符合条件的，省级司法行政机关应当作出准予执业的决定，颁发《司法鉴定人执业证》；不符合条件的，作出不予登记的决定，书面通知其所在司法鉴定机构并说明理由。"},{"i":17,"n":"第十七条","txt":"《司法鉴定人执业证》由司法部统一监制。《司法鉴定人执业证》是司法鉴定人的执业凭证。 《司法鉴定人执业证》使用期限为五年，自颁发之日起计算。 《司法鉴定人执业证》应当载明下列内容： (一)姓名； (二)性别； (三)身份证号码； (四)专业技术职称； (五)行业执业资格； (六)执业类别； (七)执业机构； (八)使用期限； (九)颁证机关和颁证时间； (十)证书号码。"},{"i":18,"n":"第十八条","txt":"司法鉴定人要求变更有关登记事项的，应当及时通过所在司法鉴定机构向原负责登记的司法行政机关提交变更登记申请书和相关材料，经审核符合本办法规定的，司法行政机关应当依法办理变更登记手续。"},{"i":19,"n":"第十九条","txt":"《司法鉴定人执业证》使用期限届满后，需要继续执业的，司法鉴定人应当在使用期限届满三十日前通过所在司法鉴定机构，向原负责登记的司法行政机关提出延续申请，司法行政机关依法审核办理。延续申请的条件和需要提交的材料按照本办法第十二条、第十三条、第十四条、第十五条的规定执行。 不申请延续的司法鉴定人，《司法鉴定人执业证》使用期限届满后，由原负责登记的司法行政机关办理注销登记手续。"},{"i":20,"n":"第二十条","txt":"司法鉴定人有下列情形之一的，原负责登记的司法行政机关应当依法办理注销登记手续： (一)依法申请终止司法鉴定活动的； (二)所在司法鉴定机构注销或者被撤销的； (三)《司法鉴定人执业证》使用期限届满未申请延续的； (四)法律、法规规定的其他情形。"},{"i":21,"n":"第二十一条","txt":"司法鉴定人享有下列权利： (一)了解、查阅与鉴定事项有关的情况和资料，询问与鉴定事项有关的当事人、证人等； (二)要求鉴定委托人无偿提供鉴定所需要的鉴材、样本； (三)进行鉴定所必需的检验、检查和模拟实验； (四)拒绝接受不合法、不具备鉴定条件或者超出登记的执业类别的鉴定委托； (五)拒绝解决、回答与鉴定无关的问题； (六)鉴定意见不一致时，保留不同意见； (七)接受岗前培训和继续教育； (八)获得合法报酬； (九)法律、法规规定的其他权利。"},{"i":22,"n":"第二十二条","txt":"司法鉴定人应当履行下列义务： (一)受所在司法鉴定机构指派按照规定时限独立完成鉴定工作，并出具鉴定意见； (二)对鉴定意见负责； (三)依法回避； (四)妥善保管送鉴的鉴材、样本和资料； (五)保守在执业活动中知悉的国家秘密、商业秘密和个人隐私； (六)依法出庭作证，回答与鉴定有关的询问； (七)自觉接受司法行政机关的管理和监督、检查； (八)参加司法鉴定岗前培训和继续教育； (九)法律、法规规定的其他义务。"},{"i":23,"n":"第二十三条","txt":"司法鉴定人应当在所在司法鉴定机构接受司法行政机关统一部署的监督、检查。"},{"i":24,"n":"第二十四条","txt":"司法行政机关应当就下列事项，对司法鉴定人进行监督、检查： (一)遵守法律、法规和规章的情况； (二)遵守司法鉴定程序、技术标准和技术操作规范的情况； (三)遵守执业规则、职业道德和职业纪律的情况； (四)遵守所在司法鉴定机构内部管理制度的情况； (五)法律、法规和规章规定的其他事项。"},{"i":25,"n":"第二十五条","txt":"公民、法人和其他组织对司法鉴定人违反本办法规定的行为进行举报、投诉的，司法行政机关应当及时进行调查处理。"},{"i":26,"n":"第二十六条","txt":"司法行政机关对司法鉴定人进行监督、检查或者根据举报、投诉进行调查时，可以依法查阅或者要求司法鉴定人报送有关材料。司法鉴定人应当如实提供有关情况和材料。"},{"i":27,"n":"第二十七条","txt":"司法行政机关依法建立司法鉴定人诚信档案，对司法鉴定人进行诚信等级评估。评估结果向社会公开。"},{"i":28,"n":"第二十八条","txt":"未经登记的人员，从事已纳入本办法调整范围司法鉴定业务的，省级司法行政机关应当责令其停止司法鉴定活动，并处以违法所得一至三倍的罚款，罚款总额最高不得超过三万元。"},{"i":29,"n":"第二十九条","txt":"司法鉴定人有下列情形之一的，由省级司法行政机关依法给予警告，并责令其改正： (一)同时在两个以上司法鉴定机构执业的； (二)超出登记的执业类别执业的； (三)私自接受司法鉴定委托的； (四)违反保密和回避规定的； (五)拒绝接受司法行政机关监督、检查或者向其提供虚假材料的； (六)法律、法规和规章规定的其他情形。"},{"i":30,"n":"第三十条","txt":"司法鉴定人有下列情形之一的，由省级司法行政机关给予停止执业三个月以上一年以下的处罚；情节严重的，撤销登记；构成犯罪的，依法追究刑事责任： (一)因严重不负责任给当事人合法权益造成重大损失的； (二)具有本办法第二十九条规定的情形之一并造成严重后果的； (三)提供虚假证明文件或者采取其他欺诈手段，骗取登记的； (四)经人民法院依法通知，非法定事由拒绝出庭作证的； (五)故意做虚假鉴定的； (六)法律、法规规定的其他情形。"},{"i":31,"n":"第三十一条","txt":"司法鉴定人在执业活动中，因故意或者重大过失行为给当事人造成损失的，其所在的司法鉴定机构依法承担赔偿责任后，可以向有过错行为的司法鉴定人追偿。"},{"i":32,"n":"第三十二条","txt":"司法行政机关工作人员在管理工作中滥用职权、玩忽职守造成严重后果的，依法追究相应的法律责任。"},{"i":33,"n":"第三十三条","txt":"司法鉴定人对司法行政机关的行政许可和行政处罚有异议的，可以依法申请行政复议。"},{"i":34,"n":"第三十四条","txt":"本办法所称司法鉴定人不含《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》第七条规定的鉴定机构中从事鉴定工作的鉴定人。"},{"i":35,"n":"第三十五条","txt":"本办法自公布之日起施行。2000年8月14日公布的《司法鉴定人管理办法》(司法部令第63号)同时废止。"}],"sifajiandingzhiyehuodongtousuchulibanfa":[{"i":1,"n":"第一条","txt":"为了规范司法鉴定执业活动投诉处理工作，加强司法鉴定执业活动监督，维护投诉人的合法权益，根据《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》等规定，结合司法鉴定工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"投诉人对司法行政机关审核登记的司法鉴定机构或者司法鉴定人执业活动进行投诉，以及司法行政机关开展司法鉴定执业活动投诉处理工作，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称投诉人，是指认为司法鉴定机构或者司法鉴定人违法违规执业侵犯其合法权益，向司法行政机关投诉的与鉴定事项有利害关系的公民、法人和非法人组织。 本办法所称被投诉人，是指被投诉的司法鉴定机构或者司法鉴定人。"},{"i":4,"n":"第四条","txt":"投诉人应当自知道或者应当知道被投诉人鉴定活动侵犯其合法权益之日起三年内，向司法行政机关投诉。法律另有规定的除外。"},{"i":5,"n":"第五条","txt":"司法行政机关开展司法鉴定执业活动投诉处理工作，应当遵循属地管理、分级负责、依法查处、处罚与教育相结合的原则。 司法行政机关应当依法保障和维护投诉人、被投诉人的合法权益。"},{"i":6,"n":"第六条","txt":"司法行政机关应当向社会公布投诉受理范围、投诉处理机构的通讯方式等事项，并指定专人负责投诉接待和处理工作。"},{"i":7,"n":"第七条","txt":"司法部负责指导、监督全国司法鉴定执业活动投诉处理工作。 省级司法行政机关负责指导、监督本行政区域内司法鉴定执业活动投诉处理工作。"},{"i":8,"n":"第八条","txt":"司法行政机关指导、监督司法鉴定协会实施行业惩戒；司法鉴定协会协助和配合司法行政机关开展投诉处理工作。"},{"i":9,"n":"第九条","txt":"司法行政机关可以引导双方当事人在自愿、平等的基础上，依法通过调解方式解决涉及司法鉴定活动的民事纠纷。"},{"i":10,"n":"第十条","txt":"公民、法人和非法人组织认为司法鉴定机构或者司法鉴定人在执业活动中有下列违法违规情形的，可以向司法鉴定机构住所地或者司法鉴定人执业机构住所地的县级以上司法行政机关投诉： (一)司法鉴定机构组织未取得《司法鉴定人执业证》的人员违规从事司法鉴定业务的； (二)超出登记的业务范围或者执业类别从事司法鉴定活动的； (三)司法鉴定机构无正当理由拒绝接受司法鉴定委托的； (四)司法鉴定人私自接受司法鉴定委托的； (五)违反司法鉴定收费管理规定的； (六)违反司法鉴定程序规则从事司法鉴定活动的； (七)支付回扣、介绍费以及进行虚假宣传等不正当行为的； (八)因不负责任给当事人合法权益造成损失的； (九)司法鉴定人经人民法院通知，无正当理由拒绝出庭作证的； (十)司法鉴定人故意做虚假鉴定的； (十一)其他违反司法鉴定管理规定的行为。"},{"i":11,"n":"第十一条","txt":"省级司法行政机关接到投诉的，可以交由设区的市级或者直辖市的区(县)司法行政机关处理。 设区的市级或者直辖市的区(县)司法行政机关以及县级司法行政机关接到投诉的，应当按照本办法的规定直接处理。"},{"i":12,"n":"第十二条","txt":"投诉人应当向司法行政机关提交书面投诉材料。投诉材料内容包括：被投诉人的姓名或者名称、投诉事项、投诉请求、相关的事实和理由以及投诉人的联系方式，并提供投诉人身份证明、司法鉴定委托书或者司法鉴定意见书等与投诉事项相关的证明材料。投诉材料应当真实、合法、充分，并经投诉人签名或者盖章。 投诉人或者其法定代理人委托他人代理投诉的，代理人应当提供投诉人或者其法定代理人的授权委托书、代理人的联系方式和投诉人、代理人的身份证明。"},{"i":13,"n":"第十三条","txt":"负责处理的司法行政机关收到投诉材料后，应当及时进行登记。登记内容应当包括投诉人及其代理人的姓名或者名称、性别、身份证号码、职业、住址、联系方式，被投诉人的姓名或者名称、投诉事项、投诉请求、投诉理由以及相关证明材料目录，投诉的方式和时间等信息。"},{"i":14,"n":"第十四条","txt":"司法行政机关收到投诉材料后发现投诉人提供的信息不齐全或者无相关证明材料的，应当在收到投诉材料之日起七个工作日内一次性书面告知投诉人补充。书面告知内容应当包括需要补充的信息或者证明材料和合理的补充期限。 投诉人经告知后无正当理由逾期不补充的，视为投诉人放弃投诉。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，不予受理： (一)投诉事项已经司法行政机关处理，或者经行政复议、行政诉讼结案，且没有新的事实和证据的； (二)对人民法院、人民检察院、公安机关以及其他行政执法机关等在执法办案过程中，是否采信鉴定意见有异议的； (三)仅对鉴定意见有异议的； (四)对司法鉴定程序规则及司法鉴定标准、技术操作规范的规定有异议的； (五)投诉事项不属于违反司法鉴定管理规定的。"},{"i":16,"n":"第十六条","txt":"司法行政机关应当及时审查投诉材料，对投诉材料齐全，属于本机关管辖范围并符合受理条件的投诉，应当受理；对不属于本机关管辖范围或者不符合受理条件的投诉，不予受理并说明理由。对于司法行政机关已经按照前款规定作出不予受理决定的投诉事项，投诉人重复投诉且未能提供新的事实和理由的，司法行政机关不予受理。"},{"i":17,"n":"第十七条","txt":"投诉材料齐全的，司法行政机关应当自收到投诉材料之日起七个工作日内，作出是否受理的决定，并书面告知投诉人。情况复杂的，可以适当延长作出受理决定的时间，但延长期限不得超过十五个工作日，并应当将延长的时间和理由书面告知投诉人。 投诉人补充投诉材料所需的时间和投诉案件移送、转办的流转时间，不计算在前款规定期限内。"},{"i":18,"n":"第十八条","txt":"司法行政机关受理投诉后，应当全面、客观、公正地进行调查。调查工作不得妨碍被投诉人正常的司法鉴定执业活动。 上级司法行政机关认为有必要的，可以委托下一级司法行政机关进行调查。"},{"i":19,"n":"第十九条","txt":"司法行政机关进行调查，应当要求被投诉人说明情况、提交有关材料，调阅被投诉人有关业务案卷和档案材料，向有关单位、个人核实情况、收集证据；并根据情况，可以组织专家咨询、论证或者听取有关部门的意见和建议。 调查应当由两名以上工作人员进行。必要时，应当制作调查笔录，并由相关人员签字或者盖章；不能或者拒绝签字、盖章的，应当在笔录中注明有关情况。 调查人员应当对被投诉人及有关单位、个人提供的证据和有关材料进行登记、审核并妥善保管；不能保存原件的，应当经调查人员和被投诉人或者有关单位、个人确认，并签字或者盖章后保留复制件。"},{"i":20,"n":"第二十条","txt":"司法行政机关根据投诉处理工作需要，可以委托司法鉴定协会协助开展调查工作。 接受委托的司法鉴定协会可以组织专家对投诉涉及的相关专业技术问题进行论证，并提供论证意见；组织有关专家接待投诉人并提供咨询等。"},{"i":21,"n":"第二十一条","txt":"被投诉人应当配合调查工作，在司法行政机关要求的期限内如实陈述事实、提供有关材料，不得提供虚假、伪造的材料或者隐匿、毁损、涂改有关证据材料。 被投诉人为司法鉴定人的，其所在的司法鉴定机构应当配合调查。"},{"i":22,"n":"第二十二条","txt":"司法行政机关在调查过程中发现有本办法第十五条规定情形的，或者投诉人书面申请撤回投诉的，可以终止投诉处理工作，并将终止决定和理由书面告知投诉人、被投诉人。 投诉人书面申请撤回投诉的，不得再以同一事实和理由投诉。但是，投诉人能够证明撤回投诉违背其真实意思表示的除外。"},{"i":23,"n":"第二十三条","txt":"司法行政机关在调查过程中，发现被投诉人的违法违规行为仍处在连续或者继续状态的，应当责令被投诉人立即停止违法违规行为。"},{"i":24,"n":"第二十四条","txt":"司法行政机关应当根据对投诉事项的调查结果，分别作出以下处理： (一)被投诉人有应当给予行政处罚的违法违规行为的，依法给予行政处罚或者移送有处罚权的司法行政机关依法给予行政处罚； (二)被投诉人违法违规情节轻微，没有造成危害后果，依法可以不予行政处罚的，应当给予批评教育、训诫、通报、责令限期整改等处理； (三)投诉事项查证不实或者无法查实的，对被投诉人不作处理，并向投诉人说明情况。 涉嫌违反职业道德、执业纪律和行业自律规范的，移交有关司法鉴定协会调查处理；涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"司法行政机关受理投诉的，应当自作出投诉受理决定之日起六十日内作出处理决定；情况复杂，不能在规定期限内作出处理的，经本机关负责人批准，可以适当延长办理期限，但延长期限不得超过三十日，并应当将延长的时间和理由书面告知投诉人。"},{"i":26,"n":"第二十六条","txt":"司法行政机关应当自作出处理决定之日起七个工作日内，将投诉处理结果以及不服处理结果的救济途径和期限等书面告知投诉人、被投诉人。"},{"i":27,"n":"第二十七条","txt":"对于被投诉人存在违法违规行为并被处罚、处理的，司法行政机关应当及时将投诉处理结果通报委托办案机关和相关司法鉴定协会，并向社会公开。 司法行政机关应当将前款中的投诉处理结果记入被投诉人的司法鉴定执业诚信档案。"},{"i":28,"n":"第二十八条","txt":"投诉人、被投诉人认为司法行政机关的投诉处理结果侵犯其合法权益的，可以依法申请行政复议或者提起行政诉讼。"},{"i":29,"n":"第二十九条","txt":"司法行政机关应当建立司法鉴定执业活动投诉处理工作档案，并妥善保管和使用。"},{"i":30,"n":"第三十条","txt":"司法行政机关应当对被投诉人履行处罚、处理决定，纠正违法违规行为的情况进行检查、监督，发现问题应当责令其限期整改。"},{"i":31,"n":"第三十一条","txt":"上级司法行政机关应当加强对下级司法行政机关投诉处理工作的指导、监督和检查，发现有违法、不当情形的，应当及时责令改正。下级司法行政机关应当及时上报纠正情况。"},{"i":32,"n":"第三十二条","txt":"司法行政机关工作人员在投诉处理工作中有滥用职权、玩忽职守或者其他违法行为，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":33,"n":"第三十三条","txt":"司法行政机关应当按年度将司法鉴定执业活动投诉处理工作情况书面报告上一级司法行政机关。 对于涉及重大违法违规行为的投诉处理结果，应当及时报告上一级司法行政机关。"},{"i":34,"n":"第三十四条","txt":"与司法鉴定活动没有利害关系的公民、法人和非法人组织举报司法鉴定机构或者司法鉴定人违法违规执业的，司法行政机关应当参照本办法第十八条至第二十四条有关规定进行处理。"},{"i":35,"n":"第三十五条","txt":"对司法鉴定机构或者司法鉴定人在诉讼活动之外开展的相关鉴定业务提出投诉的，参照本办法规定执行。"},{"i":36,"n":"第三十六条","txt":"外国人、无国籍人、外国组织提出投诉的，适用本办法。"},{"i":37,"n":"第三十七条","txt":"本办法由司法部解释。"},{"i":38,"n":"第三十八条","txt":"本办法自2019年6月1日起施行。2010年4月8日发布的《司法鉴定执业活动投诉处理办法》(司法部令第123号)同时废止。"}],"sifajiandingjigoudengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对司法鉴定机构的管理，规范司法鉴定活动，建立统一的司法鉴定管理体制，适应司法机关和公民、组织的诉讼需要，保障当事人的诉讼权利，促进司法公正与效率，根据《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》和其他相关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"司法鉴定机构从事《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》第二条规定的司法鉴定业务，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称的司法鉴定机构是指从事《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》第二条规定的司法鉴定业务的法人或者其他组织。 司法鉴定机构是司法鉴定人的执业机构，应当具备本办法规定的条件，经省级司法行政机关审核登记，取得《司法鉴定许可证》，在登记的司法鉴定业务范围内，开展司法鉴定活动。"},{"i":4,"n":"第四条","txt":"司法鉴定管理实行行政管理与行业管理相结合的管理制度。 司法行政机关对司法鉴定机构及其司法鉴定活动依法进行指导、管理和监督、检查。司法鉴定行业协会依法进行自律管理。"},{"i":5,"n":"第五条","txt":"全国实行统一的司法鉴定机构及司法鉴定人审核登记、名册编制和名册公告制度。"},{"i":6,"n":"第六条","txt":"司法鉴定机构的发展应当符合统筹规划、合理布局、优化结构、有序发展的要求。"},{"i":7,"n":"第七条","txt":"司法鉴定机构开展司法鉴定活动应当遵循合法、中立、规范、及时的原则。"},{"i":8,"n":"第八条","txt":"司法鉴定机构统一接受委托，组织所属的司法鉴定人开展司法鉴定活动，遵守法律、法规和有关制度，执行统一的司法鉴定实施程序、技术标准和技术操作规范。"},{"i":9,"n":"第九条","txt":"司法部负责全国司法鉴定机构的登记管理工作，依法履行下列职责： (一)制定全国司法鉴定发展规划并指导实施； (二)指导和监督省级司法行政机关对司法鉴定机构的审核登记、名册编制和名册公告工作； (三)制定全国统一的司法鉴定机构资质管理评估制度和司法鉴定质量管理评估制度并指导实施； (四)组织制定全国统一的司法鉴定实施程序、技术标准和技术操作规范等司法鉴定技术管理制度并指导实施； (五)指导司法鉴定科学技术研究、开发、引进与推广，组织司法鉴定业务的中外交流与合作； (六)法律、法规规定的其他职责。"},{"i":10,"n":"第十条","txt":"省级司法行政机关负责本行政区域内司法鉴定机构的登记管理工作，依法履行下列职责： (一)制定本行政区域司法鉴定发展规划并组织实施； (二)负责司法鉴定机构的审核登记、名册编制和名册公告工作； (三)负责司法鉴定机构资质管理评估和司法鉴定质量管理评估工作； (四)负责对司法鉴定机构进行监督、检查； (五)负责对司法鉴定机构违法违纪的执业行为进行调查处理； (六)组织司法鉴定科学技术开发、推广和应用； (七)法律、法规和规章规定的其他职责。"},{"i":11,"n":"第十一条","txt":"省级司法行政机关可以委托下一级司法行政机关协助办理本办法第十条规定的有关工作。"},{"i":12,"n":"第十二条","txt":"司法行政机关负责监督指导司法鉴定行业协会及其专业委员会依法开展活动。"},{"i":13,"n":"第十三条","txt":"司法鉴定机构的登记事项包括：名称、住所、法定代表人或者鉴定机构负责人、资金数额、仪器设备和实验室、司法鉴定人、司法鉴定业务范围等。"},{"i":14,"n":"第十四条","txt":"法人或者其他组织申请从事司法鉴定业务，应当具备下列条件： (一)有自己的名称、住所； (二)有不少于二十万至一百万元人民币的资金； (三)有明确的司法鉴定业务范围； (四)有在业务范围内进行司法鉴定必需的仪器、设备； (五)有在业务范围内进行司法鉴定必需的依法通过计量认证或者实验室认可的检测实验室； (六)每项司法鉴定业务有三名以上司法鉴定人。"},{"i":15,"n":"第十五条","txt":"法人或者其他组织申请从事司法鉴定业务，应当提交下列申请材料： (一)申请表； (二)证明申请者身份的相关文件； (三)住所证明和资金证明； (四)相关的行业资格、资质证明； (五)仪器、设备说明及所有权凭证； (六)检测实验室相关资料； (七)司法鉴定人申请执业的相关材料； (八)相关的内部管理制度材料； (九)应当提交的其他材料。 申请人应当对申请材料的真实性、完整性和可靠性负责。"},{"i":16,"n":"第十六条","txt":"申请设立具有独立法人资格的司法鉴定机构，除应当提交本办法第十五条规定的申请材料外，还应当提交司法鉴定机构章程，按照司法鉴定机构名称管理的有关规定向司法行政机关报核其机构名称。"},{"i":17,"n":"第十七条","txt":"司法鉴定机构在本省(自治区、直辖市)行政区域内设立分支机构的，分支机构应当符合本办法第十四条规定的条件，并经省级司法行政机关审核登记后，方可依法开展司法鉴定活动。 跨省(自治区、直辖市)设立分支机构的，除应当经拟设分支机构所在行政区域的省级司法行政机关审核登记外，还应当报经司法鉴定机构所在行政区域的省级司法行政机关同意。"},{"i":18,"n":"第十八条","txt":"司法鉴定机构应当参加司法鉴定执业责任保险或者建立执业风险金制度。"},{"i":19,"n":"第十九条","txt":"法人或者其他组织申请从事司法鉴定业务，有下列情形之一的，司法行政机关不予受理，并出具不予受理决定书： (一)法定代表人或者鉴定机构负责人受过刑事处罚或者开除公职处分的； (二)法律、法规规定的其他情形。"},{"i":20,"n":"第二十条","txt":"司法行政机关决定受理申请的，应当出具受理决定书，并按照法定的时限和程序完成审核工作。 司法行政机关应当组织专家，对申请人从事司法鉴定业务必需的仪器、设备和检测实验室进行评审，评审的时间不计入审核时限。"},{"i":21,"n":"第二十一条","txt":"经审核符合条件的，省级司法行政机关应当作出准予登记的决定，颁发《司法鉴定许可证》；不符合条件的，作出不予登记的决定，书面通知申请人并说明理由。"},{"i":22,"n":"第二十二条","txt":"《司法鉴定许可证》是司法鉴定机构的执业凭证，司法鉴定机构必须持有省级司法行政机关准予登记的决定及《司法鉴定许可证》，方可依法开展司法鉴定活动。 《司法鉴定许可证》由司法部统一监制，分为正本和副本。《司法鉴定许可证》正本和副本具有同等的法律效力。 《司法鉴定许可证》使用期限为五年，自颁发之日起计算。 《司法鉴定许可证》应当载明下列内容： (一)机构名称； (二)机构住所； (三)法定代表人或者鉴定机构负责人姓名； (四)资金数额； (五)业务范围； (六)使用期限； (七)颁证机关和颁证时间； (八)证书号码。"},{"i":23,"n":"第二十三条","txt":"司法鉴定资源不足的地区，司法行政机关可以采取招标的方式审核登记司法鉴定机构。招标的具体程序、时限按照有关法律、法规的规定执行。"},{"i":24,"n":"第二十四条","txt":"司法鉴定机构要求变更有关登记事项的，应当及时向原负责登记的司法行政机关提交变更登记申请书和相关材料，经审核符合本办法规定的，司法行政机关应当依法办理变更登记手续。"},{"i":25,"n":"第二十五条","txt":"司法鉴定机构变更后的登记事项，应当在《司法鉴定许可证》副本上注明。在《司法鉴定许可证》使用期限内获准变更的事项，使用期限应当与《司法鉴定许可证》的使用期限相一致。"},{"i":26,"n":"第二十六条","txt":"《司法鉴定许可证》使用期限届满后，需要延续的，司法鉴定机构应当在使用期限届满三十日前，向原负责登记的司法行政机关提出延续申请，司法行政机关依法审核办理。延续的条件和需要提交的申请材料按照本办法第三章申请登记的有关规定执行。 不申请延续的司法鉴定机构，《司法鉴定许可证》使用期限届满后，由原负责登记的司法行政机关办理注销登记手续。"},{"i":27,"n":"第二十七条","txt":"司法鉴定机构有下列情形之一的，原负责登记的司法行政机关应当依法办理注销登记手续： (一)依法申请终止司法鉴定活动的； (二)自愿解散或者停业的； (三)登记事项发生变化，不符合设立条件的； (四)《司法鉴定许可证》使用期限届满未申请延续的； (五)法律、法规规定的其他情形。"},{"i":28,"n":"第二十八条","txt":"凡经司法行政机关审核登记的司法鉴定机构及司法鉴定人，必须统一编入司法鉴定人和司法鉴定机构名册并公告。"},{"i":29,"n":"第二十九条","txt":"省级司法行政机关负责编制本行政区域的司法鉴定人和司法鉴定机构名册，报司法部备案后，在本行政区域内每年公告一次。司法部负责汇总省级司法行政机关编制的司法鉴定人和司法鉴定机构名册，在全国范围内每五年公告一次。 未经司法部批准，其他部门和组织不得以任何名义编制司法鉴定人和司法鉴定机构名册或者类似名册。"},{"i":30,"n":"第三十条","txt":"司法鉴定人和司法鉴定机构名册分为电子版和纸质版。电子版由司法行政机关负责公告，纸质版由司法行政机关组织司法鉴定机构在有关媒体上公告并正式出版。"},{"i":31,"n":"第三十一条","txt":"司法机关和公民、组织可以委托列入司法鉴定人和司法鉴定机构名册的司法鉴定机构及司法鉴定人进行鉴定。 在诉讼活动中，对《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》第二条所规定的鉴定事项发生争议，需要鉴定的，司法机关和公民、组织应当委托列入司法鉴定人和司法鉴定机构名册的司法鉴定机构及司法鉴定人进行鉴定。"},{"i":32,"n":"第三十二条","txt":"编制、公告司法鉴定人和司法鉴定机构名册的具体程序、内容和格式由司法部另行制定。"},{"i":33,"n":"第三十三条","txt":"司法行政机关应当按照统一部署，依法对司法鉴定机构进行监督、检查。 公民、法人和其他组织对司法鉴定机构违反本办法规定的行为进行举报、投诉的，司法行政机关应当及时进行监督、检查，并根据调查结果进行处理。"},{"i":34,"n":"第三十四条","txt":"司法行政机关可以就下列事项，对司法鉴定机构进行监督、检查： (一)遵守法律、法规和规章的情况； (二)遵守司法鉴定程序、技术标准和技术操作规范的情况； (三)所属司法鉴定人执业的情况； (四)法律、法规和规章规定的其他事项。"},{"i":35,"n":"第三十五条","txt":"司法行政机关对司法鉴定机构进行监督、检查时，可以依法查阅或者要求司法鉴定机构报送有关材料。司法鉴定机构应当如实提供有关情况和材料。"},{"i":36,"n":"第三十六条","txt":"司法行政机关对司法鉴定机构进行监督、检查时，不得妨碍司法鉴定机构的正常业务活动，不得索取或者收受司法鉴定机构的财物，不得谋取其他不正当利益。"},{"i":37,"n":"第三十七条","txt":"司法行政机关对司法鉴定机构进行资质评估，对司法鉴定质量进行评估。评估结果向社会公开。"},{"i":38,"n":"第三十八条","txt":"法人或者其他组织未经登记，从事已纳入本办法调整范围司法鉴定业务的，省级司法行政机关应当责令其停止司法鉴定活动，并处以违法所得一至三倍的罚款，罚款总额最高不得超过三万元。"},{"i":39,"n":"第三十九条","txt":"司法鉴定机构有下列情形之一的，由省级司法行政机关依法给予警告，并责令其改正： (一)超出登记的司法鉴定业务范围开展司法鉴定活动的； (二)未经依法登记擅自设立分支机构的； (三)未依法办理变更登记的； (四)出借《司法鉴定许可证》的； (五)组织未取得《司法鉴定人执业证》的人员从事司法鉴定业务的； (六)无正当理由拒绝接受司法鉴定委托的； (七)违反司法鉴定收费管理办法的； (八)支付回扣、介绍费，进行虚假宣传等不正当行为的； (九)拒绝接受司法行政机关监督、检查或者向其提供虚假材料的； (十)法律、法规和规章规定的其他情形。"},{"i":40,"n":"第四十条","txt":"司法鉴定机构有下列情形之一的，由省级司法行政机关依法给予停止从事司法鉴定业务三个月以上一年以下的处罚；情节严重的，撤销登记： (一)因严重不负责任给当事人合法权益造成重大损失的； (二)具有本办法第三十九条规定的情形之一，并造成严重后果的； (三)提供虚假证明文件或采取其他欺诈手段，骗取登记的； (四)法律、法规规定的其他情形。"},{"i":41,"n":"第四十一条","txt":"司法鉴定机构在开展司法鉴定活动中因违法和过错行为应当承担民事责任的，按照民事法律的有关规定执行。"},{"i":42,"n":"第四十二条","txt":"司法行政机关的工作人员在管理工作中滥用职权、玩忽职守造成严重后果的，依法追究相应的法律责任。"},{"i":43,"n":"第四十三条","txt":"司法鉴定机构对司法行政机关的行政许可和行政处罚有异议的，可以依法申请行政复议。"},{"i":44,"n":"第四十四条","txt":"本办法所称司法鉴定机构不含《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》第七条规定的鉴定机构。"},{"i":45,"n":"第四十五条","txt":"本办法自公布之日起施行。2000年8月14日公布的《司法鉴定机构登记管理办法》(司法部令第62号)同时废止。"}],"sifajiandingchengxutongze":[{"i":1,"n":"第一条","txt":"为了规范司法鉴定机构和司法鉴定人的司法鉴定活动，保障司法鉴定质量，保障诉讼活动的顺利进行，根据《全国人民代表大会常务委员会关于司法鉴定管理问题的决定》和有关法律、法规的规定，制定本通则。"},{"i":2,"n":"第二条","txt":"司法鉴定是指在诉讼活动中鉴定人运用科学技术或者专门知识对诉讼涉及的专门性问题进行鉴别和判断并提供鉴定意见的活动。司法鉴定程序是指司法鉴定机构和司法鉴定人进行司法鉴定活动的方式、步骤以及相关规则的总称。"},{"i":3,"n":"第三条","txt":"本通则适用于司法鉴定机构和司法鉴定人从事各类司法鉴定业务的活动。"},{"i":4,"n":"第四条","txt":"司法鉴定机构和司法鉴定人进行司法鉴定活动，应当遵守法律、法规、规章，遵守职业道德和执业纪律，尊重科学，遵守技术操作规范。"},{"i":5,"n":"第五条","txt":"司法鉴定实行鉴定人负责制度。司法鉴定人应当依法独立、客观、公正地进行鉴定，并对自己作出的鉴定意见负责。司法鉴定人不得违反规定会见诉讼当事人及其委托的人。"},{"i":6,"n":"第六条","txt":"司法鉴定机构和司法鉴定人应当保守在执业活动中知悉的国家秘密、商业秘密，不得泄露个人隐私。"},{"i":7,"n":"第七条","txt":"司法鉴定人在执业活动中应当依照有关诉讼法律和本通则规定实行回避。"},{"i":8,"n":"第八条","txt":"司法鉴定收费执行国家有关规定。"},{"i":9,"n":"第九条","txt":"司法鉴定机构和司法鉴定人进行司法鉴定活动应当依法接受监督。对于有违反有关法律、法规、规章规定行为的，由司法行政机关依法给予相应的行政处罚；对于有违反司法鉴定行业规范行为的，由司法鉴定协会给予相应的行业处分。"},{"i":10,"n":"第十条","txt":"司法鉴定机构应当加强对司法鉴定人执业活动的管理和监督。司法鉴定人违反本通则规定的，司法鉴定机构应当予以纠正。"},{"i":11,"n":"第十一条","txt":"司法鉴定机构应当统一受理办案机关的司法鉴定委托。"},{"i":12,"n":"第十二条","txt":"委托人委托鉴定的，应当向司法鉴定机构提供真实、完整、充分的鉴定材料，并对鉴定材料的真实性、合法性负责。司法鉴定机构应当核对并记录鉴定材料的名称、种类、数量、性状、保存状况、收到时间等。 诉讼当事人对鉴定材料有异议的，应当向委托人提出。 本通则所称鉴定材料包括生物检材和非生物检材、比对样本材料以及其他与鉴定事项有关的鉴定资料。"},{"i":13,"n":"第十三条","txt":"司法鉴定机构应当自收到委托之日起七个工作日内作出是否受理的决定。对于复杂、疑难或者特殊鉴定事项的委托，司法鉴定机构可以与委托人协商决定受理的时间。"},{"i":14,"n":"第十四条","txt":"司法鉴定机构应当对委托鉴定事项、鉴定材料等进行审查。对属于本机构司法鉴定业务范围，鉴定用途合法，提供的鉴定材料能够满足鉴定需要的，应当受理。 对于鉴定材料不完整、不充分，不能满足鉴定需要的，司法鉴定机构可以要求委托人补充；经补充后能够满足鉴定需要的，应当受理。"},{"i":15,"n":"第十五条","txt":"具有下列情形之一的鉴定委托，司法鉴定机构不得受理： (一)委托鉴定事项超出本机构司法鉴定业务范围的； (二)发现鉴定材料不真实、不完整、不充分或者取得方式不合法的； (三)鉴定用途不合法或者违背社会公德的； (四)鉴定要求不符合司法鉴定执业规则或者相关鉴定技术规范的； (五)鉴定要求超出本机构技术条件或者鉴定能力的； (六)委托人就同一鉴定事项同时委托其他司法鉴定机构进行鉴定的； (七)其他不符合法律、法规、规章规定的情形。"},{"i":16,"n":"第十六条","txt":"司法鉴定机构决定受理鉴定委托的，应当与委托人签订司法鉴定委托书。司法鉴定委托书应当载明委托人名称、司法鉴定机构名称、委托鉴定事项、是否属于重新鉴定、鉴定用途、与鉴定有关的基本案情、鉴定材料的提供和退还、鉴定风险，以及双方商定的鉴定时限、鉴定费用及收取方式、双方权利义务等其他需要载明的事项。"},{"i":17,"n":"第十七条","txt":"司法鉴定机构决定不予受理鉴定委托的，应当向委托人说明理由，退还鉴定材料。"},{"i":18,"n":"第十八条","txt":"司法鉴定机构受理鉴定委托后，应当指定本机构具有该鉴定事项执业资格的司法鉴定人进行鉴定。 委托人有特殊要求的，经双方协商一致，也可以从本机构中选择符合条件的司法鉴定人进行鉴定。 委托人不得要求或者暗示司法鉴定机构、司法鉴定人按其意图或者特定目的提供鉴定意见。"},{"i":19,"n":"第十九条","txt":"司法鉴定机构对同一鉴定事项，应当指定或者选择二名司法鉴定人进行鉴定；对复杂、疑难或者特殊鉴定事项，可以指定或者选择多名司法鉴定人进行鉴定。"},{"i":20,"n":"第二十条","txt":"司法鉴定人本人或者其近亲属与诉讼当事人、鉴定事项涉及的案件有利害关系，可能影响其独立、客观、公正进行鉴定的，应当回避。 司法鉴定人曾经参加过同一鉴定事项鉴定的，或者曾经作为专家提供过咨询意见的，或者曾被聘请为有专门知识的人参与过同一鉴定事项法庭质证的，应当回避。"},{"i":21,"n":"第二十一条","txt":"司法鉴定人自行提出回避的，由其所属的司法鉴定机构决定；委托人要求司法鉴定人回避的，应当向该司法鉴定人所属的司法鉴定机构提出，由司法鉴定机构决定。 委托人对司法鉴定机构作出的司法鉴定人是否回避的决定有异议的，可以撤销鉴定委托。"},{"i":22,"n":"第二十二条","txt":"司法鉴定机构应当建立鉴定材料管理制度，严格监控鉴定材料的接收、保管、使用和退还。 司法鉴定机构和司法鉴定人在鉴定过程中应当严格依照技术规范保管和使用鉴定材料，因严重不负责任造成鉴定材料损毁、遗失的，应当依法承担责任。"},{"i":23,"n":"第二十三条","txt":"司法鉴定人进行鉴定，应当依下列顺序遵守和采用该专业领域的技术标准、技术规范和技术方法： (一)国家标准； (二)行业标准和技术规范； (三)该专业领域多数专家认可的技术方法。"},{"i":24,"n":"第二十四条","txt":"司法鉴定人有权了解进行鉴定所需要的案件材料，可以查阅、复制相关资料，必要时可以询问诉讼当事人、证人。 经委托人同意，司法鉴定机构可以派员到现场提取鉴定材料。现场提取鉴定材料应当由不少于二名司法鉴定机构的工作人员进行，其中至少一名应为该鉴定事项的司法鉴定人。现场提取鉴定材料时，应当有委托人指派或者委托的人员在场见证并在提取记录上签名。"},{"i":25,"n":"第二十五条","txt":"鉴定过程中，需要对无民事行为能力人或者限制民事行为能力人进行身体检查的，应当通知其监护人或者近亲属到场见证；必要时，可以通知委托人到场见证。 对被鉴定人进行法医精神病鉴定的，应当通知委托人或者被鉴定人的近亲属或者监护人到场见证。 对需要进行尸体解剖的，应当通知委托人或者死者的近亲属或者监护人到场见证。 到场见证人员应当在鉴定记录上签名。见证人员未到场的，司法鉴定人不得开展相关鉴定活动，延误时间不计入鉴定时限。"},{"i":26,"n":"第二十六条","txt":"鉴定过程中，需要对被鉴定人身体进行法医临床检查的，应当采取必要措施保护其隐私。"},{"i":27,"n":"第二十七条","txt":"司法鉴定人应当对鉴定过程进行实时记录并签名。记录可以采取笔记、录音、录像、拍照等方式。记录应当载明主要的鉴定方法和过程，检查、检验、检测结果，以及仪器设备使用情况等。记录的内容应当真实、客观、准确、完整、清晰，记录的文本资料、音像资料等应当存入鉴定档案。"},{"i":28,"n":"第二十八条","txt":"司法鉴定机构应当自司法鉴定委托书生效之日起三十个工作日内完成鉴定。 鉴定事项涉及复杂、疑难、特殊技术问题或者鉴定过程需要较长时间的，经本机构负责人批准，完成鉴定的时限可以延长，延长时限一般不得超过三十个工作日。鉴定时限延长的，应当及时告知委托人。 司法鉴定机构与委托人对鉴定时限另有约定的，从其约定。 在鉴定过程中补充或者重新提取鉴定材料所需的时间，不计入鉴定时限。"},{"i":29,"n":"第二十九条","txt":"司法鉴定机构在鉴定过程中，有下列情形之一的，可以终止鉴定： (一)发现有本通则第十五条第二项至第七项规定情形的； (二)鉴定材料发生耗损，委托人不能补充提供的； (三)委托人拒不履行司法鉴定委托书规定的义务、被鉴定人拒不配合或者鉴定活动受到严重干扰，致使鉴定无法继续进行的； (四)委托人主动撤销鉴定委托，或者委托人、诉讼当事人拒绝支付鉴定费用的； (五)因不可抗力致使鉴定无法继续进行的； (六)其他需要终止鉴定的情形。 终止鉴定的，司法鉴定机构应当书面通知委托人，说明理由并退还鉴定材料。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，司法鉴定机构可以根据委托人的要求进行补充鉴定： (一)原委托鉴定事项有遗漏的； (二)委托人就原委托鉴定事项提供新的鉴定材料的； (三)其他需要补充鉴定的情形。 补充鉴定是原委托鉴定的组成部分，应当由原司法鉴定人进行。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，司法鉴定机构可以接受办案机关委托进行重新鉴定： (一)原司法鉴定人不具有从事委托鉴定事项执业资格的； (二)原司法鉴定机构超出登记的业务范围组织鉴定的； (三)原司法鉴定人应当回避没有回避的； (四)办案机关认为需要重新鉴定的； (五)法律规定的其他情形。"},{"i":32,"n":"第三十二条","txt":"重新鉴定应当委托原司法鉴定机构以外的其他司法鉴定机构进行；因特殊原因，委托人也可以委托原司法鉴定机构进行，但原司法鉴定机构应当指定原司法鉴定人以外的其他符合条件的司法鉴定人进行。 接受重新鉴定委托的司法鉴定机构的资质条件应当不低于原司法鉴定机构，进行重新鉴定的司法鉴定人中应当至少有一名具有相关专业高级专业技术职称。"},{"i":33,"n":"第三十三条","txt":"鉴定过程中，涉及复杂、疑难、特殊技术问题的，可以向本机构以外的相关专业领域的专家进行咨询，但最终的鉴定意见应当由本机构的司法鉴定人出具。 专家提供咨询意见应当签名，并存入鉴定档案。"},{"i":34,"n":"第三十四条","txt":"对于涉及重大案件或者特别复杂、疑难、特殊技术问题或者多个鉴定类别的鉴定事项，办案机关可以委托司法鉴定行业协会组织协调多个司法鉴定机构进行鉴定。"},{"i":35,"n":"第三十五条","txt":"司法鉴定人完成鉴定后，司法鉴定机构应当指定具有相应资质的人员对鉴定程序和鉴定意见进行复核；对于涉及复杂、疑难、特殊技术问题或者重新鉴定的鉴定事项，可以组织三名以上的专家进行复核。 复核人员完成复核后，应当提出复核意见并签名，存入鉴定档案。"},{"i":36,"n":"第三十六条","txt":"司法鉴定机构和司法鉴定人应当按照统一规定的文本格式制作司法鉴定意见书。"},{"i":37,"n":"第三十七条","txt":"司法鉴定意见书应当由司法鉴定人签名。多人参加的鉴定，对鉴定意见有不同意见的，应当注明。"},{"i":38,"n":"第三十八条","txt":"司法鉴定意见书应当加盖司法鉴定机构的司法鉴定专用章。"},{"i":39,"n":"第三十九条","txt":"司法鉴定意见书应当一式四份，三份交委托人收执，一份由司法鉴定机构存档。司法鉴定机构应当按照有关规定或者与委托人约定的方式，向委托人发送司法鉴定意见书。"},{"i":40,"n":"第四十条","txt":"委托人对鉴定过程、鉴定意见提出询问的，司法鉴定机构和司法鉴定人应当给予解释或者说明。"},{"i":41,"n":"第四十一条","txt":"司法鉴定意见书出具后，发现有下列情形之一的，司法鉴定机构可以进行补正： (一)图像、谱图、表格不清晰的； (二)签名、盖章或者编号不符合制作要求的； (三)文字表达有瑕疵或者错别字，但不影响司法鉴定意见的。 补正应当在原司法鉴定意见书上进行，由至少一名司法鉴定人在补正处签名。必要时，可以出具补正书。 对司法鉴定意见书进行补正，不得改变司法鉴定意见的原意。"},{"i":42,"n":"第四十二条","txt":"司法鉴定机构应当按照规定将司法鉴定意见书以及有关资料整理立卷、归档保管。"},{"i":43,"n":"第四十三条","txt":"经人民法院依法通知，司法鉴定人应当出庭作证，回答与鉴定事项有关的问题。"},{"i":44,"n":"第四十四条","txt":"司法鉴定机构接到出庭通知后，应当及时与人民法院确认司法鉴定人出庭的时间、地点、人数、费用、要求等。"},{"i":45,"n":"第四十五条","txt":"司法鉴定机构应当支持司法鉴定人出庭作证，为司法鉴定人依法出庭提供必要条件。"},{"i":46,"n":"第四十六条","txt":"司法鉴定人出庭作证，应当举止文明，遵守法庭纪律。"},{"i":47,"n":"第四十七条","txt":"本通则是司法鉴定机构和司法鉴定人进行司法鉴定活动应当遵守和采用的一般程序规则，不同专业领域对鉴定程序有特殊要求的，可以依据本通则制定鉴定程序细则。"},{"i":48,"n":"第四十八条","txt":"本通则所称办案机关，是指办理诉讼案件的侦查机关、审查起诉机关和审判机关。"},{"i":49,"n":"第四十九条","txt":"在诉讼活动之外，司法鉴定机构和司法鉴定人依法开展相关鉴定业务的，参照本通则规定执行。"},{"i":50,"n":"第五十条","txt":"本通则自2016年5月1日起施行。司法部2007年8月7日发布的《司法鉴定程序通则》(司法部第107号令)同时废止。"}],"shangshitiaojiezuzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对商事调解组织的监督和管理，促进商事调解行业健康发展，根据《商事调解条例》（以下简称《条例》）和其他相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"商事调解组织的设立、变更、注销和执业管理、监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"商事调解组织应当依法设立并取得执业证书。 设立商事调解组织，应当根据国家和地方经济社会发展的需要，实现合理布局，有序发展。"},{"i":4,"n":"第四条","txt":"商事调解组织应当加强党的建设，依照有关规定建立完善党组织参与商事调解组织决策、管理的工作机制，为党组织开展活动、做好工作提供场地、人员和经费等支持。 司法行政机关、商事调解行业自律组织应当结合监督管理职责，加强对商事调解组织党的建设的指导。"},{"i":5,"n":"第五条","txt":"商事调解组织应当依法开展业务活动，加强内部管理和对商事调解员执业行为的监督，依法承担相应的责任。"},{"i":6,"n":"第六条","txt":"商事调解组织依法从事商事调解活动受法律保护，不受其他组织和个人的非法干涉。"},{"i":7,"n":"第七条","txt":"司法行政机关依照《条例》和有关法律、法规、规章的规定对商事调解组织进行指导、规范、监督管理。 商事调解行业自律组织依照《条例》、章程和行业规范对商事调解组织实行行业自律，接受司法行政机关的指导、监督。 司法行政机关、商事调解行业自律组织应当建立健全行政管理与行业自律相结合的协作机制。"},{"i":8,"n":"第八条","txt":"设立商事调解组织应当符合《条例》第八条规定的条件。 设立商事调解组织应当有符合本办法第九条规定的名称和2名以上专职工作人员。专职工作人员的具体数量可以由省、自治区、直辖市司法行政机关确定。"},{"i":9,"n":"第九条","txt":"商事调解组织的名称应当由“所在地设区的市级以上行政区划名称+字号+商事调解+中心或者院”四部分内容依次组成，司法部另有规定的除外。 商事调解组织名称中的字号，应当由两个以上文字组成，并符合国家有关规定，不得含有下列内容和文字： （一）有损国家利益、社会公共利益或者有损社会主义道德风尚； （二）党政军机关名称及其简称； （三）重大节日名称、县级以上行政区划名称； （四）外国国家（地区）名称、国际组织名称及其简称； （五）可能对公众造成欺骗或者误解； （六）汉语拼音字母、外文字母、阿拉伯数字、全部由中文数字组成或者带有排序性质的文字； （七）与已经设立的商事调解组织的字号相同、近似或者存在包含关系； （八）其他不适当的内容和文字。 商事调解组织名称中含有“国际、跨国、跨境、涉外、海外、环球”等字样的，该组织应当具有开展涉外商事调解的能力。"},{"i":10,"n":"第十条","txt":"申请设立商事调解组织，应当向所在地设区的市级司法行政机关提交下列材料： （一）设立申请书； （二）商事调解组织的名称及组织章程、调解规则、收费标准等草案； （三）发起人资格文件； （四）发起人决策机构同意设立商事调解组织的证明材料。发起人有业务主管单位的，应当提交业务主管单位同意设立商事调解组织的意见；没有业务主管单位的，司法行政机关可以根据需要，要求其提交行业管理部门同意设立商事调解组织的意见； （五）住所证明和有30万元以上资产的证明； （六）拟任负责人基本情况及身份证明； （七）拟聘任的商事调解员符合《条例》第十二条规定条件的相关材料； （八）专职工作人员身份证明以及拟签订劳动合同和缴纳社保的承诺材料； （九）其他必要材料。 申请人应当对申请材料的真实性负责。"},{"i":11,"n":"第十一条","txt":"商事调解组织的章程应当包括以下内容： （一）商事调解组织的名称和住所； （二）商事调解组织的宗旨； （三）商事调解组织党组织的设置形式、地位作用、职责权限、参与决策和管理的工作机制以及党建工作保障措施等； （四）商事调解组织的业务范围； （五）设立资产的数额和来源以及出资方式； （六）发起人的权利与义务； （七）商事调解组织负责人的职责以及产生、变更程序； （八）商事调解组织内部决策、管理、监督规则； （九）商事调解组织财务、资产等主要管理制度； （十）商事调解组织解散的事由、程序以及清算办法； （十一）商事调解组织章程的解释、修改程序； （十二）其他需要载明的事项。 商事调解组织章程的内容不得与有关法律、法规、规章相抵触。 商事调解组织章程自省、自治区、直辖市司法行政机关作出准予设立商事调解组织决定之日起生效。"},{"i":12,"n":"第十二条","txt":"司法行政机关对申请人提出的设立商事调解组织申请，应当根据下列情况分别作出处理： （一）申请材料齐全、符合法定形式的，应当受理； （二）申请材料不齐全或者不符合法定形式的，应当当场或者自收到申请材料之日起5日内一次性告知申请人需要补正的全部内容。申请人按要求补正的，应当受理；逾期不告知的，自收到申请材料之日起即为受理； （三）申请事项明显不符合法定条件或者申请人拒绝补正、无法补正有关材料的，不予受理，并向申请人书面说明理由。"},{"i":13,"n":"第十三条","txt":"司法行政机关按照《条例》第九条第二款的规定准予设立商事调解组织的，应当自决定之日起10日内向申请人颁发执业证书；不准予设立商事调解组织的，应当作出书面决定并说明理由，同时告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":14,"n":"第十四条","txt":"商事调解组织执业证书分为正本和副本。正本用于办公场所悬挂，副本用于接受查验。正本和副本具有同等的法律效力。 商事调解组织执业证书由司法部统一制作。"},{"i":15,"n":"第十五条","txt":"商事调解组织设立申请人应当在领取执业证书后的60日内，按照有关规定刻制印章、开立银行账户、办理税务登记和社会保险登记，完成开业各项准备工作。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市司法行政机关对于以欺骗、贿赂等不正当手段取得准予设立决定的，应当依法撤销；对不符合法定条件的申请或者违反法定程序等情形作出准予设立决定的，可以依法撤销。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市司法行政机关应当编制并动态更新本行政区域内的商事调解组织名册，向社会公布经其审核批准的商事调解组织名称、统一社会信用代码、住所、负责人以及变更、注销等信息。 其他部门和组织不得以任何名义编制和公布商事调解组织名册。"},{"i":18,"n":"第十八条","txt":"商事调解组织变更名称、负责人、住所、章程等事项的，应当向所在地省、自治区、直辖市司法行政机关提出申请。"},{"i":19,"n":"第十九条","txt":"商事调解组织有下列情形之一，应当办理执业证书的注销手续： （一）不能保持《条例》第八条规定的设立条件，经限期整改仍不符合条件的； （二）执业证书被依法吊销的； （三）自行决定解散的； （四）商事调解组织在取得执业证书后6个月内未开展业务活动或者无正当理由停止业务活动满1年等终止商事调解业务活动的； （五）法律、行政法规规定应当注销的其他情形。 商事调解组织在受到停业整顿处罚期限届满前，不得自行决定解散。"},{"i":20,"n":"第二十条","txt":"商事调解组织应当在出现本办法第十九条第一款情形之日起60日内向社会公告，并依照有关规定进行清算。清算期间，商事调解组织不得开展与清算无关的活动。 商事调解组织应当自完成清算之日起30日内向所在地设区的市级司法行政机关提交注销申请书和清算报告，由省、自治区、直辖市司法行政机关办理注销手续，收回执业证书。 商事调解组织拒不履行公告、清算义务的，可以由所在地设区的市级司法行政机关向人民法院申请指定有关人员组成清算组进行清算，依法办理注销手续。"},{"i":21,"n":"第二十一条","txt":"商事调解组织应当建立健全内部管理规则，制定业务管理、财务管理、利益冲突审查和保密、风险防控、投诉处理、档案管理等制度。"},{"i":22,"n":"第二十二条","txt":"商事调解组织应当建立信息公开制度，及时向社会公开章程、商事调解员名册、调解规则、服务流程、收费标准以及每年度办理案件数量等信息。 商事调解员名册应当包含调解员基本情况、擅长领域、使用语言等信息。"},{"i":23,"n":"第二十三条","txt":"商事调解组织应当从符合《条例》第十二条规定的条件的人员中聘任商事调解员，对商事调解员在调解活动中遵守法律法规、职业道德、执业行为规范的情况进行监督。 商事调解组织聘任境外人士为商事调解员的，应当自聘任之日起10日内向所在地设区的市级司法行政机关提交符合《条例》第十二条第三款规定的具有专业影响力和公信力的相关材料。设区的市级司法行政机关自收到材料之日起5日内报省、自治区、直辖市司法行政机关备案。聘任的境外商事调解员需入境工作的，应当依法办理工作许可等手续。"},{"i":24,"n":"第二十四条","txt":"商事调解组织应当为本组织聘任的商事调解员参加业务培训和继续教育提供条件。鼓励和支持商事调解组织培养具有处理涉外案件能力的商事调解员。 全国性商事调解行业自律组织负责制定商事调解员培训标准，推动商事调解员能力水平国际互认。"},{"i":25,"n":"第二十五条","txt":"鼓励和支持商事调解组织加强品牌建设和国际交流合作，依法到境外设立业务机构，积极参与国际商事调解规则制定，提升公信力和国际影响力。"},{"i":26,"n":"第二十六条","txt":"商事调解组织应当综合考虑商事争议具体情况、组织运行成本、商事调解员合理报酬等因素，按照公平、合理的原则制定商事调解费用标准。鼓励商事调解组织提高商事调解员报酬在商事调解费用中的占比。 商事调解行业自律组织可以制定商事调解收费指导标准。"},{"i":27,"n":"第二十七条","txt":"商事调解组织资产来源必须合法，任何单位和个人不得侵占、私分或者挪用商事调解组织的资产。 商事调解组织的资产应当用于章程规定的业务活动，不得向其发起人分配或者用于营利性经营活动。"},{"i":28,"n":"第二十八条","txt":"县级司法行政机关对本行政区域内的商事调解组织的执业活动进行日常监督管理，履行下列职责： （一）监督商事调解组织在开展业务活动过程中遵守法律、法规、规章的情况； （二）监督商事调解组织执业和内部管理制度的建立和实施情况以及提交年度工作报告情况； （三）监督商事调解组织保持法定设立条件以及执行应当报批或者备案事项的情况； （四）监督商事调解组织进行清算、申请注销的情况； （五）受理对商事调解组织的投诉和举报； （六）监督商事调解组织履行行政处罚决定和实行整改的情况； （七）依照法定职权对商事调解组织、商事调解员的违法行为实施行政处罚或者提出处罚建议； （八）法律、法规、规章规定的其他职责。 省、自治区、直辖市及设区的市级司法行政机关依据《条例》和有关法律、法规、规章的规定对本行政区域内的商事调解组织的执业活动履行监督管理职责。"},{"i":29,"n":"第二十九条","txt":"商事调解组织应当于每年3月31日前向所在地县级司法行政机关提交本组织的年度工作报告。 年度工作报告应当真实、全面地反映本组织上一年度人员队伍、开展业务、案件质量、投诉处理、收费、财务会计报告、内部制度建设、商事调解员遵守职业道德和执业行为规范等方面的情况。"},{"i":30,"n":"第三十条","txt":"司法行政机关实施监督检查，可以对商事调解组织进行实地检查，要求商事调解组织和商事调解员说明有关情况，查阅、复制相关材料和档案，采取约谈、询问等措施向相关单位和人员调查、核实有关情况。 商事调解组织和商事调解员应当接受司法行政机关依法实施的监督检查，如实说明有关情况、提供相关资料，不得谎报、隐匿、伪造、销毁相关材料。 司法行政机关在监督检查或者处理投诉举报中，发现商事调解组织或者商事调解员的行为涉嫌违反行业自律规范的，可以移送商事调解行业自律组织处理。"},{"i":31,"n":"第三十一条","txt":"未经司法行政机关批准，擅自以商事调解组织名义开展《条例》规定的商事调解活动的，由省、自治区、直辖市或者设区的市级司法行政机关按照《条例》第二十八条的规定进行处罚。"},{"i":32,"n":"第三十二条","txt":"商事调解组织有《条例》第二十九条、商事调解员有《条例》第三十条规定行为的，县级以上司法行政机关依法对商事调解组织及其负责人、商事调解员予以处罚。 《条例》第二十九条第二款所称以不正当手段承揽业务，是指商事调解组织或者商事调解员违反诚实信用原则、公平竞争原则或者职业道德，通过欺骗、诱导、利益输送、诋毁同业、开展催收等违规方式获取调解案件，扰乱正常执业秩序，损害行业公信力和当事人合法权益的行为。"},{"i":33,"n":"第三十三条","txt":"《条例》第二十九条第二款、第三十条所称情节严重是指下列情形： （一）因违法违规行为对国家利益、社会公共利益和他人合法权益造成重大损失或者恶劣社会影响的； （二）伪造、变造、隐匿、销毁重要证据材料，阻碍司法行政机关调查取证的； （三）组织、参与虚假调解活动，涉及金额较大或者干扰正常司法、仲裁秩序的； （四）一年内因同一性质违法行为受过行政处罚的； （五）违法所得数额较大或者违法行为持续时间较长的； （六）其他依法可以认定为情节严重的情形。"},{"i":34,"n":"第三十四条","txt":"县级以上地方司法行政机关及其工作人员对商事调解组织实施监督管理，不得妨碍商事调解组织依法执业，不得侵害商事调解组织的合法权益，不得索取或者收受商事调解组织和商事调解员的财物，不得谋取其他利益。"},{"i":35,"n":"第三十五条","txt":"司法行政机关工作人员在商事调解组织申请执业证书和实施监督管理活动中，滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":36,"n":"第三十六条","txt":"《条例》施行前已经成立的从事商事调解的组织继续开展商事调解活动的，应当符合《条例》第八条及本办法第八条规定的条件，并于2027年4月30日前按照本办法的规定取得执业证书。其他不符合条件的组织应当于2027年4月30日前向原登记机关办理名称、业务范围变更或者注销登记，不得再开展商事调解活动，但是属于《条例》第三十二条规定情形的除外。 《条例》施行前已经成立的从事商事调解的组织符合颁发执业证书条件的，可以使用原字号；出现相同字号的，原登记时间在前的组织优先使用。"},{"i":37,"n":"第三十七条","txt":"在国务院批准设立的自由贸易试验区、海南自由贸易港等区域内境外商事调解组织依照国家有关规定设立业务机构开展涉外商事调解活动、有关地方试点建立商事调解员独立开展涉外商事调解活动制度的，由省、自治区、直辖市司法行政机关征求司法部意见后，按程序作出决定。"},{"i":38,"n":"第三十八条","txt":"本办法有关“5日”、“10日”的规定是指工作日，不含法定休假日。"},{"i":39,"n":"第三十九条","txt":"本办法由司法部负责解释。"},{"i":40,"n":"第四十条","txt":"本办法自公布之日起施行。"}],"guojiasifakaoshiweijixingweichulibanfa":[{"i":1,"n":"第一条","txt":"为加强国家司法考试管理，严肃考试纪律，保证考试顺利实施，根据《国家司法考试实施办法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国家司法考试报名人员、应试人员、考试工作人员。"},{"i":3,"n":"第三条","txt":"司法行政机关根据本办法对国家司法考试报名人员、应试人员、考试工作人员的违纪行为进行处理。根据本办法规定由监考人员对违纪行为进行处理的，监考人员应当依照规定进行处理，并接受司法行政机关的监督。"},{"i":4,"n":"第四条","txt":"处理国家司法考试违纪行为，应当做到事实清楚、证据确凿、程序规范、适用规定准确。"},{"i":5,"n":"第五条","txt":"报名人员提供虚假证明材料或者以其他形式骗取报名的，由其报名所在地司法行政机关作出报名无效的决定；已经参加考试的，由省、自治区、直辖市司法行政机关给予其当年考试成绩无效的处理；已经取得法律职业资格的，由司法部撤销授予法律职业资格的决定，并收回、注销其《法律职业资格证书》。"},{"i":6,"n":"第六条","txt":"应试人员有下列行为之一的，由其所在考场场内监考人员给予口头警告，并责令改正；经口头警告仍不改正的，由场内监考人员报考点总监考人决定给予其责令离开考场的处理，并报考区所在地司法行政机关决定取消其本场考试成绩： (一)违反规定随身携带书籍、笔记、报纸、稿纸、通讯工具、电子用品等物品进入考场或者未放至指定位置的； (二)考试开始前答题或者考试结束后继续答题的； (三)考试开始三十分钟后仍未按规定在试卷、答卷(答题卡)标明的位置填写、填涂姓名、准考证号或者不粘贴条形码的； (四)考试期间交头接耳、左顾右盼的； (五)在考场内喧哗、走动或者有其他影响考试秩序行为的； (六)未在与本人准考证号相符的位置就座答题的； (七)答题用笔不符合规定的； (八)抄写试题或者本人答案带出考场的； (九)考试期间违反规定擅自出入考场的； (十)有需要给予相应处理的其他违纪行为的。 有前款第(一)项规定情形的，在"},{"i":7,"n":"第七条","txt":"应试人员有下列行为之一的，由其所在考场场内监考人员报考点总监考人决定给予其责令离开考场的处理，并报考区所在地司法行政机关决定给予其当年考试成绩无效的处理： (一)抄袭、查看、偷听违规带进考场的与考试内容有关的文字、视听资料的； (二)考试开始后被查出携带电子作弊设备的； (三)以讨论、互打手势等方式传递答题信息的； (四)与他人交换试卷、答卷(答题卡)的； (五)偷看、抄袭他人答案或者同意、默许、协助他人抄袭本人答案的； (六)在答卷(答题卡)上作提示标记或者在非署名处署名的； (七)故意损毁试卷、答卷(答题卡)、条形码或者将试卷、答卷(答题卡)带出考场的； (八)有需要给予相应处理的其他违纪行为的。"},{"i":8,"n":"第八条","txt":"应试人员有下列行为之一的，由省、自治区、直辖市司法行政机关决定给予其当年考试成绩无效、二年内不得报名参加国家司法考试的处理；当场发现的，由考点总监考人决定给予其责令离开考场的处理，并经考区所在地司法行政机关报省、自治区、直辖市司法行政机关按照前述规定处理： (一)使用伪造、变造的居民身份证、户口簿、准考证以及其他证明材料参加考试的； (二)故意妨碍监考人员或者其他考试工作人员履行职责的； (三)威胁、侮辱、殴打监考人员或者其他考试工作人员的； (四)有其他严重作弊或者严重扰乱考场秩序行为的。 有前款规定情形，构成违反治安管理行为的，移交公安机关处理。"},{"i":9,"n":"第九条","txt":"应试人员有下列行为之一的，由省、自治区、直辖市司法行政机关决定给予其当年考试成绩无效、终身不得报名参加国家司法考试的处理；当场发现的，由考点总监考人决定给予其责令离开考场的处理，并经考区所在地司法行政机关报省、自治区、直辖市司法行政机关按照前述规定处理： (一)有第八条第一款第(一)项规定情形，情节严重的； (二)在考试过程中使用考试作弊器材接收或者发送与考试内容相关信息的； (三)组织作弊，或者为他人实施组织作弊行为提供作弊器材或者其他帮助的； (四)为实施考试作弊行为，非法获取考试试题、答案或者向他人非法出售、提供考试试题、答案的； (五)代替他人考试或者让他人代替自己参加考试的； (六)有其他特别严重作弊行为的。 应试人员以及其他相关人员有前款规定情形，构成违反治安管理行为的，移交公安机关处理；构成犯罪的，移交司法机关处理。"},{"i":10,"n":"第十条","txt":"在评卷过程中发现的下列涉嫌作弊情形，由评卷专家组确认： (一)应试人员在答卷(答题卡)上做提示标记； (二)应试人员答卷(答题卡)笔迹前后不一致； (三)两卷以上(含两卷)答案文字表述、答案信息点错误高度一致(雷同)。 确认前款规定情形的具体标准，由国家司法考试中心制定。评卷专家组确认应试人员有前款规定情形并有其他相关证据证明其作弊行为成立的，由司法部根据其作弊事实和情节，依照本办法的相关规定给予当年考试成绩无效、二年内或者终身不得报名参加国家司法考试的处理。"},{"i":11,"n":"第十一条","txt":"考试工作人员有下列行为之一的，司法行政机关应当停止其继续参加考试工作： (一)不认真履行考务工作职责的； (二)违反国家司法考试有关规定，造成后果的。"},{"i":12,"n":"第十二条","txt":"考试工作人员有下列行为之一的，司法行政机关应当停止其继续参加考试工作，并作出禁止其再从事司法考试工作的处理，同时给予相应处分或者建议其所在单位给予相应处理；涉嫌犯罪的，移交司法机关处理： (一)对不符合报名条件的人员准予报名、发放准考证的； (二)纵容、包庇报名人员、应试人员违纪的； (三)考试期间擅自将试卷、答卷(答题卡)带出或者传出考场的； (四)擅自变动每场考试开始或者结束时间的； (五)未经批准擅自交换负责监考考场的； (六)采用明示或者暗示的方式协助应试人员答题的； (七)在运送、接收、保管试卷等环节丢失、损毁试卷，在监考、评卷、成绩核查等环节丢失、严重损坏答卷(答题卡)的； (八)指使、组织考试作弊或者参与有组织作弊的； (九)在考试开始前泄露试题内容的； (十)外传、截留、窃取、擅自开拆未开考试卷或者偷拆已密封答卷(答题卡)的； (十一)偷换、涂改答卷(答题卡)或者私自变"},{"i":13,"n":"第十三条","txt":"监考人员或者其他考试工作人员在考试过程中发现应试人员有本办法规定违纪行为的，在依照本办法实施现场处理措施的同时，可以对违纪人员作弊用的工具、材料及相关试卷、答卷(答题卡)采取必要的保全证据措施，并应当将应试人员违纪的事实、情节，查收的作弊证据以及现场处理情况，在《违纪行为处理报告单》上作出记录，并由二名以上监考人员或者其他考试工作人员签字确认。 考试结束后，《违纪行为处理报告单》及有关证据，经考点总监考人审查确认后，报送考区所在地司法行政机关。"},{"i":14,"n":"第十四条","txt":"对报名人员、应试人员、考试工作人员违纪行为的处理，总监考人、相关司法行政机关应当在《违纪行为处理报告单》上作出记录并签字，相关司法行政机关应当作出书面处理决定并加盖公章。 对应试人员给予取消本场考试成绩、当年考试成绩无效、二年内或者终身不得报名参加国家司法考试处理的，作出处理决定的司法行政机关应当制作《国家司法考试违纪行为处理决定书》，并自作出处理决定之日起十日内将《国家司法考试违纪行为处理决定书》送达被处理人。"},{"i":15,"n":"第十五条","txt":"对应试人员作出取消本场考试成绩、当年考试成绩无效、二年内或者终身不得报名参加国家司法考试处理决定之前，司法行政机关应当告知应试人员作出处理决定的事实、理由及依据，并告知应试人员享有陈述、申辩和要求听证的权利。"},{"i":16,"n":"第十六条","txt":"报名人员、应试人员、考试工作人员对司法行政机关作出的违纪处理决定不服的，可以根据有关法律规定申请行政复议或者提起行政诉讼。"},{"i":17,"n":"第十七条","txt":"考试工作人员在考试违纪行为处理工作中，有对应试人员进行挟私报复或者诬陷等行为的，司法行政机关应当对其给予相应处分或者建议其所在单位给予相应处理。"},{"i":18,"n":"第十八条","txt":"报名人员、应试人员、考试工作人员因违纪行为受到处理的，作出处理决定的司法行政机关应当将有关情况通报其所在单位。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市司法行政机关应当于每年国家司法考试结束后，将本地区考试违纪的情况及处理结果报司法部备案。在考试组织和考试进行的过程中发生特别严重的考试违纪事件的，应当及时向司法部报告。 司法部和省、自治区、直辖市司法行政机关应当建立报名人员、应试人员诚信档案，记录司法考试违纪人员信息及处理结果，建立报名人员、应试人员信用记录披露和查询制度，并与其他部门实现信用信息交换共享。"},{"i":20,"n":"第二十条","txt":"本办法所称“考区所在地司法行政机关”，是指设置考区所在地的设区的市级司法行政机关、直辖市的区(县)司法行政机关或者直辖市司法行政机关。"},{"i":21,"n":"第二十一条","txt":"本办法自发布之日起施行。2005年7月29日司法部令第97号发布的《国家司法考试违纪行为处理办法》同时废止。"}],"guojiatongyifalvzhiyezigekaoshishishibanfa":[{"i":1,"n":"第一条","txt":"为了规范国家统一法律职业资格考试工作，根据《中华人民共和国法官法》《中华人民共和国检察官法》《中华人民共和国公务员法》《中华人民共和国律师法》《中华人民共和国公证法》《中华人民共和国仲裁法》《中华人民共和国行政复议法》《中华人民共和国行政处罚法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家统一法律职业资格考试是国家统一组织的选拔合格法律职业人才的国家考试。 初任法官、初任检察官，申请律师执业、公证员执业和初次担任法律类仲裁员，以及行政机关中初次从事行政处罚决定审核、行政复议、行政裁决、法律顾问的公务员，应当通过国家统一法律职业资格考试，取得法律职业资格。 法律、行政法规另有规定的除外。"},{"i":3,"n":"第三条","txt":"国家统一法律职业资格考试应当依法、公平、公正。"},{"i":4,"n":"第四条","txt":"司法部会同最高人民法院、最高人民检察院等有关部门、单位组成国家统一法律职业资格考试协调委员会，就国家统一法律职业资格考试的重大事项进行协商。"},{"i":5,"n":"第五条","txt":"国家统一法律职业资格考试的实施工作应当接受监察机关、保密机关和社会监督。"},{"i":6,"n":"第六条","txt":"国家统一法律职业资格考试由司法部负责实施。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市司法行政机关应当明确专门机构，按照有关规定承办国家统一法律职业资格考试的考务等工作。 设区的市级或者直辖市的区(县)司法行政机关，应当在上级司法行政机关的监督指导下，承担本辖区内的国家统一法律职业资格考试的考务等工作。"},{"i":8,"n":"第八条","txt":"负责考试组织实施的司法行政机关及其考试工作人员应当严格遵守国家保密法律法规的规定，加强国家统一法律职业资格考试保密管理。"},{"i":9,"n":"第九条","txt":"符合以下条件的人员，可以报名参加国家统一法律职业资格考试： (一)具有中华人民共和国国籍； (二)拥护中华人民共和国宪法，享有选举权和被选举权； (三)具有良好的政治、业务素质和道德品行； (四)具有完全民事行为能力； (五)具备全日制普通高等学校法学类本科学历并获得学士及以上学位；全日制普通高等学校非法学类本科及以上学历，并获得法律硕士、法学硕士及以上学位；全日制普通高等学校非法学类本科及以上学历并获得相应学位且从事法律工作满三年。"},{"i":10,"n":"第十条","txt":"有下列情形之一的人员，不得报名参加国家统一法律职业资格考试： (一)因故意犯罪受过刑事处罚的； (二)曾被开除公职或者曾被吊销律师执业证书、公证员执业证书的； (三)被吊销法律职业资格证书的； (四)被给予二年内不得报名参加国家统一法律职业资格考试(国家司法考试)处理期限未满或者被给予终身不得报名参加国家统一法律职业资格考试(国家司法考试)处理的； (五)因严重失信行为被国家有关单位确定为失信联合惩戒对象并纳入国家信用信息共享平台的； (六)因其他情形被给予终身禁止从事法律职业处理的。 有前款规定情形之一的人员，已经办理报名手续的，报名无效；已经参加考试的，考试成绩无效。"},{"i":11,"n":"第十一条","txt":"国家统一法律职业资格考试的具体考试时间和相关安排在举行考试三个月前向社会公布。"},{"i":12,"n":"第十二条","txt":"国家统一法律职业资格考试实行全国统一命题。 国家统一法律职业资格考试的内容和命题范围以司法部当年公布的《国家统一法律职业资格考试大纲》为准。"},{"i":13,"n":"第十三条","txt":"国家统一法律职业资格考试每年举行一次，分为客观题考试和主观题考试两部分，综合考查应试人员从事法律职业应当具有的政治素养、业务能力和职业伦理。 应试人员客观题考试成绩合格的方可参加主观题考试，客观题考试合格成绩在本年度和下一个考试年度内有效。"},{"i":14,"n":"第十四条","txt":"国家统一法律职业资格考试实行纸笔考试或者计算机化考试。"},{"i":15,"n":"第十五条","txt":"国家统一法律职业资格考试实行全国统一评卷，统一确定合格分数线，考试成绩及合格分数线由司法部公布。"},{"i":16,"n":"第十六条","txt":"应试人员有违反考试纪律行为的，由司法行政机关按照有关规定，视其情节、后果，分别给予口头警告、责令离开考场并取消本场考试成绩、确认当年考试成绩无效、二年内不得报名参加国家统一法律职业资格考试的处理；构成故意犯罪的，给予终身不得报名参加国家统一法律职业资格考试的处理。 应试人员及其他相关人员有违反治安管理行为的，由公安机关进行处理；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"考试工作人员有违反工作纪律行为的，应当按照有关规定，视其情节、后果给予相应的处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"参加国家统一法律职业资格考试成绩合格，且不具有本办法第十条第一款规定情形的人员，可以按照规定程序申请授予法律职业资格，由司法部颁发法律职业资格证书。"},{"i":19,"n":"第十九条","txt":"以欺骗、贿赂等不正当手段取得法律职业资格证书的，由司法部撤销原授予法律职业资格的决定，注销其法律职业资格证书。"},{"i":20,"n":"第二十条","txt":"取得法律职业资格人员有违反宪法和法律、妨害司法公正、违背职业伦理道德等行为的，由司法行政机关根据司法部有关规定，视其情节、后果，对其给予相应处理。"},{"i":21,"n":"第二十一条","txt":"司法行政机关应当将取得法律职业资格人员的有关信息，以及依据本办法第十九条、第二十条作出相应处理人员的有关信息，录入国家法律职业资格管理系统，在司法部官方网站上公布。"},{"i":22,"n":"第二十二条","txt":"本办法实施前已取得学籍(考籍)或者已取得相应学历的高等学校法学类专业本科及以上学历毕业生，或者高等学校非法学类专业本科及以上学历毕业生并具有法律专业知识的，可以报名参加国家统一法律职业资格考试。"},{"i":23,"n":"第二十三条","txt":"国家统一法律职业资格考试的实施，可以在一定时期内，对艰苦边远和少数民族地区的应试人员，在报名学历条件、考试合格标准等方面适当放宽，对其取得的法律职业资格实行分别管理，具体办法由国家统一法律职业资格考试协调委员会确定。 在民族自治地方组织国家统一法律职业资格考试，应试人员可以使用民族语言文字进行考试。"},{"i":24,"n":"第二十四条","txt":"香港特别行政区、澳门特别行政区永久性居民中的中国公民和台湾地区居民参加国家统一法律职业资格考试，适用本办法规定。"},{"i":25,"n":"第二十五条","txt":"现役军人参加国家统一法律职业资格考试的具体规则，由司法部会同中央军委政法委员会另行规定。"},{"i":26,"n":"第二十六条","txt":"国家统一法律职业资格考试的其他政策规定，经国家统一法律职业资格考试协调委员会确定后，在年度国家统一法律职业资格考试公告中公布。"},{"i":27,"n":"第二十七条","txt":"本办法由司法部负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自公布之日起施行。"}],"guojiatongyifalvzhiyezigekaoshiweijixingweichuliba641fcc":[{"i":1,"n":"第一条","txt":"为了加强国家统一法律职业资格考试管理，严肃考试纪律，维护公平公正的考试秩序，制定本办法。"},{"i":2,"n":"第二条","txt":"国家统一法律职业资格考试报名人员、应试人员、考试工作人员以及其他相关人员，违反考试管理规定和考试纪律的认定与处理，适用本办法。"},{"i":3,"n":"第三条","txt":"司法部负责对国家统一法律职业资格考试违纪行为处理的指导监督。 省、自治区、直辖市和考区所在地司法行政机关负责对考试违纪行为的具体处理。 监考人员根据本办法规定对有关违纪行为进行现场处理，并接受司法行政机关的指导监督。"},{"i":4,"n":"第四条","txt":"国家统一法律职业资格考试违纪行为的认定和处理，应当做到事实清楚、证据确凿、程序规范、适用规定准确。"},{"i":5,"n":"第五条","txt":"不具备考试报名条件的人员通过隐瞒个人信息、虚假承诺等方式取得报名资格的，由考区所在地司法行政机关作出报名无效的决定；对通过提供伪造、变造的学历学位证书及证明书、法律工作经历、身份及户籍信息等骗取报名或者通过贿赂、胁迫等其他不正当手段取得报名资格的，由考区所在地司法行政机关一并给予其二年内不得报名参加国家统一法律职业资格考试的处理。 具有上述情形，已经参加考试的，由省、自治区、直辖市司法行政机关给予其当年考试成绩无效的处理；已经取得法律职业资格的，由司法部作出撤销授予法律职业资格的决定，并注销其法律职业资格证书。"},{"i":6,"n":"第六条","txt":"应试人员有下列行为之一的，由监考人员给予口头警告，责令改正；经口头警告仍不改正或者情节严重的，由考点总监考决定给予其终止本场考试、责令离开考场的处理，并由考区所在地司法行政机关给予其取消本场考试成绩的处理： (一)携带考试规定以外的物品进入考场，经提醒后仍未放至指定位置的； (二)考试开始前答题或者考试结束后继续答题的； (三)考试开始三十分钟后仍未按规定在试卷、答卷、电子试题答卷页面上标明位置填涂或者录入姓名、准考证号、身份证号，在答卷上作标记或者在非署名处署名的； (四)擅自关闭考试机、大幅度调整考试机显示屏摆放位置和角度、搬动主机箱、更换键盘和鼠标等设备的； (五)考试期间在考场内交头接耳、左顾右盼、喧哗或者交卷后在考场内、考场附近逗留、喧哗等影响考试秩序的； (六)未在规定座位参加考试或者考试期间擅自离开座位、出入考场的； (七)故意损毁试卷、答卷或者考场配发材料、考试机等考试"},{"i":7,"n":"第七条","txt":"应试人员有下列行为之一的，由总监考决定给予其终止本场考试、责令离开考场的处理，并由考区所在地司法行政机关决定给予其当年考试成绩无效、二年内不得报名参加国家统一法律职业资格考试的处理： (一)考试开始后被查出携带具有发送或者接收信息功能的设备，或者在计算机化考试中使用外接设备、安装作弊工具、作弊程序的； (二)抄袭、查看、偷听违规带进考场与考试内容有关的文字、视听资料的； (三)以讨论、打手势等方式传递答题信息，抢夺、窃取他人试卷、答卷、草稿纸或者与他人交换试卷、答卷、草稿纸的； (四)抄袭他人答案或者同意、协助他人抄袭答案的； (五)有需要给予相应处理的其他作弊行为的。"},{"i":8,"n":"第八条","txt":"应试人员有下列行为之一的，由省、自治区、直辖市司法行政机关决定给予其当年考试成绩无效、终身不得报名参加国家统一法律职业资格考试的处理；当场发现的，由考点总监考给予其终止本场考试、责令离开考场的处理，并经考区所在地司法行政机关报省、自治区、直辖市司法行政机关按照前述规定处理： (一)使用伪造、变造或者盗用他人的居民身份证、户口簿、准考证以及其他证明材料参加考试的； (二)非法侵入计算机化考试系统或者非法获取、删除、修改、增加考试信息系统数据，破坏计算机考试系统正常运行的； (三)实施组织作弊，或者为他人组织作弊提供作弊器材、程序或者其他帮助行为的； (四)为实施考试作弊行为，非法获取考试试题、答案或者向他人非法出售、提供考试试题、答案的； (五)实施代替他人考试或者让他人代替自己参加考试的； (六)有其他特别严重作弊行为的。"},{"i":9,"n":"第九条","txt":"报名人员、应试人员或者其他相关人员有本章规定情形，涉嫌构成违反治安管理行为的，移交公安机关处理；涉嫌构成犯罪的，移交司法机关处理。 违纪人员为国家公职人员的，同时将违纪违法情况通报所在单位并移交处理。"},{"i":10,"n":"第十条","txt":"考区所在地司法行政机关应当于每年度国家统一法律职业资格考试结束后，将本地考试违纪情况和处理结果逐级上报司法部备案。在考试进行过程中发生特别严重的考试违纪事件的，应当立即直报司法部。 司法部和省、自治区、直辖市司法行政机关应当建立报名人员、应试人员失信档案和信用记录披露、查询制度，记录考试违纪人员信息及处理结果，对处以取消本场考试成绩、二年内或者终身禁止参加法律职业资格考试处理的，通过司法行政机关官方网站予以公示，并与其他部门实现信用信息交换共享。"},{"i":11,"n":"第十一条","txt":"考试工作人员有下列行为之一的，司法行政机关应当停止其继续从事本年度及下一年度国家统一法律职业资格考试工作，并视情节给予其相应处理或者建议所在单位给予相应处理： (一)因失职造成不符合条件人员取得法律职业资格的； (二)未准确记录、报告考试违纪行为并造成不良影响，或者未认真履行职责，造成考试秩序混乱，所负责考试出现大面积雷同答卷的； (三)擅自变动考试开始、结束时间或者违规补时，以及未按规定时间开启考试机、下载上传考试数据或者未在规定时间、场所启封、封装试卷的； (四)擅自调换监考考场、进入其他考场或者为应试人员调换考场、座位(机位)或者对试题内容作解释说明的； (五)在考场、阅卷场所或者保密监控室内使用通讯工具等电子用品扰乱考试工作秩序的； (六)擅自将考场配发材料带出考场或者将阅卷评分标准等材料带出阅卷场所的； (七)从事命题、阅卷、保密、监考等工作的人员违反回避规定，本人或者近亲属"},{"i":12,"n":"第十二条","txt":"考试工作人员有下列行为之一的，司法行政机关应当停止其继续从事本年度考试工作，并作出禁止其再从事法律职业资格考试工作的处理，同时给予其相应处理或者建议所在单位给予相应处理： (一)因严重失职造成应试人员未能如期参加考试的； (二)造成报名人员信息数据、考试试题、试卷、答案、评分标准及考试数据丢失、损毁、泄露，或者使应试人员答卷在保密期限内发生重大事故的； (三)命题、审题发生错误，造成严重后果或者在评卷、统分中严重失职，造成明显的错评、漏评或者其他差错的； (四)利用考试工作便利打击报复应试人员或者索取他人财物、非法收受他人财物的； (五)考试期间擅自将试卷、答卷、草稿纸以及考场配发材料带出考场，或者通过非法侵入计算机系统或者安装作弊程序将试题信息传出考场的； (六)采用明示或者暗示的方式协助应试人员答题或者纵容、包庇报名人员、应试人员及其他相关人员考试违纪的； (七)截留、窃取、擅自开"},{"i":13,"n":"第十三条","txt":"从事考试命题管理等考试工作人员在国家统一法律职业资格考试社会培训机构兼职的，由司法行政机关停止其继续从事考试工作，并根据有关规定给予相应处理或者建议相关单位给予相应处理。"},{"i":14,"n":"第十四条","txt":"发生重大考试责任事故或者出现大规模作弊情况等严重违纪问题的考区，由省、自治区、直辖市司法行政机关报司法部撤销该考区，且二年内不得恢复考区设置。对存在失职或者渎职的司法行政机关主管人员和直接责任人员，应当按照有关规定给予相应处理。"},{"i":15,"n":"第十五条","txt":"司法行政机关违反保密规定，造成考试试题、答案及评分标准丢失、泄密，或者使考生答卷在保密期限内发生重大事故的，对存在失职或者渎职的司法行政机关主管人员和直接责任人员，应当按照有关规定分别给予相应处理。"},{"i":16,"n":"第十六条","txt":"考试工作人员有本章规定情形，涉嫌构成违反治安管理行为的，移交公安机关处理；涉嫌构成犯罪的，移交监察机关、司法机关处理。"},{"i":17,"n":"第十七条","txt":"监考人员在考试期间发现应试人员以及其他相关人员有违纪行为的，在依照本办法实施现场处理措施的同时，可以对违纪人员作弊的工具、材料及试卷、答卷和相关视频录像等证据材料采取必要的登记保存措施，并在七个工作日内由考区所在地司法行政机关对保存的物品或材料作出处理。 违纪事实、情节及现场处理情况应当在违纪行为处理报告单上作出记录，由二名监考人员或者其他考试工作人员签字确认。考试结束后，经考点总监考审查确认后报送考区所在地司法行政机关，考区所在地司法行政机关应当在违纪行为处理报告单上签署意见。 考试工作人员应当向违纪考生告知违纪记录的内容，对保存的考生物品应当填写保存清单，并由考生和考试工作人员签字确认。"},{"i":18,"n":"第十八条","txt":"非考试期间发现相关违纪线索的，由考区所在地司法行政机关组成不少于二人的调查组进行调查取证，必要时由上级司法行政机关直接调查取证。调查人员应当对有关事实情况进行了解核实。 调查结束后，调查组应当依据调查的事实和证据形成调查报告，报本级司法行政机关。需要由上级司法行政机关处理的，应当及时上报。"},{"i":19,"n":"第十九条","txt":"在评卷过程中发现下列违纪情形的，由评卷专家组确认： (一)应试人员在答卷上做标记的； (二)应试人员答卷笔迹前后不一致的； (三)应试人员两卷答案文字表述、答案信息点错误、答题轨迹高度一致(雷同)的。 评卷专家组确认上述违纪行为情形时，可以根据需要通过鉴定机构进行鉴定或者进行实验。确认应试人员有前款规定情形并有其他相关证据证明其作弊行为成立的，根据作弊事实和情节，由考区所在地司法行政机关依照本办法相关规定处理。"},{"i":20,"n":"第二十条","txt":"对于事实清楚、证据确凿的违纪行为，司法行政机关应当在决定调查后六十日内作出处理决定。 六十日内无法作出处理决定的，经本级司法行政机关负责人批准，可以延长三十日。"},{"i":21,"n":"第二十一条","txt":"司法行政机关对违纪行为作出处理决定前，应当告知当事人作出处理决定的事实、理由及依据，并告知其享有陈述、申辩或者要求听证的权利。 作出二年内或者终身不得报名参加国家统一法律职业资格考试处理决定的，当事人有权在被告知处理结果之日起五个工作日内要求举行听证；当事人要求听证的，司法行政机关应当在二十日内组织听证，并于举行听证前七个工作日通知当事人。"},{"i":22,"n":"第二十二条","txt":"司法行政机关对违纪行为作出处理的，应当出具国家统一法律职业资格考试违纪行为处理决定书，并载明下列事项： (一)被处理人姓名、性别、身份证号及住址； (二)违纪行为的事实和证据； (三)处理的依据和种类； (四)不服处理决定申请行政复议或者提起行政诉讼的途径和期限； (五)作出处理决定的单位名称和日期。"},{"i":23,"n":"第二十三条","txt":"违纪行为处理决定应当自作出处理决定之日起十日内送达被处理人；直接送达有困难的，可以采取委托送达、邮寄送达；受送达人下落不明，或者用其他方式无法送达的，可以采取公告方式送达。"},{"i":24,"n":"第二十四条","txt":"报名人员、应试人员及其他相关人员对司法行政机关作出的违纪处理决定不服的，可以根据有关法律规定申请行政复议或者提起行政诉讼。 考试工作人员对违纪行为处理不服的，可以依法申请复核或者提出申诉。"},{"i":25,"n":"第二十五条","txt":"考试违纪行为调查处理人员在考试违纪行为调查处理工作中，有对报名人员、应试人员及其他相关人员报复或者诬陷等行为的，司法行政机关应当给予其相应处理或者建议所在单位给予相应处理。"},{"i":26,"n":"第二十六条","txt":"本办法所称“二年”不包括本年度。"},{"i":27,"n":"第二十七条","txt":"本办法规定的“其他相关人员”，是指报名人员、应试人员、考试工作人员以外参与考试违纪作弊行为的人员。"},{"i":28,"n":"第二十八条","txt":"本办法由司法部负责解释。"},{"i":29,"n":"第二十九条","txt":"本办法自公布之日起施行。"}],"jicengfalvfuwugongzuozheguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对基层法律服务工作者的监督和管理，保障基层法律服务工作者依法执业，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"符合本办法规定的执业条件，经司法行政机关核准取得《基层法律服务工作者执业证》，在基层法律服务所执业，为社会提供法律服务的人员，是基层法律服务工作者。"},{"i":3,"n":"第三条","txt":"基层法律服务工作者的职责是按照司法部规定的业务范围和执业要求，开展法律服务，维护当事人合法权益，维护法律正确实施，促进社会稳定、经济发展和法治建设。 基层法律服务工作者依法执业受法律保护，任何组织和个人不得侵害其合法权益。"},{"i":4,"n":"第四条","txt":"基层法律服务工作者应当把拥护中国共产党领导、拥护社会主义法治作为从业的基本要求。"},{"i":5,"n":"第五条","txt":"司法行政机关依据本办法对基层法律服务工作者进行管理和指导。"},{"i":6,"n":"第六条","txt":"申请基层法律服务工作者执业，应当具备下列条件： (一)拥护中华人民共和国宪法； (二)高等学校法律专业本科毕业，参加省、自治区、直辖市司法行政机关组织的考试合格； (三)品行良好； (四)身体健康； (五) 在基层法律服务所实习满一年，但具有二年以上其他法律职业经历的除外。 各省、自治区、直辖市的自治县(旗)，国务院审批确定的国家扶贫开发工作重点县，西部地区省、自治区、直辖市所辖县，可以将前款第二项规定的学历专业条件放宽为高等学校法律专业专科毕业，或者非法律专业本科毕业并具有法律专业知识。"},{"i":7,"n":"第七条","txt":"具有法律职业资格或者曾经取得基层法律服务工作者执业资格的人员，符合本办法第六条第一款第一、三、四、五项规定的，也可以申请基层法律服务工作者执业核准。"},{"i":8,"n":"第八条","txt":"有下列情形之一的人员，不得参加本办法第六条第一款第二项规定的考试或者申请执业核准： (一)因故意犯罪受到刑事处罚的； (二)被开除公职的； (三)无民事行为能力或者限制民事行为能力的。"},{"i":9,"n":"第九条","txt":"设区的市级或者直辖市的区(县)司法行政机关负责基层法律服务工作者执业核准，颁发《基层法律服务工作者执业证》。"},{"i":10,"n":"第十条","txt":"申请基层法律服务工作者执业核准的，应当填写申请执业登记表，并提交下列材料： (一)符合本办法第六条规定的学历证书和考试合格证明，或者第七条规定的资格证书； (二)基层法律服务所对申请人实习表现的鉴定意见，或者具有二年以上其他法律职业经历的证明； (三)基层法律服务所出具的同意接收申请人的证明； (四)申请人的身份证明。"},{"i":11,"n":"第十一条","txt":"申请执业核准材料，由拟聘用申请人的基层法律服务所提交所在地县级司法行政机关审查，由其出具审查意见后报设区的市级司法行政机关审核，或者由拟聘用申请人的基层法律服务所报所在地直辖市的区(县)司法行政机关审核。"},{"i":12,"n":"第十二条","txt":"执业核准机关应当自决定受理申请之日起二十日内完成审核，作出准予执业核准或者不准予执业核准的书面决定。不准予执业核准的，应当在决定中说明理由。 对准予执业核准的申请人，由执业核准机关颁发《基层法律服务工作者执业证》。 申请人对不准予执业核准决定有异议的，可以依照《中华人民共和国行政复议法》和司法部有关规定申请行政复议。"},{"i":13,"n":"第十三条","txt":"对有下列情形之一的申请执业核准的人员，司法行政机关应当作出不准予执业核准的决定： (一)具有本办法第八条规定情形之一的； (二)曾因严重违法违纪违规行为被基层法律服务所解除聘用合同或者劳动合同的； (三)曾被吊销律师执业证书或者受到停止执业处罚期限未满的； (四)具有法律职业资格或者律师资格、公证员资格并已在律师事务所或者公证机构执业的。"},{"i":14,"n":"第十四条","txt":"符合本办法第六条或者第七条规定的条件，在教育科研部门工作、民营企业工作或者务农的人员，经基层法律服务所聘用，可以兼职从事基层法律服务工作，但在教育科研部门工作的人员按照有关规定不得兼职的除外。申请兼职基层法律服务者执业核准，按照本办法规定的条件和程序办理。 基层法律服务所聘用兼职基层法律服务工作者的人数，不得超过专职基层法律服务工作者的人数。"},{"i":15,"n":"第十五条","txt":"基层法律服务工作者变更执业机构的，持与原执业的基层法律服务所解除聘用关系、劳动关系的证明和拟变更的基层法律服务所同意接收的证明，按照本办法规定的程序，申请更换《基层法律服务工作者执业证》。 有下列情形之一的，基层法律服务工作者不得变更执业机构： (一)本人承办的业务或者工作交接手续尚未办结； (二)本人与所在基层法律服务所尚存在债权债务关系； (三)本人有正在接受调查处理的违反执业纪律的行为。"},{"i":16,"n":"第十六条","txt":"基层法律服务工作者有下列情形之一的，由执业核准机关注销并收回《基层法律服务工作者执业证》： (一)因严重违法违纪违规行为被基层法律服务所解除聘用合同或者劳动合同的； (二)因与基层法律服务所解除聘用合同、劳动合同或者所在的基层法律服务所被注销，在六个月内未被其他基层法律服务所聘用的； (三)因本人申请注销的； (四)因其他原因停止执业的。"},{"i":17,"n":"第十七条","txt":"基层法律服务工作者应当妥善保管《基层法律服务工作者执业证》，不得伪造、涂改、抵押、出借、出租。 《基层法律服务工作者执业证》遗失或者损坏无法使用的，持证人应当立即向所在地县级司法行政机关或者直辖市的区(县)司法行政机关申请办理补发或更换手续。"},{"i":18,"n":"第十八条","txt":"基层法律服务所应当依法与在本所执业的基层法律服务工作者签订聘用合同或者劳动合同。"},{"i":19,"n":"第十九条","txt":"基层法律服务所应当为基层法律服务工作者执业提供必要的工作条件，维护其在执业活动和本所管理工作中应享有的合法权利，保障其应享有的劳动报酬、保险和福利待遇。"},{"i":20,"n":"第二十条","txt":"基层法律服务所应当建立对基层法律服务工作者执业实绩和遵守职业道德、执业纪律情况的年度考核制度。 年度考核结果分为优秀、称职、基本称职、不称职四个等次。年度考核结果应当作为对基层法律服务工作者奖惩的依据。"},{"i":21,"n":"第二十一条","txt":"基层法律服务所对年度考核被评为优秀或者在平时执业中有突出事迹或者显著贡献的基层法律服务工作者，应当给予奖励。 对事迹特别突出的，可以报请有关司法行政机关给予表彰。"},{"i":22,"n":"第二十二条","txt":"基层法律服务所对违反职业道德和执业纪律，违反司法行政机关管理规定和本所章程、制度或者有其他违法行为的基层法律服务工作者，可以按照有关规定予以处分或者处理。"},{"i":23,"n":"第二十三条","txt":"基层法律服务工作者有下列情形之一的，基层法律服务所可以按照有关规定解除聘用合同或者劳动合同： (一)在年度考核中连续两年被评为不称职的； (二)严重违反本所规章制度，经多次教育仍不改正的； (三)无正当理由连续停止执业满三个月的； (四)因患病或者非因公负伤，在规定的医疗期满后不能从事基层法律服务工作的。 基层法律服务所按照前款规定与基层法律服务工作者解除聘用合同或者劳动合同的，应当报所在地县级司法行政机关备案，并按照规定程序办理注销手续。"},{"i":24,"n":"第二十四条","txt":"基层法律服务所和基层法律服务工作者对履行聘用合同发生争议的，可以提请所在地的县级司法行政机关或者直辖市的区(县)司法行政机关进行调解处理。"},{"i":25,"n":"第二十五条","txt":"基层法律服务工作者应当遵守宪法和法律，恪守职业道德和执业纪律，做到依法执业、诚信执业、规范执业。 基层法律服务工作者执业应当以事实为依据，以法律为准绳。 基层法律服务工作者应当接受国家、社会和当事人的监督。"},{"i":26,"n":"第二十六条","txt":"基层法律服务工作者可以从事下列业务： (一)担任法律顾问； (二)代理参加民事、行政诉讼活动； (三)代理非诉讼法律事务； (四)接受委托，参加调解、仲裁活动； (五)解答法律咨询； (六)代写法律事务文书。"},{"i":27,"n":"第二十七条","txt":"基层法律服务工作者办理本办法第二十六条第二项规定的业务，应当符合下列条件之一： (一)至少有一方当事人的住所位于其执业的基层法律服务所所在的县级行政区划辖区或者直辖市的区(县)行政区划辖区内。 (二)案件由其执业的基层法律服务所所在的县级行政区划辖区或者直辖市的区(县)行政区划辖区内的基层人民法院审理；该案进入二审、审判监督程序的，可以继续接受原当事人的委托，担任诉讼代理人。 省、自治区、直辖市司法行政机关根据本地实际，认为确有必要的，可以适当调整前款第一项规定的条件。"},{"i":28,"n":"第二十八条","txt":"基层法律服务工作者持基层法律服务所出具的介绍信、当事人的委托书和《基层法律服务工作者执业证》，经有关单位或者个人同意，可以依法向其调查、收集与承办法律事务有关的证据材料；依法查阅所代理案件有关材料。"},{"i":29,"n":"第二十九条","txt":"基层法律服务工作者对坚持非法要求、故意隐瞒重大事实、提供虚假证据或者严重违反委托合同约定义务的当事人，可以拒绝为其代理或者解除委托关系。"},{"i":30,"n":"第三十条","txt":"基层法律服务工作者在执业中发现本地区政府机关、基层群众性自治组织、企业事业单位、社会组织在执行法律、法规和规章方面存在问题的，可以向其提出法律服务建议。"},{"i":31,"n":"第三十一条","txt":"基层法律服务工作者在执业期间，有权获得执业所需的工作条件，参加政治学习和业务培训，参与本所民主管理，获得劳动报酬和享受保险、福利待遇。"},{"i":32,"n":"第三十二条","txt":"基层法律服务工作者对违反本办法第三十一条规定，或者侵犯其执业权利的行为，可以请求司法行政机关、基层法律服务行业协会依法予以保障其合法权益。"},{"i":33,"n":"第三十三条","txt":"基层法律服务工作者应当遵守基层法律服务所统一收案、统一委派、统一收费的相关规定。"},{"i":34,"n":"第三十四条","txt":"基层法律服务工作者应当按照有关规定履行法律援助义务。"},{"i":35,"n":"第三十五条","txt":"基层法律服务工作者在执业过程中应当遵守司法、仲裁和行政执法活动的有关制度，尊重司法机关、仲裁委员会和行政执法机关及其工作人员依法行使职权。 曾担任法官的基层法律服务工作者，不得担任原任职法院办理案件的诉讼代理人。"},{"i":36,"n":"第三十六条","txt":"基层法律服务工作者应当尊重同行，同业互助，公平竞争，共同提高执业水平。"},{"i":37,"n":"第三十七条","txt":"基层法律服务工作者应当保守在执业活动中知悉的国家秘密、商业秘密和个人隐私。"},{"i":38,"n":"第三十八条","txt":"基层法律服务工作者应当爱岗敬业、坚持原则、诚实守信、举止文明、廉洁自律，自觉维护执业声誉和社会形象。"},{"i":39,"n":"第三十九条","txt":"基层法律服务工作者应当勤奋学习，加强职业修养，积极参加司法行政机关组织的业务培训，不断提高专业水平和服务技能。"},{"i":40,"n":"第四十条","txt":"设区的市级或者直辖市的区(县)司法行政机关应当对基层法律服务工作者进行年度考核。 对基层法律服务工作者进行年度考核的具体办法，由省、自治区、直辖市司法行政机关依据本办法和有关规定确定。"},{"i":41,"n":"第四十一条","txt":"基层法律服务工作者参加年度考核，应当提交下列材料： (一)上年度执业情况和遵守职业道德、执业纪律情况的个人总结； (二)基层法律服务所出具的执业表现年度考核意见； (三)《基层法律服务工作者执业证》。"},{"i":42,"n":"第四十二条","txt":"基层法律服务工作者年度考核材料，由基层法律服务所报经所在地县级司法行政机关审查后报设区的市级司法行政机关审核，或者由基层法律服务所报所在地直辖市的区(县)司法行政机关审核。"},{"i":43,"n":"第四十三条","txt":"设区的市级或者直辖市的区(县)司法行政机关在年度考核中，对有本办法第四十六条所列行为、尚未处理的基层法律服务工作者，按照本办法第四十六条至第四十八条的规定进行处理。"},{"i":44,"n":"第四十四条","txt":"县级司法行政机关或者直辖市的区(县)司法行政机关对基层法律服务工作者的日常执业活动和遵守职业道德、执业纪律的情况进行指导和监督，可以按照有关规定对基层法律服务工作者的执业情况进行检查，要求有关人员报告工作、说明情况、提交有关材料。司法所可以根据县级司法行政机关或者直辖市的区(县)司法行政机关要求，承担对基层法律服务工作者进行指导监督的具体工作。"},{"i":45,"n":"第四十五条","txt":"司法行政机关对有突出事迹或者显著贡献的基层法律服务工作者，按照有关规定给予表彰奖励。"},{"i":46,"n":"第四十六条","txt":"基层法律服务工作者有下列行为之一的，由所在地县级司法行政机关或者直辖市的区(县)司法行政机关予以警告；有违法所得的，依照法律、法规的规定没收违法所得，并由设区的市级或者直辖市的区(县)司法行政机关处以违法所得三倍以下的罚款，罚款数额最高为三万元： (一)超越业务范围和诉讼代理执业区域的； (二)以贬损他人、抬高自己、虚假承诺或者支付介绍费等不正当手段争揽业务的； (三)曾担任法官的基层法律服务工作者，担任原任职法院办理案件的诉讼代理人的； (四)冒用律师名义执业的； (五)同时在基层法律服务所和律师事务所或者公证机构执业，或者同时在两个以上基层法律服务所执业的； (六)无正当理由拒绝履行法律援助义务的； (七)明知委托人的要求是非法的、欺诈性的，仍为其提供帮助的； (八)在代理活动中超越代理权限或者滥用代理权，侵犯被代理人合法利益的； (九)在同一诉讼、仲裁、行政裁决中，为双方当事人或"},{"i":47,"n":"第四十七条","txt":"司法行政机关对基层法律服务工作者实施行政处罚，应当依照《中华人民共和国行政处罚法》和司法部有关规定进行。"},{"i":48,"n":"第四十八条","txt":"基层法律服务工作者对行政处罚不服的，可以依照《中华人民共和国行政复议法》和司法部有关规定申请行政复议。"},{"i":49,"n":"第四十九条","txt":"基层法律服务工作者有下列情形之一的，基层法律服务所可以按照有关规定解除聘用合同或者劳动合同： (一)有本办法第四十六条第一款第十三至第十七项规定行为，情节严重的； (二)有本办法第四十六条第一款第十八、十九、二十项规定行为之一的； (三)因故意犯罪受到刑事处罚的。"},{"i":50,"n":"第五十条","txt":"司法行政机关应当建立对基层法律服务工作者执业的投诉监督制度，设立投诉电话、投诉信箱，受理当事人和其他公民对基层法律服务工作者违法违纪行为的投诉，将调查处理结果告知投诉人。"},{"i":51,"n":"第五十一条","txt":"上级司法行政机关认为下级司法行政机关在执业核准、年度考核和行政处罚工作中有错误或者不当的，应当及时责令其纠正。 司法行政机关不履行管理职责或者干涉基层法律服务工作者执业、侵犯其合法权益的，应当追究主管人员和直接责任人员的行政责任。"},{"i":52,"n":"第五十二条","txt":"省、自治区、直辖市司法行政机关应当从解决乡镇和欠发达地区律师资源不足问题、满足基层人民群众的法律服务需求出发，制定本地区基层法律服务队伍发展方案。"},{"i":53,"n":"第五十三条","txt":"《基层法律服务工作者执业证》由司法部统一制作。"},{"i":54,"n":"第五十四条","txt":"本办法由司法部负责解释。"},{"i":55,"n":"第五十五条","txt":"本办法自2018年2月1日起施行。司法部此前制定的有关基层法律服务工作者管理的规章、规范性文件与本办法相抵触的，以本办法为准。"}],"jicengfalvfuwusuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对基层法律服务所的监督和管理，保障基层法律服务所依法执业，根据有关法律法规，结合基层法律服务工作实际和发展需要，制定本办法。"},{"i":2,"n":"第二条","txt":"基层法律服务所是在乡镇和街道设立的法律服务组织，是基层法律服务工作者的执业机构。"},{"i":3,"n":"第三条","txt":"基层法律服务所按照司法部规定的业务范围和执业要求，面向基层的政府机关、基层群众性自治组织、企业事业单位、社会组织和承包经营户、个体工商户、合伙组织以及公民提供法律服务，维护当事人合法权益，维护法律正确实施，促进社会稳定、经济发展和法治建设。"},{"i":4,"n":"第四条","txt":"基层法律服务所依法执业受法律保护，任何组织和个人不得侵害其合法权益。"},{"i":5,"n":"第五条","txt":"基层法律服务所应当把拥护中国共产党领导、拥护社会主义法治作为从业的基本要求。"},{"i":6,"n":"第六条","txt":"司法行政机关依据本办法对基层法律服务所进行管理和指导。"},{"i":7,"n":"第七条","txt":"基层法律服务所应当有规范的名称和章程；有三名以上符合司法部规定条件、能够专职执业的基层法律服务工作者；有住所和必要的资产。 事业体制基层法律服务所除应当符合第一款规定外，还应当持有事业单位登记管理机关颁发的《事业单位法人证书》。 普通合伙制基层法律服务所除应当符合第一款规定外，还应当至少有两名具有三年以上执业经历、能够专职执业的基层法律服务工作者作为合伙人，并有经全体合伙人协商一致并签名的合伙协议。 基层法律服务所的人员、财务、职能应当与司法所分离。"},{"i":8,"n":"第八条","txt":"基层法律服务所只能使用一个名称。名称应当由以下三部分内容依次排列组成：县级行政区划名称，乡镇、街道行政区划名称或者字号，法律服务所。"},{"i":9,"n":"第九条","txt":"基层法律服务所章程应当载明下列事项： (一)名称、住所； (二)本所法定代表人或者负责人的职责； (三)执业工作制度； (四)基层法律服务工作者及辅助工作人员的聘用、管理办法； (五)财务管理制度、分配制度； (六)其他内部管理制度； (七)停办、解散及清算办法； (八)章程修改的程序； (九)其他需要载明的事项。"},{"i":10,"n":"第十条","txt":"基层法律服务所变更名称、法定代表人或者负责人、合伙人、住所和修改章程的，应当由所在地县级司法行政机关审查同意后报设区的市级司法行政机关批准，或者由直辖市的区(县)司法行政机关批准。"},{"i":11,"n":"第十一条","txt":"基层法律服务所有下列情形之一的，应当终止： (一)不符合本办法第七条规定的基层法律服务所应当具备的条件，经限期整改仍不符合相关规定的； (二)停办或者决定解散的； (三)法律、行政法规规定应当终止的其他情形。 基层法律服务所无正当理由停止业务活动满一年的，视为自行停办、解散，应当终止。"},{"i":12,"n":"第十二条","txt":"基层法律服务所在终止事由发生后，应当向社会公告，按照有关规定进行清算，并不得受理新的业务。 基层法律服务所应当在清算结束后十五日内，经所在地县级司法行政机关审查后报设区的市级司法行政机关办理注销手续，或者由直辖市的区(县)司法行政机关办理注销手续。基层法律服务所拒不履行公告、清算义务的，可以由县级司法行政机关向社会公告后报设区的市级司法行政机关办理注销手续，或者由直辖市的区(县)司法行政机关向社会公告后办理注销手续。"},{"i":13,"n":"第十三条","txt":"《基层法律服务所执业证》分正本和副本。正本应当悬挂于执业场所，副本用于接受查验。正本和副本具有同等的法律效力。执业证不得伪造、涂改、抵押、出租、出借。"},{"i":14,"n":"第十四条","txt":"设区的市级或者直辖市的区(县)司法行政机关应当按年度将本地区基层法律服务所变更、注销的情况报省、自治区、直辖市司法行政机关备案。"},{"i":15,"n":"第十五条","txt":"基层法律服务所应当依据本办法建立健全各项管理制度，完善工作运行机制。"},{"i":16,"n":"第十六条","txt":"基层法律服务所设主任一名，根据需要可以设副主任。基层法律服务所主任，除应当取得基层法律服务工作者执业证外，还应当有三年以上从事基层法律服务工作或者基层司法行政工作的经历。"},{"i":17,"n":"第十七条","txt":"基层法律服务所主任，应当经基层法律服务所民主推选或者按照有关规定产生。"},{"i":18,"n":"第十八条","txt":"基层法律服务所主任为该所的法定代表人或者负责人，负责管理本所行政事务和组织开展业务工作，负责向所在地县级司法行政机关或者直辖市的区(县)司法行政机关报告工作。"},{"i":19,"n":"第十九条","txt":"基层法律服务所应当建立基层法律服务工作者会议制度，民主管理本所重大事务，行使下列职权： (一)制定本所发展规划和年度工作计划； (二)制定本所管理规章制度； (三)审议本所年度工作总结报告； (四)审议本所年度预决算报告和重大财务开支项目； (五)决定对本所基层法律服务工作者和辅助工作人员的奖惩； (六)审议其他重要事项。"},{"i":20,"n":"第二十条","txt":"基层法律服务所应当依法与在本所执业的基层法律服务工作者签订聘用合同或者劳动合同。"},{"i":21,"n":"第二十一条","txt":"基层法律服务所应当建立健全执业管理、业务培训、投诉查处、人员奖惩等内部管理制度，对基层法律服务工作者加强职业道德和执业纪律教育，加强业务知识和技能的培训，加强执业活动的检查、监督。"},{"i":22,"n":"第二十二条","txt":"基层法律服务所对违反职业道德、执业纪律，司法行政机关管理规定和本所章程、制度或者有其他违法行为的基层法律服务工作者，可以依据有关规定予以处分或者处理。"},{"i":23,"n":"第二十三条","txt":"基层法律服务所根据工作需要，可以按照有关规定聘用文秘、财务、行政等辅助工作人员，依法签订聘用合同或者劳动合同。 辅助工作人员的聘用、变更情况，应当报所在地县级司法行政机关或者直辖市的区(县)司法行政机关备案。"},{"i":24,"n":"第二十四条","txt":"基层法律服务所组织基层法律服务工作者开展业务活动，应当遵守下列要求： (一)严格执行司法部关于基层法律服务业务范围、工作原则和服务程序的规定，建立统一收案、统一委派、疑难法律事务集体讨论、重要案件报告等制度； (二)建立对基层法律服务工作者遵守职业道德、执业纪律和服务质量、效率的检查、监督、考评制度； (三)接受国家、社会和委托人的监督； (四)由基层法律服务所按照有关规定统一收取服务费，公开收费项目和收费标准，严格遵守基层法律服务收费管理制度； (五)对符合规定条件的当事人提供法律援助； (六)建立健全基层法律服务业务档案管理制度。"},{"i":25,"n":"第二十五条","txt":"基层法律服务所应当按照规定建立健全财务管理制度，建立和实行合理的分配制度以及激励机制。"},{"i":26,"n":"第二十六条","txt":"基层法律服务所应当根据本所收支情况和实际需要，留存用于事业发展、社会保障和奖励等事项的费用。"},{"i":27,"n":"第二十七条","txt":"基层法律服务所应当按照国家和地方有关社会保障的政策和规定，为基层法律服务工作者和辅助工作人员办理社会保险。"},{"i":28,"n":"第二十八条","txt":"基层法律服务所应当积极创造条件，加强办公用房、办公设施、办公装备的建设，不断改善执业条件，提高服务质量，提升工作效率。"},{"i":29,"n":"第二十九条","txt":"设区的市级或者直辖市的区(县)司法行政机关应当每年对基层法律服务所进行年度考核。 对基层法律服务所进行年度考核的具体办法，由省、自治区、直辖市司法行政机关依据本办法和有关规定制定。"},{"i":30,"n":"第三十条","txt":"基层法律服务所接受年度考核，应当提交下列材料： (一)上年度本所工作总结报告和本年度工作计划； (二)上年度本所财务报表； (三)《基层法律服务所执业证》副本； (四)司法行政机关要求提交的其他材料。"},{"i":31,"n":"第三十一条","txt":"基层法律服务所的年度考核材料，经所在地县级司法行政机关审查后报送设区的市级司法行政机关审核，或者由直辖市的区(县)司法行政机关审核。"},{"i":32,"n":"第三十二条","txt":"设区的市级或者直辖市的区(县)司法行政机关在年度考核中，对有本办法第三十六条所列行为、尚未处理的基层法律服务所，按照本办法第三十六条至第三十九条的规定进行处理。 在年度考核中，不符合本办法规定条件的基层法律服务所，应当在所在地县级司法行政机关或者直辖市的区(县)司法行政机关监督下，限期整改。期满后仍不符合本办法相关规定的，应当办理注销手续。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市司法行政机关应当建立基层法律服务所和基层法律服务工作者信息管理系统，按照有关规定向社会公开基层法律服务所、基层法律服务工作者基本信息和年度考核结果、奖惩情况，并将基层法律服务所、基层法律服务工作者信用记录纳入本省、自治区、直辖市信用信息共享平台。"},{"i":34,"n":"第三十四条","txt":"县级司法行政机关或者直辖市的区(县)司法行政机关对基层法律服务所的日常执业活动和内部管理工作进行指导和监督，可以按照有关规定对基层法律服务所进行检查，要求基层法律服务所报告工作、说明情况、提交有关材料。司法所可以根据县级司法行政机关或者直辖市的区(县)司法行政机关要求，承担对基层法律服务所进行指导监督的具体工作。"},{"i":35,"n":"第三十五条","txt":"司法行政机关对工作成绩显著、队伍建设良好、管理制度完善的基层法律服务所，按照有关规定给予表彰奖励。"},{"i":36,"n":"第三十六条","txt":"基层法律服务所有下列行为之一的，由所在地县级司法行政机关或者直辖市的区(县)司法行政机关予以警告；有违法所得的，依照法律、法规的规定没收违法所得，并由设区的市级或者直辖市的区(县)司法行政机关处以违法所得三倍以下的罚款，罚款数额最高为三万元： (一)超越业务范围和诉讼代理执业区域的； (二)违反规定不以基层法律服务所名义统一接受委托、统一收取服务费，不向委托人出具有效收费凭证的； (三)冒用律师事务所名义执业的； (四)以贬损他人、抬高自己、虚假承诺或者支付介绍费等不正当手段争揽业务的； (五)伪造、涂改、抵押、出租、出借本所执业证的； (六)违反规定变更本所名称、法定代表人或者负责人、合伙人、住所和章程的； (七)不按规定接受年度考核，或者在年度考核中弄虚作假的； (八)违反财务管理规定，私分、挪用或者以其他方式非法处置本所资产的； (九)聘用未获准基层法律服务工作者执业的人员以基层"},{"i":37,"n":"第三十七条","txt":"司法行政机关对基层法律服务所实施行政处罚，应当依照《中华人民共和国行政处罚法》和司法部有关规定进行。"},{"i":38,"n":"第三十八条","txt":"基层法律服务所对行政处罚不服的，可以依照《中华人民共和国行政复议法》和司法部有关规定申请行政复议。"},{"i":39,"n":"第三十九条","txt":"司法行政机关对基层法律服务所实施行政处罚的，应当按照有关规定追究其法定代表人或者负责人的责任。"},{"i":40,"n":"第四十条","txt":"司法行政机关对基层法律服务所实施行政处罚的同时，应当责令其限期整改。期满后仍不能改正，不宜继续执业的，由设区的市级或者直辖市的区(县)司法行政机关予以注销。"},{"i":41,"n":"第四十一条","txt":"司法行政机关应当建立对基层法律服务所的投诉监督制度，设立投诉电话、投诉信箱，受理公民、法人和其他非法人组织对基层法律服务所及其从业人员的投诉。 涉及委托人与基层法律服务所发生争议的投诉，由基层法律服务所所在地县级司法行政机关或者直辖市的区(县)司法行政机关予以调解处理；涉及基层法律服务所及其从业人员违法违纪的投诉，司法行政机关应当立案调查处理，并将查处结果告知投诉人。"},{"i":42,"n":"第四十二条","txt":"上级司法行政机关认为下级司法行政机关在年度考核和行政处罚工作中有错误或者不当的，应当及时责令其改正。 司法行政机关及其工作人员不履行管理职责或者侵犯基层法律服务所合法权益的，应当追究主管人员和直接责任人员的行政责任。"},{"i":43,"n":"第四十三条","txt":"《基层法律服务所执业证》由司法部统一制作。"},{"i":44,"n":"第四十四条","txt":"本办法由司法部负责解释。"},{"i":45,"n":"第四十五条","txt":"本办法自2018年2月1日起施行。司法部此前制定的有关基层法律服务所管理的规章、规范性文件与本办法相抵触的，以本办法为准。"}],"waiguojizuifanhuijiantongxunguiding":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国监狱法》和我国参加的有关国际公约及对外缔结的双边领事条约的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外国籍罪犯，是指经我国人民法院依法判处刑罚，在我国监狱内服刑的外国公民。 在监狱内服刑的无国籍罪犯，比照外国籍罪犯执行。"},{"i":3,"n":"第三条","txt":"外国籍罪犯经批准可以与所属国驻华使、领馆外交、领事官员，亲属或者监护人会见、通讯。"},{"i":4,"n":"第四条","txt":"办理外交、领事官员与本国籍罪犯的会见、通讯，应当遵照以下原则：与我国缔结领事条约的，按照条约并结合本规定办理；未与我国缔结领事条约但参加《维也纳领事关系公约》的，按照《维也纳领事关系公约》并结合本规定办理；未与我国缔结领事条约，也未参加《维也纳领事关系公约》，但与我国有外交关系的，应当按照互惠对等原则，根据本规定并参照国际惯例办理。"},{"i":5,"n":"第五条","txt":"外交、领事官员或者亲属、监护人索要有关法律、法规、规章的，省、自治区、直辖市监狱管理局或者监狱应当提供。"},{"i":6,"n":"第六条","txt":"外交、领事官员要求会见正在服刑的本国公民，应当向省、自治区、直辖市监狱管理局提出书面申请。申请应当说明：驻华使、领馆名称，参与会见的人数、姓名及职务，会见人的证件名称、证件号码，被会见人的姓名、罪名、刑期、服刑地点，申请会见的日期，会见所用语言。"},{"i":7,"n":"第七条","txt":"外国籍罪犯的非中国籍亲属或者监护人首次要求会见的，应当通过驻华使、领馆向省、自治区、直辖市监狱管理局提出书面申请。申请应当说明：亲属或者监护人的姓名和身份证件名称、证件号码，与被会见人的关系，被会见人的姓名、罪名、刑期、服刑地点，申请会见的日期，会见所用语言，并应同时提交与被会见人关系的证明材料。"},{"i":8,"n":"第八条","txt":"外国籍罪犯的中国籍亲属或者监护人首次要求会见的，应当向省、自治区、直辖市监狱管理局提出书面申请，同时提交本人身份和与被会见人关系的证明材料。"},{"i":9,"n":"第九条","txt":"外国籍罪犯的亲属或者监护人再次要求会见的，可以直接向监狱提出申请。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市监狱管理局收到外交、领事官员要求会见的书面申请后，应当在五个工作日内作出准予或者不准予会见的决定，并书面答复。准予会见的，应当在答复中确认：收到申请的时间，被会见人的姓名、服刑地点，会见人的人数及其姓名，会见的时间、地点安排，并告知应当携带的证件。 外国籍罪犯拒绝与外交、领事官员会见的，应当由本人写出书面声明，由省、自治区、直辖市监狱管理局通知驻华使、领馆，并附书面声明复印件。通知及附件同时抄送地方外事办公室备案。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市监狱管理局收到外国籍罪犯的亲属或者监护人首次要求会见的书面申请后，应当在五个工作日内作出准予或者不准予会见的决定，并书面答复。准予会见的，应当在答复中确认：会见人和被会见人的姓名，会见的时间、地点安排，并告知应当携带的证件。 外国籍罪犯的亲属或者监护人再次要求会见，直接向监狱提出申请的，监狱应当在两个工作日内予以答复。"},{"i":12,"n":"第十二条","txt":"外交、领事官员会见正在服刑的本国公民，一般每月可以安排一至二次，每次前来会见的人员一般不超过三人。要求增加会见次数或者人数的，应当提出书面申请，省、自治区、直辖市监狱管理局可以酌情安排。 亲属或者监护人会见外国籍罪犯，一般每月可以安排一至二次，每次前来会见的人员一般不超过三人。要求增加会见次数或者人数的，监狱可以酌情安排。"},{"i":13,"n":"第十三条","txt":"每次会见的时间不超过一小时。要求延时的，经监狱批准，可以适当延长。"},{"i":14,"n":"第十四条","txt":"会见一般安排在监狱会见室。"},{"i":15,"n":"第十五条","txt":"会见人应当按照省、自治区、直辖市监狱管理局或者监狱的安排到监狱会见。 外交、领事官员因故变更会见时间或者会见人的，应当提前提出申请，由省、自治区、直辖市监狱管理局重新安排。 亲属或者监护人因故变更会见时间的，应当提前提出申请，由省、自治区、直辖市监狱管理局或者监狱重新安排；变更会见人的，应当重新办理申请手续。"},{"i":16,"n":"第十六条","txt":"会见时应当遵守中国籍罪犯会见的有关规定。"},{"i":17,"n":"第十七条","txt":"会见开始前，监狱警察应当向会见人通报被会见人近期的服刑情况和健康状况，告知会见有关事项。"},{"i":18,"n":"第十八条","txt":"会见可以使用本国语言，也可以使用中国语言。"},{"i":19,"n":"第十九条","txt":"会见人和被会见人需要相互转交信件、物品，应当提前向监狱申明，并按规定将信件、物品提交检查，经批准后方可交会见人或者被会见人。"},{"i":20,"n":"第二十条","txt":"会见人向被会见人提供药品，应当同时提供中文或者英文药品使用说明，经审查后，由监狱转交被会见人。"},{"i":21,"n":"第二十一条","txt":"会见人或者被会见人违反会见规定，经警告无效的，监狱可以中止会见。"},{"i":22,"n":"第二十二条","txt":"监狱应当安排监狱警察陪同会见。"},{"i":23,"n":"第二十三条","txt":"监狱对外国籍罪犯与所属国驻华使、领馆外交、领事官员的往来信件，应当按照《维也纳领事关系公约》以及我国缔结的双边领事条约的规定，及时转交。 监狱对外国籍罪犯与亲属或者监护人的往来信件要进行检查。对正常的往来信件，应当及时邮寄转交；对有违反监狱管理规定内容的信件，可以将其退回，同时应当书面或者口头说明理由，并记录备案。"},{"i":24,"n":"第二十四条","txt":"外国籍罪犯的申诉、控告、检举信以及写给监狱的上级机关和司法机关的信件，不受监狱检查。监狱应当及时转交。"},{"i":25,"n":"第二十五条","txt":"经监狱批准，外国籍罪犯可以与所属国驻华使、领馆外交、领事官员或者亲属、监护人拨打电话。通话时应当遵守中国籍罪犯通话的有关规定。通话费用由本人承担。"},{"i":26,"n":"第二十六条","txt":"在司法部直属监狱服刑的外国籍罪犯的会见、通讯，由司法部监狱管理机构和直属监狱根据本规定办理。"},{"i":27,"n":"第二十七条","txt":"本规定由司法部解释。"},{"i":28,"n":"第二十八条","txt":"本规定自发布之日起施行。"}],"lvshishiwusuocongshizhengquanfalvyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对律师事务所从事证券法律业务活动的监督管理，规范律师在证券发行、上市和交易等活动中的执业行为，完善法律风险防范机制，维护证券市场秩序，保护投资者的合法权益，根据《中华人民共和国证券法》（以下简称证券法）、《中华人民共和国证券投资基金法》（以下简称证券投资基金法）和《中华人民共和国律师法》（以下简称律师法）等相关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"律师事务所及其指派的律师从事证券法律业务，适用本办法。 前款所称证券法律业务，是指律师事务所接受当事人委托，为其证券发行、上市和交易等证券业务活动，提供的制作、出具法律意见书等文件的法律服务。"},{"i":3,"n":"第三条","txt":"律师事务所从事证券法律业务，应当按照规定报中国证券监督管理委员会（以下简称中国证监会）和司法部备案。"},{"i":4,"n":"第四条","txt":"律师事务所及其指派的律师从事证券法律业务，应当遵守法律、行政法规及相关规定，遵循诚实、守信、独立、勤勉、尽责的原则，恪守律师职业道德和执业纪律，严格履行法定职责，保证其所出具文件的真实性、准确性、完整性。"},{"i":5,"n":"第五条","txt":"中国证监会及其派出机构、司法部及地方司法行政机关依法对律师事务所从事证券法律业务进行监督管理。 律师协会依照章程和律师行业规范对律师事务所从事证券法律业务进行自律管理。"},{"i":6,"n":"第六条","txt":"律师事务所从事证券法律业务，可以为下列事项出具法律意见： （一）首次公开发行股票、存托凭证及上市； （二）上市公司发行证券及上市； （三）股份有限公司申请股票在全国中小企业股份转让系统挂牌并公开转让； （四）股份有限公司向特定对象发行或转让股票导致股东累计超过二百人； （五）非上市公众公司向特定对象发行股票； （六）向不特定合格投资者公开发行股票并在北京证券交易所上市； （七）上市公司、非上市公众公司的收购、重大资产重组及股份回购； （八）上市公司合并、分立及分拆； （九）上市公司、非上市公众公司实行股权激励计划、员工持股计划； （十）上市公司、非上市公众公司召开股东大会； （十一）上市公司、非上市公众公司的信息披露； （十二）北京证券交易所上市公司转板； （十三）公司（企业）债券的发行及交易、转让； （十四）境内企业直接或者间接到境外发行证券或者将其证券在境外上市交易； （十五）证券"},{"i":7,"n":"第七条","txt":"律师事务所可以接受当事人的委托，组织起草招股说明书等与证券业务活动相关的法律文件。 鼓励律师事务所在组织起草招股说明书时，对招股说明书中对投资者作出投资决策有重大影响的信息进行验证，制作验证笔录。"},{"i":8,"n":"第八条","txt":"律师被吊销执业证书的，不得再从事证券法律业务。 律师被中国证监会采取证券市场禁入措施或者被司法行政机关给予停止执业处罚的，在规定禁入或者停止执业的期间不得从事证券法律业务。"},{"i":9,"n":"第九条","txt":"同一律师事务所不得同时为同一证券发行的发行人和保荐人、承销的证券公司出具法律意见，不得同时为同一收购行为的收购人和被收购的上市公司出具法律意见，不得在其他同一证券业务活动中为具有利害关系的不同当事人出具法律意见。 律师与当事人及其关联方具有利害关系，影响其执业独立性的，该律师所在律师事务所不得接受委托，提供证券法律服务。"},{"i":10,"n":"第十条","txt":"律师事务所从事证券法律业务应当建立健全分工合理、权责明确、相互制衡、有效监督的风险控制制度，覆盖证券法律业务的立项、利益冲突审查、内幕信息及未公开信息管理、核查和验证工作、法律意见复核、工作底稿管理等方面，加强对律师从事证券法律业务的管理，提高律师证券法律业务水平。"},{"i":11,"n":"第十一条","txt":"律师事务所应当按照以下要求建立和执行风险控制制度: (一)明确利益冲突审查的具体要求，建立贯穿执业全流程的审查机制，确保执业中不存在本办法第九条规定的情形; (二)明确执业过程中知悉的内幕信息和未公开信息管理的具体要求，建立信息知情人登记管理制度，禁止泄露、利用内幕信息、未公开信息; (三)明确对律师在执业过程中买卖证券的要求，确保律师在执业过程中不存在证券法第四十二条禁止的情形; (四)明确廉洁从业的要求，加强对执业人员的管理，不得在执业过程中谋求或者输送不正当利益。"},{"i":12,"n":"第十二条","txt":"律师事务所从事证券法律业务，应当设立风险控制委员会或者承担风险控制职能的内部机构，或者设置专门的风险控制岗位，负责证券法律业务的风险控制工作。 律师事务所从事证券法律业务时，应当将风险控制制度的执行情况记录在工作底稿中。"},{"i":13,"n":"第十三条","txt":"律师事务所及其指派的律师从事证券法律业务，应当按照依法制定的业务规则，勤勉尽责，审慎履行核查和验证义务。 律师进行核查和验证，可以采用面谈、书面审查、实地调查、查询和函证、计算、复核等方法。"},{"i":14,"n":"第十四条","txt":"律师事务所及其指派的律师从事证券法律业务，应当依法对所依据的文件资料内容的真实性、准确性、完整性进行核查和验证；在进行核查和验证前，应当编制核查和验证计划，明确需要核查和验证的具体事项和方式，并根据业务的进展情况，对其予以适当调整。"},{"i":15,"n":"第十五条","txt":"律师在出具法律意见时，对与法律相关的业务事项应当履行法律专业人士特别的注意义务，对其他业务事项履行普通人一般的注意义务，其制作、出具的文件不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":16,"n":"第十六条","txt":"律师从国家机关、具有管理公共事务职能的组织、会计师事务所、资产评估机构、资信评级机构、公证机构直接取得的文书，可以作为出具法律意见的依据，但应当履行本办法第十五条规定的注意义务并加以说明；对于不是从上述机构直接取得的文书，经核查和验证后方可作为出具法律意见的依据。 律师从上述机构抄录、复制的材料，经该机构确认后，可以作为出具法律意见的依据，但应当履行本办法第十五条规定的注意义务并加以说明；未取得确认的，对相关内容进行核查和验证后方可作为出具法律意见的依据。"},{"i":17,"n":"第十七条","txt":"律师进行核查和验证，需要会计师事务所、资产评估机构等证券服务机构作出判断的，应当直接委托或者要求委托人委托会计师事务所、资产评估机构等证券服务机构出具意见。"},{"i":18,"n":"第十八条","txt":"律师在从事证券法律业务时，委托人应当向其提供真实、准确、完整的有关材料，不得拒绝、隐匿、谎报。 律师发现委托人提供的材料有虚假记载、误导性陈述、重大遗漏，或者委托人有重大违法行为的，应当要求委托人纠正、补充；委托人拒不纠正、补充的，律师可以拒绝继续接受委托，同时应当按照规定向有关方面履行报告义务。"},{"i":19,"n":"第十九条","txt":"律师应当归类整理核查和验证中形成的工作记录和获取的材料，并对法律意见书等文件中各具体意见所依据的事实、国家相关规定以及律师的分析判断作出说明，形成真实完整、记录清晰的工作底稿。"},{"i":20,"n":"第二十条","txt":"律师事务所应当在业务委托结束后60日内完成工作底稿归档工作，并妥善保存。工作底稿保存期限不得少于10年，自业务委托结束之日起算。"},{"i":21,"n":"第二十一条","txt":"律师事务所从事证券法律业务，应当指派律师进行有关的核查和验证工作，未取得律师执业证书的工作人员只能从事相关的辅助工作。"},{"i":22,"n":"第二十二条","txt":"法律意见是律师事务所及其指派的律师针对委托人委托事项的合法性，出具的明确结论性意见，是委托人、投资者和中国证监会及其派出机构、证券交易场所确认相关事项是否合法的重要依据。法律意见应当由律师事务所及其指派的律师在核查和验证所依据的文件资料内容的真实性、准确性、完整性的基础上，依据法律、行政法规及相关规定作出。"},{"i":23,"n":"第二十三条","txt":"法律意见书应当列明相关材料、事实、具体核查和验证结果、国家有关规定和结论性意见。 法律意见不得使用“基本符合”、“未发现”等含糊措辞。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，律师应当在法律意见中予以说明，并充分揭示其对相关事项的影响程度及其风险： （一）委托人的全部或者部分事项不符合中国证监会规定； （二）事实不清楚，材料不充分，不能全面反映委托人情况； （三）核查和验证范围受到客观条件的限制，无法取得应有证据； （四）律师已要求委托人纠正、补充而委托人未予纠正、补充； （五）律师已依法履行勤勉尽责义务，仍不能对全部或者部分事项作出准确判断； （六）律师认为应当予以说明的其他情形。"},{"i":25,"n":"第二十五条","txt":"律师从事本办法第六条规定的证券法律业务，其所出具的法律意见应当经所在律师事务所讨论复核，并制作相关记录作为工作底稿留存。"},{"i":26,"n":"第二十六条","txt":"律师从事本办法第六条规定的证券法律业务，其所出具的法律意见应当由2名以上执业律师和所在律师事务所负责人签名，加盖该律师事务所印章，并签署日期。"},{"i":27,"n":"第二十七条","txt":"法律意见书等文件的具体内容和格式，应当符合中国证监会的规定。"},{"i":28,"n":"第二十八条","txt":"法律意见书等文件在按规定报送中国证监会及其派出机构、证券交易场所后，发生重大事项或者律师发现需要补充意见的，应当及时提出补充意见。"},{"i":29,"n":"第二十九条","txt":"律师从事证券法律业务期间，律师或者其所在律师事务所因涉嫌违法被有关机关立案调查的，该律师、律师事务所应当及时如实告知委托人，并明确提示可能的法律后果。"},{"i":30,"n":"第三十条","txt":"律师事务所应当按照中国证监会的要求，定期报送从事证券法律业务的基本情况。"},{"i":31,"n":"第三十一条","txt":"中国证监会及其派出机构、司法行政机关及律师协会建立律师从事证券法律业务的资料库、诚信档案和信息公示平台，记载律师、律师事务所从事证券法律业务的执业情况和所受处理处罚等情况，并按照规定予以公开。"},{"i":32,"n":"第三十二条","txt":"中国证监会及其派出机构、证券交易场所在审核律师出具的法律意见时，对其真实性、准确性、完整性有疑义的，可以要求律师作出解释、补充，或者调阅其工作底稿。律师和律师事务所应当配合。"},{"i":33,"n":"第三十三条","txt":"律师、律师事务所从事证券法律业务有下列情形之一的，中国证监会及其派出机构可以采取责令改正、监管谈话、出具警示函等措施： （一）未按照本办法第三条、第三十条的规定进行备案、报送执业情况，或者报送的备案、执业情况材料中存在虚假记载、误导性陈述或者重大遗漏； （二）未按照本办法第十条、第十一条、第十二条的规定建立、执行风险控制制度； （三）未按照本办法第十三条的规定勤勉尽责，对所依据的文件资料内容的真实性、准确性、完整性进行核查和验证； （四）未按照本办法第十四条的规定编制核查和验证计划； （五）未按照本办法第十八条的规定要求委托人予以纠正、补充，或者履行报告义务； （六）未按照本办法第十九条、第二十条的规定制作、保存工作底稿； （七）未按照本办法第二十一条的规定完成核查和验证工作； （八）未按照本办法第二十四条的规定在法律意见中作出说明； （九）未按照本办法第二十五条的规定讨论复核法律意见"},{"i":34,"n":"第三十四条","txt":"中国证监会及其派出机构作出监管谈话决定的，应当将监管谈话的对象、原因、时间、地点等以书面形式通知律师或者律师事务所负责人。律师或者律师事务所负责人应当按照通知要求，接受监管谈话。 中国证监会及其派出机构对律师或者律师事务所负责人监管谈话，可以会同或者委托司法行政机关进行。 进行监管谈话，应当有2名以上工作人员在场，并对监管谈话的内容作出书面记录。"},{"i":35,"n":"第三十五条","txt":"中国证监会及其派出机构或者司法行政机关对律师、律师事务所采取责令改正、监管谈话、出具警示函等措施的，律师、律师事务所应当按照要求改正所存在的问题，提高证券法律业务水平。"},{"i":36,"n":"第三十六条","txt":"律师、律师事务所负责人未按照规定接受监管谈话，或者未按照要求改正所存在问题的，中国证监会及其派出机构或者司法行政机关可以责令其限期整改。"},{"i":37,"n":"第三十七条","txt":"律师事务所及其指派的律师从事证券法律业务，违反证券法、证券投资基金法和有关证券管理的行政法规，应当给予行政处罚的，由中国证监会及其派出机构依法实施处罚。"},{"i":38,"n":"第三十八条","txt":"律师事务所从事证券法律业务，未按照中国证监会的规定进行备案的，由中国证监会依照证券法第二百一十三条的规定实施处罚。"},{"i":39,"n":"第三十九条","txt":"律师事务所从事证券法律业务，未勤勉尽责，所制作、出具的文件有虚假记载、误导性陈述或者重大遗漏的，由中国证监会依照证券法第二百一十三条、证券投资基金法第一百四十三条的规定实施处罚。"},{"i":40,"n":"第四十条","txt":"律师事务所从事证券法律业务，未按照本办法第二十条的规定保存工作底稿的，由中国证监会依照证券法第二百一十四条的规定实施处罚。"},{"i":41,"n":"第四十一条","txt":"律师从事证券法律业务，违反证券法、证券投资基金法、有关行政法规和本办法规定，情节严重的，中国证监会可以依照证券法第二百二十一条、证券投资基金法第一百四十八条的规定，对其采取证券市场禁入的措施。"},{"i":42,"n":"第四十二条","txt":"律师事务所及其指派的律师从事证券法律业务，违反律师法和有关律师执业管理规定的，由司法行政机关给予相应的行政处罚。 律师事务所及其指派的律师从事证券法律业务，违反律师行业规范的，由律师协会给予相应的行业惩戒。"},{"i":43,"n":"第四十三条","txt":"律师事务所及其指派的律师违反规定从事证券法律业务，涉嫌犯罪的，依法移送司法机关处理。"},{"i":44,"n":"第四十四条","txt":"中国证监会及其派出机构、司法行政机关在查处律师事务所、律师从事证券法律业务的违法行为的工作中，应当相互配合，互通情况，建立协调协商机制。对于依法应当由对方实施处罚的，及时移送对方处理；一方实施处罚后，应当将处罚结果书面告知另一方，并抄送证券交易场所、证券基金行业协会和律师协会。"},{"i":45,"n":"第四十五条","txt":"律师事务所及其指派的律师从事期货法律业务，参照本办法执行。"},{"i":46,"n":"第四十六条","txt":"本办法自2023年12月1日起施行。中国证监会、司法部2007年3月9日颁布的《律师事务所从事证券法律业务管理办法》（证监会令第41号）同时废止。"}],"lvshishiwusuomingchengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强律师事务所名称管理，规范律师事务所名称使用，根据《中华人民共和国律师法》(以下简称《律师法》)和有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"律师事务所对经司法行政机关依法核准的律师事务所名称享有专用权。律师事务所依法使用名称，受法律保护。"},{"i":3,"n":"第三条","txt":"设立律师事务所，应当在申请设立许可前，按照本办法的规定办理律师事务所名称预核准。 预核准的律师事务所名称，由省、自治区、直辖市司法行政机关在实施律师事务所设立许可时予以核准。"},{"i":4,"n":"第四条","txt":"律师事务所只能选择、使用一个名称。"},{"i":5,"n":"第五条","txt":"律师事务所名称应当使用符合国家规范的汉字。 民族自治地方律师事务所的名称，可以同时使用本民族自治地方通用的民族语言文字。"},{"i":6,"n":"第六条","txt":"律师事务所名称应当由“省(自治区、直辖市)行政区划地名、字号、律师事务所”三部分内容依次组成。 合伙律师事务所的名称，可以使用设立人的姓名连缀或者姓氏连缀作字号。"},{"i":7,"n":"第七条","txt":"律师事务所名称中的字号应当由两个以上汉字组成，并不得含有下列内容和文字： (一)有损国家利益、社会公共利益或者有损社会主义道德风尚的，不尊重民族、宗教习俗的； (二)政党名称、党政军机关名称、群众组织名称、社会团体名称及其简称； (三)国家名称，重大节日名称，县(市辖区)以上行政区划名称或者地名； (四)外国国家(地区)名称、国际组织名称及其简称； (五)可能对公众造成欺骗或者误解的； (六)汉语拼音字母、外文字母、阿拉伯数字、全部由中文数字组成或者带有排序性质的文字； (七)“中国”、“中华”、“全国”、“国家”、“国际”、“中心”、“集团”、“联盟”等字样； (八)带有“涉外”、“金融”、“证券”、“专利”、“房地产”等表明特定业务范围的文字或者与其谐音的文字； (九)与已经核准或者预核准的其他律师事务所名称中的字号相同或者近似的； (十)字号中包括已经核准或者预核准的其他律师事务"},{"i":8,"n":"第八条","txt":"律师事务所分所名称应当由“总所所在地省(自治区、直辖市)行政区划地名、总所字号、分所所在地的市(含直辖市、设区的市)或者县行政区划地名(地名加括号)、律师事务所”四部分内容依次组成。"},{"i":9,"n":"第九条","txt":"律师事务所名称预核准，由省、自治区、直辖市司法行政机关依设立人的申请予以办理。"},{"i":10,"n":"第十条","txt":"申请律师事务所名称预核准，由设立人或者设立人指定的代表向省、自治区、直辖市司法行政机关提交《律师事务所名称预核准申请表》，提出五至十个备选名称，并标明拟选用的先后顺序。 在民族自治地方设立律师事务所的，申请名称预核准的材料，应当先提交所在地设区的市级司法行政机关，经其审核后报送省、自治区、直辖市司法行政机关。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市司法行政机关应当自收到名称预核准申请材料之日起十日内进行审核，对于符合规定的备选名称，提交司法部进行名称检索。 对于所有备选名称不符合规定或者符合规定的备选名称少于五个的，应当告知申请人重新选报或者补报备选名称。"},{"i":12,"n":"第十二条","txt":"司法部自收到律师事务所备选名称材料之日起十日内完成名称检索，并将检索结果通知提交检索的省、自治区、直辖市司法行政机关。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市司法行政机关自收到检索结果之日起七日内，应当根据检索结果，向申请人发出《律师事务所名称预核准通知书》；对所有备选名称均不符合规定的，应当在通知中说明理由，并告知申请人重新选报名称。"},{"i":14,"n":"第十四条","txt":"有两个或者两个以上的申请人申请预核准的律师事务所名称相同或者近似的，应当根据收到申请的先后顺序办理名称预核准。"},{"i":15,"n":"第十五条","txt":"经预核准的律师事务所名称，自省、自治区、直辖市司法行政机关发出《律师事务所名称预核准通知书》之日起六个月内有效。有效期满，设立人未提交律师事务所设立申请的，预核准的律师事务所名称失效。 在有效期内，律师事务所未经司法行政机关许可设立的，不得使用预核准的律师事务所名称。"},{"i":16,"n":"第十六条","txt":"申请律师事务所设立许可时，申请人应当提交《律师事务所名称预核准通知书》。 省、自治区、直辖市司法行政机关在作出准予设立律师事务所决定时，核准使用预核准的律师事务所名称，并在行政许可决定书和颁发的《律师事务所执业许可证》中予以载明。 律师事务所分所名称，由分所设立所在地的省、自治区、直辖市司法行政机关在作出准予分所设立决定时予以核准。"},{"i":17,"n":"第十七条","txt":"律师事务所变更名称，应当按照本办法规定办理名称预核准。省、自治区、直辖市司法行政机关应当根据律师事务所变更名称的申请及已预核准的律师事务所名称，办理律师事务所名称变更手续。 律师事务所设立分所的，应当自总所名称获准变更之日起三十日内，向分所设立许可机关申请变更分所名称。"},{"i":18,"n":"第十八条","txt":"律师事务所应当在住所醒目位置标明律师事务所名称。"},{"i":19,"n":"第十九条","txt":"律师事务所使用名称从事执业活动或者其他活动，应当遵循诚实信用的原则，不得违反法律、法规和规章的规定。"},{"i":20,"n":"第二十条","txt":"律师事务所印章、银行账户、牌匾、信笺、对外推介材料以及本所律师名片使用的名称，应当使用司法行政机关核准的律师事务所名称。 律师事务所在其出具的法律文书及其他文件上使用的名称，应当与司法行政机关核准使用的名称相同。 律师事务所自本所名称获准变更之日起一年内，可以在本所推介材料、律师名片上使用新名称时加注变更前的名称。"},{"i":21,"n":"第二十一条","txt":"律师事务所使用名称，不得在核准使用的名称中或者名称后使用或者加注“律师集团”、“律师联盟”等文字。 律师事务所可以根据业务需要，将本所名称译成外文。律师事务所外文名称，应当自决定使用之日起十五日内报省、自治区、直辖市司法行政机关备案。外文名称违反译文规则的，备案机关应当责令其纠正。"},{"i":22,"n":"第二十二条","txt":"律师事务所有下列情形之一的，不得申请变更名称： (一)受到停业整顿处罚，期限未满的； (二)发生终止事由的； (三)本所取得设立许可后不满一年的，但发生变更组织形式或者分立、合并情形的除外。"},{"i":23,"n":"第二十三条","txt":"省、自治区、直辖市司法行政机关应当依照《律师法》、《律师事务所管理办法》和本办法的规定，办理律师事务所名称预核准、律师事务所设立许可名称核准和律师事务所变更名称核准。 预核准的名称、设立许可核准的名称和核准变更的名称，应当自核准之日起三十日内报司法部备案。 律师事务所因终止被注销的，应当自注销之日起三十日内，将被注销的律师事务所名称报司法部备案。 分所的审核机关应当将核准分所名称或者注销分所名称的决定自核准之日或者注销之日起三十日内抄送设立分所的律师事务所的审核机关。"},{"i":24,"n":"第二十四条","txt":"律师事务所获准变更名称，或者因终止被注销的，其变更或者被注销前使用的名称，自获准变更或者被注销之日起三年内，省、自治区、直辖市司法行政机关不得核准其他律师事务所使用。"},{"i":25,"n":"第二十五条","txt":"律师事务所违反规定使用名称的，由县级司法行政机关给予批评教育，责令改正，并对其整改情况进行监督；情节严重的，由所在地设区的市级司法行政机关或者直辖市区(县)司法行政机关依据《律师法》等有关规定给予相应的行政处罚。"},{"i":26,"n":"第二十六条","txt":"司法行政机关违反本办法规定办理律师事务所名称预核准或者核准的，上一级司法行政机关应当责令其改正。"},{"i":27,"n":"第二十七条","txt":"本办法所称的行政区划地名，是指不包括“省”、“自治区”、“直辖市”、“市”、“县”、“区”等行政区划称谓的地方名称。"},{"i":28,"n":"第二十八条","txt":"《律师事务所名称预核准申请表》、《律师事务所名称预核准通知书》和《律师事务所名称变更预核准申请表》、《律师事务所名称变更预核准通知书》的格式文本，由司法部规定。"},{"i":29,"n":"第二十九条","txt":"司法部建立全国律师事务所名称检索系统，为各地办理律师事务所名称预核准提供名称检索服务。"},{"i":30,"n":"第三十条","txt":"本办法自2010年3月1日起施行。司法部1995年2月22日发布的《律师事务所名称管理办法》(司法部令第36号)同时废止。 本办法施行前律师事务所名称不符合本办法有关规定的，应当自本办法施行后一年内按照本办法的有关规定予以变更。"}],"lvshishiwusuoniandujianchakaohebanfa":[{"i":1,"n":"第一条","txt":"为了规范律师事务所年度检查考核工作，加强对律师事务所执业和管理活动的监督，根据《中华人民共和国律师法》(以下简称《律师法》)的规定，结合律师管理工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"律师事务所年度检查考核，是指司法行政机关定期对律师事务所上一年度的执业和管理情况进行检查考核，对其执业和管理状况作出评价。 年度检查考核，应当引导律师事务所及其律师遵守宪法和法律，加强自律管理，依法、诚信、尽责执业，忠实履行中国特色社会主义法律工作者的职业使命，维护当事人合法权益，维护法律正确实施，维护社会公平和正义。"},{"i":3,"n":"第三条","txt":"司法行政机关对律师事务所进行年度检查考核，应当坚持依法、公正、公开的原则。"},{"i":4,"n":"第四条","txt":"省、自治区、直辖市司法行政机关负责指导、监督本行政区域律师事务所的年度检查考核工作。 设区的市级或者直辖市区(县)司法行政机关负责组织实施对本行政区域内律师事务所的年度检查考核工作。 县级司法行政机关负责年度检查考核的初审工作。"},{"i":5,"n":"第五条","txt":"司法行政机关对律师事务所的年度检查考核应当与律师协会对律师执业的年度考核相结合。"},{"i":6,"n":"第六条","txt":"对律师事务所进行年度检查考核，主要检查考核律师事务所遵守宪法和法律、履行法定职责、实行自律管理的情况，具体包括下列内容： (一)律师队伍建设情况； (二)业务活动开展情况； (三)律师执业表现情况； (四)内部管理情况； (五)受行政奖惩、行业奖惩的情况； (六)履行律师协会会员义务的情况； (七)省、自治区、直辖市司法行政机关根据需要认为应当检查考核的其他事项。"},{"i":7,"n":"第七条","txt":"本办法第六条第一项规定的“律师队伍建设情况”，主要包括并可分解为下列事项： (一)律师人员的数量、素质、结构变化的情况； (二)组织律师开展思想政治教育和律师职业道德、执业纪律教育的情况； (三)组织律师开展业务学习和参加职业培训的情况； (四)开展律师党建工作的情况。"},{"i":8,"n":"第八条","txt":"本办法第六条第二项规定的“业务活动开展情况”，主要包括并可分解为下列事项： (一)办理业务的数量和类别、拓展服务领域、提高服务质量以及业务收入等方面的情况； (二)在开展业务活动中遵守法律、法规、规章和行业规范的情况； (三)指导和监督律师代理重大案件、群体性案件的情况； (四)对律师执业实施监督和投诉查处的情况； (五)履行法律援助义务、参加社会服务及其他社会公益活动的情况； (六)因执业活动受到当事人、有关部门及社会公众表扬、投诉的情况。"},{"i":9,"n":"第九条","txt":"本办法第六条第三项规定的“律师执业表现情况”，主要包括并可分解为下列事项： (一)律师在执业活动中遵守法律、法规和规章，遵守职业道德、执业纪律和执业行为规范的情况； (二)律师履行法律援助义务、参加社会服务及其他社会公益活动的情况； (三)律师受行政奖惩、行业奖惩的情况； (四)律师执业年度考核的情况。"},{"i":10,"n":"第十条","txt":"本办法第六条第四项规定的“内部管理情况”，主要包括并可分解为下列事项： (一)执业管理制度建立和实施的情况； (二)收费管理、财务管理和分配管理制度建立和实施的情况； (三)依法纳税的情况； (四)建立执业风险、事业发展等基金及其使用的情况； (五)管理聘用律师和辅助人员的情况； (六)管理分支机构的情况； (七)管理申请律师执业人员实习的情况； (八)业务档案、律师执业档案建立和管理的情况； (九)章程、合伙制度实施的情况。"},{"i":11,"n":"第十一条","txt":"司法行政机关对律师事务所进行年度检查考核，应当同时对律师协会对律师执业年度考核的结果进行备案审查。"},{"i":12,"n":"第十二条","txt":"律师事务所年度检查考核结果分为“合格”和“不合格”二个等次。 考核等次是司法行政机关对律师事务所上一年度执业和管理情况的总体评价。"},{"i":13,"n":"第十三条","txt":"律师事务所的执业和管理活动符合下列标准的，考核等次为“合格”： (一)能够遵守宪法和法律，较好地履行法定职责； (二)在律师队伍建设、开展业务活动、实行内部管理等方面符合法律、法规、规章和行业规范的要求； (三)本所未因执业违法行为受到行政处罚，或者受到行政处罚已按要求完成整改。"},{"i":14,"n":"第十四条","txt":"律师事务所有下列情形之一的，考核等次为“不合格”： (一)放任、纵容、袒护律师执业违法行为，造成严重后果的； (二)不按规定建立健全内部管理制度，日常管理松懈、混乱，造成本所不能正常运转的； (三)本所受到行政处罚未按要求进行整改或者整改未达标的； (四)本所不能保持法定设立条件的； (五)提交的年度执业情况报告和律师执业年度考核情况存在严重弄虚作假行为的； (六)有其他严重违法行为，造成恶劣社会影响的。"},{"i":15,"n":"第十五条","txt":"律师事务所年度检查考核工作，应当在每年的三月至五月集中办理。具体工作流程和时间安排，由省、自治区、直辖市司法行政机关规定。"},{"i":16,"n":"第十六条","txt":"律师事务所接受年度检查考核，应当在完成对本所律师执业年度考核和本所执业、管理情况总结后，依据本办法规定的检查考核内容，按照规定时间，向所在地的县级司法行政机关报送本所上一年度执业情况报告和对本所律师执业年度考核的情况，并提交下列材料： (一)年度财务审计报告； (二)开展业务活动的统计报表； (三)纳税凭证； (四)年度内被获准的重大变更事项的批件； (五)获得行政或者行业表彰奖励、受到行政处罚或者行业惩戒的证明材料； (六)建立执业风险、事业发展等基金的证明材料； (七)为聘用律师和辅助人员办理养老、失业、医疗等社会保险的证明材料； (八)履行法律援助义务、参加社会服务及其他社会公益活动的证明材料； (九)履行律师协会会员义务的证明材料； (十)省、自治区、直辖市司法行政机关要求提供的其他材料。"},{"i":17,"n":"第十七条","txt":"县级司法行政机关收到律师事务所报送的材料后，应当依照本办法的规定进行审查，发现报送的执业情况报告及有关材料不齐全或者有疑义的，应当要求律师事务所予以补充或者作出说明，必要时可以进行调查核实。 县级司法行政机关应当在规定的时间内完成审查，出具初审意见和考核等次评定建议，连同律师事务所报送的材料，一并报设区的市级司法行政机关。"},{"i":18,"n":"第十八条","txt":"律师事务所在向县级司法行政机关报送年度检查考核材料的同时，应当将对本所律师执业年度考核的意见报所在地市级律师协会进行审查，由其确定考核结果。 律师协会应当将律师执业年度考核结果按规定时间报设区的市级或者直辖市区(县)司法行政机关备案。"},{"i":19,"n":"第十九条","txt":"设区的市级司法行政机关收到县级司法行政机关报送的律师事务所的材料和初审意见后，应当依照本办法规定的考核内容和考核标准，对律师事务所上一年度的执业和管理情况进行审查，同时对市级律师协会报备的律师执业年度考核结果予以备案审查。根据审查结果，为律师事务所评定考核等次。 在审查中，发现律师事务所报送的材料以及县级司法行政机关的初审意见、律师协会对律师的考核结果与实际情况不符，或者收到相关投诉、举报的，可以进行调查核实或者责成县级司法行政机关、律师协会重新进行审查。 考核机关对律师事务所评定考核等次，应当征求市级律师协会的意见。"},{"i":20,"n":"第二十条","txt":"直辖市区域内的律师事务所，由直辖市区(县)司法行政机关按照本办法第十六条、第十八条和第十九条的相关规定，直接进行年度检查考核。"},{"i":21,"n":"第二十一条","txt":"律师事务所的考核等次评定后，设区的市级或者直辖市区(县)司法行政机关应当将考核结果在本地律师工作管理网站上予以公示。公示期不得少于七日。 律师事务所对考核结果有异议的，可以向考核机关申请复查。考核机关应当自收到申请之日起十日内进行复查，并将复查结果书面告知申请人。"},{"i":22,"n":"第二十二条","txt":"设区的市级或者直辖市区(县)司法行政机关在年度考核结果确定后，应当在律师事务所执业许可证副本上加盖“律师事务所年度检查考核”专用章，并注明考核结果；在律师执业证书上加盖“律师年度考核备案”专用章。"},{"i":23,"n":"第二十三条","txt":"律师事务所因涉嫌违法正在接受查处，或者受到停业整顿处罚且处罚期未满的，应当暂缓考核，待有查处结果或者处罚期满后再予考核。"},{"i":24,"n":"第二十四条","txt":"对被评定为“合格”的律师事务所，经检查考核发现该所在律师队伍建设、开展业务活动、实行内部管理等方面存在问题的，由设区的市级或者直辖市区(县)司法行政机关责令其限期整改，并对其整改情况进行监督。"},{"i":25,"n":"第二十五条","txt":"对被评定为“不合格”的律师事务所，由设区的市级或者直辖市区(县)司法行政机关根据其存在违法行为的性质、情节及危害程度，依法给予停业整顿一个月以上六个月以下的处罚，并责令其整改；同时对该所负责人和负有直接责任的律师依法给予相应的处罚；情节特别严重的，依法吊销其执业许可证。 律师事务所因有本办法第十四条第四项规定情形被评定为“不合格”的，考核机关应当责令其限期整改。经整改仍不符合法定设立条件的，应当终止。"},{"i":26,"n":"第二十六条","txt":"律师事务所不按规定接受年度检查考核的，由设区的市级或者直辖市区(县)司法行政机关公告责令其限期接受年度检查考核；逾期仍未接受年度检查考核的，视为自行停办，由司法行政机关收回并注销其执业许可证。"},{"i":27,"n":"第二十七条","txt":"律师事务所年度检查考核结果和律师执业年度考核结果，应当分别记入律师事务所和律师执业档案。 律师事务所年度检查考核结果应当记入该所负责人、合伙人的律师执业档案。"},{"i":28,"n":"第二十八条","txt":"设区的市级或者直辖市区(县)司法行政机关在年度检查考核工作结束后，应当将本行政区域开展律师事务所年度检查考核的情况总结及考核结果报省、自治区、直辖市司法行政机关备案，同时抄送当地市级律师协会。"},{"i":29,"n":"第二十九条","txt":"省、自治区、直辖市司法行政机关收到备案材料后应当及时进行审核，完成汇总，将本行政区域律师事务所年度检查考核的结果在指定的报刊和政府网站上予以公告。 公告的内容，应当同时包括律师事务所的名称、执业许可证号、组织形式、住所地址、邮编、电话、负责人、律师姓名及执业证号等内容。"},{"i":30,"n":"第三十条","txt":"省、自治区、直辖市司法行政机关应当于每年的五月底将本行政区域开展律师事务所年度检查考核的情况总结及考核结果报告司法部，同时抄送省、自治区、直辖市律师协会。"},{"i":31,"n":"第三十一条","txt":"司法部根据省、自治区、直辖市司法行政机关报送的律师事务所年度检查考核结果及相关资料，按年度编制全国律师事务所及律师名录，并向社会公布。"},{"i":32,"n":"第三十二条","txt":"律师事务所分所由其所在地的设区的市级或者直辖市区(县)司法行政机关依照本办法的规定进行年度检查考核。考核结果应当报省、自治区、直辖市司法行政机关备案，同时抄送设立分所的律师事务所所在地的设区的市级或者直辖市区(县)司法行政机关。"},{"i":33,"n":"第三十三条","txt":"本办法自发布之日起施行。"}],"lvshishiwusuoshoufeichengxuguize":[{"i":1,"n":"第一条","txt":"为了规范律师事务所的收费行为，根据有关法律、法规和律师收费管理规定，制定本规则。"},{"i":2,"n":"第二条","txt":"律师事务所收费的项目、标准和方式应当依照《律师服务收费管理暂行办法》和省、自治区、直辖市价格主管部门、司法行政机关制定的律师服务收费的有关规定执行。"},{"i":3,"n":"第三条","txt":"律师事务所收取律师服务费，应当遵循合法、公开、公平、协商一致的原则。"},{"i":4,"n":"第四条","txt":"律师事务所采用协商收费、计时收费的，应当按照《律师服务收费管理暂行办法》第四条、第七条规定的范围进行。"},{"i":5,"n":"第五条","txt":"律师服务费由律师事务所统一收取。 律师不得私自向委托人收取任何费用。"},{"i":6,"n":"第六条","txt":"律师事务所应当采取张贴、印制服务指南等方式，公示律师服务收费项目、收费标准和收费方式，接受委托人的监督。"},{"i":7,"n":"第七条","txt":"律师事务所接受委托后，应当与委托人签订收费合同或者在委托合同中载明收费条款。 收费合同应当包括下列内容：收费项目、收费方式和标准、收费数额(比例)、付款和结算方式、争议解决途径等内容。"},{"i":8,"n":"第八条","txt":"律师事务所应当按照收费合同或者委托合同中的收费条款约定的收费方式和收费数额(比例)收取律师服务费。"},{"i":9,"n":"第九条","txt":"律师事务所应当直接向委托人收取律师服务费。应委托人请求或者其他原因，由承办律师代交费用的，承办律师应当向律师事务所提供经委托人签字并载明交费数额的委托书。"},{"i":10,"n":"第十条","txt":"律师事务所向委托人收取律师服务费，应当及时向委托人开具合法票据。"},{"i":11,"n":"第十一条","txt":"律师事务所应当统一管理委托合同、收费合同、收费票据、印章以及有关介绍信函等。"},{"i":12,"n":"第十二条","txt":"根据《律师服务收费管理暂行办法》第八条的规定，需要由委托人另行支付的办案费用，律师事务所应当事先告知委托人，具体项目和支付方式由双方协商确定。"},{"i":13,"n":"第十三条","txt":"律师事务所代委托人支付鉴定费、评估费、翻译费、人民法院依法收取的费用等办案费用的，应当凭有效凭证与委托人结算。"},{"i":14,"n":"第十四条","txt":"律师事务所预收律师异地办案所需的差旅费用时，应当向委托人提供费用概算，经协商一致，由双方签字确认。办案过程中，因情况变化确需调整费用概算时，律师事务所应当与委托人再行协商，并由双方签字确认后执行。 承办律师不得私自向委托人收取异地办案差旅费用。"},{"i":15,"n":"第十五条","txt":"律师事务所应当对承办律师使用预收的异地办案差旅费用的情况实施监督。 承办律师办结委托事项后，应当向律师事务所提交费用使用清单及开支的有效凭证，接受律师事务所的审核。 律师事务所经审核，认定开支项目、标准不当的，应当核减。被核减的费用由承办律师承担。"},{"i":16,"n":"第十六条","txt":"律师事务所在办结委托事项后，应当及时与委托人结算预收的律师异地办案差旅费用。结算时，应当向委托人提交费用使用清单和开支的有效凭证，由委托人审核确认。"},{"i":17,"n":"第十七条","txt":"律师事务所经有关部门批准，可以设立用于存放代委托人保管的合同资金、执行回款、履约保证金等款项的专用账户。 律师事务所应当严格管理专用账户，防范风险。对专用账户资金的支付，必须严格审核把关，专款专用。严禁将专用账户的资金挪作他用。"},{"i":18,"n":"第十八条","txt":"律师事务所对确有经济困难的委托人，可以减收或者缓收律师服务费。承办律师不得自行决定对委托人减收或者缓收律师服务费。"},{"i":19,"n":"第十九条","txt":"律师事务所不得采用不正当的收费方式招揽业务，不得以任何方式和名目给委托人回扣或者向中介人支付介绍费。"},{"i":20,"n":"第二十条","txt":"律师事务所与委托人因收费发生争议的，应当协商解决。协商不成的，可以提请所在地律师协会调解处理，也可以向人民法院提起诉讼。"},{"i":21,"n":"第二十一条","txt":"律师事务所的收费行为，应当接受当地价格主管部门、司法行政机关的监督检查。"},{"i":22,"n":"第二十二条","txt":"律师事务所及其律师违反本规则的，由司法行政机关、律师协会依照有关规定，给予行政处罚或者行业处分。"},{"i":23,"n":"第二十三条","txt":"本规则自2004年5月1日起施行。"}],"lvshishiwusuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范律师事务所的设立，加强对律师事务所的监督和管理，根据《中华人民共和国律师法》(以下简称《律师法》)和其他有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"律师事务所是律师的执业机构。律师事务所应当依法设立并取得执业许可证。 律师事务所的设立和发展，应当根据国家和地方经济社会发展的需要，实现合理分布、均衡发展。"},{"i":3,"n":"第三条","txt":"律师事务所应当坚持以习近平新时代中国特色社会主义思想为指导，坚持和加强党对律师工作的全面领导，坚定维护以习近平同志为核心的党中央权威和集中统一领导，把拥护中国共产党领导、拥护社会主义法治作为从业的基本要求，增强广大律师走中国特色社会主义法治道路的自觉性和坚定性。 律师事务所应当依法开展业务活动，加强内部管理和对律师执业行为的监督，依法承担相应的法律责任。 任何组织和个人不得非法干预律师事务所的业务活动，不得侵害律师事务所的合法权益。"},{"i":4,"n":"第四条","txt":"律师事务所应当加强党的建设，充分发挥党组织的战斗堡垒作用和党员律师的先锋模范作用。 律师事务所有三名以上正式党员的，应当根据《中国共产党章程》的规定，经上级党组织批准，成立党的基层组织，并按期进行换届。律师事务所正式党员不足三人的，应当通过联合成立党组织、上级党组织选派党建工作指导员等方式开展党的工作，并在条件具备时及时成立党的基层组织。 律师事务所应当建立完善党组织参与律师事务所决策、管理的工作机制，为党组织开展活动、做好工作提供场地、人员和经费等支持。"},{"i":5,"n":"第五条","txt":"司法行政机关依照《律师法》和本办法的规定对律师事务所进行监督、指导。 律师协会依照《律师法》、协会章程和行业规范，对律师事务所实行行业自律。 司法行政机关、律师协会应当结合监督管理职责，加强对律师行业党的建设的指导。"},{"i":6,"n":"第六条","txt":"司法行政机关、律师协会应当建立健全律师事务所表彰奖励制度，根据有关规定设立综合性和单项表彰项目，对为维护人民群众合法权益、促进经济社会发展和国家法治建设作出突出贡献的律师事务所进行表彰奖励。"},{"i":7,"n":"第七条","txt":"律师事务所可以由律师合伙设立、律师个人设立或者由国家出资设立。 合伙律师事务所可以采用普通合伙或者特殊的普通合伙形式设立。"},{"i":8,"n":"第八条","txt":"设立律师事务所应当具备下列基本条件： (一)有自己的名称、住所和章程; (二)有符合《律师法》和本办法规定的律师; (三)设立人应当是具有一定的执业经历并能够专职执业的律师，且在申请设立前三年内未受过停止执业处罚; (四)有符合本办法规定数额的资产。"},{"i":9,"n":"第九条","txt":"设立普通合伙律师事务所，除应当符合本办法第八条规定的条件外，还应当具备下列条件： (一)有书面合伙协议; (二)有三名以上合伙人作为设立人; (三)设立人应当是具有三年以上执业经历并能够专职执业的律师; (四)有人民币三十万元以上的资产。"},{"i":10,"n":"第十条","txt":"设立特殊的普通合伙律师事务所，除应当符合本办法第八条规定的条件外，还应当具备下列条件： (一)有书面合伙协议; (二)有二十名以上合伙人作为设立人; (三)设立人应当是具有三年以上执业经历并能够专职执业的律师; (四)有人民币一千万元以上的资产。"},{"i":11,"n":"第十一条","txt":"设立个人律师事务所，除应当符合本办法第八条规定的条件外，还应当具备下列条件： (一)设立人应当是具有五年以上执业经历并能够专职执业的律师; (二)有人民币十万元以上的资产。"},{"i":12,"n":"第十二条","txt":"国家出资设立的律师事务所，除符合《律师法》规定的一般条件外，应当至少有二名符合《律师法》规定并能够专职执业的律师。 需要国家出资设立律师事务所的，由当地县级司法行政机关筹建，申请设立许可前须经所在地县级人民政府有关部门核拨编制、提供经费保障。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市司法行政机关可以根据本地经济社会发展状况和律师业发展需要，适当调整本办法规定的普通合伙律师事务所、特殊的普通合伙律师事务所和个人律师事务所的设立资产数额，报司法部批准后实施。"},{"i":14,"n":"第十四条","txt":"设立律师事务所，其申请的名称应当符合司法部有关律师事务所名称管理的规定，并应当在申请设立许可前按规定办理名称检索。"},{"i":15,"n":"第十五条","txt":"律师事务所负责人人选，应当在申请设立许可时一并报审核机关核准。 合伙律师事务所的负责人，应当从本所合伙人中经全体合伙人选举产生;国家出资设立的律师事务所的负责人，由本所律师推选，经所在地县级司法行政机关同意。 个人律师事务所设立人是该所的负责人。"},{"i":16,"n":"第十六条","txt":"律师事务所章程应当包括下列内容： (一)律师事务所的名称和住所; (二)律师事务所的宗旨; (三)律师事务所的组织形式; (四)设立资产的数额和来源; (五)律师事务所负责人的职责以及产生、变更程序; (六)律师事务所决策、管理机构的设置、职责; (七)本所律师的权利与义务; (八)律师事务所有关执业、收费、财务、分配等主要管理制度; (九)律师事务所解散的事由、程序以及清算办法; (十)律师事务所章程的解释、修改程序; (十一)律师事务所党组织的设置形式、地位作用、职责权限、参与本所决策、管理的工作机制和党建工作保障措施等; (十二)其他需要载明的事项。 设立合伙律师事务所的，其章程还应当载明合伙人的姓名、出资额及出资方式。 律师事务所章程的内容不得与有关法律、法规、规章相抵触。 律师事务所章程自省、自治区、直辖市司法行政机关作出准予设立律师事务所决定之日起生效。"},{"i":17,"n":"第十七条","txt":"合伙协议应当载明下列内容： (一)合伙人，包括姓名、居住地、身份证号、律师执业经历等; (二)合伙人的出资额及出资方式; (三)合伙人的权利、义务; (四)合伙律师事务所负责人的职责以及产生、变更程序; (五)合伙人会议的职责、议事规则等; (六)合伙人收益分配及债务承担方式; (七)合伙人入伙、退伙及除名的条件和程序; (八)合伙人之间争议的解决方法和程序，违反合伙协议承担的责任; (九)合伙协议的解释、修改程序; (十)其他需要载明的事项。 合伙协议的内容不得与有关法律、法规、规章相抵触。 合伙协议由全体合伙人协商一致并签名，自省、自治区、直辖市司法行政机关作出准予设立律师事务所决定之日起生效。"},{"i":18,"n":"第十八条","txt":"律师事务所的设立许可，由设区的市级或者直辖市的区(县)司法行政机关受理设立申请并进行初审，报省、自治区、直辖市司法行政机关进行审核，作出是否准予设立的决定。"},{"i":19,"n":"第十九条","txt":"申请设立律师事务所，应当向所在地设区的市级或者直辖市的区(县)司法行政机关提交下列材料： (一)设立申请书; (二)律师事务所的名称、章程; (三)设立人的名单、简历、身份证明、律师执业证书，律师事务所负责人人选; (四)住所证明; (五)资产证明。 设立合伙律师事务所，还应当提交合伙协议。 设立国家出资设立的律师事务所，应当提交所在地县级人民政府有关部门出具的核拨编制、提供经费保障的批件。 申请设立许可时，申请人应当如实填报《律师事务所设立申请登记表》。"},{"i":20,"n":"第二十条","txt":"设区的市级或者直辖市的区(县)司法行政机关对申请人提出的设立律师事务所申请，应当根据下列情况分别作出处理： (一)申请材料齐全、符合法定形式的，应当受理; (二)申请材料不齐全或者不符合法定形式的，应当当场或者自收到申请材料之日起五日内一次告知申请人需要补正的全部内容。申请人按要求补正的，予以受理;逾期不告知的，自收到申请材料之日起即为受理; (三)申请事项明显不符合法定条件或者申请人拒绝补正、无法补正有关材料的，不予受理，并向申请人书面说明理由。"},{"i":21,"n":"第二十一条","txt":"受理申请的司法行政机关应当在决定受理之日起二十日内完成对申请材料的审查。 在审查过程中，可以征求拟设立律师事务所所在地县级司法行政机关的意见;对于需要调查核实有关情况的，可以要求申请人提供有关证明材料，也可以委托县级司法行政机关进行核实。 经审查，应当对设立律师事务所的申请是否符合法定条件、材料是否真实齐全出具审查意见，并将审查意见和全部申请材料报送省、自治区、直辖市司法行政机关。"},{"i":22,"n":"第二十二条","txt":"省、自治区、直辖市司法行政机关应当自收到受理申请机关报送的审查意见和全部申请材料之日起十日内予以审核，作出是否准予设立律师事务所的决定。 准予设立的，应当自决定之日起十日内向申请人颁发律师事务所执业许可证。 不准予设立的，应当向申请人书面说明理由。"},{"i":23,"n":"第二十三条","txt":"律师事务所执业许可证分为正本和副本。正本用于办公场所悬挂，副本用于接受查验。正本和副本具有同等的法律效力。 律师事务所执业许可证应当载明的内容、制作的规格、证号编制办法，由司法部规定。执业许可证由司法部统一制作。"},{"i":24,"n":"第二十四条","txt":"律师事务所设立申请人应当在领取执业许可证后的六十日内，按照有关规定刻制印章、开立银行账户、办理税务登记，完成律师事务所开业的各项准备工作，并将刻制的律师事务所公章、财务章印模和开立的银行账户报所在地设区的市级或者直辖市的区(县)司法行政机关备案。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，由作出准予设立律师事务所决定的省、自治区、直辖市司法行政机关撤销原准予设立的决定，收回并注销律师事务所执业许可证： (一)申请人以欺骗、贿赂等不正当手段取得准予设立决定的; (二)对不符合法定条件的申请或者违反法定程序作出准予设立决定的。"},{"i":26,"n":"第二十六条","txt":"律师事务所变更名称、负责人、章程、合伙协议的，应当经所在地设区的市级或者直辖市的区(县)司法行政机关审查后报原审核机关批准。具体办法按律师事务所设立许可程序办理。 律师事务所变更住所、合伙人的，应当自变更之日起十五日内经所在地设区的市级或者直辖市的区(县)司法行政机关报原审核机关备案。"},{"i":27,"n":"第二十七条","txt":"律师事务所跨县、不设区的市、市辖区变更住所，需要相应变更负责对其实施日常监督管理的司法行政机关的，应当在办理备案手续后，由其所在地设区的市级司法行政机关或者直辖市司法行政机关将有关变更情况通知律师事务所迁入地的县级司法行政机关。 律师事务所拟将住所迁移其他省、自治区、直辖市的，应当按注销原律师事务所、设立新的律师事务所的程序办理。"},{"i":28,"n":"第二十八条","txt":"律师事务所变更合伙人，包括吸收新合伙人、合伙人退伙、合伙人因法定事由或者经合伙人会议决议被除名。 新合伙人应当从专职执业的律师中产生，并具有三年以上执业经历，但司法部另有规定的除外。受到六个月以上停止执业处罚的律师，处罚期满未逾三年的，不得担任合伙人。 合伙人退伙、被除名的，律师事务所应当依照法律、本所章程和合伙协议处理相关财产权益、债务承担等事务。 因合伙人变更需要修改合伙协议的，修改后的合伙协议应当按照本办法第二十六条第一款的规定报批。"},{"i":29,"n":"第二十九条","txt":"律师事务所变更组织形式的，应当在自行依法处理好业务衔接、人员安排、资产处置、债务承担等事务并对章程、合伙协议作出相应修改后，方可按照本办法第二十六条第一款的规定申请变更。"},{"i":30,"n":"第三十条","txt":"律师事务所因分立、合并，需要对原律师事务所进行变更或者注销原律师事务所、设立新的律师事务所的，应当在自行依法处理好相关律师事务所的业务衔接、人员安排、资产处置、债务承担等事务后，提交分立协议或者合并协议等申请材料，按照本办法的相关规定办理。"},{"i":31,"n":"第三十一条","txt":"律师事务所有下列情形之一的，应当终止： (一)不能保持法定设立条件，经限期整改仍不符合条件的; (二)执业许可证被依法吊销的; (三)自行决定解散的; (四)法律、行政法规规定应当终止的其他情形。 律师事务所在取得设立许可后，六个月内未开业或者无正当理由停止业务活动满一年的，视为自行停办，应当终止。 律师事务所在受到停业整顿处罚期限未满前，不得自行决定解散。"},{"i":32,"n":"第三十二条","txt":"律师事务所在终止事由发生后，不得受理新的业务。 律师事务所在终止事由发生后，应当向社会公告，依照有关规定进行清算，依法处置资产分割、债务清偿等事务。 律师事务所应当在清算结束后十五日内向所在地设区的市级或者直辖市的区(县)司法行政机关提交注销申请书、清算报告、本所执业许可证以及其他有关材料，由其出具审查意见后连同全部注销申请材料报原审核机关审核，办理注销手续。 律师事务所拒不履行公告、清算义务的，由设区的市级或者直辖市的区(县)司法行政机关向社会公告后，可以直接报原审核机关办理注销手续。律师事务所被注销后的债权、债务由律师事务所的设立人、合伙人承担。 律师事务所被注销的，其业务档案、财务账簿、本所印章的移管、处置，按照有关规定办理。"},{"i":33,"n":"第三十三条","txt":"成立三年以上并具有二十名以上执业律师的合伙律师事务所，根据业务发展需要，可以在本所所在地的市、县以外的地方设立分所。设在直辖市、设区的市的合伙律师事务所也可以在本所所在城区以外的区、县设立分所。 律师事务所及其分所受到停业整顿处罚期限未满的，该所不得申请设立分所;律师事务所的分所受到吊销执业许可证处罚的，该所自分所受到处罚之日起二年内不得申请设立分所。"},{"i":34,"n":"第三十四条","txt":"分所应当具备下列条件： (一)有符合《律师事务所名称管理办法》规定的名称; (二)有自己的住所; (三)有三名以上律师事务所派驻的专职律师; (四)有人民币三十万元以上的资产; (五)分所负责人应当是具有三年以上的执业经历并能够专职执业，且在担任负责人前三年内未受过停止执业处罚的律师。 律师事务所到经济欠发达的市、县设立分所的，前款规定的派驻律师条件可以降至一至二名;资产条件可以降至人民币十万元。具体适用地区由省、自治区、直辖市司法行政机关确定。 省、自治区、直辖市司法行政机关根据本地经济社会发展和律师业发展状况，需要提高第一款第(三)、(四)项规定的条件的，按照本办法第十三条规定的程序办理。"},{"i":35,"n":"第三十五条","txt":"律师事务所申请设立分所，应当提交下列材料： (一)设立分所申请书; (二)本所基本情况，本所设立许可机关为其出具的符合《律师法》第十九条和本办法第三十三条规定条件的证明; (三)本所执业许可证复印件，本所章程和合伙协议; (四)拟在分所执业的律师的名单、简历、身份证明和律师执业证书复印件; (五)拟任分所负责人的人选及基本情况，该人选执业许可机关为其出具的符合本办法第三十四条第一款第五项规定条件的证明; (六)分所的名称，分所住所证明和资产证明; (七)本所制定的分所管理办法。 申请设立分所时，申请人应当如实填报《律师事务所分所设立申请登记表》。"},{"i":36,"n":"第三十六条","txt":"律师事务所申请设立分所，由拟设立分所所在地设区的市级或者直辖市区(县)司法行政机关受理并进行初审，报省、自治区、直辖市司法行政机关审核，决定是否准予设立分所。具体程序按照本办法第二十条、第二十一条、第二十二条的规定办理。 准予设立分所的，由设立许可机关向申请人颁发律师事务所分所执业许可证。"},{"i":37,"n":"第三十七条","txt":"分所律师除由律师事务所派驻外，可以依照《律师执业管理办法》的规定面向社会聘用律师。 派驻分所律师，参照《律师执业管理办法》有关律师变更执业机构的规定办理，由准予设立分所的省、自治区、直辖市司法行政机关予以换发执业证书，原执业证书交回原颁证机关;分所聘用律师，依照《律师执业管理办法》规定的申请律师执业许可或者变更执业机构的程序办理。"},{"i":38,"n":"第三十八条","txt":"律师事务所决定变更分所负责人的，应当经分所所在地设区的市级或者直辖市区(县)司法行政机关报分所设立许可机关批准;变更派驻分所律师的，参照《律师执业管理办法》有关律师变更执业机构的规定办理。 分所变更住所的，应当自变更之日起十五日内，经分所所在地设区的市级或者直辖市区(县)司法行政机关报分所设立许可机关备案。 律师事务所变更名称的，应当自名称获准变更之日起三十日内，经分所所在地设区的市级或者直辖市区(县)司法行政机关向分所设立许可机关申请变更分所名称。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，分所应当终止： (一)律师事务所依法终止的; (二)律师事务所不能保持《律师法》和本办法规定设立分所的条件，经限期整改仍不符合条件的; (三)分所不能保持本办法规定的设立条件，经限期整改仍不符合条件的; (四)分所在取得设立许可后六个月内未开业或者无正当理由停止业务活动满一年的; (五)律师事务所决定停办分所的; (六)分所执业许可证被依法吊销的; (七)法律、行政法规规定应当终止的其他情形。 分所终止的，由分所设立许可机关注销分所执业许可证。分所终止的有关事宜按照本办法第三十二条的规定办理。"},{"i":40,"n":"第四十条","txt":"律师事务所应当建立健全执业管理和其他各项内部管理制度，规范本所律师执业行为，履行监管职责，对本所律师遵守法律、法规、规章及行业规范，遵守职业道德和执业纪律的情况进行监督，发现问题及时予以纠正。"},{"i":41,"n":"第四十一条","txt":"律师事务所应当保障本所律师和辅助人员享有下列权利： (一)获得本所提供的必要工作条件和劳动保障; (二)获得劳动报酬及享受有关福利待遇; (三)向本所提出意见和建议; (四)法律、法规、规章及行业规范规定的其他权利。"},{"i":42,"n":"第四十二条","txt":"律师事务所应当监督本所律师和辅助人员履行下列义务： (一)遵守宪法和法律，遵守职业道德和执业纪律; (二)依法、诚信、规范执业; (三)接受本所监督管理，遵守本所章程和规章制度，维护本所的形象和声誉; (四)法律、法规、规章及行业规范规定的其他义务。"},{"i":43,"n":"第四十三条","txt":"律师事务所应当建立违规律师辞退和除名制度，对违法违规执业、违反本所章程及管理制度或者年度考核不称职的律师，可以将其辞退或者经合伙人会议通过将其除名，有关处理结果报所在地县级司法行政机关和律师协会备案。"},{"i":44,"n":"第四十四条","txt":"律师事务所应当在法定业务范围内开展业务活动，不得以独资、与他人合资或者委托持股方式兴办企业，并委派律师担任企业法定代表人、总经理职务，不得从事与法律服务无关的其他经营性活动。"},{"i":45,"n":"第四十五条","txt":"律师事务所应当与其他律师事务所公平竞争，不得以诋毁其他律师事务所、律师或者支付介绍费等不正当手段承揽业务。"},{"i":46,"n":"第四十六条","txt":"律师承办业务，由律师事务所统一接受委托，与委托人签订书面委托合同。 律师事务所受理业务，应当进行利益冲突审查，不得违反规定受理与本所承办业务及其委托人有利益冲突的业务。"},{"i":47,"n":"第四十七条","txt":"律师事务所应当按照有关规定统一收取服务费用并如实入账，建立健全收费管理制度，及时查处有关违规收费的举报和投诉，不得在实行政府指导价的业务领域违反规定标准收取费用，或者违反风险代理管理规定收取费用。 律师事务所应当按照规定建立健全财务管理制度，建立和实行合理的分配制度及激励机制。 律师事务所应当依法纳税。"},{"i":48,"n":"第四十八条","txt":"律师事务所应当依法履行法律援助义务，及时安排本所律师承办法律援助案件，为办理法律援助案件提供条件和便利，无正当理由不得拒绝接受法律援助机构指派的法律援助案件。"},{"i":49,"n":"第四十九条","txt":"律师事务所应当建立健全重大疑难案件的请示报告、集体研究和检查督导制度，规范受理程序，指导监督律师依法办理重大疑难案件。"},{"i":50,"n":"第五十条","txt":"律师事务所应当依法履行管理职责，教育管理本所律师依法、规范承办业务，加强对本所律师执业活动的监督管理，不得放任、纵容本所律师有下列行为： (一)采取煽动、教唆和组织当事人或者其他人员到司法机关或者其他国家机关静坐、举牌、打横幅、喊口号、声援、围观等扰乱公共秩序、危害公共安全的非法手段，聚众滋事，制造影响，向有关部门施加压力; (二)对本人或者其他律师正在办理的案件进行歪曲、有误导性的宣传和评论，恶意炒作案件; (三)以串联组团、联署签名、发表公开信、组织网上聚集、声援等方式或者借个案研讨之名，制造舆论压力，攻击、诋毁司法机关和司法制度; (四)无正当理由，拒不按照人民法院通知出庭参与诉讼，或者违反法庭规则，擅自退庭; (五)聚众哄闹、冲击法庭，侮辱、诽谤、威胁、殴打司法工作人员或者诉讼参与人，否定国家认定的邪教组织的性质，或者有其他严重扰乱法庭秩序的行为; (六)发表、散布否定宪法确立"},{"i":51,"n":"第五十一条","txt":"合伙律师事务所和国家出资设立的律师事务所应当按照规定为聘用的律师和辅助人员办理失业、养老、医疗等社会保险。 个人律师事务所聘用律师和辅助人员的，应当按前款规定为其办理社会保险。"},{"i":52,"n":"第五十二条","txt":"律师事务所应当按照规定，建立执业风险、事业发展、社会保障等基金。 律师参加执业责任保险的具体办法另行规定。"},{"i":53,"n":"第五十三条","txt":"律师违法执业或者因过错给当事人造成损失的，由其所在的律师事务所承担赔偿责任。律师事务所赔偿后，可以向有故意或者重大过失行为的律师追偿。 普通合伙律师事务所的合伙人对律师事务所的债务承担无限连带责任。特殊的普通合伙律师事务所一个合伙人或者数个合伙人在执业活动中因故意或者重大过失造成律师事务所债务的，应当承担无限责任或者无限连带责任，其他合伙人以其在律师事务所中的财产份额为限承担责任;合伙人在执业活动中非因故意或者重大过失造成的律师事务所债务，由全体合伙人承担无限连带责任。个人律师事务所的设立人对律师事务所的债务承担无限责任。国家出资设立的律师事务所以其全部资产对其债务承担责任。"},{"i":54,"n":"第五十四条","txt":"律师事务所的负责人负责对律师事务所的业务活动和内部事务进行管理，对外代表律师事务所，依法承担对律师事务所违法行为的管理责任。 合伙人会议或者律师会议为合伙律师事务所或者国家出资设立的律师事务所的决策机构;个人律师事务所的重大决策应当充分听取聘用律师的意见。 律师事务所根据本所章程可以设立相关管理机构或者配备专职管理人员，协助本所负责人开展日常管理工作。"},{"i":55,"n":"第五十五条","txt":"律师事务所应当加强对本所律师的职业道德和执业纪律教育，组织开展业务学习和经验交流活动，为律师参加业务培训和继续教育提供条件。"},{"i":56,"n":"第五十六条","txt":"律师事务所应当建立律师表彰奖励制度，对依法、诚信、规范执业表现突出的律师予以表彰奖励。"},{"i":57,"n":"第五十七条","txt":"律师事务所应当建立投诉查处制度，及时查处、纠正本所律师在执业活动中的违法违规行为，调处在执业中与委托人之间的纠纷;认为需要对被投诉律师给予行政处罚或者行业惩戒的，应当及时向所在地县级司法行政机关或者律师协会报告。 已担任合伙人的律师受到六个月以上停止执业处罚的，自处罚决定生效之日起至处罚期满后三年内，不得担任合伙人。"},{"i":58,"n":"第五十八条","txt":"律师事务所应当建立律师执业年度考核制度，按照规定对本所律师的执业表现和遵守职业道德、执业纪律的情况进行考核，评定等次，实施奖惩，建立律师执业档案和诚信档案。"},{"i":59,"n":"第五十九条","txt":"律师事务所应当于每年的一季度经所在地县级司法行政机关向设区的市级司法行政机关提交上一年度本所执业情况报告和律师执业考核结果，直辖市的律师事务所的执业情况报告和律师执业考核结果直接向所在地区(县)司法行政机关提交，接受司法行政机关的年度检查考核。具体年度检查考核办法，由司法部规定。"},{"i":60,"n":"第六十条","txt":"律师事务所应当按照规定建立健全档案管理制度，对所承办业务的案卷和有关资料及时立卷归档，妥善保管。"},{"i":61,"n":"第六十一条","txt":"律师事务所应当通过本所网站等，公开本所律师和辅助人员的基本信息和奖惩情况。"},{"i":62,"n":"第六十二条","txt":"律师事务所应当妥善保管、依法使用本所执业许可证，不得变造、出借、出租。如有遗失或者损毁的，应当及时报告所在地县级司法行政机关，经所在地设区的市级或者直辖市区(县)司法行政机关向原审核机关申请补发或者换发。律师事务所执业许可证遗失的，应当在当地报刊上刊登遗失声明。 律师事务所被撤销许可、受到吊销执业许可证处罚的，由所在地县级司法行政机关收缴其执业许可证。 律师事务所受到停业整顿处罚的，应当自处罚决定生效后至处罚期限届满前，将执业许可证缴存其所在地县级司法行政机关。"},{"i":63,"n":"第六十三条","txt":"律师事务所应当加强对分所执业和管理活动的监督，履行下列管理职责： (一)任免分所负责人; (二)决定派驻分所律师，核准分所聘用律师人选; (三)审核、批准分所的内部管理制度; (四)审核、批准分所的年度工作计划、年度工作总结; (五)指导、监督分所的执业活动及重大法律事务的办理; (六)指导、监督分所的财务活动，审核、批准分所的分配方案和年度财务预算、决算; (七)决定分所重要事项的变更、分所停办和分所资产的处置; (八)本所规定的其他由律师事务所决定的事项。 律师事务所应当依法对其分所的债务承担责任。"},{"i":64,"n":"第六十四条","txt":"县级司法行政机关对本行政区域内的律师事务所的执业活动进行日常监督管理，履行下列职责： (一)监督律师事务所在开展业务活动过程中遵守法律、法规、规章的情况; (二)监督律师事务所执业和内部管理制度的建立和实施情况; (三)监督律师事务所保持法定设立条件以及变更报批或者备案的执行情况; (四)监督律师事务所进行清算、申请注销的情况; (五)监督律师事务所开展律师执业年度考核和上报年度执业总结的情况; (六)受理对律师事务所的举报和投诉; (七)监督律师事务所履行行政处罚和实行整改的情况; (八)司法部和省、自治区、直辖市司法行政机关规定的其他职责。 县级司法行政机关在开展日常监督管理过程中，对发现、查实的律师事务所在执业和内部管理方面存在的问题，应当对律师事务所负责人或者有关律师进行警示谈话，责令改正，并对其整改情况进行监督;对律师事务所的违法行为认为依法应当给予行政处罚的，应当向上一级司"},{"i":65,"n":"第六十五条","txt":"设区的市级司法行政机关履行下列监督管理职责： (一)掌握本行政区域律师事务所的执业活动和组织建设、队伍建设、制度建设的情况，制定加强律师工作的措施和办法; (二)指导、监督下一级司法行政机关的日常监督管理工作，组织开展对律师事务所的专项监督检查工作，指导对律师事务所重大投诉案件的查处工作; (三)对律师事务所进行表彰; (四)依法定职权对律师事务所的违法行为实施行政处罚;对依法应当给予吊销执业许可证处罚的，向上一级司法行政机关提出处罚建议; (五)组织开展对律师事务所的年度检查考核工作; (六)受理、审查律师事务所设立、变更、设立分所、注销申请事项; (七)建立律师事务所执业档案，负责有关律师事务所的许可、变更、终止及执业档案信息的公开工作; (八)法律、法规、规章规定的其他职责。 直辖市的区(县)司法行政机关负有前款规定的有关职责。"},{"i":66,"n":"第六十六条","txt":"省、自治区、直辖市司法行政机关履行下列监督管理职责： (一)制定本行政区域律师事务所的发展规划和有关政策，制定律师事务所管理的规范性文件; (二)掌握本行政区域律师事务所组织建设、队伍建设、制度建设和业务开展情况; (三)监督、指导下级司法行政机关的监督管理工作，指导对律师事务所的专项监督检查和年度检查考核工作; (四)组织对律师事务所的表彰活动; (五)依法对律师事务所的严重违法行为实施吊销执业许可证的处罚，监督下一级司法行政机关的行政处罚工作，办理有关行政复议和申诉案件; (六)办理律师事务所设立核准、变更核准或者备案、设立分所核准及执业许可证注销事项; (七)负责本行政区域律师事务所有关重大信息的公开工作; (八)法律、法规规定的其他职责。"},{"i":67,"n":"第六十七条","txt":"律师事务所违反本办法有关规定的，依照《律师法》和有关法规、规章规定追究法律责任。 律师事务所违反本办法第四十四条、第四十五条、第四十七条、第四十八条、第五十条规定的，司法行政机关应当依照《律师法》第五十条相关规定予以行政处罚。"},{"i":68,"n":"第六十八条","txt":"律师事务所管理分所的情况，应当纳入司法行政机关对该所年度检查考核的内容;律师事务所对分所及其律师疏于管理、造成严重后果的，由该所所在地司法行政机关依法实施行政处罚。 律师事务所分所及其律师，应当接受分所所在地司法行政机关的监督、指导，接受分所所在地律师协会的行业管理。"},{"i":69,"n":"第六十九条","txt":"跨省、自治区、直辖市设立分所的，分所所在地的省、自治区、直辖市司法行政机关应当将分所设立、变更、终止以及年度考核、行政处罚等情况及时抄送设立分所的律师事务所所在的省、自治区、直辖市司法行政机关。"},{"i":70,"n":"第七十条","txt":"各级司法行政机关及其工作人员对律师事务所实施监督管理，不得妨碍律师事务所依法执业，不得侵害律师事务所的合法权益，不得索取或者收受律师事务所及其律师的财物，不得谋取其他利益。"},{"i":71,"n":"第七十一条","txt":"司法行政机关应当加强对实施许可和管理活动的层级监督，按照规定建立有关工作的统计、请示、报告、督办等制度。 负责律师事务所许可实施、年度检查考核或者奖励、处罚的司法行政机关，应当及时将有关许可决定、考核结果或者奖惩情况通报下级司法行政机关，并报送上一级司法行政机关。"},{"i":72,"n":"第七十二条","txt":"司法行政机关、律师协会应当建立律师和律师事务所信息管理系统，按照有关规定向社会公开律师事务所基本信息和年度检查考核结果、奖惩情况。"},{"i":73,"n":"第七十三条","txt":"司法行政机关应当加强对律师协会的指导、监督，支持律师协会依照《律师法》和协会章程、行业规范对律师事务所实行行业自律，建立健全行政管理与行业自律相结合的协调、协作机制。"},{"i":74,"n":"第七十四条","txt":"各级司法行政机关应当定期将本行政区域律师事务所的组织、队伍、业务情况的统计资料、年度管理工作总结报送上一级司法行政机关。"},{"i":75,"n":"第七十五条","txt":"人民法院、人民检察院、公安机关、国家安全机关或者其他有关部门对律师事务所的违法违规行为向司法行政机关、律师协会提出予以处罚、处分建议的，司法行政机关、律师协会应当自作出处理决定之日起7日内通报建议机关。"},{"i":76,"n":"第七十六条","txt":"司法行政机关工作人员在律师事务所设立许可和实施监督管理活动中，滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任;尚不构成犯罪的，依法给予行政处分。"},{"i":77,"n":"第七十七条","txt":"军队法律顾问处的管理，按照国务院和中央军事委员会有关规定执行。"},{"i":78,"n":"第七十八条","txt":"本办法自2016年11月1日起施行。此前司法部制定的有关律师事务所管理的规章、规范性文件与本办法相抵触的，以本办法为准。"}],"lvshihelvshishiwusuozhiyezhengshuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范和加强律师执业证书和律师事务所执业许可证书(以下统称“执业证书”)的管理，根据《中华人民共和国律师法》的有关规定，结合律师工作管理实际，制定本办法。"},{"i":2,"n":"第二条","txt":"律师执业证书是律师依法获准执业的有效证件。 律师事务所执业证书是律师事务所依法获准设立并执业的有效证件。"},{"i":3,"n":"第三条","txt":"律师执业证书包括适用于专职、兼职律师的“律师执业证”和适用于香港、澳门、台湾居民在内地(大陆)从事律师职业的“律师执业证”两种。 律师事务所执业证书包括律师事务所执业许可证书、律师事务所分所执业许可证书。律师事务所(含律师事务所分所，下同)执业证书分为正本和副本，正本和副本具有同等的法律效力。"},{"i":4,"n":"第四条","txt":"律师和律师事务所执业证书应当载明的内容、制作的规格式样、证号编制办法由司法部规定。执业证书由司法部统一制作。 律师和律师事务所执业证书制作时印制执业证书流水号。省、自治区、直辖市司法行政机关颁发、注销或者换发、补发执业证书，应当登记执业证书流水号。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市司法行政机关领取空白执业证书，应当于每年年初向司法部提出申领报告，并提交《律师和律师事务所执业证书发放使用情况统计表》及相关登记表。"},{"i":6,"n":"第六条","txt":"省、自治区、直辖市司法行政机关应当自作出准予律师执业决定或者准予律师事务所设立决定之日起十日内，向申请人颁发执业证书。 执业证书应当加盖发证机关印章。"},{"i":7,"n":"第七条","txt":"律师、律师事务所应当妥善保管执业证书，不得变造、涂改、抵押、出借、出租和故意损毁。"},{"i":8,"n":"第八条","txt":"律师、律师事务所应当依法使用执业证书。律师执业应当出示律师执业证书。律师事务所应当将执业证书正本悬挂于执业场所的醒目位置；执业证书副本用于接受查验。"},{"i":9,"n":"第九条","txt":"律师申请变更执业机构的，变更审核机关应当自作出准予变更决定之日起十日内为申请人换发律师执业证书。 律师事务所变更名称、负责人、组织形式、住所等事项的，变更审核或者备案机关应当自作出准予变更决定或者备案之日起十日内，为律师事务所办理执业证书变更事项登记或者换发执业证书。"},{"i":10,"n":"第十条","txt":"律师、律师事务所因执业证书损毁等原因，导致执业证书无法使用的，应当申请换发执业证书。 换发执业证书，应当向设区的市级或者直辖市的区(县)司法行政机关提出申请，由其在收到申请之日起五日内完成审查，并上报原发证机关。原发证机关应当自收到申请之日起十日内完成审查，符合规定的，为申请人换发执业证书；不符合规定的，不予换发执业证书，并向申请人说明理由。 准予换发执业证书的，申请人在领取新的执业证书时，应当将原执业证书交回原发证机关。"},{"i":11,"n":"第十一条","txt":"执业证书遗失的，律师或者律师事务所应当及时报告所在地县(区)司法行政机关，并在省级以上报刊或者发证机关指定网站上刊登遗失声明。遗失声明应当载明遗失的执业证书的种类、持证人姓名(名称)、执业证号和执业证书流水号。 律师、律师事务所申请补发执业证书的，按照本办法第十条第二款规定的程序办理。申请时应当同时提交已刊登遗失声明的证明材料。"},{"i":12,"n":"第十二条","txt":"设区的市级或者直辖市的区(县)司法行政机关于每年完成对律师事务所年度检查考核后，应当在律师事务所和律师执业证书相应栏目内填写考核年度、考核结果、考核(备案)机关、考核(备案)日期；在律师事务所执业证书副本上加盖“律师事务所年度检查考核”专用章，在律师执业证书上加盖“律师年度考核备案”专用章。"},{"i":13,"n":"第十三条","txt":"律师受到停止执业处罚、律师事务所受到停业整顿处罚的，由作出处罚决定的司法行政机关或者由其委托的下一级司法行政机关在宣布或者送达处罚决定时扣缴被处罚律师、律师事务所的执业证书。处罚期满予以发还。"},{"i":14,"n":"第十四条","txt":"司法行政机关依法对律师事务所违法行为给予行政处罚的，作出处罚决定的司法行政机关应当自决定之日起十五日内，将处罚的内容登记在该律师事务所执业证书副本上。"},{"i":15,"n":"第十五条","txt":"律师、律师事务所被依法撤销执业许可或者被吊销执业证书的，由作出撤销或者处罚决定的司法行政机关或者由其委托的下一级司法行政机关在宣布或者送达撤销或者处罚决定时收缴该律师、律师事务所的执业证书，并依照规定程序予以注销。 律师、律师事务所因其他原因终止执业，需要注销其执业证书的，该律师、律师事务所应当将执业证书上交其所在地县(区)司法行政机关，由其按照规定程序交原发证机关予以注销。 律师、律师事务所被撤销执业许可、被吊销执业证书或者因其他原因终止执业，拒不上交执业证书的，由原发证机关公告注销其执业证书。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市司法行政机关应当及时将注销、作废的执业证书销毁。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市司法行政机关应当将颁发、注销、换发、补发、作废和销毁执业证书的情况按年度登记造册，填制执业证书发放使用情况统计表，报司法部备案。"},{"i":18,"n":"第十八条","txt":"律师、律师事务所对执业证书保管不善或者违法使用执业证书的，由所在地县(区)司法行政机关给予批评教育，责令改正；情节严重的，由设区的市级或者直辖市的区(县)司法行政机关依法给予相应的处罚。"},{"i":19,"n":"第十九条","txt":"司法行政机关工作人员在发放、管理执业证书的工作中，违反《律师法》、《律师执业管理办法》、《律师事务所管理办法》和本办法规定，滥用职权、玩忽职守的，应当依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"司法行政机关应当建立律师和律师事务所执业证书信息管理系统，根据执业证书颁发、注销及其他有关变更情况适时进行更新，为公民、法人、其他社会组织和国家机关提供有关执业证书信息查询服务。"},{"i":21,"n":"第二十一条","txt":"对公职律师、公司律师、法律援助律师的律师工作证的管理，参照本办法执行。 军队律师工作证的管理办法，另行制定。"},{"i":22,"n":"第二十二条","txt":"本办法自发布之日起施行。"}],"lvshihelvshishiwusuoweifaxingweichufabanfa":[{"i":1,"n":"第一条","txt":"为了加强对律师、律师事务所执业活动的监督，规范律师执业行为，维护正常的法律服务秩序，根据《中华人民共和国律师法》(以下简称《律师法》)、《中华人民共和国行政处罚法》(以下简称《行政处罚法》)的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"律师、律师事务所有违法行为，应当给予行政处罚的，由司法行政机关依照《律师法》、《行政处罚法》和有关法律、法规、规章以及本办法的规定实施行政处罚。"},{"i":3,"n":"第三条","txt":"司法行政机关实施行政处罚，应当遵循公正、公开的原则；应当以事实为依据，与违法行为的性质、情节以及社会危害程度相当；应当坚持处罚与教育相结合，教育引导律师、律师事务所依法执业，恪守职业道德和执业纪律。"},{"i":4,"n":"第四条","txt":"司法行政机关应当建立健全对行政处罚的监督制度。上一级司法行政机关应当加强对下一级司法行政机关实施行政处罚的监督和指导，发现行政处罚违法、不当的，应当及时责令纠正。 司法行政机关工作人员在实施行政处罚活动中，有违法违纪行为的，应当依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，属于《律师法》第四十七条第一项规定的律师“同时在两个以上律师事务所执业的”违法行为： (一)在律师事务所执业的同时又在其他律师事务所或者社会法律服务机构执业的； (二)在获准变更执业机构前以拟变更律师事务所律师的名义承办业务，或者在获准变更后仍以原所在律师事务所律师的名义承办业务的。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，属于《律师法》第四十七条第二项规定的律师“以不正当手段承揽业务的”违法行为： (一)以误导、利诱、威胁或者作虚假承诺等方式承揽业务的； (二)以支付介绍费、给予回扣、许诺提供利益等方式承揽业务的； (三)以对本人及所在律师事务所进行不真实、不适当宣传或者诋毁其他律师、律师事务所声誉等方式承揽业务的； (四)在律师事务所住所以外设立办公室、接待室承揽业务的。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，属于《律师法》第四十七条第三项规定的律师“在同一案件中为双方当事人担任代理人，或者代理与本人及其近亲属有利益冲突的法律事务的”违法行为： (一)在同一民事诉讼、行政诉讼或者非诉讼法律事务中同时为有利益冲突的当事人担任代理人或者提供相关法律服务的； (二)在同一刑事案件中同时为被告人和被害人担任辩护人、代理人，或者同时为二名以上的犯罪嫌疑人、被告人担任辩护人的； (三)担任法律顾问期间，为与顾问单位有利益冲突的当事人提供法律服务的； (四)曾担任法官、检察官的律师，以代理人、辩护人的身份承办原任职法院、检察院办理过的案件的； (五)曾经担任仲裁员或者仍在担任仲裁员的律师，以代理人身份承办本人原任职或者现任职的仲裁机构办理的案件的。"},{"i":8,"n":"第八条","txt":"曾经担任法官、检察官的律师，从人民法院、人民检察院离任后二年内，担任诉讼代理人、辩护人或者以其他方式参与所在律师事务所承办的诉讼法律事务的，属于《律师法》第四十七条第四项规定的“从人民法院、人民检察院离任后二年内担任诉讼代理人或者辩护人的”违法行为。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，属于《律师法》第四十七条第五项规定的律师“拒绝履行法律援助义务的”违法行为： (一)无正当理由拒绝接受律师事务所或者法律援助机构指派的法律援助案件的； (二)接受指派后，懈怠履行或者擅自停止履行法律援助职责的。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，属于《律师法》第四十八条第一项规定的律师“私自接受委托、收取费用，接受委托人财物或者其他利益的”违法行为： (一)违反统一接受委托规定或者在被处以停止执业期间，私自接受委托，承办法律事务的； (二)违反收费管理规定，私自收取、使用、侵占律师服务费以及律师异地办案差旅费用的； (三)在律师事务所统一收费外又向委托人索要其他费用、财物或者获取其他利益的； (四)向法律援助受援人索要费用或者接受受援人的财物或者其他利益的。"},{"i":11,"n":"第十一条","txt":"律师接受委托后，除有下列情形之外，拒绝辩护或者代理，不按时出庭参加诉讼或者仲裁的，属于《律师法》第四十八条第二项规定的违法行为： (一)委托事项违法，或者委托人利用律师提供的法律服务从事违法活动的； (二)委托人故意隐瞒与案件有关的重要事实或者提供虚假、伪造的证据材料的； (三)委托人不履行委托合同约定义务的； (四)律师因患严重疾病或者受到停止执业以上行政处罚的； (五)其他依法可以拒绝辩护、代理的。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，属于《律师法》第四十八条第三项规定的律师“利用提供法律服务的便利牟取当事人争议的权益的”违法行为： (一)采用诱导、欺骗、胁迫、敲诈等手段获取当事人与他人争议的财物、权益的； (二)指使、诱导当事人将争议的财物、权益转让、出售、租赁给他人，并从中获取利益的。"},{"i":13,"n":"第十三条","txt":"律师未经委托人或者其他当事人的授权或者同意，在承办案件的过程中或者结束后，擅自披露、散布在执业中知悉的委托人或者其他当事人的商业秘密、个人隐私或者其他不愿泄露的情况和信息的，属于《律师法》第四十八条第四项规定的“泄露商业秘密或者个人隐私的”违法行为。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，属于《律师法》第四十九条第一项规定的律师“违反规定会见法官、检察官、仲裁员以及其他有关工作人员，或者以其他不正当方式影响依法办理案件的”违法行为： (一)在承办代理、辩护业务期间，以影响案件办理结果为目的，在非工作时间、非工作场所会见法官、检察官、仲裁员或者其他有关工作人员的； (二)利用与法官、检察官、仲裁员或者其他有关工作人员的特殊关系，影响依法办理案件的； (三)以对案件进行歪曲、不实、有误导性的宣传或者诋毁有关办案机关和工作人员以及对方当事人声誉等方式，影响依法办理案件的。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，属于《律师法》第四十九条第二项规定的律师“向法官、检察官、仲裁员以及其他有关工作人员行贿，介绍贿赂或者指使、诱导当事人行贿的”违法行为： (一)利用承办案件的法官、检察官、仲裁员以及其他工作人员或者其近亲属举办婚丧喜庆事宜等时机，以向其馈赠礼品、金钱、有价证券等方式行贿的； (二)以装修住宅、报销个人费用、资助旅游娱乐等方式向法官、检察官、仲裁员以及其他工作人员行贿的； (三)以提供交通工具、通讯工具、住房或者其他物品等方式向法官、检察官、仲裁员以及其他工作人员行贿的； (四)以影响案件办理结果为目的，直接向法官、检察官、仲裁员以及其他工作人员行贿、介绍贿赂或者指使、诱导当事人行贿的。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，属于《律师法》第四十九条第三项规定的律师“向司法行政部门提供虚假材料或者有其他弄虚作假行为的”违法行为： (一)在司法行政机关实施检查、监督工作中，向其隐瞒真实情况，拒不提供或者提供不实、虚假材料，或者隐匿、毁灭、伪造证据材料的； (二)在参加律师执业年度考核、执业评价、评先创优活动中，提供不实、虚假、伪造的材料或者有其他弄虚作假行为的； (三)在申请变更执业机构、办理执业终止、注销等手续时，提供不实、虚假、伪造的材料的。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，属于《律师法》第四十九条第四项规定的律师“故意提供虚假证据或者威胁、利诱他人提供虚假证据，妨碍对方当事人合法取得证据的”违法行为： (一)故意向司法机关、行政机关或者仲裁机构提交虚假证据，或者指使、威胁、利诱他人提供虚假证据的； (二)指示或者帮助委托人或者他人伪造、隐匿、毁灭证据，指使或者帮助犯罪嫌疑人、被告人串供，威胁、利诱证人不作证或者作伪证的； (三)妨碍对方当事人及其代理人、辩护人合法取证的，或者阻止他人向案件承办机关或者对方当事人提供证据的。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，属于《律师法》第四十九条第五项规定的律师“接受对方当事人财物或者其他利益，与对方当事人或者第三人恶意串通，侵害委托人权益的”违法行为： (一)向对方当事人或者第三人提供不利于委托人的信息或者证据材料的； (二)与对方当事人或者第三人恶意串通、暗中配合，妨碍委托人合法行使权利的； (三)接受对方当事人财物或者其他利益，故意延误、懈怠或者不依法履行代理、辩护职责，给委托人及委托事项的办理造成不利影响和损失的。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，属于《律师法》第四十九条第六项规定的律师“扰乱法庭、仲裁庭秩序，干扰诉讼、仲裁活动的正常进行的”违法行为： (一)在法庭、仲裁庭上发表或者指使、诱导委托人发表扰乱诉讼、仲裁活动正常进行的言论的； (二)阻止委托人或者其他诉讼参与人出庭，致使诉讼、仲裁活动不能正常进行的； (三)煽动、教唆他人扰乱法庭、仲裁庭秩序的； (四)无正当理由，当庭拒绝辩护、代理，拒绝签收司法文书或者拒绝在有关诉讼文书上签署意见的。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，属于《律师法》第四十九条第七项规定的律师“煽动、教唆当事人采取扰乱公共秩序、危害公共安全等非法手段解决争议的”违法行为： (一)煽动、教唆当事人采取非法集会、游行示威，聚众扰乱公共场所秩序、交通秩序，围堵、冲击国家机关等非法手段表达诉求，妨害国家机关及其工作人员依法履行职责，抗拒执法活动或者判决执行的； (二)利用媒体或者其他方式，煽动、教唆当事人以扰乱公共秩序、危害公共安全等手段干扰诉讼、仲裁及行政执法活动正常进行的。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，属于《律师法》第四十九条第八项规定的律师“发表危害国家安全、恶意诽谤他人、严重扰乱法庭秩序的言论的”违法行为： (一)在承办代理、辩护业务期间，发表、散布危害国家安全，恶意诽谤法官、检察官、仲裁员及对方当事人、第三人，严重扰乱法庭秩序的言论的； (二)在执业期间，发表、制作、传播危害国家安全的言论、信息、音像制品或者支持、参与、实施以危害国家安全为目的活动的。"},{"i":22,"n":"第二十二条","txt":"律师违反保密义务规定，故意或者过失泄露在执业中知悉的国家秘密的，属于《律师法》第四十九条第九项规定的“泄露国家秘密的”违法行为。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，属于《律师法》第五十条第一项规定的律师事务所“违反规定接受委托、收取费用的”违法行为： (一)违反规定不以律师事务所名义统一接受委托、统一收取律师服务费和律师异地办案差旅费，不向委托人出具有效收费凭证的； (二)向委托人索要或者接受规定、合同约定之外的费用、财物或者其他利益的； (三)纵容或者放任本所律师有本办法第十条规定的违法行为的。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，属于《律师法》第五十条第二项规定的律师事务所“违反法定程序办理变更名称、负责人、章程、合伙协议、住所、合伙人等重大事项的”违法行为： (一)不按规定程序办理律师事务所名称、负责人、章程、合伙协议、住所、合伙人、组织形式等事项变更报批或者备案的； (二)不按规定的条件和程序发展合伙人，办理合伙人退伙、除名或者推选律师事务所负责人的； (三)不按规定程序办理律师事务所分立、合并，设立分所，或者终止、清算、注销事宜的。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，属于《律师法》第五十条第三项规定的律师事务所“从事法律服务以外的经营活动的”违法行为： (一)以独资、与他人合资或者委托持股方式兴办企业，并委派律师担任企业法定代表人或者总经理职务的； (二)从事与法律服务无关的中介服务或者其他经营性活动的。"},{"i":26,"n":"第二十六条","txt":"律师事务所从事或者纵容、放任本所律师从事本办法第六条规定的违法行为的，属于《律师法》第五十条第四项规定的律师事务所“以诋毁其他律师事务所、律师或者支付介绍费等不正当手段承揽业务的”违法行为。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，属于《律师法》第五十条第五项规定的律师事务所“违反规定接受有利益冲突的案件的”违法行为： (一)指派本所律师担任同一诉讼案件的原告、被告代理人，或者同一刑事案件被告人辩护人、被害人代理人的； (二)未按规定对委托事项进行利益冲突审查，指派律师同时或者先后为有利益冲突的非诉讼法律事务各方当事人担任代理人或者提供相关法律服务的； (三)明知本所律师及其近亲属同委托事项有利益冲突，仍指派该律师担任代理人、辩护人或者提供相关法律服务的； (四)纵容或者放任本所律师有本办法第七条规定的违法行为的。"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，属于《律师法》第五十条第六项规定的律师事务所“拒绝履行法律援助义务的”违法行为： (一)无正当理由拒绝接受法律援助机构指派的法律援助案件的； (二)接受指派后，不按规定及时安排本所律师承办法律援助案件或者拒绝为法律援助案件的办理提供条件和便利的； (三)纵容或者放任本所律师有本办法第九条规定的违法行为的。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，属于《律师法》第五十条第七项规定的律师事务所“向司法行政部门提供虚假材料或者有其他弄虚作假行为的”违法行为： (一)在司法行政机关实施检查、监督工作时，故意隐瞒真实情况，拒不提供有关材料或者提供不实、虚假的材料，或者隐匿、毁灭、伪造证据材料的； (二)在参加律师事务所年度检查考核、执业评价、评先创优活动中，提供不实、虚假、伪造的材料或者有其他弄虚作假行为的； (三)在办理律师事务所重大事项变更、设立分所、分立、合并或者终止、清算、注销的过程中，提供不实、虚假、伪造的证明材料或者有其他弄虚作假行为的。"},{"i":30,"n":"第三十条","txt":"有下列情形之一，造成严重后果和恶劣影响，属于《律师法》第五十条第八项规定的律师事务所“对本所律师疏于管理，造成严重后果的”违法行为： (一)不按规定建立健全内部管理制度，日常管理松懈、混乱，造成律师事务所无法正常运转的； (二)不按规定对律师执业活动实行有效监督，或者纵容、袒护、包庇本所律师从事违法违纪活动，造成严重后果的； (三)纵容或者放任律师在本所被处以停业整顿期间或者律师被处以停止执业期间继续执业的； (四)不按规定接受年度检查考核，或者经年度检查考核被评定为“不合格”的； (五)不按规定建立劳动合同制度，不依法为聘用律师和辅助人员办理失业、养老、医疗等社会保险的； (六)有其他违法违规行为，造成严重后果的。"},{"i":31,"n":"第三十一条","txt":"司法行政机关对律师的违法行为给予警告、罚款、没收违法所得、停止执业处罚的，由律师执业机构所在地的设区的市级或者直辖市区(县)司法行政机关实施；给予吊销执业证书处罚的，由许可该律师执业的省、自治区、直辖市司法行政机关实施。 司法行政机关对律师事务所的违法行为给予警告、罚款、没收违法所得、停业整顿处罚的，由律师事务所所在地的设区的市级或者直辖市区(县)司法行政机关实施；给予吊销执业许可证书处罚的，由许可该律师事务所设立的省、自治区、直辖市司法行政机关实施。"},{"i":32,"n":"第三十二条","txt":"律师有《律师法》第四十七条以及本办法第五条至第九条规定的违法行为的，由司法行政机关给予警告，可以处五千元以下的罚款；有违法所得的，没收违法所得；情节严重的，给予停止执业三个月以下的处罚。 律师有《律师法》第四十八条以及本办法第十条至第十三条规定的违法行为的，由司法行政机关给予警告，可以处一万元以下的罚款；有违法所得的，没收违法所得；情节严重的，给予停止执业三个月以上六个月以下的处罚。 律师有《律师法》第四十九条以及本办法第十四条至第二十二条规定的违法行为的，由司法行政机关给予停止执业六个月以上一年以下的处罚，可以处五万元以下的罚款；有违法所得的，没收违法所得；情节严重的，吊销其律师执业证书；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"律师事务所有《律师法》第五十条以及本办法第二十三条至第三十条规定的违法行为的，由司法行政机关视其情节给予警告、停业整顿一个月以上六个月以下的处罚，可以处十万元以下的罚款；有违法所得的，没收违法所得；情节特别严重的，吊销律师事务所执业许可证书。"},{"i":34,"n":"第三十四条","txt":"司法行政机关对律师、律师事务所的违法行为实施行政处罚，应当根据《行政处罚法》、《律师法》和司法部关于行政处罚程序的规定以及本办法的规定进行。"},{"i":35,"n":"第三十五条","txt":"律师、律师事务所对司法行政机关给予的行政处罚，享有陈述权、申辩权、要求听证权；对行政处罚决定不服的，有权依法申请行政复议或者提起行政诉讼；因司法行政机关违法给予行政处罚受到损害的，有权依法提出赔偿要求。"},{"i":36,"n":"第三十六条","txt":"司法行政机关实施行政处罚，应当对律师、律师事务所违法行为的事实、证据进行全面、客观、公正地调查、核实，必要时可以依法进行检查。 调查违法行为，可以要求被调查的律师、律师事务所说明情况、提交有关材料；可以调阅律师事务所有关业务案卷和档案材料；可以向有关单位、个人调查核实情况、收集证据；对可能灭失或者以后难以取得的证据，可以先行登记保存。 司法行政机关可以委托下一级司法行政机关或者违法行为发生地的司法行政机关进行调查，也可以委托律师协会协助进行调查。"},{"i":37,"n":"第三十七条","txt":"行政处罚的具体适用，由司法行政机关依照《律师法》和本办法的有关规定，根据律师、律师事务所违法行为的事实、性质、情节以及危害程度，在法定的处罚种类及幅度的范围内进行裁量，作出具体处罚决定。 对律师给予警告、停止执业、吊销律师执业证书的处罚，对律师事务所给予警告、停业整顿、吊销律师事务所执业许可证书的处罚，可以酌情并处罚款；有违法所得的，没收违法所得。"},{"i":38,"n":"第三十八条","txt":"律师、律师事务所有下列情形之一的，可以从轻或者减轻行政处罚： (一)主动消除或者减轻违法行为危害后果的； (二)主动报告，积极配合司法行政机关查处违法行为的； (三)受他人胁迫实施违法行为的； (四)其他依法应当从轻或者减轻处罚的。 违法行为轻微并及时纠正，没有造成危害后果的，不予行政处罚。"},{"i":39,"n":"第三十九条","txt":"律师、律师事务所的违法行为有下列情形之一的，属于《律师法》规定的违法情节严重或者情节特别严重，应当在法定的行政处罚种类及幅度的范围内从重处罚： (一)违法行为给当事人、第三人或者社会公共利益造成重大损失的； (二)违法行为性质、情节恶劣，严重损害律师行业形象，造成恶劣社会影响的； (三)同时有两项以上违法行为或者违法涉案金额巨大的； (四)在司法行政机关查处违法行为期间，拒不纠正或者继续实施违法行为，拒绝提交、隐匿、毁灭证据或者提供虚假、伪造的证据的； (五)其他依法应当从重处罚的。"},{"i":40,"n":"第四十条","txt":"律师在受到警告处罚后一年内又发生应当给予警告处罚情形的，应当给予停止执业三个月以上一年以下的处罚；在受到停止执业处罚期限未满或者期满后二年内又发生应当给予停止执业处罚情形的，应当吊销律师执业证书。 律师事务所在受到停业整顿处罚期限未满或者期满后二年内又发生应当给予停业整顿处罚情形的，应当吊销其律师事务所执业许可证书。"},{"i":41,"n":"第四十一条","txt":"律师事务所因违法行为受到处罚的，司法行政机关应当依照《律师法》第五十条第二款的规定，对该所负责人视其管理责任以及失职行为情节轻重，给予相应的行政处罚。 律师事务所因违法行为受到处罚的，应当同时追究负有直接责任的律师的法律责任，依法给予相应的行政处罚。"},{"i":42,"n":"第四十二条","txt":"律师、律师事务所的违法行为构成犯罪，应当依法追究刑事责任的，司法行政机关应当将案件移送司法机关处理，不得以行政处罚代替刑事处罚。 律师因违法执业构成故意犯罪或者因非执业事由构成故意犯罪受到刑事处罚的，司法行政机关应当吊销其律师执业证书；因过失犯罪受到刑事处罚的，在其服刑或者执行缓刑期间应当停止履行律师职务，刑期届满后可再申请恢复执业。"},{"i":43,"n":"第四十三条","txt":"司法行政机关实施行政处罚，应当经机关负责人审批，并依照《行政处罚法》的要求制作行政处罚决定书。 对情节复杂或者重大违法行为给予较重的行政处罚的，司法行政机关的负责人应当集体讨论决定；集体讨论决定时，可以邀请律师协会派员列席。"},{"i":44,"n":"第四十四条","txt":"司法行政机关实施行政处罚，可以根据需要，采用适当方式，将有关行政处罚决定在律师行业内予以通报或者向社会公告。"},{"i":45,"n":"第四十五条","txt":"被处罚的律师、律师事务所应当自觉、按时、全面地履行行政处罚决定，并向司法行政机关如实报告履行情况。 司法行政机关应当对律师、律师事务所履行行政处罚决定的情况实施监督，发现问题及时责令纠正或者依法采取相应的措施。"},{"i":46,"n":"第四十六条","txt":"律师、律师事务所因违法执业受到行政处罚，其违法行为对当事人或者第三人造成损害的，应当依法承担相应的民事责任。 因律师违法行为造成律师事务所承担赔偿责任的，律师事务所赔偿后可以向有故意或者重大过失行为的律师追偿。"},{"i":47,"n":"第四十七条","txt":"律师受到停止执业处罚期限未满的，不得申请变更执业机构；受到六个月以上停止执业处罚的，执行处罚的期间以及期满未愈三年的，不得担任合伙人。 律师事务所受到停业整顿处罚期限未满的，不得自行决定解散，不得申请变更名称，不得申请分立、合并，不得申请设立分所；该所负责人、合伙人和对律师事务所受到停业整顿处罚负有直接责任的律师不得申请变更执业机构。"},{"i":48,"n":"第四十八条","txt":"对律师事务所分所及其律师的违法行为给予行政处罚，由分所所在地的司法行政机关依照《律师法》和本办法的规定实施。处罚决定应当抄送设立分所的律师事务所及其所在地设区的市级或者直辖市区(县)司法行政机关。"},{"i":49,"n":"第四十九条","txt":"本办法所称的设区的市级司法行政机关，包括地区、州以及不设区的地级市司法行政机关。"},{"i":50,"n":"第五十条","txt":"本办法自2010年6月1日起施行。司法部2004年3月19日发布的《律师和律师事务所违法行为处罚办法》(司法部令第86号)同时废止。"}],"lvshizhiyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范律师执业许可，保障律师依法执业，加强对律师执业行为的监督和管理，根据《中华人民共和国律师法》(以下简称《律师法》)和其他有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"律师应当把拥护中国共产党领导、拥护社会主义法治作为从业的基本要求。 律师通过执业活动，应当维护当事人合法权益，维护法律正确实施，维护社会公平和正义。"},{"i":3,"n":"第三条","txt":"律师依法执业受法律保护，任何组织和个人不得侵害律师的合法权益。 司法行政机关和律师协会应当依法维护律师的执业权利。"},{"i":4,"n":"第四条","txt":"司法行政机关依照《律师法》和本办法的规定对律师执业进行监督、指导。 律师协会依照《律师法》、协会章程和行业规范对律师执业实行行业自律。"},{"i":5,"n":"第五条","txt":"司法行政机关、律师协会应当建立健全律师表彰奖励制度，根据有关规定设立综合性和单项表彰项目，对为维护人民群众合法权益、促进经济社会发展和国家法治建设作出突出贡献的律师进行表彰奖励。"},{"i":6,"n":"第六条","txt":"申请律师执业，应当具备下列条件： (一)拥护中华人民共和国宪法； (二)通过国家统一司法考试取得法律职业资格证书； (三)在律师事务所实习满一年； (四)品行良好。 实行国家统一司法考试前取得的律师资格证书，在申请律师执业时，与法律职业资格证书具有同等效力。 享受国家统一司法考试有关报名条件、考试合格优惠措施，取得法律职业资格证书的，其申请律师执业的地域限制，按照有关规定办理。 申请律师执业的人员，应当按照规定参加律师协会组织的实习活动，并经律师协会考核合格。"},{"i":7,"n":"第七条","txt":"申请兼职律师执业，除符合本办法第六条规定的条件外，还应当具备下列条件： (一)在高等院校、科研机构中从事法学教育、研究工作； (二)经所在单位同意。"},{"i":8,"n":"第八条","txt":"申请特许律师执业，应当符合《律师法》和国务院有关条例规定的条件。"},{"i":9,"n":"第九条","txt":"有下列情形之一的人员，不予颁发律师执业证书： (一)无民事行为能力或者限制民事行为能力的； (二)受过刑事处罚的，但过失犯罪的除外； (三)被开除公职或者被吊销律师执业证书的。"},{"i":10,"n":"第十条","txt":"律师执业许可，由设区的市级或者直辖市的区(县)司法行政机关受理执业申请并进行初审，报省、自治区、直辖市司法行政机关审核，作出是否准予执业的决定。"},{"i":11,"n":"第十一条","txt":"申请律师执业，应当向设区的市级或者直辖市的区(县)司法行政机关提交下列材料： (一)执业申请书； (二)法律职业资格证书或者律师资格证书； (三)律师协会出具的申请人实习考核合格的材料； (四)申请人的身份证明； (五)律师事务所出具的同意接收申请人的证明。 申请执业许可时，申请人应当如实填报《律师执业申请登记表》。"},{"i":12,"n":"第十二条","txt":"申请兼职律师执业，除按照本办法第十一条的规定提交有关材料外，还应当提交下列材料： (一)在高等院校、科研机构从事法学教育、研究工作的经历及证明材料； (二)所在单位同意申请人兼职律师执业的证明。"},{"i":13,"n":"第十三条","txt":"设区的市级或者直辖市的区(县)司法行政机关对申请人提出的律师执业申请，应当根据下列情况分别作出处理： (一)申请材料齐全、符合法定形式的，应当受理。 (二)申请材料不齐全或者不符合法定形式的，应当当场或者自收到申请材料之日起五日内一次告知申请人需要补正的全部内容。申请人按要求补正的，予以受理；逾期不告知的，自收到申请材料之日起即为受理。 (三)申请事项明显不符合法定条件或者申请人拒绝补正、无法补正有关材料的，不予受理，并向申请人书面说明理由。"},{"i":14,"n":"第十四条","txt":"受理申请的司法行政机关应当自决定受理之日起二十日内完成对申请材料的审查。 在审查过程中，可以征求申请执业地的县级司法行政机关的意见；对于需要调查核实有关情况的，可以要求申请人提供有关的证明材料，也可以委托县级司法行政机关进行核实。 经审查，应当对申请人是否符合法定条件、提交的材料是否真实齐全出具审查意见，并将审查意见和全部申请材料报送省、自治区、直辖市司法行政机关。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市司法行政机关应当自收到受理申请机关报送的审查意见和全部申请材料之日起十日内予以审核，作出是否准予执业的决定。 准予执业的，应当自决定之日起十日内向申请人颁发律师执业证书。 不准予执业的，应当向申请人书面说明理由。"},{"i":16,"n":"第十六条","txt":"申请特许律师执业，需要提交的材料以及受理、考核、批准的程序，依照国务院有关条例的规定办理。"},{"i":17,"n":"第十七条","txt":"申请人有本办法第九条规定情形之一的，不得准予其律师执业。"},{"i":18,"n":"第十八条","txt":"律师执业证书是律师依法获准执业的有效证件。 律师执业证书应当载明的内容、制作的规格、证号编制办法，由司法部规定。执业证书由司法部统一制作。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，由作出准予该申请人执业决定的省、自治区、直辖市司法行政机关撤销原准予执业的决定： (一)申请人以欺诈、贿赂等不正当手段取得准予执业决定的； (二)对不符合法定条件的申请人准予执业或者违反法定程序作出准予执业决定的。"},{"i":20,"n":"第二十条","txt":"律师变更执业机构，应当向拟变更的执业机构所在地设区的市级或者直辖市的区(县)司法行政机关提出申请，并提交下列材料： (一)原执业机构所在地县级司法行政机关出具的申请人不具有本办法第二十一条规定情形的证明； (二)与原执业机构解除聘用关系或者合伙关系以及办结业务、档案、财务等交接手续的证明； (三)拟变更的执业机构同意接收申请人的证明； (四)申请人的执业经历证明材料。 受理机关应当对变更申请及提交的材料出具审查意见，并连同全部申请材料报送省、自治区、直辖市司法行政机关审核。对准予变更的，由审核机关为申请人换发律师执业证书；对不准予变更的，应当向申请人书面说明理由。有关审查、核准、换证的程序和期限，参照本办法第十四条、第十五条的规定办理。 准予变更的，申请人在领取新的执业证书前，应当将原执业证书上交原审核颁证机关。 律师跨设区的市或者省、自治区、直辖市变更执业机构的，原执业机构所在地和变"},{"i":21,"n":"第二十一条","txt":"律师受到停止执业处罚期间或者受到投诉正在调查处理的，不得申请变更执业机构；律师事务所受到停业整顿处罚期限未满的，该所负责人、合伙人和对律师事务所受到停业整顿处罚负有直接责任的律师不得申请变更执业机构；律师事务所应当终止的，在完成清算、办理注销前，该所负责人、合伙人和对律师事务所被吊销执业许可证负有直接责任的律师不得申请变更执业机构。"},{"i":22,"n":"第二十二条","txt":"律师被所在的律师事务所派驻分所执业的，其律师执业证书的换发及管理办法，按照司法部有关规定办理。"},{"i":23,"n":"第二十三条","txt":"律师有下列情形之一的，由其执业地的原审核颁证机关收回、注销其律师执业证书： (一)受到吊销律师执业证书处罚的； (二)原准予执业的决定被依法撤销的； (三)因本人不再从事律师职业申请注销的； (四)因与所在律师事务所解除聘用合同或者所在的律师事务所被注销，在六个月内未被其他律师事务所聘用的； (五)因其他原因终止律师执业的。 因前款第(三)项、第(四)项、第(五)项规定情形被注销律师执业证书的人员，重新申请律师执业的，按照本办法规定的程序申请律师执业。 律师正在接受司法机关、司法行政机关、律师协会立案调查期间，不得申请注销执业证书。"},{"i":24,"n":"第二十四条","txt":"律师执业必须遵守宪法和法律，恪守律师职业道德和执业纪律，做到依法执业、诚信执业、规范执业。 律师执业必须以事实为根据，以法律为准绳。 律师执业应当接受国家、社会和当事人的监督。"},{"i":25,"n":"第二十五条","txt":"律师可以从事下列业务： (一)接受自然人、法人或者其他组织的委托，担任法律顾问； (二)接受民事案件、行政案件当事人的委托，担任代理人，参加诉讼； (三)接受刑事案件犯罪嫌疑人、被告人的委托或者依法接受法律援助机构的指派，担任辩护人，接受自诉案件自诉人、公诉案件被害人或者其近亲属的委托，担任代理人，参加诉讼； (四)接受委托，代理各类诉讼案件的申诉； (五)接受委托，参加调解、仲裁活动； (六)接受委托，提供非诉讼法律服务； (七)解答有关法律的询问、代写诉讼文书和有关法律事务的其他文书。"},{"i":26,"n":"第二十六条","txt":"律师承办业务，应当由律师事务所统一接受委托，与委托人签订书面委托合同，并服从律师事务所对受理业务进行的利益冲突审查及其决定。"},{"i":27,"n":"第二十七条","txt":"律师担任各级人民代表大会常务委员会组成人员的，任职期间不得从事诉讼代理或者辩护业务。 律师明知当事人已经委托两名诉讼代理人、辩护人的，不得再接受委托担任诉讼代理人、辩护人。"},{"i":28,"n":"第二十八条","txt":"律师不得在同一案件中为双方当事人担任代理人，或者代理与本人及其近亲属有利益冲突的法律事务。律师接受犯罪嫌疑人、被告人委托后，不得接受同一案件或者未同案处理但实施的犯罪存在关联的其他犯罪嫌疑人、被告人的委托担任辩护人。 曾经担任法官、检察官的律师从人民法院、人民检察院离任后，二年内不得以律师身份担任诉讼代理人或者辩护人；不得担任原任职人民法院、人民检察院办理案件的诉讼代理人或者辩护人，但法律另有规定的除外。 律师不得担任所在律师事务所其他律师担任仲裁员的案件的代理人。曾经或者仍在担任仲裁员的律师，不得承办与本人担任仲裁员办理过的案件有利益冲突的法律事务。"},{"i":29,"n":"第二十九条","txt":"律师担任法律顾问的，应当按照约定为委托人就有关法律问题提供意见，草拟、审查法律文书，代理参加诉讼、调解或者仲裁活动，办理委托的其他法律事务，维护委托人的合法权益。"},{"i":30,"n":"第三十条","txt":"律师担任诉讼法律事务代理人或者非诉讼法律事务代理人的，应当在受委托的权限内代理法律事务，维护委托人的合法权益。"},{"i":31,"n":"第三十一条","txt":"律师担任辩护人的，应当根据事实和法律，提出犯罪嫌疑人、被告人无罪、罪轻或者减轻、免除其刑事责任的材料和意见，维护犯罪嫌疑人、被告人的诉讼权利和其他合法权益。 律师担任辩护人的，其所在律师事务所应当在接受委托后三日以内，向办案机关提交接受委托告知函，告知委托事项、承办律师及联系方式。"},{"i":32,"n":"第三十二条","txt":"律师出具法律意见，应当严格依法履行职责，保证其所出具意见的真实性、合法性。 律师提供法律咨询、代写法律文书，应当以事实为根据，以法律为准绳，并符合法律咨询规则和法律文书体例、格式的要求。"},{"i":33,"n":"第三十三条","txt":"律师承办业务，应当告知委托人该委托事项办理可能出现的法律风险，不得用明示或者暗示方式对办理结果向委托人作出不当承诺。 律师承办业务，应当及时向委托人通报委托事项办理进展情况；需要变更委托事项、权限的，应当征得委托人的同意和授权。 律师接受委托后，无正当理由的，不得拒绝辩护或者代理，但是，委托事项违法，委托人利用律师提供的服务从事违法活动或者委托人故意隐瞒与案件有关的重要事实的，律师有权拒绝辩护或者代理。"},{"i":34,"n":"第三十四条","txt":"律师承办业务，应当维护当事人合法权益，不得利用提供法律服务的便利牟取当事人争议的权益或者不当利益。"},{"i":35,"n":"第三十五条","txt":"律师承办业务，应当诚实守信，不得接受对方当事人的财物及其他利益，与对方当事人、第三人恶意串通，向对方当事人、第三人提供不利于委托人的信息、证据材料，侵害委托人的权益。"},{"i":36,"n":"第三十六条","txt":"律师与法官、检察官、仲裁员以及其他有关工作人员接触交往，应当遵守法律及相关规定，不得违反规定会见法官、检察官、仲裁员以及其他有关工作人员，向其行贿、许诺提供利益、介绍贿赂，指使、诱导当事人行贿，或者向法官、检察官、仲裁员以及其他工作人员打探办案机关内部对案件的办理意见、承办其介绍的案件，利用与法官、检察官、仲裁员以及其他有关工作人员的特殊关系，影响依法办理案件。"},{"i":37,"n":"第三十七条","txt":"律师承办业务，应当引导当事人通过合法的途径、方式解决争议，不得采取煽动、教唆和组织当事人或者其他人员到司法机关或者其他国家机关静坐、举牌、打横幅、喊口号、声援、围观等扰乱公共秩序、危害公共安全的非法手段，聚众滋事，制造影响，向有关部门施加压力。"},{"i":38,"n":"第三十八条","txt":"律师应当依照法定程序履行职责，不得以下列不正当方式影响依法办理案件： (一)未经当事人委托或者法律援助机构指派，以律师名义为当事人提供法律服务、介入案件，干扰依法办理案件； (二)对本人或者其他律师正在办理的案件进行歪曲、有误导性的宣传和评论，恶意炒作案件； (三)以串联组团、联署签名、发表公开信、组织网上聚集、声援等方式或者借个案研讨之名，制造舆论压力，攻击、诋毁司法机关和司法制度； (四)违反规定披露、散布不公开审理案件的信息、材料，或者本人、其他律师在办案过程中获悉的有关案件重要信息、证据材料。"},{"i":39,"n":"第三十九条","txt":"律师代理参与诉讼、仲裁或者行政处理活动，应当遵守法庭、仲裁庭纪律和监管场所规定、行政处理规则，不得有下列妨碍、干扰诉讼、仲裁或者行政处理活动正常进行的行为： (一)会见在押犯罪嫌疑人、被告人时，违反有关规定，携带犯罪嫌疑人、被告人的近亲属或者其他利害关系人会见，将通讯工具提供给在押犯罪嫌疑人、被告人使用，或者传递物品、文件； (二)无正当理由，拒不按照人民法院通知出庭参与诉讼，或者违反法庭规则，擅自退庭； (三)聚众哄闹、冲击法庭，侮辱、诽谤、威胁、殴打司法工作人员或者诉讼参与人，否定国家认定的邪教组织的性质，或者有其他严重扰乱法庭秩序的行为； (四)故意向司法机关、仲裁机构或者行政机关提供虚假证据或者威胁、利诱他人提供虚假证据，妨碍对方当事人合法取得证据； (五)法律规定的妨碍、干扰诉讼、仲裁或者行政处理活动正常进行的其他行为。"},{"i":40,"n":"第四十条","txt":"律师对案件公开发表言论，应当依法、客观、公正、审慎，不得发表、散布否定宪法确立的根本政治制度、基本原则和危害国家安全的言论，不得利用网络、媒体挑动对党和政府的不满，发起、参与危害国家安全的组织或者支持、参与、实施危害国家安全的活动，不得以歪曲事实真相、明显违背社会公序良俗等方式，发表恶意诽谤他人的言论，或者发表严重扰乱法庭秩序的言论。"},{"i":41,"n":"第四十一条","txt":"律师应当按照有关规定接受业务，不得为争揽业务哄骗、唆使当事人提起诉讼，制造、扩大矛盾，影响社会稳定。"},{"i":42,"n":"第四十二条","txt":"律师应当尊重同行，公平竞争，不得以诋毁其他律师事务所、律师，支付介绍费，向当事人明示或者暗示与办案机关、政府部门及其工作人员有特殊关系，或者在司法机关、监管场所周边违规设立办公场所、散发广告、举牌等不正当手段承揽业务。"},{"i":43,"n":"第四十三条","txt":"律师应当保守在执业活动中知悉的国家秘密、商业秘密，不得泄露当事人和其他人的个人隐私。 律师对在执业活动中知悉的委托人和其他人不愿泄露的有关情况和信息，应当予以保密。但是，委托人或者其他人准备或者正在实施危害国家安全、公共安全以及严重危害他人人身安全的犯罪事实和信息除外。"},{"i":44,"n":"第四十四条","txt":"律师承办业务，应当按照规定由律师事务所向委托人统一收取律师费和有关办案费用，不得私自收费，不得接受委托人的财物或者其他利益。"},{"i":45,"n":"第四十五条","txt":"律师应当按照国家规定履行法律援助义务，为受援人提供符合标准的法律服务，维护受援人的合法权益，不得拖延、懈怠履行或者擅自停止履行法律援助职责，或者未经律师事务所、法律援助机构同意，擅自将法律援助案件转交其他人员办理。"},{"i":46,"n":"第四十六条","txt":"律师承办业务，应当妥善保管与承办事项有关的法律文书、证据材料、业务文件和工作记录。在法律事务办结后，按照有关规定立卷建档，上交律师事务所保管。"},{"i":47,"n":"第四十七条","txt":"律师只能在一个律师事务所执业。 律师在从业期间应当专职执业，但兼职律师或者法律、行政法规另有规定的除外。 律师执业，应当遵守所在律师事务所的执业管理制度，接受律师事务所的指导和监督，参加律师执业年度考核。"},{"i":48,"n":"第四十八条","txt":"律师应当妥善使用和保管律师执业证书，不得变造、抵押、出借、出租。如有遗失或者损毁的，应当及时报告所在地县级司法行政机关，经所在地设区的市级或者直辖市区(县)司法行政机关向原审核颁证机关申请补发或者换发。律师执业证书遗失的，应当在省级以上报刊或者发证机关指定网站上刊登遗失声明。 律师受到停止执业处罚的，应当自处罚决定生效后至处罚期限届满前，将律师执业证书缴存其执业机构所在地县级司法行政机关。"},{"i":49,"n":"第四十九条","txt":"律师应当按照规定参加司法行政机关和律师协会组织的职业培训。"},{"i":50,"n":"第五十条","txt":"县级司法行政机关对其执业机构在本行政区域的律师的执业活动进行日常监督管理，履行下列职责： (一)检查、监督律师在执业活动中遵守法律、法规、规章和职业道德、执业纪律的情况； (二)受理对律师的举报和投诉； (三)监督律师履行行政处罚和实行整改的情况； (四)掌握律师事务所对律师执业年度考核的情况； (五)司法部和省、自治区、直辖市司法行政机关规定的其他职责。 县级司法行政机关在开展日常监督管理过程中，发现、查实律师在执业活动中存在问题的，应当对其进行警示谈话，责令改正，并对其整改情况进行监督；对律师的违法行为认为依法应当给予行政处罚的，应当向上一级司法行政机关提出处罚建议；认为需要给予行业惩戒的，移送律师协会处理。"},{"i":51,"n":"第五十一条","txt":"设区的市级司法行政机关履行下列监督管理职责： (一)掌握本行政区域律师队伍建设和发展情况，制定加强律师队伍建设的措施和办法； (二)指导、监督下一级司法行政机关对律师执业的日常监督管理工作，组织开展对律师执业的专项检查或者专项考核工作，指导对律师重大投诉案件的查处工作； (三)对律师进行表彰； (四)依法定职权对律师的违法行为实施行政处罚；对依法应当给予吊销律师执业证书处罚的，向上一级司法行政机关提出处罚建议； (五)对律师事务所的律师执业年度考核结果实行备案监督； (六)受理、审查律师执业、变更执业机构、执业证书注销申请事项； (七)建立律师执业档案，负责有关律师执业许可、变更、注销等信息的公开工作； (八)法律、法规、规章规定的其他职责。 直辖市的区(县)司法行政机关负有前款规定的有关职责。"},{"i":52,"n":"第五十二条","txt":"省、自治区、直辖市司法行政机关履行下列监督管理职责： (一)掌握、评估本行政区域律师队伍建设情况和总体执业水平，制定律师队伍的发展规划和有关政策，制定加强律师执业管理的规范性文件； (二)监督、指导下级司法行政机关对律师执业的监督管理工作，组织、指导对律师执业的专项检查或者专项考核工作； (三)组织对律师的表彰活动； (四)依法对律师的严重违法行为实施吊销律师执业证书的处罚，监督、指导下一级司法行政机关的行政处罚工作，办理有关行政复议和申诉案件； (五)办理律师执业核准、变更执业机构核准和执业证书注销事项； (六)负责有关本行政区域律师队伍、执业情况、管理事务等重大信息的公开工作； (七)法律、法规、规章规定的其他职责。"},{"i":53,"n":"第五十三条","txt":"律师违反本办法有关规定的，依照《律师法》和有关法规、规章规定追究法律责任。 律师违反本办法第二十八条、第四十一条、第四十二条规定的，司法行政机关应当依照《律师法》第四十七条相关规定予以行政处罚；违反第三十四条规定的，依照《律师法》第四十八条相关规定予以行政处罚；违反第三十五条至第四十条规定的，依照《律师法》第四十九条相关规定予以行政处罚。"},{"i":54,"n":"第五十四条","txt":"各级司法行政机关及其工作人员对律师执业实施监督管理，不得妨碍律师依法执业，不得侵害律师的合法权益，不得索取或者收受律师的财物，不得谋取其他利益。"},{"i":55,"n":"第五十五条","txt":"司法行政机关应当加强对实施律师执业许可和日常监督管理活动的层级监督，按照规定建立有关工作的统计、请示、报告、督办等制度。 负责律师执业许可实施、律师执业年度考核结果备案或者奖励、处罚的司法行政机关，应当及时将有关许可决定、备案情况、奖惩情况通报下级司法行政机关，并报送上一级司法行政机关。"},{"i":56,"n":"第五十六条","txt":"司法行政机关、律师协会应当建立律师和律师事务所信息管理系统，按照有关规定向社会公开律师基本信息和年度考核结果、奖惩情况。"},{"i":57,"n":"第五十七条","txt":"司法行政机关应当加强对律师协会的指导、监督，支持律师协会依照《律师法》和协会章程、行业规范对律师执业活动实行行业自律，建立健全行政管理与行业自律相结合的协调、协作机制。"},{"i":58,"n":"第五十八条","txt":"各级司法行政机关应当定期将本行政区域律师队伍建设、执业活动情况的统计资料、年度管理工作总结报送上一级司法行政机关。"},{"i":59,"n":"第五十九条","txt":"人民法院、人民检察院、公安机关、国家安全机关或者其他有关部门对律师的违法违规行为向司法行政机关、律师协会提出予以处罚、处分建议的，司法行政机关、律师协会应当自作出处理决定之日起七日内通报建议机关。"},{"i":60,"n":"第六十条","txt":"司法行政机关工作人员在律师执业许可和实施监督管理活动中，滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":61,"n":"第六十一条","txt":"军队律师的执业管理，按照国务院和中央军事委员会有关规定执行。"},{"i":62,"n":"第六十二条","txt":"本办法自2016年11月1日起施行。此前司法部制定的有关律师执业管理的规章、规范性文件与本办法相抵触的，以本办法为准。"}],"fangwuchaiqianzhengjubaoquangongzhengxize":[{"i":1,"n":"第一条","txt":"为规范城市房屋拆迁证据保全公证活动，根据《中华人民共和国公证暂行条例》、《城市房屋拆迁管理条例》、《公证程序规则(试行)》，制订本细则。"},{"i":2,"n":"第二条","txt":"房屋拆迁证据保全公证是指在房屋拆迁之前，公证机关对房屋及附属物的现状依法采取勘测、拍照或摄像等保全措施，以确保其真实性和证明力的活动。"},{"i":3,"n":"第三条","txt":"本细则适用于《城市房屋拆迁管理条例》规定的拆除依法代管的房屋，代管人是房屋主管部门的；拆除有产权纠纷的房屋，在房屋拆迁主管部门公布的规定期限内纠纷未解决的；拆除设有抵押权的房屋实行产权调换，抵押权人和抵押人在房屋拆迁主管部门公布的规定期限内达不成抵押协议的以及其他房屋拆迁证据保全的公证事项。"},{"i":4,"n":"第四条","txt":"房屋拆迁证据保全公证，由被拆迁房屋所在地公证处管辖。"},{"i":5,"n":"第五条","txt":"房屋拆迁证据保全公证申请人是拆迁人或被拆迁人，房屋拆迁主管部门也可以作为申请人。上述申请人可以委托他人代为提出公证申请。"},{"i":6,"n":"第六条","txt":"申请人应填写公证申请表，并提交下列材料： (一)身份证明；申请人为法人的，应提交法人资格和法定代表人的身份证明；被拆迁人为公民个人的，应提交身份证明； (二)资格证明；拆迁人应提交房屋拆迁主管部门核发的拆迁许可证明；接受拆迁委托的被委托人应提交房屋拆迁资格证书；被拆迁人应提交作为被拆除房屋及其附属物的所有人(包括代管人、国家授权的国有房屋及其附属物的管理人)和被拆除房屋及其附属物的使用人的证明； (三)拆除有产权纠纷的房屋，提交由县级以上人民政府房屋拆迁主管部门批准的补偿安置方案的证明； (四)实施强制拆迁的房屋，提交县级以上人民政府作出的限期拆迁的决定或人民法院院长签发的限期拆迁的公告； (五)公证人员认为应当提交的其他有关材料。"},{"i":7,"n":"第七条","txt":"符合下列条件的申请，公证处应予受理，并书面通知申请人： (一)申请人符合本细则第五条的规定； (二)申请公证事项属于本公证处管辖； (三)提供本细则第六条所需材料。 不符合前款规定条件的申请，公证处应作出不予受理的决定，通知申请人，并告知对拒绝受理不服的复议程序。 受理或拒绝受理的决定，应在申请人依据本细则规定正式提出申请后的七日内作出。"},{"i":8,"n":"第八条","txt":"公证人员应认真接待申请人，应按《公证程序规则(试行)》第二十四条的规定制作谈话笔录，并着重记录下列内容： (一)申请证据保全的目的和理由； (二)申请证据保全的种类、名称、地点和现存状况； (三)证据保全的方式； (四)公证人员认为应当记录的其他内容。 申请人也可以提交包含上述内容的书面材料。"},{"i":9,"n":"第九条","txt":"符合证据保全公证条件的，公证处应派两名以上公证人员(其中至少有一名公证员)参与整个证据保全活动。"},{"i":10,"n":"第十条","txt":"办理房屋拆迁证据保全公证，公证员应当客观、全面的记录被拆迁房屋的现场状况，收集、提取有关证据。应该根据被保全对象的不同特点，采取勘测、拍照、摄像等方式进行证据保全。"},{"i":11,"n":"第十一条","txt":"对房屋进行勘测的，应当制作勘测记录，记明勘测时间、地点、测验人、记录人、被保全房屋的产权人、座落、四至、房屋性质、结构、层次、面积、新旧程度、屋面及地面质地、附属设施以及其它应当记明的事项；能够用图示标明的房屋长度、宽度应当图示；记录应当由勘测人、公证员签名或者盖章；拆迁活动当事人在场的，应请当事人签名或盖章；该当事人拒绝签名或盖章的，公证员应在记录中记明。"},{"i":12,"n":"第十二条","txt":"对房屋进行拍照和摄像的，应当全面反映、记录房屋的全貌。房屋结构、门窗、厨房以及附属设施等，要有单独的图片显示。"},{"i":13,"n":"第十三条","txt":"公证机关对保全事项认为需要勘测的，应当聘请专业技术部门或其他部门中有该项能力的人员进行勘测。 专业技术部门及其勘测人应当提出书面勘测结论，在勘测书上签名或者盖章。其他部门勘测人勘测的，应由勘测人所在单位加盖印章，证明勘测人身份。"},{"i":14,"n":"第十四条","txt":"实施强制拆迁房屋证据保全时，公证机关应通知被拆迁人到场。如其拒不到场，公证员应在笔录中记明。 实施强制拆迁房屋中有物品的，公证员应当组织对所有物品逐一核对、清点、登记，分类造册。并记录上述活动的时间、地点，交两名有完全行为能力的在场人员核对后，由公证员和在场人在记录上签名。被拆迁人拒绝签名的，公证员应在记录中记明。 物品清点登记后，凡不能立即交与被拆迁人接收的，公证员要监督拆迁人将物品存放在其提供的仓库中，并对物品挂签标码，丢失损坏的，仓库保管人应承担赔偿责任。 拆迁人应制作通知书，通知当事人在一定期限内领取物品。逾期不领的，公证处可以接受拆迁人的提存申请，办理提存。"},{"i":15,"n":"第十五条","txt":"公证员对房屋证据保全的活动结束后应出具公证书。公证书应当按照《公证程序规则(试行)》第三十八条的规定及《公证书格式(试行)》第四十八式保全证据公证书格式(之二)制作。公证词应当记明申请保全的理由及时间，公证员审查申请人主体资格及证据情况的内容，采取保全的时间、地点、方法，保全证据所制作的笔录、拍摄的照片、录像带的名称、数量及保存地点。"},{"i":16,"n":"第十六条","txt":"本细则自1994年2月1日起施行。"}],"ticungongzhengguize":[{"i":1,"n":"第一条","txt":"为维护经济流转秩序，预防和减少债务纠纷，保证提存公证质量，根据《中华人民共和国民法通则》、《中华人民共和国公证暂行条例》及有关规定，制订本规则。"},{"i":2,"n":"第二条","txt":"提存公证是公证处依照法定条件和程序，对债务人或担保人为债权人的利益而交付的债之标的物或担保物(含担保物的替代物)进行寄托、保管，并在条件成就时交付债权人的活动。为履行清偿义务或担保义务而向公证处申请提存的人为提存人。提存之债的债权人为提存受领人。"},{"i":3,"n":"第三条","txt":"以清偿为目的的提存公证具有债的消灭和债之标的物风险责任转移的法律效力。 以担保为目的的提存公证具有保证债务履行和替代其他担保形式的法律效力。 不符合法定条件的提存或提存人取回提存标的的，不具有提存公证的法律效力。"},{"i":4,"n":"第四条","txt":"提存公证由债务履行地的公证处管辖。 以担保为目的的提存公证或在债务履行地申办提存公证有困难的，可由担保人住所地或债务人住所地的公证处管辖。"},{"i":5,"n":"第五条","txt":"债务清偿期限届至，有下列情况之一使债务人无法按时给付的，公证处可以根据债务人申请依法办理提存： (一)债权人无正当理由拒绝或延迟受领债之标的的； (二)债权人不在债务履行地又不能到履行地受领的； (三)债权人不清、地址不详，或失踪、死亡(消灭)其继承人不清，或无行为能力其法定代理人不清的。"},{"i":6,"n":"第六条","txt":"有下列情况之一的，公证处可以根据当事人申请办理提存公证： (一)债的双方在合同(协议)中约定以提存方式给付的； (二)为了保护债权人利益，保证人、抵押人或质权人请求将担保物(金)或其替代物提存的； 当事人申办前款所列提存公证，必须列明提存物给付条件，公证处应按提存人所附条件给付提存标的物。"},{"i":7,"n":"第七条","txt":"下列标的物可以提存： (一)货币； (二)有价证券、票据、提单、权利证书； (三)贵重物品； (四)担保物(金)或其替代物； (五)其他适宜提存的标的物。"},{"i":8,"n":"第八条","txt":"公证处应当在指定银行设立提存帐户，并置备保管有价证券、贵重物品的专用设备或租用银行的保险箱。"},{"i":9,"n":"第九条","txt":"提存申请人应当填写公证申请表，并提交下列材料： (一)申请人的身份证明；法人应提交法人资格证明和法定代表人身份证明，法定代理人应提交与被代理人关系的证明，委托代理人应提交授权委托书； (二)合同(协议)、担保书、赠与书、司法文书、行政决定等据以履行义务的依据； (三)存在本规则第五条或第六条规定情况的有关证明材料； (四)提存受领人姓名(名称)、地址、邮编、联系电话等； (五)提存标的物种类、质量、数量、价值的明细表； (六)公证员认为应当提交的其他材料。"},{"i":10,"n":"第十条","txt":"符合下列条件的申请，公证处应当受理： (一)申请人对提存受领人负有清偿或担保义务； (二)具有本规则第五条或第六条规定的情况； (三)申请事项属于本公证处管辖； (四)本规则第九条规定的材料基本齐全。 公证处应在收到申请之日起三日内作出受理或不予受理的决定。不予受理的，公证处应当告知申请人对不予受理不服的复议程序。"},{"i":11,"n":"第十一条","txt":"公证人员应按《公证程序规则(试行)》第二十四条规定制作谈话笔录，记录下列内容： (一)提存理由和相关事实(如无法给付债的标的物的事由和经过)； (二)有关提存受领人的详细情况； (三)提存标的物的详细情况； (四)提存人所作的特别说明等。"},{"i":12,"n":"第十二条","txt":"公证员应当按《公证程序规则(试行)》第二十三条规定，审查下列内容： (一)本规则第九条所列材料是否齐全，内容是否属实； (二)提存人的行为能力和清偿依据； (三)申请提存之债的真实性、合法性； (四)请求提存的原因和事实是否属实； (五)提存标的物与债的标的是否相符，是否适宜提存； (六)提存标的物是否需要采取特殊的处理或保管措施。"},{"i":13,"n":"第十三条","txt":"符合下列条件的，公证处应当予以提存： (一)提存人具有行为能力，意思表示真实； (二)提存之债真实、合法； (三)符合本规则第五条或第六条以及第七条规定条件； (四)提存标的与债的标的相符。 提存标的与债的标的不符或在提存时难以判明两者是否相符的，公证处应告知提存人如提存受领人因此原因拒绝受领提存物则不能产生提存的效力。提存人仍要求提存的，公证处可以办理提存公证，并记载上述条件。 不符合前两款规定的，公证处应当拒绝办理提存公证，并告知申请人对拒绝公证不服的复议程序。"},{"i":14,"n":"第十四条","txt":"公证处应当验收提存标的物并登记存档。对不能提交公证处的提存物，公证处应当派公证员到现场实地验收。验收时，提存申请人(或其代理人)应当在场，公证员应制作验收笔录。 验收笔录应当记录验收的时间、地点、方式、参加人员、物品的数量、种类、规格、价值以及存放地点、保管环境等内容。验收笔录应交提存人核对。公证员、提存人及其他参与人员应当在验收笔录上签名。 对难以验收的提存标的物，公证处可予以证据保全，并在公证笔录和公证书中注明。 经验收的提存标的物，公证处应当采用封存、委托代管等必要的保管措施。 对易腐易烂易燃易爆等物品，公证处应当在保全证据后，由债务人拍卖或变卖，提存其价款。"},{"i":15,"n":"第十五条","txt":"对提存的贵重物品、有价证券、不动产或其他物品的价值难以确定的，公证处可以聘请专业机构或人员进行估价。"},{"i":16,"n":"第十六条","txt":"提存货币的，以现金、支票交付公证处的日期或提存款划入公证处提存帐户的日期为提存日期。 提存的物品需要验收的，以公证处验收合格的日期为提存日期。 提存的有价证券、提单、权利证书或无需验收的物品，以实际交付公证处的日期为提存日期。"},{"i":17,"n":"第十七条","txt":"公证处应当从提存之日起三日内出具提存公证书。提存之债从提存之日即告清偿。"},{"i":18,"n":"第十八条","txt":"提存人应将提存事实及时通知提存受领人。 以清偿为目的的提存或提存人通知有困难的，公证处应自提存之日起七日内，以书面形式通知提存受领人，告知其领取提存物的时间、期限、地点、方法。 提存受领人不清或下落不明、地址不详无法送达通知的，公证处应自提存之日起六十日内，以公告方式通知。公告应刊登在国家或债权人在国内住所地的法制报刊上，公告应在一个月内在同一报刊刊登三次。"},{"i":19,"n":"第十九条","txt":"公证处有保管提存标的物的权利和义务。公证处应当采取适当的方法妥善保管提存标的，以防毁损、变质或灭失。 对不宜保存的、提存受领人到期不领取或超过保管期限的提存物品，公证处可以拍卖，保存其价款。"},{"i":20,"n":"第二十条","txt":"下列物品的保管期限为六个月： (一)不适于长期保管或长期保管将损害其价值的； (二)六个月的保管费用超过物品价值5%的。"},{"i":21,"n":"第二十一条","txt":"从提存之日起，超过二十年无人领取的提存标的物，视为无主财产；公证处应在扣除提存费用后将其余额上缴国库。"},{"i":22,"n":"第二十二条","txt":"提存物在提存期间所产生的孳息归提存受领人所有。提存人取回提存物的，孳息归提存人所有。 提存的存款单、有价证券、奖券需要领息、承兑、领奖的，公证处应当代为承兑或领取，所获得的本金和孳息在不改变用途的前提下，按不损害提存受领人利益的原则处理。无法按原用途使用的，应以货币形式存入提存帐户。 定期存款到期的，原则上按原来期限将本金和利息一并转存。股息红利除用于支付有关的费用外，剩余部分应当存入提存专用帐户。 提存的不动产或其他物品的收益，除用于维护费用外剩余部分应当存入提存帐户。"},{"i":23,"n":"第二十三条","txt":"公证处应当按照当事人约定或法定的条件给付提存标的。本规则第六条第一项规定的以对待给付为条件的提存，在提存受领人未为对待给付之前，公证处不得给付提存标的物。 提存受领人领取提存标的物时，应提供身份证明、提存通知书或公告，以及有关债权的证明，并承担因提存所支出的费用。提存受领人负有对待给付义务的，应提供履行对待给付义务的证明。委托他人代领的，还应提供有效的授权委托书。由其继承人领取的，应当提交继承公证书或其他有效的法律文书。"},{"i":24,"n":"第二十四条","txt":"因债权的转让、抵销等原因需要由第三人领取提存标的物的，该第三人应当提供已取得提存之债债权的有效法律文书。"},{"i":25,"n":"第二十五条","txt":"除当事人另有约定外，提存费用由提存受领人承担。 提存费用包括：提存公证费、公告费、邮电费、保管费、评估鉴定费、代管费、拍卖变卖费、保险费，以及为保管、处理、运输提存标的物所支出的其他费用。 提存受领人未支付提存费用前，公证处有权留置价值相当的提存标的物。"},{"i":26,"n":"第二十六条","txt":"提存人可以凭人民法院生效的判决、裁定或提存之债已经清偿的公证证明取回提存物。 提存受领人以书面形式向公证处表示抛弃提存受领权的，提存人得取回提存物。 提存人取回提存物的，视为未提存。因此产生的费用由提存人承担。提存人未支付提存费用前，公证处有权留置价值相当的提存标的。"},{"i":27,"n":"第二十七条","txt":"公证处不得挪用提存标的。公证处或公证人员挪用提存标的的，除应负相应的赔偿责任外，对直接责任人员要追究行政或刑事责任。 提存期间，提存物毁损灭失的风险责任由提存受领人负担；但因公证处过错造成毁损、灭失的，公证处负有赔偿责任。 公民、法人以不正当手段骗取提存标的的，负有赔偿责任；构成犯罪的，依法追究刑事责任。 公证处未按法定或当事人约定条件给付提存标的给当事人造成损失的，公证处负有连带赔偿责任。"},{"i":28,"n":"第二十八条","txt":"符合法定或当事人约定的给付条件，公证处拒绝给付的，由其主管的司法行政机关责令限期给付；给当事人造成损失的，公证处负有赔偿责任。 根据人民法院、仲裁机构的裁决或司法行政机关决定给付的，由此产生的法律后果由作出决定的机构承担。"},{"i":29,"n":"第二十九条","txt":"司法机关或行政机关因执行公务而申办提存公证的，参照本规则办理。 监护人、遗产管理人为保护被监护人、继承人利益，请求将所监护或管理的财产提存的，参照本规则办理。 遗嘱人或赠与人为保护遗嘱受益人或未成年的受赠人利益，请求将遗嘱所处分的财产或赠与财产提存的，参照本规则办理。"},{"i":30,"n":"第三十条","txt":"外国人、无国籍人在中国境内申办提存公证，适用本规则。"},{"i":31,"n":"第三十一条","txt":"本规则自发布之日起施行。由司法部负责解释。"}],"weichengnianfanguanjiaosuoguanliguiding":[{"i":1,"n":"第一条","txt":"为了正确执行刑罚，加强对未成年犯管教所的管理，根据《中华人民共和国监狱法》(以下简称《监狱法》)、《中华人民共和国未成年人保护法》和有关法律法规，结合未成年犯管教所工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"未成年犯管教所是监狱的一种类型，是国家的刑罚执行机关。 由人民法院依法判处有期徒刑、无期徒刑未满十八周岁的罪犯应当在未成年犯管教所执行刑罚、接受教育改造。"},{"i":3,"n":"第三条","txt":"未成年犯管教所贯彻“惩罚和改造相结合，以改造人为宗旨”和“教育、感化、挽救”的方针，将未成年犯改造成为具有一定文化知识和劳动技能的守法公民。"},{"i":4,"n":"第四条","txt":"对未成年犯的改造，应当根据其生理、心理、行为特点，以教育为主，坚持因人施教、以理服人、形式多样的教育改造方式；实行依法、科学、文明、直接管理。未成年犯的劳动，应当以学习、掌握技能为主。"},{"i":5,"n":"第五条","txt":"未成年犯管教所应当依法保障未成年犯的合法权益，尊重未成年犯的人格，创造有益于未成年犯身心健康、积极向上的改造环境。 在日常管理中，可以对未成年犯使用“学员”称谓。"},{"i":6,"n":"第六条","txt":"未成年犯管教所应当加强同未成年人保护组织、教育、共青团、妇联、工会等有关部门的联系，共同做好对未成年犯的教育改造工作。"},{"i":7,"n":"第七条","txt":"未成年犯管教所所需经费由国家保障。未成年犯的教育改造费、生活费应高于成年犯。"},{"i":8,"n":"第八条","txt":"各省、自治区、直辖市根据需要设置未成年犯管教所，由司法部批准。"},{"i":9,"n":"第九条","txt":"未成年犯管教所设置管理、教育、劳动、生活卫生、政治工作等机构。 根据对未成年犯的管理需要，实行所、管区两级管理。管区押犯不超过一百五十名。"},{"i":10,"n":"第十条","txt":"未成年犯管教所和管区的人民警察配备比例应当分别高于成年犯监狱和监区。"},{"i":11,"n":"第十一条","txt":"未成年犯管教所的人民警察须具备大专以上文化程度。其中具有法学、教育学、心理学等相关专业学历的应达到百分之四十。"},{"i":12,"n":"第十二条","txt":"未成年犯管教所的人民警察应当忠于职守，秉公执法，文明管理，为人师表。"},{"i":13,"n":"第十三条","txt":"未成年犯管教所除依据《监狱法》第十六条、第十七条的规定执行收监外，对年满十八周岁的罪犯不予收监。"},{"i":14,"n":"第十四条","txt":"收监后，未成年犯管教所应当在五日内通知未成年犯的父母或者其他监护人。"},{"i":15,"n":"第十五条","txt":"对未成年男犯、女犯，应当分别编队关押和管理。未成年女犯由女性人民警察管理。少数民族未成年犯较多的，可单独编队关押和管理。"},{"i":16,"n":"第十六条","txt":"未成年犯管教所按照未成年犯的刑期、犯罪类型，实行分别关押和管理。根据未成年犯的改造表现，在活动范围、通信、会见、收受物品、离所探亲、考核奖惩等方面给予不同的处遇。"},{"i":17,"n":"第十七条","txt":"未成年犯管教所建立警卫机构，负责警戒、看押工作。"},{"i":18,"n":"第十八条","txt":"未成年犯管教所监管区的围墙，可以安装电网。在重要部位安装监控、报警装置。"},{"i":19,"n":"第十九条","txt":"未成年犯管教所应当配备必要的通讯设施、交通工具和警用器材。"},{"i":20,"n":"第二十条","txt":"对未成年犯原则上不使用戒具。如遇有监狱法第四十五条规定的情形之一时，可以使用手铐。"},{"i":21,"n":"第二十一条","txt":"经批准，未成年犯可以与其亲属或者其他监护人通电话，必要时由人民警察监听。"},{"i":22,"n":"第二十二条","txt":"未成年犯会见的时间和次数，可以比照成年犯适当放宽。对改造表现突出的，可准许其与亲属一同用餐或者延长会见时间，最长不超过二十四小时。"},{"i":23,"n":"第二十三条","txt":"未成年犯遇有直系亲属病重、死亡以及家庭发生其他重大变故时，经所长批准，可以准许其回家探望及处理，在家期限最多不超过七天，必要时由人民警察护送。"},{"i":24,"n":"第二十四条","txt":"对未成年犯的档案材料应当严格管理，不得公开和传播，不得向与管理教育或办案无关的人员泄漏。 对未成年犯的采访、报道，须经省、自治区、直辖市监狱管理局批准，且不得披露其姓名、住所、照片及可能推断出该未成年犯的资料。任何组织和个人不得披露未成年犯的隐私。"},{"i":25,"n":"第二十五条","txt":"未成年犯管教所应当依法保障未成年犯的申诉、控告、检举权利。"},{"i":26,"n":"第二十六条","txt":"未成年犯服刑期满，未成年犯管教所应当按期释放，发给释放证明书及路费，通知其亲属接回或者由人民警察送回。"},{"i":27,"n":"第二十七条","txt":"刑满释放的未成年人具备复学、就业条件的，未成年犯管教所应当积极向有关部门介绍情况，提出建议。"},{"i":28,"n":"第二十八条","txt":"对未成年犯的教育采取集体教育与个别教育相结合，课堂教育与辅助教育相结合，所内教育与社会教育相结合的方法。"},{"i":29,"n":"第二十九条","txt":"对未成年犯应当进行思想教育，其内容包括法律常识、所规纪律、形势政策、道德修养、人生观、爱国主义、劳动常识等，所用教材由司法部监狱管理局统编。"},{"i":30,"n":"第三十条","txt":"未成年犯的文化教育列入当地教育发展的总体规划，未成年犯管教所应与当地教育行政部门联系，争取在教育经费、师资培训、业务指导、考试及颁发证书等方面得到支持。"},{"i":31,"n":"第三十一条","txt":"未成年犯管教所应当配备符合国家规定学历的人民警察担任教师，按押犯数百分之四的比例配备。教师实行专业技术职务制度。 禁止罪犯担任教师。"},{"i":32,"n":"第三十二条","txt":"未成年犯管教所应当设立教学楼、实验室、图书室、运动场馆等教学设施，配置教学仪器、图书资料和文艺、体育器材。各管区应当设立谈话室、阅览室、活动室。"},{"i":33,"n":"第三十三条","txt":"对未成年犯进行思想、文化、技术教育的课堂化教学时间，每周不少于二十课时，每年不少于一千课时，文化、技术教育时间不低于总课时数的百分之七十。"},{"i":34,"n":"第三十四条","txt":"对未成年犯的文化教育应当根据其文化程度，分别进行扫盲教育、小学教育、初中教育。采取分年级编班施教，按规定的课程开课，使用经国务院教育行政部门审定的教材。有条件的可以进行高中教育。鼓励完成义务教育的未成年犯自学，组织参加各类自学考试。"},{"i":35,"n":"第三十五条","txt":"对未成年犯的技术教育应当根据其刑期、文化程度和刑满释放后的就业需要，重点进行职业技术教育和技能培训，其课程设置和教学要求可以参照社会同类学校。"},{"i":36,"n":"第三十六条","txt":"对参加文化、技术学习的未成年犯，经考试合格的，由当地教育、劳动行政部门发给相应的毕业或者结业证书及技术证书。"},{"i":37,"n":"第三十七条","txt":"对新入所的未成年犯，应当进行入所教育，其内容包括认罪服法、行为规范和所规纪律教育等；对即将刑满的罪犯在形势、政策、遵纪守法等方面进行出所教育，并在就业、复学等方面给予指导，提供必要的技能培训。入所、出所教育时间各不得少于两个月。"},{"i":38,"n":"第三十八条","txt":"根据未成年犯的案情、刑期、心理特点和改造表现进行有针对性的个别教育，实行教育转化责任制。"},{"i":39,"n":"第三十九条","txt":"未成年犯管教所应当建立心理矫治机构，对未成年犯进行生理、心理健康教育，进行心理测试、心理咨询和心理矫治。 未成年犯管教所应当对未成年犯进行生活常识教育，培养其生活自理能力。"},{"i":40,"n":"第四十条","txt":"未成年犯管教所应当开展文化、娱乐、体育活动，办好报刊、黑板报、广播站、闭路电视等。"},{"i":41,"n":"第四十一条","txt":"定期举行升国旗仪式，开展成人宣誓活动。"},{"i":42,"n":"第四十二条","txt":"根据需要，设立适合未成年犯特点的习艺劳动场所及其设施。"},{"i":43,"n":"第四十三条","txt":"组织未成年犯劳动，应当在工种、劳动强度和保护措施等方面严格执行国家有关规定，不得安排未成年犯从事过重的劳动或者危险作业，不得组织未成年犯从事外役劳动。未满十六周岁的未成年犯不参加生产劳动。 未成年犯的劳动时间，每天不超过四小时，每周不超过二十四小时。"},{"i":44,"n":"第四十四条","txt":"未成年犯管教所应当加强与社会各界的联系，争取更多的社会力量参与对未成年犯的教育帮助。"},{"i":45,"n":"第四十五条","txt":"对未成年犯的社会教育，采取到社会上参观或者参加公益活动，邀请社会各界人士及未成年犯的父母或者其他监护人来所帮教的方法。 未成年犯管教所可以聘请社会知名人士或者有影响的社会志愿者担任辅导员。"},{"i":46,"n":"第四十六条","txt":"未成年犯的父母或者其他监护人应当依法履行监护职责和义务，协助未成年犯管教所做好对未成年犯的教育改造，不得遗弃或者歧视。"},{"i":47,"n":"第四十七条","txt":"未成年犯的生活水平，应当以保证其身体健康发育为最低标准。"},{"i":48,"n":"第四十八条","txt":"未成年犯管教所应当合理配膳，保证未成年犯吃饱、吃得卫生。对有特殊饮食习惯的少数民族罪犯，应当单独设灶配膳；对生病者，在伙食上给予照顾。"},{"i":49,"n":"第四十九条","txt":"未成年犯的被服，须依照规定按时发放。"},{"i":50,"n":"第五十条","txt":"未成年犯以班组为单位住宿，不得睡通铺。人均居住面积不得少于三平方米。"},{"i":51,"n":"第五十一条","txt":"未成年犯管教所应当合理安排作息时间，保证未成年犯每天的睡眠时间不少于八小时。"},{"i":52,"n":"第五十二条","txt":"未成年犯管教所定期安排未成年犯洗澡、理发、洗晒被服。 禁止未成年犯吸烟、喝酒。"},{"i":53,"n":"第五十三条","txt":"经检查批准，未成年犯可以收受学习、生活用品以及钱款，现金由未成年犯管教所登记保管。"},{"i":54,"n":"第五十四条","txt":"对未成年犯的私人财物，未成年犯管教所应当登记、造册，并发给本人收据。"},{"i":55,"n":"第五十五条","txt":"未成年犯管教所在当地卫生主管部门指导下开展医疗、防病工作，设立医疗机构，保证未成年犯有病得到及时治疗，按照“预防为主，防治结合”的要求，做好未成年犯的防疫保健工作，每年进行一次健康检查。"},{"i":56,"n":"第五十六条","txt":"未成年犯管教所设立生活物资供应站，由人民警察负责管理，保证未成年犯日常生活用品的供应。供应站所得收入，用于改善未成年犯的生活。"},{"i":57,"n":"第五十七条","txt":"对未成年犯的减刑、假释，可以比照成年犯依法适度放宽。 对被判处无期徒刑确有悔改表现的未成年犯，一般在执行一年六个月以上即可提出减刑建议。 对被判处有期徒刑确有悔改表现的未成年犯，一般在执行一年以上即可提出减刑建议。 未成年犯两次减刑的间隔时间应在六个月以上。 对未成年犯有《监狱法》第二十九条规定的重大立功表现情形之一的，可以不受前三款所述时间的限制，及时提出减刑建议。"},{"i":58,"n":"第五十八条","txt":"对未成年犯的日常考核，采用日记载、周评议、月小结的方法，由人民警察直接考核。考核的结果应当作为对未成年犯奖惩的依据。"},{"i":59,"n":"第五十九条","txt":"未成年犯有《监狱法》第五十七条情形之一的，未成年犯管教所应当给予表扬、物质奖励或者记功。"},{"i":60,"n":"第六十条","txt":"对被判处有期徒刑的未成年犯在执行原判刑期三分之一以上，服刑期间一贯表现良好，离所后不致再危害社会的，未成年犯管教所可以根据情况准其离所探亲。"},{"i":61,"n":"第六十一条","txt":"未成年犯被批准离所探亲的时间为五至七天(不包括在途时间)，两次探亲的间隔时间至少在六个月以上。离所探亲的未成年犯必须由其父母或者其他监护人接送。"},{"i":62,"n":"第六十二条","txt":"未成年犯有《监狱法》第五十八条规定的破坏监管秩序情形之一的，未成年犯管教所可以给予警告、记过或者禁闭处分；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"对未成年犯实行禁闭的期限为三至七天。未成年犯禁闭期间，每天放风两次，每次不少于一小时。"},{"i":64,"n":"第六十四条","txt":"对于年满十八周岁，余刑不满二年继续留在未成年犯管教所服刑的罪犯，仍适用本规定。"},{"i":65,"n":"第六十五条","txt":"本规定自公布之日起实施，1986年颁布的《少年管教所暂行管理办法(试行)》同时废止。"}],"falvyuanzhutousuchulibanfa":[{"i":1,"n":"第一条","txt":"为规范法律援助投诉处理工作，加强对法律援助工作的指导监督，维护投诉人和被投诉人合法权益，根据《中华人民共和国法律援助法》《中华人民共和国律师法》《法律援助条例》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"司法行政机关开展法律援助投诉处理工作，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称投诉，是指法律援助申请人、受援人或者利害关系人（以下统称投诉人）认为法律援助机构、律师事务所、基层法律服务所和法律援助人员（以下统称被投诉人）在提供法律援助过程中未依法履行职责或者义务，向司法行政机关投诉，请求予以处理的行为。"},{"i":4,"n":"第四条","txt":"法律援助投诉处理工作应当坚持中国共产党的领导，坚持以人民为中心，遵循属地管理、依法公正、处罚与教育相结合的原则。"},{"i":5,"n":"第五条","txt":"司法部指导、监督全国法律援助投诉处理工作。县级以上地方司法行政机关指导、监督本行政区域的法律援助投诉处理工作。 设立法律援助机构的司法行政机关（以下称投诉处理机关），具体负责投诉处理工作。"},{"i":6,"n":"第六条","txt":"司法行政机关应当向社会公示法律援助投诉地址、电话、传真、电子邮箱及投诉事项范围、投诉处理程序等信息，指定专人负责投诉接待和处理工作，并根据实际情况为老年人、残疾人投诉提供无障碍信息交流方式等便利。"},{"i":7,"n":"第七条","txt":"投诉人认为有下列情形之一的，可以向投诉处理机关投诉： （一）法律援助机构、律师事务所、基层法律服务所在提供法律援助过程中未依法履行职责或者义务； （二）法律援助人员接受指派或者安排后，无正当理由拒绝、拖延或者擅自终止提供法律援助服务； （三）法律援助人员未能提供符合标准的法律援助服务； （四）法律援助人员未依法向受援人通报法律援助事项办理情况； （五）被投诉人收取受援人财物； （六）被投诉人泄露法律援助过程中知悉的国家秘密、商业秘密或者个人隐私； （七）法律、法规、规章规定的其他投诉事项。 法律援助申请人、受援人对法律援助机构不予法律援助、终止法律援助的决定提出异议的，按照异议审查相关规定处理。"},{"i":8,"n":"第八条","txt":"投诉人应当自知道或者应当知道被投诉人未依法履行职责或者义务之日起三年内提出投诉。法律另有规定的除外。"},{"i":9,"n":"第九条","txt":"投诉人提出投诉，一般应当采用书面形式，说明投诉人的基本情况、投诉请求、主要事实、理由和时间，如有相关材料，可一并提供。 采用书面形式投诉确有困难的，可以口头或者其他适当方式投诉，投诉处理机关应当当场记录前款规定的相关信息，并由投诉人确认。 被羁押的犯罪嫌疑人、被告人、服刑人员，以及强制隔离戒毒人员等提出法律援助投诉的，办案机关、监管场所应当依法及时转交投诉处理机关。"},{"i":10,"n":"第十条","txt":"投诉人应当如实投诉，对其所提供材料内容真实性负责，不得捏造、歪曲事实，不得诬告、陷害他人。 投诉人不实投诉侵犯被投诉人名誉等合法权益的，依法承担相应法律责任。"},{"i":11,"n":"第十一条","txt":"投诉人或者其法定代理人委托他人代理投诉的，代理人应当提供委托人的授权委托书、代理人的联系方式和委托人、代理人的身份证明。"},{"i":12,"n":"第十二条","txt":"投诉人提供的信息不齐全的，投诉处理机关应当一次性告知投诉人需要补充提供的信息及期限。投诉人经告知后无正当理由逾期不补充的，视为投诉人放弃投诉。"},{"i":13,"n":"第十三条","txt":"符合下列条件的投诉，应当予以受理： （一）具有投诉人主体资格； （二）有明确的被投诉人和投诉请求； （三）有具体的投诉事实和理由； （四）属于本机关管辖范围； （五）属于本办法规定的投诉事项范围。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，不予受理： （一）投诉事项已经依法处理，且没有新的事实和证据的； （二）投诉事项正在通过诉讼等法定程序解决的，或者已被纪检监察等部门受理的； （三）投诉人仅对办案机关、劳动人事争议仲裁机构等依法作出的法律文书有异议的； （四）投诉事项不属于本办法第七条第一款规定情形的。"},{"i":15,"n":"第十五条","txt":"投诉处理机关收到投诉后，应当在五个工作日内作出是否受理的决定，并书面告知投诉人。决定不予受理的，应当一并说明理由。 投诉人补充投诉材料所需的时间，不计算在前款规定期限内。 其他司法行政机关收到投诉的，应当告知投诉人向投诉处理机关提出。"},{"i":16,"n":"第十六条","txt":"投诉处理机关受理投诉后，应当及时调查核实。调查应当全面、客观、公正。必要时，可以委托下级司法行政机关、法律援助人员所在行业协会等单位进行调查。调查工作不得妨碍被投诉人正常的法律援助活动。 调查过程中，投诉人就同一投诉事项，以不同事实、理由和诉求对被投诉人多次提出投诉的，可以合并办理。"},{"i":17,"n":"第十七条","txt":"投诉处理机关可以进行实地调查，要求被投诉人说明情况、提交有关材料，调阅被投诉人有关业务案卷和档案材料，向有关单位、个人核实情况、收集证据；并可以根据需要，组织专家论证或者听取有关部门的意见和建议。 调查应当由两名以上工作人员进行，并制作调查笔录。调查笔录应当由被调查人签名或者盖章；不能或者拒绝签名、盖章的，调查人员应当在笔录中注明有关情况。 调查人员应当对被投诉人及有关单位、个人提供的证据和有关材料进行登记并妥善保管；不能保存原件的，应当保存复印件，并由被投诉人或者有关单位、个人在复印件上签名或者盖章。"},{"i":18,"n":"第十八条","txt":"调查人员与投诉人、被投诉人或者投诉事项有直接利害关系或者有其他关系可能影响公正调查的，应当回避。 投诉人或者被投诉人认为有前款情形的，有权申请回避。投诉人或者被投诉人提出回避申请的，投诉处理机关应当依法审查，由本机关负责人决定是否回避。决定作出之前，不停止调查。"},{"i":19,"n":"第十九条","txt":"投诉处理机关在调查过程中，发现被投诉人的违法违规行为仍处在连续或者继续状态的，应当责令被投诉人立即停止违法违规行为。"},{"i":20,"n":"第二十条","txt":"被投诉人应当配合调查工作，按要求如实陈述事实、提供有关材料，不得提供虚假、伪造的材料或者隐匿、毁损、涂改有关证据材料。 被投诉人为法律援助人员的，其所在的单位应当配合调查。"},{"i":21,"n":"第二十一条","txt":"调查过程中，投诉处理机关发现有本办法第十四条第一项、第三项、第四项规定情形，或者投诉人申请撤回投诉的，投诉处理机关应当终止调查程序，将终止决定和理由书面告知投诉人、被投诉人。 投诉人一般应当采用书面形式申请撤回投诉；采用书面形式确有困难的，可以口头或者其他适当方式申请撤回投诉。 投诉处理机关发现有本办法第十四条第二项规定情形，尚未处理完毕的，应当中止调查，并书面告知投诉人。"},{"i":22,"n":"第二十二条","txt":"投诉处理机关应当根据调查结果，分别作出以下处理： （一）投诉事项查证不实或者无法查实的，对投诉请求不予支持，向投诉人说明情况并向被投诉人反馈调查结果； （二）被投诉人违法违规情节轻微，依法不予行政处罚或者处分的，应当给予批评教育等处理； （三）被投诉人涉嫌违反职业道德、执业纪律和行业规范的，移交有关行业协会等单位核实处理； （四）被投诉人具有应当给予行政处罚行为的，依法给予或者移送有权处理机关给予行政处罚，并责令被投诉人改正或者限期改正违法行为； （五）被投诉人具有应当给予处分行为的，根据违法违纪情形和干部管理权限依法作出处理。 被投诉人涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"投诉处理机关受理投诉后，应当在六十日内办结；投诉事项复杂的，经本机关负责人批准，可以适当延长办理期限，但延长期限不得超过三十日。延长办理期限的，应当将延长的时间和理由告知投诉人。 根据本办法第十六条规定合并办理投诉事项的，办理期限自最后一次投诉受理的时间开始计算。 根据本办法第二十一条第三款规定中止调查的，中止调查期间不计入办理期限。"},{"i":24,"n":"第二十四条","txt":"投诉处理机关应当自作出处理决定之日起五个工作日内，将投诉处理决定以及不服处理决定的法律救济途径和期限等书面告知投诉人、被投诉人。"},{"i":25,"n":"第二十五条","txt":"司法行政机关应当建立投诉处理档案，一事一卷。归档材料包括投诉受理和调查材料、处理决定或者处理意见等。"},{"i":26,"n":"第二十六条","txt":"作出处理决定的投诉处理机关应当对被投诉人执行处理决定的情况进行监督。发现问题的，应当督促其及时纠正。"},{"i":27,"n":"第二十七条","txt":"上级司法行政机关应当加强对下级司法行政机关开展法律援助投诉处理工作的指导和监督。发现投诉处理违法的，应当及时纠正。"},{"i":28,"n":"第二十八条","txt":"司法行政机关应当按年度将法律援助投诉处理工作情况书面报告上一级司法行政机关。 对于涉及重大违法违规行为的投诉处理决定，应当及时报告上一级司法行政机关。"},{"i":29,"n":"第二十九条","txt":"司法行政机关工作人员在投诉处理工作中有滥用职权、玩忽职守或者其他违法违规行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"工会、共产主义青年团、妇女联合会、残疾人联合会等群团组织组织实施法律援助工作和提供法律援助服务，被投诉至司法行政机关的，由同级司法行政机关会同被投诉的群团组织参照本办法处理。"},{"i":31,"n":"第三十一条","txt":"本办法由司法部解释。"},{"i":32,"n":"第三十二条","txt":"本办法自2025年6月15日起施行。司法部2013年11月19日印发的《法律援助投诉处理办法》（司发通〔2013〕161号）同时废止。"}],"falvzhiyezigeguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范法律职业资格申请受理、审查核查、审核认定、证书颁发、服务和管理等工作，根据《中华人民共和国行政许可法》等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"司法行政机关实施法律职业资格管理，应当以习近平法治思想为指导，坚持法律职业队伍革命化、正规化、专业化、职业化方向，建设一支高素质的社会主义法律职业队伍。"},{"i":3,"n":"第三条","txt":"司法行政机关实施法律职业资格管理，应当遵循程序规范、高效便民、公开透明、公平公正的原则。"},{"i":4,"n":"第四条","txt":"司法部负责法律职业资格审核认定、法律职业资格证书制作颁发等工作。 省、自治区、直辖市司法行政机关负责本地法律职业资格申请材料的核查、证书的组织发放等工作。 设区的市级司法行政机关负责本地法律职业资格申请材料的受理、审查和证书发放等工作。"},{"i":5,"n":"第五条","txt":"司法行政机关应当加强法律职业资格管理信息化建设，提高在线服务水平。"},{"i":6,"n":"第六条","txt":"司法行政机关统一受理法律职业资格申请，以公告方式确定统一受理日期。"},{"i":7,"n":"第七条","txt":"符合《国家统一法律职业资格考试实施办法》第十八条规定情形的人员，申请授予法律职业资格的(以下简称申请人)，应当在受理期限内通过司法部网站登录法律职业资格管理系统，如实填写申请授予法律职业资格信息，并到设区的市级或者直辖市司法行政机关(以下简称受理机关)指定的工作场所现场提交下列材料： (一)居民身份证； (二)毕业证书、学位证书或者学历、学位证明书原件； (三)司法部公告要求的其他材料。 申请享受放宽政策并达到放宽条件地区合格分数线的申请人，应当向本人户籍所在地设区的市级司法行政机关申请授予法律职业资格，并现场提交户口簿原件。 申请人应当对其所提交材料的真实性负责。证件原件由受理机关核验并复印或者扫描后退回，复印件或者扫描件留存归档。"},{"i":8,"n":"第八条","txt":"受理机关收到申请人的申请材料后，应当根据下列情况分别作出处理： (一)申请材料齐全、符合法定形式的，或者申请人按照受理机关要求提交全部补正申请材料的，应当受理并向申请人出具法律职业资格申请受理单； (二)申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次告知申请人需要补正的全部材料及内容； (三)不符合法律职业资格申请条件的，应当出具不予受理通知书并说明理由。 具有前款第二项规定等情形的，受理机关可以采用个别受理方式受理法律职业资格申请。"},{"i":9,"n":"第九条","txt":"受理机关应当自统一受理之日起对申请人提交的申请材料进行审查，并将书面审查报告与相关申请材料一并报送省级司法行政机关核查。对申请材料不真实或者不符合法律职业资格授予条件的，应当提交不授予法律职业资格的书面报告并说明理由，报省级司法行政机关核查。 省级司法行政机关应当对申请授予法律职业资格人员的申请材料进行核查，提交授予或者不授予法律职业资格的书面核查报告，报司法部审核认定。 受理机关为直辖市司法行政机关的，由该直辖市司法行政机关对申请授予法律职业资格人员的申请材料进行审查、核查，提交授予或者不授予法律职业资格的书面核查报告，报司法部审核认定。 自受理申请至向司法部报送书面核查报告的期限为二十个工作日。"},{"i":10,"n":"第十条","txt":"受理机关应当将申请授予法律职业资格的依据、条件、程序、期限以及需要提交的全部材料的目录和申请书示范文本等在办公场所和网站上公示。"},{"i":11,"n":"第十一条","txt":"司法部应当自收到省级司法行政机关书面核查报告等材料之日起二十个工作日内完成审核认定，根据下列情况分别作出处理： (一)符合《国家统一法律职业资格考试实施办法》第十八条规定的法律职业资格授予条件的，作出授予法律职业资格的决定，颁发法律职业资格证书； (二)不符合法律职业资格授予条件的，作出不授予法律职业资格的决定，并说明理由。 按照前款规定期限不能完成审核认定的，经司法部负责人批准，可以延长十个工作日。延长期限的理由以司法部公告统一告知申请人。"},{"i":12,"n":"第十二条","txt":"司法部根据下列情形，授予申请人法律职业资格，并颁发相应的法律职业资格证书： (一)符合《国家统一法律职业资格考试实施办法》第九条、第二十二条规定的条件，考试成绩达到全国统一合格分数线的，颁发A类法律职业资格证书； (二)符合《国家统一法律职业资格考试实施办法》第二十三条规定的条件，申请享受放宽政策，考试成绩达到全国统一合格分数线的，颁发B类法律职业资格证书； (三)符合《国家统一法律职业资格考试实施办法》第九条、第二十二条、第二十三条规定的条件，申请享受放宽政策，考试成绩达到放宽条件地区合格分数线的，颁发C类法律职业资格证书。"},{"i":13,"n":"第十三条","txt":"司法部应当自作出授予法律职业资格决定之日起十个工作日内颁发法律职业资格证书。 省、自治区、直辖市司法行政机关具体负责法律职业资格证书的组织发放，并将相关情况载入档案。"},{"i":14,"n":"第十四条","txt":"取得C类法律职业资格证书人员，重新参加国家统一法律职业资格考试，达到全国统一合格分数线的，可以申请授予A类或者B类法律职业资格证书，并向司法行政机关交回已取得的C类法律职业资格证书，原证书自作出授予新的法律职业资格决定之日起自动失效。"},{"i":15,"n":"第十五条","txt":"A类法律职业资格证书在全国范围内有效。B类和C类法律职业资格证书的适用范围，由国家统一法律职业资格考试协调委员会确定。 取得B类法律职业资格证书人员，在获得《国家统一法律职业资格考试实施办法》第九条规定的专业学历条件后，其B类法律职业资格证书在全国范围内有效。"},{"i":16,"n":"第十六条","txt":"法律职业资格证书采用纸质证书和电子证书形式，由设区的市级及以上司法行政机关实施管理。 法律职业资格证书的样式，由司法部统一制定。 法律职业资格纸质证书与电子证书具有同等法律效力。"},{"i":17,"n":"第十七条","txt":"取得法律职业资格人员应当妥善保管和使用法律职业资格证书，不得涂改、倒卖、出租、出借和转让。"},{"i":18,"n":"第十八条","txt":"取得法律职业资格人员遗失、损毁纸质证书的，可以向设区的市级司法行政机关申请办理法律职业资格证明书。 法律职业资格证明书与法律职业资格证书具有同等法律效力。"},{"i":19,"n":"第十九条","txt":"司法行政机关应当建立取得法律职业资格人员档案，实行纸质档案和电子档案形式，由设区的市级及以上司法行政机关管理，并及时记载、更新相关信息。 档案主要记载下列内容： (一)考试报名信息、本办法第七条规定的相关申请材料； (二)法律职业资格证书种类、取得时间和撤销、注销法律职业资格情况； (三)调转档案情况； (四)办理法律职业资格证明书情况； (五)参加职前培训情况； (六)其他应当载入档案的情况。"},{"i":20,"n":"第二十条","txt":"司法部公布授予法律职业资格有关信息，供有关部门和社会公众查询。"},{"i":21,"n":"第二十一条","txt":"取得法律职业资格人员需要调转档案的，由本人通过法律职业资格管理系统向调入地司法行政机关提出申请，办理变更手续。"},{"i":22,"n":"第二十二条","txt":"通过贿赂或者使用虚假身份证件、学历和学位证件以及其他证明文件等不正当手段取得法律职业资格的，由司法部依法予以撤销，并办理注销手续。 具有前款规定情形的，依法移送有关部门追究法律责任。"},{"i":23,"n":"第二十三条","txt":"伪造、变造或者使用伪造、变造的法律职业资格证书、法律职业资格证明书的，依法追究法律责任。"},{"i":24,"n":"第二十四条","txt":"司法行政机关作出不予受理申请、不予授予法律职业资格或者撤销法律职业资格等处理决定的，应当告知相对人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":25,"n":"第二十五条","txt":"参加国家统一法律职业资格考试成绩合格的港澳台居民，申请授予法律职业资格及其管理，适用本办法。"},{"i":26,"n":"第二十六条","txt":"实行国家统一法律职业资格考试前取得的法律职业资格证书、律师资格凭证，与参加国家统一法律职业资格考试取得的法律职业资格证书具有同等法律效力。 对参加国家司法考试取得的法律职业资格的管理，适用本办法。"},{"i":27,"n":"第二十七条","txt":"本办法由司法部负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自2021年1月1日起施行。2002年7月8日公布的《法律职业资格证书管理办法》(司法部令第74号)同时废止。"}],"yuneixingshianjianlianbiaozhun":[{"i":1,"n":"第一条","txt":"为了及时打击狱内在押罪犯的又犯罪活动，确保监狱的安全稳定，根据中华人民共和国《刑法》、《刑事诉讼法》、《监狱法》的有关规定，针对狱内又犯罪活动的特点，制定本标准。"},{"i":2,"n":"第二条","txt":"监狱发现罪犯有下列犯罪情形的，应当立案侦查： (一)煽动分裂国家、破坏国家统一的(煽动分裂国家案)。 (二)以造谣、诽谤或其他方式煽动颠覆国家政权、推翻社会主义制度的(煽动颠覆国家政权案)。 (三)故意放火破坏监狱监管设施、生产设施、生活设施，危害监狱安全的(放火案)。 (四)爆炸破坏监狱监管设施、生产设施、生活设施，危害监狱安全的(爆炸案)。 (五)投毒破坏生活设施，危害监狱安全的(投毒案)。 (六)非法制作、储存或藏匿枪支的(非法制造、储存枪支案)。 (七)以各种手段窃取枪支、弹药、爆炸物的(盗窃枪支、弹药、爆炸物案)。 (八)抢夺枪支、弹药、爆炸物的(抢夺枪支、弹药、爆炸物案)。 (九)故意非法剥夺他人生命的(故意杀人案)。 (十)过失致人死亡的(过失致人死亡案)。 (十一)故意伤害他人身体的(故意伤害案)。 (十二)过失伤害他人致人重伤的(过失致人重伤案)。 (十三)以暴力、胁"},{"i":3,"n":"第三条","txt":"情节、后果严重的下列案件，列为重大案件： (一)组织从事危害国家安全活动的犯罪集团,情节严重的。 (二)放火、决水、爆炸、投毒或以其他危险方法危害监狱安全，造成人员伤亡或者直接经济损失5000元至30000元的。 (三)非法制造、储存枪支、弹药、爆炸物的。 (四)故意杀人致死或致重伤的。 (五)故意伤害他人致死的。 (六)强奸妇女既遂，或者奸淫幼女的。 (七)以挟持人质等暴力手段脱逃，造成人员重伤的。 (八)煽动民族仇恨、民族歧视，情节特别严重的。 (九)盗窃、诈骗、抢夺、敲诈勒索，数额在5000元至30000元的。 (十)十人以上聚众斗殴或者聚众斗殴致三名以上罪犯重伤的。 (十一)破坏监管秩序，情节恶劣、后果严重的。 (十二)罪犯三人以上集体脱逃的。 (十三)尚未减刑的死缓犯、无期徒刑犯脱逃的；剩余执行刑期15年以上的罪犯脱逃的；其他被列为重要案犯的罪犯脱逃的。 (十四)暴动越狱的。"},{"i":4,"n":"第四条","txt":"情节恶劣、后果特别严重的下列案件，列为特别重大案件： (一)组织从事危害国家安全活动的犯罪集团，或进行其他危害国家安全的犯罪活动，影响恶劣，情节特别严重的。 (二)案件中一次杀死二名以上罪犯，或者重伤四名以上罪犯，或者杀害监狱警察、武装警察、工人及其家属的。 (三)暴动越狱，造成死亡一人以上，或者重伤三人以上的，或者影响恶劣的。 (四)盗窃、抢夺、抢劫枪支弹药的。 (五)放火、爆炸、投毒，致死二人以上或者造成直接经济损失30000元以上的。 (六)盗窃、诈骗、抢夺、敲诈勒索、故意毁坏公私财物，数额在30000元以上的。 (七)强奸妇女，致人重伤、死亡或者其他严重后果的，或者轮奸妇女的。 (八)挟持人质，造成人质死亡的。 (九)贩卖鸦片1000克以上、海洛因或者甲基苯丙胺50克以上或者其它毒品数量大的。 (十)司法部认为需要列为特别重大案件的。"},{"i":5,"n":"第五条","txt":"本规定中的公私财物价值数额、直接经济损失数额以及毒品数量，可在规定的数额、数量幅度内，执行本省(自治区、直辖市)高级人民法院确定的标准。"},{"i":6,"n":"第六条","txt":"本标准由司法部解释。"},{"i":7,"n":"第七条","txt":"本标准自发布之日起施行。司法部于1987年发布的《司法部关于狱内案件立案标准的规定(试行)》同日废止。"}],"jianyutiqingjianxingjiashigongzuochengxuguiding":[{"i":1,"n":"第一条","txt":"为规范监狱提请减刑、假释工作程序，根据《中华人民共和国刑法》、《中华人民共和国刑事诉讼法》、《中华人民共和国监狱法》等有关规定，结合刑罚执行工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"监狱提请减刑、假释，应当根据法律规定的条件和程序进行，遵循公开、公平、公正的原则，严格实行办案责任制。"},{"i":3,"n":"第三条","txt":"被判处有期徒刑和被减刑为有期徒刑的罪犯的减刑、假释，由监狱提出建议，提请罪犯服刑地的中级人民法院裁定。"},{"i":4,"n":"第四条","txt":"被判处死刑缓期二年执行的罪犯的减刑，被判处无期徒刑的罪犯的减刑、假释，由监狱提出建议，经省、自治区、直辖市监狱管理局审核同意后，提请罪犯服刑地的高级人民法院裁定。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市监狱管理局和监狱分别成立减刑假释评审委员会，由分管领导及刑罚执行、狱政管理、教育改造、狱内侦查、生活卫生、劳动改造、政工、监察等有关部门负责人组成，分管领导任主任。监狱管理局、监狱减刑假释评审委员会成员不得少于9人。"},{"i":6,"n":"第六条","txt":"监狱提请减刑、假释，应当由分监区或者未设分监区的监区人民警察集体研究，监区长办公会议审核，监狱刑罚执行部门审查，监狱减刑假释评审委员会评审，监狱长办公会议决定。 省、自治区、直辖市监狱管理局刑罚执行部门审查监狱依法定程序提请的减刑、假释建议并出具意见，报请分管副局长召集减刑假释评审委员会审核后，报局长审定，必要时可以召开局长办公会议决定。"},{"i":7,"n":"第七条","txt":"提请减刑、假释，应当根据法律规定的条件，结合罪犯服刑表现，由分监区人民警察集体研究，提出提请减刑、假释建议，报经监区长办公会议审核同意后，由监区报送监狱刑罚执行部门审查。 直属分监区或者未设分监区的监区，由直属分监区或者监区人民警察集体研究，提出提请减刑、假释建议，报送监狱刑罚执行部门审查。 分监区、直属分监区或者未设分监区的监区人民警察集体研究以及监区长办公会议审核情况，应当有书面记录，并由与会人员签名。"},{"i":8,"n":"第八条","txt":"监区或者直属分监区提请减刑、假释，应当报送下列材料： (一)《罪犯减刑(假释)审核表》； (二)监区长办公会议或者直属分监区、监区人民警察集体研究会议的记录； (三)终审法院裁判文书、执行通知书、历次减刑裁定书的复印件； (四)罪犯计分考核明细表、罪犯评审鉴定表、奖惩审批表和其他有关证明材料； (五)罪犯确有悔改表现或者立功、重大立功表现的具体事实的书面证明材料。"},{"i":9,"n":"第九条","txt":"监狱刑罚执行部门收到监区或者直属分监区对罪犯提请减刑、假释的材料后，应当就下列事项进行审查： (一)需提交的材料是否齐全、完备、规范； (二)罪犯确有悔改或者立功、重大立功表现的具体事实的书面证明材料是否来源合法； (三)罪犯是否符合法定减刑、假释的条件； (四)提请减刑、假释的建议是否适当。 经审查，对材料不齐全或者不符合提请条件的，应当通知监区或者直属分监区补充有关材料或者退回；对相关材料有疑义的，应当提讯罪犯进行核查；对材料齐全、符合提请条件的，应当出具审查意见，连同监区或者直属分监区报送的材料一并提交监狱减刑假释评审委员会评审。提请罪犯假释的，还应当委托县级司法行政机关对罪犯假释后对所居住社区影响进行调查评估，并将调查评估报告一并提交。"},{"i":10,"n":"第十条","txt":"监狱减刑假释评审委员会应当召开会议，对刑罚执行部门审查提交的提请减刑、假释建议进行评审，提出评审意见。会议应当有书面记录，并由与会人员签名。 监狱可以邀请人民检察院派员列席减刑假释评审委员会会议。"},{"i":11,"n":"第十一条","txt":"监狱减刑假释评审委员会经评审后，应当将提请减刑、假释的罪犯名单以及减刑、假释意见在监狱内公示。公示内容应当包括罪犯的个人情况、原判罪名及刑期、历次减刑情况、提请减刑假释的建议及依据等。公示期限为5个工作日。公示期内，如有监狱人民警察或者罪犯对公示内容提出异议，监狱减刑假释评审委员会应当进行复核，并告知复核结果。"},{"i":12,"n":"第十二条","txt":"监狱应当在减刑假释评审委员会完成评审和公示程序后，将提请减刑、假释建议送人民检察院征求意见。征求意见后，监狱减刑假释评审委员会应当将提请减刑、假释建议和评审意见连同人民检察院意见，一并报请监狱长办公会议审议决定。监狱对人民检察院意见未予采纳的，应当予以回复，并说明理由。"},{"i":13,"n":"第十三条","txt":"监狱长办公会议决定提请减刑、假释的，由监狱长在《罪犯减刑(假释)审核表》上签署意见，加盖监狱公章，并由监狱刑罚执行部门根据法律规定制作《提请减刑建议书》或者《提请假释建议书》，连同有关材料一并提请人民法院裁定。人民检察院对提请减刑、假释提出的检察意见，应当一并移送受理减刑、假释案件的人民法院。 对本规定第四条所列罪犯决定提请减刑、假释的，监狱应当将《罪犯减刑(假释)审核表》连同有关材料报送省、自治区、直辖市监狱管理局审核。"},{"i":14,"n":"第十四条","txt":"监狱在向人民法院提请减刑、假释的同时，应当将提请减刑、假释的建议书副本抄送人民检察院。"},{"i":15,"n":"第十五条","txt":"监狱提请人民法院裁定减刑、假释，应当提交下列材料： (一)《提请减刑建议书》或者《提请假释建议书》； (二)终审法院裁判文书、执行通知书、历次减刑裁定书的复印件； (三)罪犯计分考核明细表、评审鉴定表、奖惩审批表； (四)罪犯确有悔改或者立功、重大立功表现的具体事实的书面证明材料； (五)提请假释的，应当附有县级司法行政机关关于罪犯假释后对所居住社区影响的调查评估报告； (六)根据案件情况需要提交的其他材料。 对本规定第四条所列罪犯提请减刑、假释的，应当同时提交省、自治区、直辖市监狱管理局签署意见的《罪犯减刑(假释)审核表》。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市监狱管理局刑罚执行部门收到监狱报送的提请减刑、假释建议的材料后，应当进行审查。审查中发现监狱报送的材料不齐全或者有疑义的，应当通知监狱补充有关材料或者作出说明。审查无误后，应当出具审查意见，报请分管副局长召集评审委员会进行审核。"},{"i":17,"n":"第十七条","txt":"监狱管理局分管副局长主持完成审核后，应当将审核意见报请局长审定；分管副局长认为案件重大或者有其他特殊情况的，可以建议召开局长办公会议审议决定。 监狱管理局审核同意对罪犯提请减刑、假释的，由局长在《罪犯减刑(假释)审核表》上签署意见，加盖监狱管理局公章。"},{"i":18,"n":"第十八条","txt":"人民法院开庭审理减刑、假释案件的，监狱应当派员参加庭审，宣读提请减刑、假释建议书并说明理由，配合法庭核实相关情况。"},{"i":19,"n":"第十九条","txt":"分监区、直属分监区或者未设分监区的监区人民警察集体研究会议、监区长办公会议、监狱评审委员会会议、监狱长办公会议、监狱管理局评审委员会会议、监狱管理局局长办公会议的记录和本规定第十五条所列的材料，应当存入档案并永久保存。"},{"i":20,"n":"第二十条","txt":"违反法律规定和本规定提请减刑、假释，涉嫌违纪的，依照有关处分规定追究相关人员责任；涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"监狱办理职务犯罪罪犯减刑、假释案件，应当按照有关规定报请备案审查。"},{"i":22,"n":"第二十二条","txt":"本规定自2014年12月1日起施行。"}],"jianyujiaoyugaizaogongzuoguiding":[{"i":1,"n":"第一条","txt":"为了规范监狱教育改造工作，提高教育改造质量，根据《中华人民共和国监狱法》和有关法律、法规的规定，结合监狱教育改造工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"监狱教育改造工作是刑罚执行活动的重要组成部分，是改造罪犯的基本手段之一，是监狱工作法制化、科学化、社会化的重要体现，贯穿于监狱工作的全过程。"},{"i":3,"n":"第三条","txt":"监狱教育改造工作的任务，是通过各种有效的途径和方法，教育罪犯认罪悔罪，自觉接受改造，增强法律意识和道德素养，掌握一定的文化知识和劳动技能，将其改造成为守法公民。"},{"i":4,"n":"第四条","txt":"监狱教育改造工作，应当根据罪犯的犯罪类型、犯罪原因、恶性程度及其思想、行为、心理特征，坚持因人施教、以理服人、循序渐进、注重实效的原则。"},{"i":5,"n":"第五条","txt":"监狱教育改造工作主要包括：入监教育；个别教育；思想、文化、技术教育；监区文化建设；社会帮教；心理矫治；评选罪犯改造积极分子；出监教育等。"},{"i":6,"n":"第六条","txt":"监狱教育改造工作，应当坚持集体教育与个别教育相结合，课堂教育与辅助教育相结合，常规教育与专题教育相结合，狱内教育与社会教育相结合。"},{"i":7,"n":"第七条","txt":"监狱应当设立教育改造场所，包括教室、谈话室、文体活动室、图书室、阅览室、电化教育室、心理咨询室等，并配备相应的设施。"},{"i":8,"n":"第八条","txt":"监狱用于罪犯教育改造的经费，按照国家规定的有关标准执行。少数民族罪犯、未成年犯的教育改造经费应予提高。"},{"i":9,"n":"第九条","txt":"对新入监的罪犯，应当将其安排在负责新收分流罪犯的监狱或者监区，集中进行为期两个月的入监教育。"},{"i":10,"n":"第十条","txt":"新收罪犯入监后，监狱(监区)应当向其宣布罪犯在服刑期间享有的权利和应当履行的义务： (一)罪犯在服刑期间享有下列权利：人格不受侮辱，人身安全和合法财产不受侵犯，享有辩护、申诉、控告、检举以及其他未被依法剥夺或者限制的权利。 (二)罪犯在服刑期间应当履行下列义务：遵守国家法律、法规和监规纪律，服从管理，接受教育改造，按照规定参加劳动。"},{"i":11,"n":"第十一条","txt":"监狱(监区)对新收罪犯，应当进行法制教育和监规纪律教育，引导其认罪悔罪，明确改造目标，适应服刑生活。"},{"i":12,"n":"第十二条","txt":"监狱(监区)应当了解和掌握新收罪犯的基本情况、认罪态度和思想动态，进行个体分析和心理测验，对其危险程度、恶性程度、改造难度进行评估，提出关押和改造的建议。"},{"i":13,"n":"第十三条","txt":"入监教育结束后，监狱(监区)应当对新收罪犯进行考核验收。对考核合格的，移送相应类别的监狱(监区)服刑改造；对考核不合格的，应当延长入监教育，时限为一个月。"},{"i":14,"n":"第十四条","txt":"监狱应当根据每一名罪犯的具体情况，安排监狱人民警察对其进行有针对性的个别教育。"},{"i":15,"n":"第十五条","txt":"个别教育应当坚持法制教育与道德教育相结合，以理服人与以情感人相结合，戒之以规与导之以行相结合，内容的针对性与形式的灵活性相结合，解决思想问题与解决实际问题相结合。"},{"i":16,"n":"第十六条","txt":"监狱各监区的人民警察对所管理的罪犯，应当每月至少安排一次个别谈话教育。"},{"i":17,"n":"第十七条","txt":"罪犯有下列情形之一的，监狱人民警察应当及时对其进行个别谈话教育： (一)新入监或者服刑监狱、监区变更时； (二)处遇变更或者劳动岗位调换时； (三)受到奖励或者惩处时； (四)罪犯之间产生矛盾或者发生冲突时； (五)离监探亲前后或者家庭出现变故时； (六)无人会见或者家人长时间不与其联络时； (七)行为反常、情绪异常时； (八)主动要求谈话时； (九)暂予监外执行、假释或者刑满释放出监前； (十)其他需要进行个别谈话教育的。"},{"i":18,"n":"第十八条","txt":"监狱人民警察对罪犯进行个别谈话教育，应当认真做好记录，并根据罪犯的思想状况和动态，采取有针对性的教育改造措施。"},{"i":19,"n":"第十九条","txt":"监狱应当建立罪犯思想动态分析制度，并根据分析情况，组织开展有针对性的专题教育。 分监区每周分析一次，监区每半月分析一次，监狱每月分析一次；遇有重大事件，应当随时收集、分析罪犯的思想动态。分析的情况应当逐级上报。"},{"i":20,"n":"第二十条","txt":"监狱应当根据罪犯的犯罪类型，结合罪犯的危险程度、恶性程度、接受能力，对罪犯进行分类，开展分类教育。"},{"i":21,"n":"第二十一条","txt":"监狱应当建立对顽固型罪犯(简称顽固犯)和危险型罪犯(简称危险犯)的认定和教育转化制度。 有下列情形之一的，认定为顽固犯： (一)拒不认罪、无理缠诉的； (二)打击先进、拉拢落后、经常散布反改造言论的； (三)屡犯监规、经常打架斗殴、抗拒管教的； (四)无正当理由经常逃避学习和劳动的； (五)其他需要认定为顽固犯的。 有下列情形之一的，认定为危险犯： (一)有自伤、自残、自杀危险的； (二)有逃跑、行凶、破坏等犯罪倾向的； (三)有重大犯罪嫌疑的； (四)隐瞒真实姓名、身份的； (五)其他需要认定为危险犯的。"},{"i":22,"n":"第二十二条","txt":"监狱应当对顽固犯、危险犯制定有针对性的教育改造方案，建立教育转化档案，指定专人负责教育转化工作。必要时，可以采取集体攻坚等方式。"},{"i":23,"n":"第二十三条","txt":"顽固犯和危险犯的认定与撤销，由监区或者直属分监区集体研究，提出意见，分别报监狱教育改造、狱政管理部门审核，由主管副监狱长审定。"},{"i":24,"n":"第二十四条","txt":"监狱应当办好文化技术学校，对罪犯进行思想、文化、技术教育。 成年罪犯的教学时间，每年不少于500课时；未成年犯的教学时间，每年不少于1000课时。"},{"i":25,"n":"第二十五条","txt":"罪犯必须接受监狱组织的思想教育。思想教育包括以下内容： (一)认罪悔罪教育； (二)法律常识教育； (三)公民道德教育； (四)劳动常识教育； (五)时事政治教育。"},{"i":26,"n":"第二十六条","txt":"监狱组织的文化教育，应当根据罪犯不同的文化程度，分别开展扫盲、小学、初中文化教育，有条件的可以开展高中(中专)教育。鼓励罪犯自学，参加电大、函大、高等教育自学考试，并为他们参加学习和考试提供必要的条件。 尚未完成国家规定的九年制义务教育，年龄不满45周岁，能够坚持正常学习的罪犯，应当接受义务教育；已完成义务教育或者年龄在45周岁以上的罪犯，鼓励其参加其他文化学习。"},{"i":27,"n":"第二十七条","txt":"监狱应当根据罪犯在狱内劳动的岗位技能要求和刑满释放后就业的需要，组织罪犯开展岗位技术培训和职业技能教育。 年龄不满50周岁，没有一技之长，能够坚持正常学习的罪犯，应当参加技术教育；有一技之长的，可以按照监狱的安排，选择学习其他技能。"},{"i":28,"n":"第二十八条","txt":"监狱组织开展思想、文化、技术教育，其教员可以从本监狱的人民警察中选任，也可以从社会上符合条件的人员中聘任。 对罪犯的文化、技术教育，可以在本监狱选择服刑表现较好、有文化技术专长的罪犯协助。"},{"i":29,"n":"第二十九条","txt":"监狱应当积极与当地教育、劳动和社会保障行政部门以及就业培训机构联系，在狱内文化、技术教育的专业设置、教学安排、师资培训、外聘教师、教研活动、考试(考核)和颁发学历、学位(资格)证书等方面取得支持和帮助。"},{"i":30,"n":"第三十条","txt":"监狱应当积极利用社会资源，开展罪犯文化、技术教育，根据罪犯刑满释放后的就业需要，开设不同内容、种类的培训班。"},{"i":31,"n":"第三十一条","txt":"监狱对罪犯开展的思想教育和扫盲、小学、初中文化教育，使用司法部监狱管理局统一编写的教材。"},{"i":32,"n":"第三十二条","txt":"监狱应当组织罪犯开展丰富多彩的文化、体育等活动，加强监区文化建设，创造有益于罪犯身心健康和发展的改造环境。"},{"i":33,"n":"第三十三条","txt":"监狱应当办好图书室、阅览室、墙报、黑板报，组织开展经常性的读书、评报活动。 监狱图书室藏书人均不少于10本。"},{"i":34,"n":"第三十四条","txt":"监狱应当根据自身情况，成立多种形式的文艺表演队、体育运动队等，组织罪犯开展文艺、体育活动。"},{"i":35,"n":"第三十五条","txt":"监狱应当根据条件，组织罪犯学习音乐、美术、书法等，开展艺术和美育教育。"},{"i":36,"n":"第三十六条","txt":"监狱应当建立电化教育系统、广播室，各分监区要配备电视，组织罪犯收听、收看新闻及其他有益于罪犯改造的广播、影视节目。"},{"i":37,"n":"第三十七条","txt":"监狱应当根据教育改造罪犯的需要，美化监区环境，规范监区环境布置。"},{"i":38,"n":"第三十八条","txt":"监狱应当在国庆节、国际劳动节、元旦、春节和重大庆祝、纪念活动，以及每月的第一天，组织罪犯参加升挂国旗仪式。"},{"i":39,"n":"第三十九条","txt":"监狱应当积极争取社会各个方面和社会各界人士的支持，配合监狱开展有益于罪犯改造的各种社会帮教活动。"},{"i":40,"n":"第四十条","txt":"监狱应当与罪犯原所在地的政府、原单位(学校)、亲属联系，签订帮教协议，适时邀请有关单位和人士来监狱开展帮教工作；监狱也可以组织罪犯到社会上参观学习，接受教育。"},{"i":41,"n":"第四十一条","txt":"监狱应当鼓励和支持社会志愿者参与对罪犯进行思想、文化、技术教育等方面的帮教活动，并为其帮教活动提供便利。"},{"i":42,"n":"第四十二条","txt":"监狱应当为罪犯获得法律援助提供帮助，联系、协调当地法律援助机构为罪犯提供法律援助服务。"},{"i":43,"n":"第四十三条","txt":"监狱应当开展对罪犯的心理矫治工作。心理矫治工作包括：心理健康教育，心理测验，心理咨询和心理疾病治疗。"},{"i":44,"n":"第四十四条","txt":"监狱应当建立心理矫治室，配置必要的设备，由专业人员对罪犯进行心理矫治。"},{"i":45,"n":"第四十五条","txt":"监狱应当对罪犯进行心理健康教育，宣传心理健康知识，使罪犯对心理问题学会自我调节、自我矫治。"},{"i":46,"n":"第四十六条","txt":"监狱应当在罪犯入监教育、服刑改造中期、出监教育期间对罪犯进行心理测验，建立心理档案，为开展有针对性的思想教育和心理矫治提供参考，对重新犯罪的倾向进行预测。"},{"i":47,"n":"第四十七条","txt":"监狱应当配备专门人员，对罪犯提供心理咨询服务，解答罪犯提出的心理问题。"},{"i":48,"n":"第四十八条","txt":"监狱对有心理疾病的罪犯，应当实施治疗；对病情严重的，应当组织有关专业人员会诊，进行专门治疗。"},{"i":49,"n":"第四十九条","txt":"监狱从事心理测验、心理咨询工作的人员应当具备以下条件： (一)取得心理咨询员、心理咨询师、高级心理咨询师等国家职业资格证书； (二)具有强烈的事业心和高度的责任感； (三)具有良好的品行和职业道德。 监狱可以聘请社会专业人员参与对罪犯的心理矫治工作。"},{"i":50,"n":"第五十条","txt":"监狱应当采取措施，激励罪犯接受改造，在教育改造工作中注重发挥改造积极分子的典型示范作用。"},{"i":51,"n":"第五十一条","txt":"监狱和省、自治区、直辖市监狱管理局应当每年分别组织评选本监狱和本地区的改造积极分子。 改造积极分子的条件：认罪悔罪，积极改造；自觉遵守法律、法规、规章和监规纪律；讲究文明礼貌，乐于助人；认真学习文化知识和劳动技能，成绩突出；积极参加劳动，完成劳动任务；达到计分考核奖励条件。"},{"i":52,"n":"第五十二条","txt":"监狱评选改造积极分子，应当在完成年终评审的基础上，由分监区召集罪犯集体评议推荐，全体警察集体研究，报监区长办公会审议，确定人选。直属分监区或者未设分监区的监区，其人选由分监区或者监区召集罪犯集体评议推荐，全体警察集体研究确定。 监区或者直属分监区确定人选后，填写《改造积极分子审批表》，报监狱教育改造部门审核，在本监狱内履行公示程序后，提交监狱长办公会审定。"},{"i":53,"n":"第五十三条","txt":"监狱对改造积极分子人选实行公示的期限为七个工作日。公示期内，如有监狱人民警察或者罪犯对人选提出异议，由监狱教育改造部门进行复核，并告知复核结果。"},{"i":54,"n":"第五十四条","txt":"省、自治区、直辖市监狱管理局评选本地区改造积极分子，由监狱根据下达的名额，从连续两年被评为监狱改造积极分子的罪犯中提出人选，报监狱管理局教育改造部门审核，由局长办公会审定。"},{"i":55,"n":"第五十五条","txt":"监狱对即将服刑期满的罪犯，应当集中进行出监教育，时限为三个月。"},{"i":56,"n":"第五十六条","txt":"监狱组织出监教育，应当对罪犯进行形势、政策、前途教育，遵纪守法教育和必要的就业指导，开展多种类型、比较实用的职业技能培训，增强罪犯回归社会后适应社会、就业谋生的能力。"},{"i":57,"n":"第五十七条","txt":"监狱应当邀请当地公安、劳动和社会保障、民政、工商、税务等部门，向罪犯介绍有关治安、就业、安置、社会保障等方面的政策和情况，教育罪犯做好出监后应对各方面问题的思想准备，使其顺利回归社会。"},{"i":58,"n":"第五十八条","txt":"监狱应当根据罪犯在服刑期间的考核情况、奖惩情况、心理测验情况，对其改造效果进行综合评估，具体评价指标、评估方法，另行规定。"},{"i":59,"n":"第五十九条","txt":"监狱应当在罪犯刑满前一个月，将其在监狱服刑改造的评估意见、刑满释放的时间，本人职业技能特长和回归社会后的择业意向，以及对地方做好安置帮教工作的建议，填入《刑满释放人员通知书》，寄送服刑人员原户籍所在地的县级公安机关和司法行政机关。"},{"i":60,"n":"第六十条","txt":"监狱应当对刑满释放人员回归社会后的情况进行了解，评估教育改造工作的质量和效果，总结推广教育改造工作的成功经验，不断提高监狱教育改造工作的质量。"},{"i":61,"n":"第六十一条","txt":"对未成年犯的教育改造工作，依照《未成年犯管教所管理规定》(司法部令第56号)的有关规定执行；未作规定的，依照本规定执行。"},{"i":62,"n":"第六十二条","txt":"本规定由司法部解释。"},{"i":63,"n":"第六十三条","txt":"本规定自2003年8月1日起施行。"}],"jianyufuxingrenyuanxingweiguifan":[{"i":1,"n":"第一条","txt":"拥护宪法，遵守法律法规规章和监规纪律。"},{"i":2,"n":"第二条","txt":"服从管理，接受教育，参加劳动，认罪悔罪。"},{"i":3,"n":"第三条","txt":"爱祖国，爱人民，爱集体，爱学习，爱劳动。"},{"i":4,"n":"第四条","txt":"明礼诚信，互助友善，勤俭自强。"},{"i":5,"n":"第五条","txt":"依法行使权利，采用正当方式和程序维护个人合法权益。"},{"i":6,"n":"第六条","txt":"服刑期间严格遵守下列纪律： (一)不超越警戒线和规定区域、脱离监管擅自行动； (二)不私藏现金、刃具等违禁品； (三)不私自与外界人员接触，索取、借用、交换、传递钱物； (四)不在会见时私传信件、现金等物品； (五)不擅自使用绝缘、攀援、挖掘物品； (六)不偷窃、赌博； (七)不打架斗殴、自伤自残； (八)不拉帮结伙、欺压他人； (九)不传播犯罪手段、怂恿他人犯罪； (十)不习练、传播有害气功、邪教。"},{"i":7,"n":"第七条","txt":"按时起床，有秩序洗漱、如厕，衣被等个人物品摆放整齐。"},{"i":8,"n":"第八条","txt":"按要求穿着囚服，佩戴统一标识。"},{"i":9,"n":"第九条","txt":"按时清扫室内外卫生，保持环境整洁。"},{"i":10,"n":"第十条","txt":"保持个人卫生，按时洗澡、理发、剃须、剪指甲，衣服、被褥定期换洗。"},{"i":11,"n":"第十一条","txt":"按规定时间、地点就餐，爱惜粮食，不乱倒剩余饭菜。"},{"i":12,"n":"第十二条","txt":"集体行进时，听从警官指挥，保持队形整齐。"},{"i":13,"n":"第十三条","txt":"不饮酒，不违反规定吸烟。"},{"i":14,"n":"第十四条","txt":"患病时向警官报告，看病时遵守纪律，配合治疗。不私藏药品。"},{"i":15,"n":"第十五条","txt":"需要进入警官办公室时，在门外报告，经允许后进入。"},{"i":16,"n":"第十六条","txt":"在野外劳动现场需要向警官反映情况时，在三米以外报告。"},{"i":17,"n":"第十七条","txt":"遇到问题，主动向警官汇报。与警官交谈时，如实陈述、回答问题。"},{"i":18,"n":"第十八条","txt":"在指定铺位就寝，就寝时保持安静，不影响他人休息。"},{"i":19,"n":"第十九条","txt":"接受法制、道德、形势、政策等思想教育，认清犯罪危害，矫治恶习。"},{"i":20,"n":"第二十条","txt":"接受心理健康教育，配合心理测试，养成健康心理。"},{"i":21,"n":"第二十一条","txt":"尊重教师，遵守学习纪律，爱护教学设施、设备。"},{"i":22,"n":"第二十二条","txt":"接受文化教育，上课认真听讲，按时完成作业，争取良好成绩。"},{"i":23,"n":"第二十三条","txt":"接受技术教育，掌握实用技能，争当劳动能手，增强就业能力。"},{"i":24,"n":"第二十四条","txt":"阅读健康有益书刊，按规定收听、收看广播电视。"},{"i":25,"n":"第二十五条","txt":"参加文娱活动，增强体质，陶冶情操。"},{"i":26,"n":"第二十六条","txt":"积极参加劳动。因故不参加劳动，须经警官批准。"},{"i":27,"n":"第二十七条","txt":"遵守劳动纪律，坚守岗位，服从生产管理和技术指导。"},{"i":28,"n":"第二十八条","txt":"严格遵守操作规程和安全生产规定，不违章作业。"},{"i":29,"n":"第二十九条","txt":"爱护设备、工具。厉行节约，减少损耗，杜绝浪费。"},{"i":30,"n":"第三十条","txt":"保持劳动现场卫生整洁，遵守定置管理规定，工具、材料、产品摆放整齐。"},{"i":31,"n":"第三十一条","txt":"不将劳动工具和危险品、违禁品带进监舍。"},{"i":32,"n":"第三十二条","txt":"完成劳动任务，保证劳动质量，珍惜劳动成果。"},{"i":33,"n":"第三十三条","txt":"爱护公共环境。不随地吐痰，不乱扔杂物，不损坏花草树木。"},{"i":34,"n":"第三十四条","txt":"言谈举止文明。不讲脏话、粗话。"},{"i":35,"n":"第三十五条","txt":"礼貌称谓他人。对人民警察称“警官”，对其他人员采用相应礼貌称谓。"},{"i":36,"n":"第三十六条","txt":"服刑人员之间互称姓名，不起(叫)绰号。"},{"i":37,"n":"第三十七条","txt":"来宾、警官进入监舍时，除患病和按规定就寝外，起立致意。"},{"i":38,"n":"第三十八条","txt":"与来宾、警官相遇时，文明礼让。"}],"yizhugongzhengxize":[{"i":1,"n":"第一条","txt":"为规范遗嘱公证程序，根据《中华人民共和国继承法》、《中华人民共和国公证暂行条例》等有关规定，制定本细则。"},{"i":2,"n":"第二条","txt":"遗嘱是遗嘱人生前在法律允许的范围内，按照法律规定的方式处分其个人财产或者处理其他事务，并在其死亡时发生效力的单方法律行为。"},{"i":3,"n":"第三条","txt":"遗嘱公证是公证处按照法定程序证明遗嘱人设立遗嘱行为真实、合法的活动。经公证证明的遗嘱为公证遗嘱。"},{"i":4,"n":"第四条","txt":"遗嘱公证由遗嘱人住所地或者遗嘱行为发生地公证处管辖。"},{"i":5,"n":"第五条","txt":"遗嘱人申办遗嘱公证应当亲自到公证处提出申请。 遗嘱人亲自到公证处有困难的，可以书面或者口头形式请求有管辖权的公证处指派公证人员到其住所或者临时处所办理。"},{"i":6,"n":"第六条","txt":"遗嘱公证应当由两名公证人员共同办理，由其中一名公证员在公证书上署名。因特殊情况由一名公证员办理时，应当有一名见证人在场，见证人应当在遗嘱和笔录上签名。 见证人、遗嘱代书人适用《中华人民共和国继承法》第十八条的规定。"},{"i":7,"n":"第七条","txt":"申办遗嘱公证，遗嘱人应当填写公证申请表，并提交下列证件和材料： (一)居民身份证或者其他身份证件； (二)遗嘱涉及的不动产、交通工具或者其他有产权凭证的财产的产权证明； (三)公证人员认为应当提交的其他材料。 遗嘱人填写申请表确有困难的，可由公证人员代为填写，遗嘱人应当在申请表上签名。"},{"i":8,"n":"第八条","txt":"对于属于本公证处管辖，并符合前条规定的申请，公证处应当受理。 对于不符合前款规定的申请，公证处应当在三日内作出不予受理的决定，并通知申请人。"},{"i":9,"n":"第九条","txt":"公证人员具有《公证程序规则(试行)》第十条规定情形的，应当自行回避，遗嘱人有权申请公证人员回避。"},{"i":10,"n":"第十条","txt":"公证人员应当向遗嘱人讲解我国《民法通则》、《继承法》中有关遗嘱和公民财产处分权利的规定，以及公证遗嘱的意义和法律后果。"},{"i":11,"n":"第十一条","txt":"公证处应当按照《公证程序规则(试行)》第二十三条的规定进行审查，并着重审查遗嘱人的身份及意思表示是否真实、有无受胁迫或者受欺骗等情况。"},{"i":12,"n":"第十二条","txt":"公证人员询问遗嘱人，除见证人、翻译人员外，其他人员一般不得在场。公证人员应当按照《公证程序规则(试行)》第二十四条的规定制作谈话笔录。谈话笔录应当着重记录下列内容： (一)遗嘱人的身体状况、精神状况；遗嘱人系老年人、间歇性精神病人、危重伤病人的，还应当记录其对事物的识别、反应能力； (二)遗嘱人家庭成员情况，包括其配偶、子女、父母及与其共同生活人员的基本情况； (三)遗嘱所处分财产的情况，是否属于遗嘱人个人所有，以前是否曾以遗嘱或者遗赠扶养协议等方式进行过处分，有无已设立担保、已被查封、扣押等限制所有权的情况； (四)遗嘱人所提供的遗嘱或者遗嘱草稿的形成时间、地点和过程，是自书还是代书，是否本人的真实意愿，有无修改、补充，对遗产的处分是否附有条件；代书人的情况，遗嘱或者遗嘱草稿上的签名、盖章或者手印是否其本人所为； (五)遗嘱人未提供遗嘱或者遗嘱草稿的，应当详细记录其处分遗产的意思表示"},{"i":13,"n":"第十三条","txt":"遗嘱应当包括以下内容： (一)遗嘱人的姓名、性别、出生日期、住址； (二)遗嘱处分的财产状况(名称、数量、所在地点以及是否共有、抵押等)； (三)对财产和其他事务的具体处理意见； (四)有遗嘱执行人的，应当写明执行人姓名、性别、年龄、住址等； (五)遗嘱制作的日期以及遗嘱人的签名。 遗嘱中一般不得包括与处分财产及处理死亡后事宜无关的其他内容。"},{"i":14,"n":"第十四条","txt":"遗嘱人提供的遗嘱，无修改、补充的，遗嘱人应当在公证人员面前确认遗嘱内容、签名及签署日期属实。 遗嘱人提供的遗嘱或者遗嘱草稿，有修改、补充的，经整理、誊清后，应当交遗嘱人核对，并由其签名。 遗嘱人未提供遗嘱或者遗嘱草稿的，公证人员可以根据遗嘱人的意思表示代为起草遗嘱。公证人员代拟的遗嘱，应当交遗嘱人核对，并由其签名。 以上情况应当记入谈话笔录。"},{"i":15,"n":"第十五条","txt":"两个以上的遗嘱人申请办理共同遗嘱公证的，公证处应当引导他们分别设立遗嘱。 遗嘱人坚持申请办理共同遗嘱公证的，共同遗嘱中应当明确遗嘱变更、撤销及生效的条件。"},{"i":16,"n":"第十六条","txt":"公证人员发现有下列情形之一的，公证人员在与遗嘱人谈话时应当录音或者录像： (一)遗嘱人年老体弱； (二)遗嘱人为危重伤病人； (三)遗嘱人为聋、哑、盲人； (四)遗嘱人为间歇性精神病患者、弱智者。"},{"i":17,"n":"第十七条","txt":"对于符合下列条件的，公证处应当出具公证书： (一)遗嘱人身份属实，具有完全民事行为能力； (二)遗嘱人意思表示真实； (三)遗嘱人证明或者保证所处分的财产是其个人财产； (四)遗嘱内容不违反法律规定和社会公共利益，内容完备，文字表述准确，签名、制作日期齐全； (五)办证程序符合规定。 不符合前款规定条件的，应当拒绝公证。"},{"i":18,"n":"第十八条","txt":"公证遗嘱采用打印形式。遗嘱人根据遗嘱原稿核对后，应当在打印的公证遗嘱上签名。 遗嘱人不会签名或者签名有困难的，可以盖章方式代替在申请表、笔录和遗嘱上的签名；遗嘱人既不能签字又无印章的，应当以按手印方式代替签名或者盖章。 有前款规定情形的，公证人员应当在笔录中注明。以按手印代替签名或者盖章的，公证人员应当提取遗嘱人全部的指纹存档。"},{"i":19,"n":"第十九条","txt":"公证处审批人批准遗嘱公证书之前，遗嘱人死亡或者丧失行为能力的，公证处应当终止办理遗嘱公证。 遗嘱人提供或者公证人员代书、录制的遗嘱，符合代书遗嘱条件或者经承办公证人员见证符合自书、录音、口头遗嘱条件的，公证处可以将该遗嘱发给遗嘱受益人，并将其复印件存入终止公证的档案。 公证处审批人批准之后，遗嘱人死亡或者丧失行为能力的，公证处应当完成公证遗嘱的制作。遗嘱人无法在打印的公证遗嘱上签名的，可依符合第十七条规定的遗嘱原稿的复印件制作公证遗嘱，遗嘱原稿留公证处存档。"},{"i":20,"n":"第二十条","txt":"公证处可根据《中华人民共和国公证暂行条例》规定保管公证遗嘱或者自书遗嘱、代书遗嘱、录音遗嘱；也可根据国际惯例保管密封遗嘱。"},{"i":21,"n":"第二十一条","txt":"遗嘱公证卷应当列为密卷保存。遗嘱人死亡后，转为普通卷保存。 公证遗嘱生效前，遗嘱卷宗不得对外借阅，公证人员亦不得对外透露遗嘱内容。"},{"i":22,"n":"第二十二条","txt":"公证遗嘱生效前，非经遗嘱人申请并履行公证程序，不得撤销或者变更公证遗嘱。 遗嘱人申请撤销或者变更公证遗嘱的程序适用本规定。"},{"i":23,"n":"第二十三条","txt":"公证遗嘱生效后，与继承权益相关的人员有确凿证据证明公证遗嘱部分违法的，公证处应当予以调查核实；经调查核实，公证遗嘱部分内容确属违法的，公证处应当撤销对公证遗嘱中违法部分的公证证明。"},{"i":24,"n":"第二十四条","txt":"因公证人员过错造成错证的，公证处应当承担赔偿责任。有关公证赔偿的规定，另行制定。"},{"i":25,"n":"第二十五条","txt":"本细则由司法部解释。"},{"i":26,"n":"第二十六条","txt":"本细则自2000年7月1日起施行。"}],"xianggangaomentebiexingzhengqulvshishiwusuozhuneid6bc106":[{"i":1,"n":"第一条","txt":"为规范香港、澳门特别行政区律师事务所(以下简称港澳律师事务所)驻内地代表机构(以下简称代表处)的设立及其法律服务活动，根据《外国律师事务所驻华代表机构管理条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"港澳律师事务所设立代表处，从事法律服务活动，适用本办法。"},{"i":3,"n":"第三条","txt":"代表处及其代表依照本办法规定从事法律服务活动，受国家法律保护。"},{"i":4,"n":"第四条","txt":"代表处及其代表从事法律服务活动，应当遵守国家法律、法规和规章，恪守律师职业道德和执业纪律，不得损害国家安全和社会公共利益。"},{"i":5,"n":"第五条","txt":"港澳律师事务所对其代表处及其代表在内地从事的法律服务活动承担民事责任。"},{"i":6,"n":"第六条","txt":"港澳律师事务所在内地设立代表处、派驻代表，应当经省、自治区、直辖市司法厅(局)许可。 港澳律师事务所、其他组织或者个人不得以咨询公司或者其他名义在内地从事法律服务活动。"},{"i":7,"n":"第七条","txt":"港澳律师事务所申请在内地设立代表处、派驻代表，应当具备下列条件： (一)该律师事务所已在港、澳特别行政区合法执业，并且没有因违反律师职业道德、执业纪律受到处罚; (二)代表处的代表应当是执业律师和港、澳特别行政区律师协会会员，并且已在内地以外执业不少于2年，没有受过刑事处罚或者没有因违反职业道德、执业纪律受过处罚;其中，首席代表已在内地以外执业不少于3年，并且是该律师事务所的合伙人或者是相同职位的人员; (三)有在内地设立代表处开展法律服务业务的实际需要。"},{"i":8,"n":"第八条","txt":"港澳律师事务所申请在内地设立代表处，应当向拟设立的代表处住所地的省、自治区、直辖市司法厅(局)提交下列文件材料： (一)该律师事务所主要负责人签署的设立代表处、派驻代表的申请书。拟设立的代表处的名称应当为“××律师事务所(该律师事务所的中文名称)驻××(内地城市名)代表处”; (二)该律师事务所在其本特别行政区已经合法设立的证明文件; (三)该律师事务所的合伙协议或者成立章程以及负责人、合伙人名单; (四)该律师事务所给代表处各拟任代表的授权书，以及拟任首席代表系该律师事务所合伙人或者相同职位人员的确认书; (五)代表处各拟任代表的律师执业资格以及拟任首席代表已在内地以外执业不少于3年、其他拟任代表已在内地以外执业不少于2年的证明文件; (六)该律师事务所所在特别行政区的律师协会出具的该代表处各拟任代表为本地区律师协会会员的证明文件; (七)该律师事务所所在特别行政区的律师管理机构出具"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市司法厅(局)应当自收到申请文件材料之日起6个月内审查完毕并作出决定，对许可设立的代表处发给执业执照，并对其代表发给执业证书，同时办理注册手续;对不予许可的，应当书面告知其理由。"},{"i":10,"n":"第十条","txt":"代表处及其代表每年应当注册一次。 省、自治区、直辖市司法厅(局)应当自接到注册申请之日起2日内办理注册手续。"},{"i":11,"n":"第十一条","txt":"代表处应当按照有关法律、行政法规的规定，办理有关的税务、银行、外汇等手续。"},{"i":12,"n":"第十二条","txt":"港澳律师事务所需要变更代表处名称、减少代表的，应当事先向代表处住所地的省、自治区、直辖市司法厅(局)提交其主要负责人签署的申请书和有关的文件材料，经省、自治区、直辖市司法厅(局)核准，并收回不再担任代表的人员的执业证书。 代表处合并、分立或者增加新任代表的，应当依照本办法有关代表处设立程序的规定办理许可手续。"},{"i":13,"n":"第十三条","txt":"代表处的代表有下列情形之一的，由省、自治区、直辖市司法厅(局)撤回其执业许可、收回其执业证书，并注销其执业注册： (一)按照本办法第八条第五项规定提供的律师执业资格失效的; (二)被所属的港澳律师事务所取消代表资格的; (三)执业证书或者所在的代表处的执业执照被依法吊销的。"},{"i":14,"n":"第十四条","txt":"代表处有下列情形之一的，由省、自治区、直辖市司法厅(局)撤回其执业许可、收回其执业执照，并注销其执业注册： (一)所属的港澳律师事务所已经解散或者被注销的; (二)所属的港澳律师事务所申请将其注销的; (三)已经丧失本办法第七条规定条件的; (四)执业执照被依法吊销的。 依照前款规定注销的代表处，应当依法进行清算;债务清偿完毕前，其财产不得转移至内地以外。"},{"i":15,"n":"第十五条","txt":"代表处及其代表，只能从事不包括内地法律事务的下列活动： (一)向当事人提供该律师事务所律师已获准从事律师执业业务的香港特别行政区、澳门特别行政区以及中国以外的其他国家的法律咨询，有关国际条约、国际惯例的咨询; (二)接受当事人或者内地律师事务所的委托，办理在该律师事务所律师已获准从事律师执业业务的地区的法律事务; (三)代表港、澳特别行政区当事人，委托内地律师事务所办理内地法律事务; (四)通过订立合同与内地律师事务所保持长期的委托关系办理法律事务; (五)提供有关内地法律环境影响的信息。 代表处按照与内地律师事务所达成的协议约定，可以直接向受委托的内地律师事务所的律师提出要求。 代表处及其代表按照所属港澳律师事务所与内地律师事务所达成的联营协议，可以与联营的内地律师事务所的律师合作，办理有关联营业务。 代表处及其代表不得从事本条第一款、第二款、第三款规定以外的其他法律服务活动或者其他"},{"i":16,"n":"第十六条","txt":"代表处不得聘用内地执业律师;聘用的辅助人员不得为当事人提供法律服务。"},{"i":17,"n":"第十七条","txt":"代表处及其代表在执业活动中，不得有下列行为： (一)提供虚假证据、隐瞒事实或者威胁、利诱他人提供虚假证据、隐瞒事实以及妨碍对方当事人合法取得证据; (二)利用法律服务的便利，收受当事人的财物或者其他好处; (三)泄露当事人的商业秘密或者个人隐私。"},{"i":18,"n":"第十八条","txt":"代表处的代表不得同时在两个以上代表处担任或者兼任代表。"},{"i":19,"n":"第十九条","txt":"代表处的代表可以自行决定在内地居留的时间。"},{"i":20,"n":"第二十条","txt":"代表处从事本办法规定的法律服务，可以向当事人收取费用。收取的费用必须在内地结算。"},{"i":21,"n":"第二十一条","txt":"司法部负责对代表处及其代表的监督管理。 省、自治区、直辖市司法厅(局)应当对设在本行政区域内的代表处及其代表是否依法开展法律服务活动进行监督管理。"},{"i":22,"n":"第二十二条","txt":"代表处应当于每年3月31日前向住所地的省、自治区、直辖市司法厅(局)提交执业执照和代表执业证书的副本以及下列上一年度检验材料，接受年度检验： (一)开展法律服务活动的情况，包括委托内地律师事务所办理法律事务的情况; (二)经会计师事务所或审计事务所审计的代表处年度财务报表，以及在内地结算和依法纳税凭证; (三)代表处的代表变动情况和雇用内地辅助人员情况; (四)代表处的代表在内地的居留情况; (五)代表处及其代表的注册情况; (六)履行本办法规定义务的其他情况。 省、自治区、直辖市司法厅(局)对设在本行政区域内的代表处进行年度检验后，应当将年度检验情况报司法部。"},{"i":23,"n":"第二十三条","txt":"省、自治区、直辖市司法厅(局)依法实施罚款的行政处罚，应当按照有关法律、行政法规的规定，实行罚款决定与罚款收缴分离;收缴的罚款以及依法没收的违法所得，必须全部上缴国库。"},{"i":24,"n":"第二十四条","txt":"代表处或者代表危害国家安全、公共安全或者社会管理秩序的，依照刑法有关规定，追究刑事责任，并由省、自治区、直辖市司法厅(局)吊销该代表处的执业执照或者该代表的执业证书;尚不够刑事处罚的，依法给予治安管理处罚，并由省、自治区、直辖市司法厅(局)吊销该代表处的执业执照或者该代表的执业证书。"},{"i":25,"n":"第二十五条","txt":"代表处或者代表违反本办法第十五条的规定，非法从事法律服务活动或者其他营利活动的，由省、自治区、直辖市司法厅(局)对代表处给予停业整顿六个月以下的处罚或者对代表给予停止执业一年以下的处罚;情节严重的，吊销该代表处的执业执照或者该代表的执业证书。 有前款所列违法行为的，由省、自治区、直辖市司法厅(局)没收违法所得，对首席代表和其他负有直接责任的代表各处5万元以上20万元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"代表处有下列情形之一的，由省、自治区、直辖市司法厅(局)给予警告，责令限期改正;情节严重的，对代表处给予停业整顿六个月以下的处罚;逾期仍不改正的，吊销其执业执照： (一)聘用内地执业律师，或者聘用的辅助人员从事法律服务的; (二)开展法律服务收取费用未在内地结算的; (三)未按时报送年度检验材料接受年度检验，或者未通过年度检验的。 有前款第(二)项所列违法行为的，由省、自治区、直辖市司法厅(局)对其处以应当在内地结算的金额1倍以上3倍以下的罚款。"},{"i":27,"n":"第二十七条","txt":"代表处或者代表有下列情形之一的，由省、自治区、直辖市司法厅(局)给予警告，没收违法所得;情节严重的，对代表处给予停业整顿六个月以下的处罚或者对代表给予停止执业一年以下的处罚，并处2万元以上10万元以下的罚款： (一)同时在两个以上代表处担任或者兼任代表的; (二)泄露当事人的商业秘密或者个人隐私的; (三)利用法律服务的便利，收受当事人财物或者其他好处的。"},{"i":28,"n":"第二十八条","txt":"代表处注销，在债务清偿完毕前将财产转移至内地以外的，由省、自治区、直辖市司法厅(局)责令退回已转移的财产，用于清偿债务;严重损害他人利益，构成犯罪的，对其首席代表和其他直接责任人员依法追究刑事责任;尚不够刑事处罚的，由省、自治区、直辖市司法厅(局)对代表处处5万元以上30万元以下的罚款，对首席代表和其他直接责任人员处2万元以上10万元以下的罚款。"},{"i":29,"n":"第二十九条","txt":"代表处的代表提供虚假证据、隐瞒事实或者威胁、利诱他人提供虚假证据、隐瞒事实的，依照刑法有关规定追究刑事责任，并由省、自治区、直辖市司法厅(局)吊销其执业证书。"},{"i":30,"n":"第三十条","txt":"港澳律师事务所、律师或者其他组织、个人擅自在内地从事法律服务活动，或者已被撤销执业许可的代表处或者代表继续在内地从事法律服务活动的，由省、自治区、直辖市司法厅(局)予以取缔，没收违法所得，并处5万元以上30万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"代表处被依法吊销执业执照的，该代表处所属的港澳律师事务所5年内不得申请在内地设立代表处;代表处的代表被依法吊销执业证书的，该代表5年内不得在内地担任代表处的代表。 代表处的代表因危害国家安全、公共安全或者社会管理秩序，被依法判处刑罚的，该代表所在的代表处所属的律师事务所不得再申请在内地设立代表处，该代表终身不得在内地担任代表处的代表。"},{"i":32,"n":"第三十二条","txt":"司法行政部门工作人员有下列违法行为之一的，对负有责任的主管人员和其他直接责任人员依法给予记过、记大过或者降级的行政处分： (一)不按照本办法规定的条件对拟设代表处、拟任代表的证明文件、材料进行审查、审核的; (二)不按照本办法的规定对代表处进行注册或者年度检验的。"},{"i":33,"n":"第三十三条","txt":"司法行政部门工作人员有下列违法行为之一的，对负有责任的主管人员和其他直接责任人员依法给予降级、撤职或者开除的行政处分： (一)对不符合本办法规定条件的拟设代表处或者拟任代表决定发给执业执照、执业证书的; (二)利用职务上的便利收受财物、谋取私利的; (三)违反本办法的规定，对应当撤销代表处或者代表执业许可，收回执业执照、执业证书的不予撤销、收回，或者对应当注销的执业注册不予注销的; (四)依法收缴罚款不开具罚款收据或者不如实填写罚款数额的; (五)不执行罚款收缴分离制度或者不按照规定将依法收取的费用、收缴的罚款及没收的违法所得全部上缴国库的; (六)对代表处及其代表违反本办法规定的行为不及时查处的; (七)有不严格执法或者滥用职权的其他行为，造成严重后果的。 有前款所列违法行为之一，致使公共财产、国家和人民利益遭受严重损失，构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本办法自2002年4月1日起施行。本办法施行前经司法部许可已经试开业的代表处及其代表，应当自本办法施行之日起90日内按照本办法的规定重新申请办理审批手续。"}],"xianggangfalvzhiyezheheaomenzhiyelvshishoupinyunei822853":[{"i":1,"n":"第一条","txt":"为了落实国务院批准的《内地与香港关于建立更紧密经贸关系的安排》和《内地与澳门关于建立更紧密经贸关系的安排》，规范香港法律执业者、澳门执业律师受聘于内地律师事务所担任法律顾问的活动及管理，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的香港法律执业者，是指具有香港永久性居民身份，依据香港有关法规在律师、大律师登记册上登记，并没有被暂时吊销执业资格的律师、大律师。 本办法所称的澳门执业律师，是指具有澳门永久性居民身份，在澳门律师公会有效注册的执业律师。"},{"i":3,"n":"第三条","txt":"香港法律执业者、澳门执业律师受聘于内地律师事务所担任法律顾问，只能办理已获准从事律师执业业务的香港、澳门以及中国以外的其他国家的法律事务。 香港法律执业者、澳门执业律师受聘于内地律师事务所担任法律顾问，应当接受内地司法行政机关的监督和管理。"},{"i":4,"n":"第四条","txt":"香港法律执业者受聘于内地律师事务所担任法律顾问，应当依照本办法申请领取香港法律顾问证。 澳门执业律师受聘于内地律师事务所担任法律顾问，应当依照本办法申请领取澳门法律顾问证。"},{"i":5,"n":"第五条","txt":"香港法律执业者、澳门执业律师具备下列条件的，可以向内地司法行政机关申请领取香港、澳门法律顾问证： (一)在香港或者澳门执业满2年； (二)未受过刑事处罚及未因违反律师职业道德、执业纪律受过处罚； (三)有内地律师事务所同意聘用。"},{"i":6,"n":"第六条","txt":"内地律师事务所具备下列条件的，可以聘用香港法律执业者、澳门执业律师为本所香港、澳门法律顾问： (一)成立满3年； (二)专职律师不少于10人； (三)最近3年内未受过行政处罚、行业处分。 内地律师事务所聘用香港法律执业者、澳门执业律师的数量合计不得超过本所专职律师总数的五分之一。"},{"i":7,"n":"第七条","txt":"香港法律执业者、澳门执业律师申请领取香港、澳门法律顾问证，应当通过拟聘其担任法律顾问的内地律师事务所提交下列材料： (一)申请书； (二)申请人身份证明的复印件； (三)申请人的香港法律执业者、澳门执业律师执业资格证书的复印件； (四)申请人如有获准从事律师执业业务的外国律师资格的，须提交其律师执业资格证书的复印件； (五)申请人在香港或者澳门执业满2年的证明材料； (六)申请人所在的香港、澳门律师事务所出具的同意其受聘于内地律师事务所的证明； (七)香港、澳门律师监管机构出具的申请人未受过刑事处罚及未因违反律师职业道德、执业纪律受过处罚的证明材料； (八)内地律师事务所出具的拟聘用申请人的证明及本所符合聘用条件的证明材料。 前款第二项、第三项、第四项、第五项所列证明材料，须经内地认可的公证人公证。 申请材料应当使用中文，一式三份。材料中如有使用外文的，应当附中文译文。"},{"i":8,"n":"第八条","txt":"内地律师事务所所在地的地(市)级司法行政机关应当自收到香港法律执业者、澳门执业律师申请材料之日起10日内完成审查，出具审查意见，并连同申请材料上报省级司法行政机关。"},{"i":9,"n":"第九条","txt":"省级司法行政机关应当自收到申请材料之日起20日内完成审核。对于符合本办法规定条件的，准予在内地受聘担任法律顾问，并办理登记，向其颁发香港、澳门法律顾问证；对于不符合本办法规定条件的，不准在内地受聘担任法律顾问，并书面通知申请人和拟聘其担任法律顾问的内地律师事务所。 省级司法行政机关应当自向申请人颁发香港、澳门法律顾问证之日起30日内，将有关登记材料及审核意见报司法部备案。"},{"i":10,"n":"第十条","txt":"香港法律执业者、澳门执业律师，只能受聘于内地一个律师事务所担任法律顾问，不得同时受聘于外国律师事务所，不得同时在香港、澳门律师事务所驻内地代表机构担任代表。"},{"i":11,"n":"第十一条","txt":"香港、澳门法律顾问不得办理内地法律事务。"},{"i":12,"n":"第十二条","txt":"香港、澳门法律顾问在内地办理法律事务，应当由所在的内地律师事务所统一接受委托、统一收取费用，不得私自受理业务、私自收费。"},{"i":13,"n":"第十三条","txt":"香港、澳门法律顾问应当遵守国家法律、法规和规章，恪守律师职业道德和执业纪律，不得损害国家安全和社会公共利益。"},{"i":14,"n":"第十四条","txt":"香港、澳门法律顾问与内地律师事务所应当依法签订聘用协议，规定双方的权利、义务及违约责任。"},{"i":15,"n":"第十五条","txt":"香港、澳门法律顾问证，每年须经省级司法行政机关年度注册。未经注册的无效。"},{"i":16,"n":"第十六条","txt":"香港、澳门法律顾问有下列行为之一的，由地(市)级司法行政机关给予警告，责令限期改正；逾期不改正的，处1万元以下罚款；有违法所得的，处违法所得1倍以上3倍以下罚款，但罚款最高不得超过3万元： (一)同时在内地两个以上律师事务所受聘的； (二)同时在香港、澳门律师事务所驻内地代表机构担任代表的； (三)同时在外国律师事务所受聘的； (四)私自受理业务或者私自向当事人收取费用的； (五)办理内地法律事务的； (六)其他违反法律、法规和规章应当给予处罚的行为。 香港、澳门法律顾问违反前款规定情节严重的，内地律师事务所应当与其解除聘用关系。"},{"i":17,"n":"第十七条","txt":"内地律师事务所有下列行为之一的，由地(市)级司法行政机关给予警告，责令限期改正；逾期不改正的，处1万元以下罚款；有违法所得的，处违法所得1倍以上3倍以下罚款，但罚款最高不得超过3万元： (一)未经核准，擅自聘用香港法律执业者、澳门执业律师担任法律顾问的； (二)对香港、澳门法律顾问的法律服务活动不实行统一接受委托、统一收取费用的； (三)对香港、澳门法律顾问的违法行为负有管理失查责任的； (四)其他违反法律、法规和规章应当给予处罚的行为。"},{"i":18,"n":"第十八条","txt":"香港、澳门法律顾问因违法行为或者过错给当事人造成损失的，由聘其担任法律顾问的内地律师事务所承担赔偿责任。律师事务所赔偿后，可以向负有直接责任的香港、澳门法律顾问追偿部分或者全部赔偿费用。 香港、澳门法律顾问应当在内地办理保险。"},{"i":19,"n":"第十九条","txt":"司法行政机关工作人员在行政管理活动中，有违反法律、法规和规章规定的行为的，依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"本办法由司法部解释。"},{"i":21,"n":"第二十一条","txt":"本办法自2004年1月1日起施行。"}],"xianggangtebiexingzhengquheaomentebiexingzhengquju6f4aba":[{"i":1,"n":"第一条","txt":"为了落实国务院批准的《内地与香港关于建立更紧密经贸关系的安排》和《内地与澳门关于建立更紧密经贸关系的安排》(以下简称两个《安排》)，允许符合规定条件的香港、澳门居民参加国家司法考试，根据最高人民法院、最高人民检察院、司法部联合制定的《国家司法考试实施办法(试行)》，制定本规定。"},{"i":2,"n":"第二条","txt":"香港、澳门永久性居民中的中国公民，可以报名参加国家司法考试。"},{"i":3,"n":"第三条","txt":"香港、澳门永久性居民中的中国公民参加国家司法考试，其报名条件、报名时间、考试科目、考试内容、考试时间、参考规则、合格标准、资格授予，适用《国家司法考试实施办法(试行)》以及有关国家司法考试的统一规定。 组织香港、澳门居民参加国家司法考试，应当同时遵守《香港特别行政区基本法》和《澳门特别行政区基本法》的有关规定。"},{"i":4,"n":"第四条","txt":"香港、澳门永久性居民中的中国公民在考试报名时，应当向受理报名的机构提交下列证明其符合本规定第二条规定条件的有效身份证件： (一)香港、澳门永久性居民的身份证明； (二)港澳居民来往内地通行证(回乡证)或者香港、澳门特别行政区护照。 提交复印件的，须经内地认可的公证人公证。"},{"i":5,"n":"第五条","txt":"香港、澳门永久性居民中的中国公民在考试报名时，持内地高等院校学历证书的，可以向受理报名的机构直接办理报名手续；持香港、澳门、台湾地区高等院校或者外国高等院校学历证书报名的，须同时提交经国务院教育行政部门有关机构出具的认证证明。"},{"i":6,"n":"第六条","txt":"香港、澳门永久性居民中的中国公民报名参加国家司法考试，在香港、澳门工作、学习或者居住的，应当在香港、澳门向承办考试组织工作的机构报名；在内地工作、学习或者居住的，可以在香港、澳门报名，也可以在其内地居所地司法行政机关指定的报名点报名。在内地报名的，须提交其在内地工作、学习或者居住的证明。"},{"i":7,"n":"第七条","txt":"香港、澳门永久性居民中的中国公民参加国家司法考试，在香港、澳门报名的，应当在香港、澳门承办考试组织工作的机构所确定的本地考场参加考试；在内地报名的，应当在报名地司法行政机关设置的考场参加考试。"},{"i":8,"n":"第八条","txt":"香港、澳门永久性居民中的中国公民参加国家司法考试合格的，可以根据司法部制定的《法律职业资格证书管理办法》的规定，向司法行政机关申请授予《中华人民共和国法律职业资格证书》。 在香港、澳门报名参加考试合格的人员，向司法部委托的承办资格申请受理事务的内地驻港澳机构递交申请及有关材料，由司法部负责审查。 在内地报名参加考试合格的人员，向报名地司法行政机关递交申请及有关材料，由其按规定程序审查上报。"},{"i":9,"n":"第九条","txt":"香港、澳门永久性居民中的中国公民取得内地法律职业资格，在内地申请律师执业，依照《中华人民共和国律师法》、两个《安排》和司法部有关规定办理。"},{"i":10,"n":"第十条","txt":"香港、澳门居民报名参加国家司法考试的具体安排，由司法部在年度国家司法考试公告以及司法部国家司法考试办公室相关文件中公布。"},{"i":11,"n":"第十一条","txt":"本规定由司法部解释。"},{"i":12,"n":"第十二条","txt":"本规定自发布之日起施行。司法部2003年11月30日发布的《香港特别行政区和澳门特别行政区居民参加国家司法考试若干规定》(司法部令第80号)同时废止。"}],"xianggangtebiexingzhengquheaomentebiexingzhengqulv543097":[{"i":1,"n":"第一条","txt":"为了落实国务院批准的《内地与香港关于建立更紧密经贸关系的安排》和《内地与澳门关于建立更紧密经贸关系的安排》，规范香港、澳门律师事务所与内地律师事务所在内地进行联营的活动及管理，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的联营，是由已在内地设立代表机构的香港、澳门律师事务所与一至三家内地律师事务所，按照协议约定的权利和义务，在内地进行联合经营，向委托人分别提供香港、澳门和内地法律服务。"},{"i":3,"n":"第三条","txt":"香港、澳门律师事务所与内地律师事务所联营，不得采取合伙型联营和法人型联营。香港、澳门律师事务所与内地律师事务所在联营期间，双方的法律地位、名称和财务应当保持独立，各自独立承担民事责任。"},{"i":4,"n":"第四条","txt":"香港、澳门律师事务所与内地律师事务所联营，应当遵守国家法律、法规和规章，恪守律师职业道德和执业纪律，不得损害国家安全和社会公共利益。"},{"i":5,"n":"第五条","txt":"符合下列条件的香港、澳门律师事务所，可以申请联营： (一)根据香港、澳门有关法规登记设立； (二)在香港、澳门拥有或者租用业务场所从事实质性商业经营满3年； (三)独资经营者或者所有合伙人必须为香港、澳门注册执业律师； (四)主要业务范围应为在香港、澳门提供本地法律服务； (五)律师事务所及其独资经营者或者所有合伙人均须缴纳香港利得税、澳门所得补充税或者职业税； (六)已获准在内地设立代表机构，且代表机构在申请联营前两年内未受过行政处罚；申请联营时代表机构设立未满两年的，自代表机构设立之日起未受过行政处罚。"},{"i":6,"n":"第六条","txt":"符合下列条件的内地律师事务所，可以申请联营： (一)成立满3年； (二)申请联营前两年内未受过行政处罚、行业惩戒。 成立满1年并至少有1名设立人具有5年以上执业经历、住所地在广东省的内地律师事务所，也可以申请联营。 内地律师事务所分所不得作为联营一方申请联营。"},{"i":7,"n":"第七条","txt":"香港、澳门律师事务所与内地律师事务所申请联营，应当共同向内地律师事务所所在地的省级司法行政机关提交下列申请材料： (一)双方签署的联营申请书； (二)双方签署的联营协议； (三)香港、澳门律师事务所获准在香港、澳门设立的有效登记证件的复印件，独资经营者或者负责人、所有合伙人名单，驻内地代表机构执业许可证的复印件及代表名单； (四)香港、澳门特别行政区政府有关部门出具的香港、澳门律师事务所符合香港、澳门法律服务提供者标准的证明书； (五)内地律师事务所执业许可证的复印件，负责人、所有合伙人名单，地(市)级司法行政机关出具的该所符合本办法第六条规定条件的证明文件； (六)香港、澳门律师事务所驻内地代表机构与内地律师事务所不在同一省、自治区、直辖市的，由香港、澳门律师事务所驻内地代表机构所在地的省级司法行政机关出具的香港、澳门律师事务所符合本办法第五条第(六)项规定条件的证明文件； (七)省"},{"i":8,"n":"第八条","txt":"省级司法行政机关应当自收到申请人联营申请材料之日起20日内作出准予或者不准联营的决定。20日内不能作出决定的，经本机关负责人批准，可以延长10日，并应当将延长期限的理由告知申请人。 对于符合本办法规定条件的，应当准予联营，颁发联营许可证；对于不符合本办法规定条件的，不准联营，并书面通知申请人。 对准予联营的，省级司法行政机关应当自颁发联营许可证之日起30日内，将准予联营的批件及有关材料报司法部备案。 香港、澳门律师事务所驻内地代表机构与内地律师事务所不在同一省、自治区、直辖市的，经内地律师事务所所在地的省级司法行政机关准予联营的，作出准予联营决定的省级司法行政机关还应当将准予联营批件同时抄送香港、澳门律师事务所驻内地代表机构所在地的省级司法行政机关。"},{"i":9,"n":"第九条","txt":"香港、澳门律师事务所与内地律师事务所联营，应当以书面形式订立联营协议。联营协议应当包括下列内容： (一)联营双方各自的名称、住所地、独资经营者、合伙人姓名； (二)联营名称、标识； (三)联营期限； (四)联营业务范围； (五)共用办公场所和设备的安排； (六)共用行政、文秘等辅助人员的安排； (七)联营收费的分享及运营费用的分摊安排； (八)联营双方律师的执业保险及责任承担方式的安排； (九)联营的终止及清算； (十)违约责任； (十一)争议解决； (十二)其他事项。 联营协议应当依照内地法律的有关规定订立。 联营协议经司法行政机关核准联营后生效。"},{"i":10,"n":"第十条","txt":"香港、澳门律师事务所与内地律师事务所联营协议约定的联营期限不得少于1年。双方联营协议约定的联营期满，经双方协商可以续延。申请联营续延，应当依照本办法第七条、第八条规定的程序办理。"},{"i":11,"n":"第十一条","txt":"香港、澳门律师事务所与内地律师事务所联营，可以使用双方商定并经核准的联营名称和联营标识。联营名称由香港或者澳门律师事务所名称与内地律师事务所名称加联营的字样组成。"},{"i":12,"n":"第十二条","txt":"香港、澳门律师事务所与内地律师事务所联营，可以共同以联营的名义，接受当事人的委托或者其他律师事务所的委托，采取合作方式办理各自获准从事律师执业业务的香港、澳门、内地以及中国以外的其他国家的法律事务。 参与联营业务的香港、澳门律师，不得办理内地法律事务。"},{"i":13,"n":"第十三条","txt":"联营双方受托办理法律事务，应当避免各自委托人之间的利益冲突。"},{"i":14,"n":"第十四条","txt":"香港、澳门律师事务所与内地律师事务所以联营名义合作办理法律事务的，可以统一向委托人收费，双方再依照联营协议进行分配；也可以根据联营中各自办理的法律事务，分别向委托人收费，但须事先告知委托人。"},{"i":15,"n":"第十五条","txt":"香港、澳门律师事务所与内地律师事务所联营，可以共同进行业务宣传推广活动。但在进行业务宣传推广时，应当披露下列事实： (一)双方联营不是合伙型联营或者法人型联营； (二)联营的香港、澳门律师事务所及其律师不能从事内地法律事务； (三)进行宣传推广的律师须明示其所在律师事务所的名称。"},{"i":16,"n":"第十六条","txt":"联营双方及其参与联营业务的律师，应当分别依照香港、澳门和内地的有关规定，以各自的名义参加律师执业保险。"},{"i":17,"n":"第十七条","txt":"联营双方在开展联营业务中违法执业或者因过错给委托人造成损失的，双方应当依照联营协议，由过错方独自承担或者双方分担赔偿责任。"},{"i":18,"n":"第十八条","txt":"香港、澳门律师事务所与内地律师事务所联营，可以共用办公场所、办公设备。联营双方决定共用办公场所的，应当选择香港、澳门律师事务所驻内地代表机构或者内地律师事务所的办公场所作为共用办公场所。共用办公场所或办公设备的费用分担由联营协议约定。"},{"i":19,"n":"第十九条","txt":"香港、澳门律师事务所与内地律师事务所联营，可以共用行政、文秘等辅助人员。有关费用分担由联营协议约定。"},{"i":20,"n":"第二十条","txt":"香港、澳门律师事务所与内地律师事务所联营，应当各自保持独立的财务制度和会计账簿。"},{"i":21,"n":"第二十一条","txt":"香港、澳门律师事务所与内地律师事务所联营，有下列情形之一的，应当终止联营： (一)联营期满双方不再申请续延的； (二)联营双方按照协议的约定终止联营的； (三)联营一方不再存续或者破产的； (四)香港、澳门律师事务所驻内地代表机构被依法注销的； (五)其他依法应当终止联营的情形。 终止联营的，由省级司法行政机关办理注销手续。"},{"i":22,"n":"第二十二条","txt":"香港、澳门律师事务所与内地律师事务所联营，应当在每年3月31日前，共同向内地律师事务所所在地的省级司法行政机关提交联营执业许可证副本以及下列年度检验材料，接受年度检验： (一)香港、澳门律师事务所驻内地代表机构和内地律师事务所的有效执业许可证副本及复印件； (二)上一年度的联营情况报告，内容包括以联营名义接受委托办理法律事务的情况，以联营名义办理法律事务的收费情况，联营收费的分享和运营费用的分摊情况，联营的收入和纳税情况，以联营名义开展业务过程中因违法执业或因过错给委托人造成损失的赔偿情况等； (三)香港、澳门律师事务所驻内地代表机构和内地律师事务所所在地的省级司法行政机关或地(市)级司法行政机关出具的代表机构和内地律师事务所在上一年度受到行政处罚或行业惩戒情况的文件。 无正当理由逾期不提交年检材料接受年度检验的，视为联营双方自行终止联营。"},{"i":23,"n":"第二十三条","txt":"香港、澳门律师事务所与内地律师事务所联营，有违反内地法律、法规和规章及本办法规定的行为的，由省级司法行政机关给予警告，责令限期改正；逾期不改正的，处1万元以下罚款；有违法所得的，处违法所得1倍以上3倍以下罚款，但罚款最高不得超过3万元。"},{"i":24,"n":"第二十四条","txt":"司法行政机关工作人员在行政管理活动中，有违反法律、法规和规章规定的行为的，依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本办法由司法部解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2004年1月1日起施行。"}]};
